public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        Map<Integer, Integer> parent = new HashMap<>();
        Map<Integer, Integer> size = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int root = findRoot(parent, i, j);
                    parent.put(root, root);
                    size.put(root, size.getOrDefault(root, 0) + 1);
                }
            }
        }

        int maxArea = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> roots = new HashSet<>();
                    for (int x = Math.max(0, i - 1); x <= Math.min(n - 1, i + 1); x++) {
                        for (int y = Math.max(0, j - 1); y <= Math.min(n - 1, j + 1); y++) {
                            if (grid[x][y] == 1) {
                                int root = findRoot(parent, x, y);
                                roots.add(root);
                            }
                        }
                    }

                    maxArea = Math.max(maxArea, sizeOfIsland(roots, parent, size));
                }
            }
        }

        return maxArea;
    }

    private int findRoot(Map<Integer, Integer> parent, int i, int j) {
        if (!parent.containsKey(i * n + j)) {
            parent.put(i * n + j, i * n + j);
        }

        if (parent.get(i * n + j) != (i * n + j)) {
            parent.put(i * n + j, findRoot(parent, i / 100, j / 100));
        }

        return parent.get(i * n + j);
    }

    private int sizeOfIsland(Set<Integer> roots, Map<Integer, Integer> parent, Map<Integer, Integer> size) {
        int maxArea = 0;
        for (int root : roots) {
            maxArea += size.get(root);
        }
        return maxArea;
    }
}

