public class Solution {
    int[] dx = {-1, 0, 1, 0};
    int[] dy = {0, -1, 0, 1};

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        Map<Integer, Integer> rootToSize = new HashMap<>();
        int maxSize = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int size = dfs(grid, i, j, rootToSize);
                    maxSize = Math.max(maxSize, size);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    int size = 1;
                    Set<Integer> visited = new HashSet<>();
                    for (int k = 0; k < 4; k++) {
                        int x = i + dx[k];
                        int y = j + dy[k];

                        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] != 0) {
                            visited.add(findRoot(grid, rootToSize, x, y));
                            size += rootToSize.get(findRoot(grid, rootToSize, x, y));
                        }
                    }

                    maxSize = Math.max(maxSize, size);
                }
            }
        }

        return maxSize;
    }

    private int findRoot(int[][] grid, Map<Integer, Integer> rootToSize, int i, int j) {
        if (grid[i][j] == 0) {
            return -1;
        }

        int root = -1;
        for (int k = 0; k < 4; k++) {
            int x = i + dx[k];
            int y = j + dy[k];

            if (x >= 0 && x < grid.length && y >= 0 && y < grid[0].length) {
                if (grid[x][y] == 1) {
                    root = findRoot(grid, rootToSize, x, y);
                    break;
                }
            }
        }

        if (root != -1) {
            return root;
        } else {
            int newRoot = grid.length * grid[0].length + i;
            rootToSize.put(newRoot, 1);
            grid[i][j] = newRoot;

            for (int k = 0; k < 4; k++) {
                int x = i + dx[k];
                int y = j + dy[k];

                if (x >= 0 && x < grid.length && y >= 0 && y < grid[0].length) {
                    if (grid[x][y] == newRoot) {
                        rootToSize.put(newRoot, rootToSize.get(newRoot) + findRoot(grid, rootToSize, x, y));
                    }
                }
            }

            return newRoot;
        }
    }

    private int dfs(int[][] grid, int i, int j, Map<Integer, Integer> rootToSize) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = -1;

        int size = 1;
        for (int k = 0; k < 4; k++) {
            int x = i + dx[k];
            int y = j + dy[k];

            if (x >= 0 && x < grid.length && y >= 0 && y < grid[0].length) {
                size += dfs(grid, x, y, rootToSize);
            }
        }

        return size;
    }
}

