import java.util.HashMap;
import java.util.Map;

public class Solution {
    private int[][] grid;
    private Map<Integer, Integer> parent;
    private Map<Integer, Integer> size;

    public int largestIsland(int[][] grid) {
        this.grid = grid;
        int n = grid.length;
        if (n == 0) return 0;

        parent = new HashMap<>();
        size = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int root = find(i, j);
                    parent.put(root, root);
                    size.put(root, 1);
                }
            }
        }

        int maxArea = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    int area = 1;
                    int root = find(i, j);
                    int[] directions = { -1, 1, 0, 0 };
                    for (int k = 0; k < 4; k++) {
                        int x = i + directions[k];
                        int y = j + directions[k];
                        if (x >= 0 && x < n && y >= 0 && y < n) {
                            int connectedRoot = find(x, y);
                            if (connectedRoot != root) {
                                area += size.get(connectedRoot);
                                union(root, connectedRoot);
                            }
                        }
                    }
                    maxArea = Math.max(maxArea, area);
                }
            }
        }

        for (int i : parent.keySet()) {
            if (parent.get(i).equals(i)) {
                maxArea = Math.max(maxArea, size.get(i));
            }
        }

        return maxArea;
    }

    private int find(int x, int y) {
        int root = x * grid[0].length + y;
        while (!parent.get(root).equals(root)) {
            parent.put(root, parent.get(parent.get(root)));
            root = parent.get(root);
        }
        return root;
    }

    private void union(int a, int b) {
        if (size.get(a) > size.get(b)) {
            parent.put(b, a);
            size.put(a, size.get(a) + size.get(b));
        } else {
            parent.put(a, b);
            size.put(b, size.get(a) + size.get(b));
        }
    }
}

