import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        Map<Integer, Integer> parent = new HashMap<>();
        Map<Integer, Integer> size = new HashMap<>();

        // Initialize the parent and size maps
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int index = i * n + j;
                    parent.put(index, index);
                    size.put(index, 1);
                }
            }
        }

        // Define a function to find the root of an island
        int find(int x) {
            if (parent.get(x).equals(x)) return x;
            return parent.put(x, find(parent.get(x)));
        }

        // Define a function to union two islands
        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                size.put(rootX, size.get(rootX) + size.get(rootY));
                parent.put(rootY, rootX);
            }
        }

        // Mark the islands with unique colors
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int index = i * n + j;
                    grid[i][j] = find(index);
                }
            }
        }

        // Apply the operation
        int maxIslandSize = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> islandColors = new HashSet<>();
                    int currentColor = grid[i][j];
                    queue.add(currentColor);
                    while (!queue.isEmpty()) {
                        int x = queue.poll();
                        islandColors.add(x);
                        if (x < n * n) {
                            int indexX = x;
                            int indexY = indexX % n;
                            int index = indexX / n + indexY * n;
                            if (grid[indexX / n][indexY] == 1 && grid[index][indexY] != currentColor) {
                                union(index, x);
                                queue.add(grid[indexX / n][indexY]);
                            }
                        } else {
                            int index = x - n * n;
                            if (grid[index][n] == 1 && grid[index + 1][n] != currentColor) {
                                union(index, x);
                                queue.add(grid[index][n]);
                            }
                        }
                    }
                    maxIslandSize = Math.max(maxIslandSize, islandColors.size());
                }
            }
        }

        // Return the maximum island size
        return maxIslandSize;
    }
}

