import java.util.HashMap;
import java.util.Stack;

public class Solution {
    private int[][] directions = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    public int largestIsland(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        HashMap<Integer, Integer> islandMap = new HashMap<>();
        Stack<int[]> stack = new Stack<>();

        int islandId = 2;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    stack.push(new int[] {i, j});
                    islandMap.put(islandId, 0);
                    while (!stack.isEmpty()) {
                        int[] cell = stack.pop();
                        visited[cell[0]][cell[1]] = true;
                        int currVal = grid[cell[0]][cell[1]];
                        islandMap.put(currVal, islandMap.get(currVal) + 1);

                        for (int[] dir : directions) {
                            int x = cell[0] + dir[0];
                            int y = cell[1] + dir[1];

                            if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] == 0 || visited[x][y]) continue;
                            stack.push(new int[] {x, y});
                        }
                    }

                    islandId++;
                }
            }
        }

        int maxSize = 1;

        for (int i = 2; i < islandMap.size(); i++) {
            int currSize = islandMap.get(i);
            if (currSize == 0) continue;
            int candidate = currSize + 1;

            for (int j = 1; j <= i - 1; j++) {
                if (islandMap.containsKey(j)) {
                    int sizeJ = islandMap.get(j);

                    for (int[] dir : directions) {
                        int x = i % cols + dir[0];
                        int y = i / cols + dir[1];

                        while (x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] == j) {
                            sizeJ++;
                            x += dir[0];
                            y += dir[1];
                        }
                    }

                    candidate = Math.max(candidate, currSize + sizeJ);
                }
            }

            maxSize = Math.max(maxSize, candidate);
        }

        return maxSize;
    }
}

