import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<String, Integer> dir = new HashMap<>();
        dir.put("right", 0);
        dir.put("up", 1);
        dir.put("left", 2);
        dir.put("down", 3);

        double x = 0;
        double y = 0;
        int maxDistance = 0;

        for (int command : commands) {
            if (command == -2) {
                String currentDir = getDirection(x, y);
                int newDir = (dir.get(currentDir) + 1) % 4;
                dir.put(currentDir, newDir);
            } else if (command == -1) {
                String currentDir = getDirection(x, y);
                int newDir = (dir.get(currentDir) - 1 + 4) % 4;
                dir.put(currentDir, newDir);
            } else {
                double newX = x;
                double newY = y;

                if (dir.get(getDirection(x, y)) == 0) { // right
                    newX += command;
                } else if (dir.get(getDirection(x, y)) == 1) { // up
                    newY += command;
                } else if (dir.get(getDirection(x, y)) == 2) { // left
                    newX -= command;
                } else if (dir.get(getDirection(x, y)) == 3) { // down
                    newY -= command;
                }

                for (int[] obstacle : obstacles) {
                    if ((newX - obstacle[0]) * (newX - obstacle[0]) + (newY - obstacle[1]) * (newY - obstacle[1]) < 4e-6) {
                        newX = x;
                        newY = y;
                        break;
                    }
                }

                x = newX;
                y = newY;

                maxDistance = Math.max(maxDistance, (int) (x * x + y * y));
            }
        }

        return maxDistance;
    }

    private String getDirection(double x, double y) {
        if (Math.abs(x) < 4e-6 && Math.abs(y - 1) > 4e-6) {
            return "up";
        } else if (Math.abs(x - 1) > 4e-6 && Math.abs(y) < 4e-6) {
            return "right";
        } else if (Math.abs(x) < 4e-6 && Math.abs(y + 1) > 4e-6) {
            return "down";
        } else if (Math.abs(x + 1) > 4e-6 && Math.abs(y) < 4e-6) {
            return "left";
        }
        return "";
    }
}

