import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        int x = 0, y = 0;
        double dir = Math.PI / 2; // initially facing north

        Map<String, Integer> obstacleMap = new HashMap<>();
        for (int[] obstacle : obstacles) {
            String key = obstacle[0] + "," + obstacle[1];
            obstacleMap.put(key, 1);
        }

        int maxDistanceSquared = 0;
        for (int command : commands) {
            if (command == -2) { // turn left
                dir -= Math.PI / 2;
            } else if (command == -1) { // turn right
                dir += Math.PI / 2;
            } else {
                int steps = command;
                for (int i = 0; i < steps; i++) {
                    double newX = x + Math.cos(dir);
                    double newY = y + Math.sin(dir);

                    String key = (int) newX + "," + (int) newY;
                    if (obstacleMap.containsKey(key)) {
                        continue; // obstacle, stay in current location
                    }

                    x = (int) newX;
                    y = (int) newY;

                    double distanceSquared = x * x + y * y;
                    maxDistanceSquared = Math.max(maxDistanceSquared, distanceSquared);
                }
            }
