public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<Integer, Integer> dir = new HashMap<>();
        dir.put(0, 1);
        dir.put(1, 0);
        dir.put(2, -1);
        dir.put(3, 0);

        double x = 0, y = 0;
        int maxDistance = 0;

        for (int command : commands) {
            if (command == -2) {
                // turn left
                int temp = dir.get(3);
                dir.put(3, dir.get(2));
                dir.put(2, temp);

                temp = dir.get(1);
                dir.put(1, dir.get(0));
