                int temp = dir.get(3);
                dir.put(3, dir.get(0));
                dir.put(0, temp);

                temp = dir.get(2);
                dir.put(2, dir.get(1));
                dir.put(1, temp);
            } else if (command > 0) {
                // move forward
                for (int i = 0; i < command; i++) {
                    int newX = x + dir.get(3);
                    int newY = y + dir.get(1);

                    boolean isObstacle = false;
                    for (int[] obstacle : obstacles) {
                        if (newX == obstacle[0] && newY == obstacle[1]) {
                            isObstacle = true;
                            break;
                        }
                    }

                    if (!isObstacle) {
                        x = newX;
