public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<String, Integer> dirs = new HashMap<>();
        dirs.put("r", 0);
        dirs.put("u", 1);
        dirs.put("l", 2);
        dirs.put("d", 3);

        int x = 0;
        int y = 0;
        int dirIndex = 0; // default: right
        int maxDistance = 0;

        for (int command : commands) {
            if (command == -2) { // turn left
                dirIndex = (dirIndex + 1) % 4;
            } else if (command == -1) { // turn right
                dirIndex = (dirIndex - 1 + 4) % 4;
            } else {
                for (int i = 0; i < command; i++) {
                    int newX = x;
                    int newY = y;

                    switch (dirs.getOrDefault("r", dirIndex)) {
                        case 0: // right
                            newX += 1;
                            break;
                        case 1: // up
                            newY += 1;
                            break;
                        case 2: // left
                            newX -= 1;
                            break;
                        default:
                            newY -= 1; // down
                    }

                    if (isObstacle(newX, newY, obstacles)) {
                        x = newX;
                        y = newY;
                    }
                }

                int distance = x * x + y * y;
                maxDistance = Math.max(maxDistance, distance);
            }
        }

        return maxDistance;
    }

    private boolean isObstacle(int x, int y, int[][] obstacles) {
        for (int[] obstacle : obstacles) {
            if (x == obstacle[0] && y == obstacle[1]) {
                return true;
            }
        }
        return false;
    }
