public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] res = new int[n];
        Arrays.fill(res, Integer.MAX_VALUE);

        // Initialize the first element as 0 because it's always closest to itself
        res[0] = 0;

        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == c) {
                res[i] = 0;
            } else {
                // If the current character is not 'c', update its distance as the minimum of its previous distance and 1 plus the distance of the previous character
                res[i] = Math.min(res[i], res[i - 1] + 1);
            }
        }

        int minDist = Integer.MAX_VALUE;
        for (int i = n - 2; i >= 0; i--) {
            if (s.charAt(i) == c) {
                // If the current character is 'c', update its distance as 0
                res[i] = 0;
            } else {
                // Update the distance of the current character as the minimum of its previous distance and 1 plus the minimum distance found so far
                minDist = Math.min(minDist, res[i + 1]);
                res[i] = Math.min(res[i], minDist + 1);
            }
        }

        return res;
    }
}

