public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] res = new int[n];

        // Initialize the distance for the first character
        int lastOccur = -n;

        // Iterate over the string from left to right
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                lastOccur = i;
            }

            // Update res with the minimum distance of two: 
            // the last occurred character and the one before current position
            res[i] = Math.min(Math.abs(lastOccur - i), i - lastOccur);
        }

        // Initialize the distance for the second time, from right to left
        lastOccur = n;

        // Iterate over the string from right to left
        for (int i = n-1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                lastOccur = i;
            }

            // Update res with the minimum distance of two: 
            // the last occurred character and the one before current position
            res[i] = Math.min(res[i], Math.abs(lastOccur - i), i - lastOccur);
        }

        return res;
    }
}

