import java.util.Arrays;

public class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        long MOD = 1000000007;
        int m = group.length;
        int[][] dp = new int[m + 1][minProfit + 1];

        for (int i = 0; i <= m; i++) {
            Arrays.fill(dp[i], -1);
        }

        return helper(0, n, minProfit, group, profit, dp, MOD);
    }

    private int helper(int idx, int remainingMembers, int currentProfit, int[] group, int[] profit, int[][] dp, long MOD) {
        if (idx == group.length || currentProfit < 0) {
            return 0;
        }

        if (dp[idx][currentProfit] != -1) {
            return dp[idx][currentProfit];
        }

        int include = 0;
        if (group[idx] <= remainingMembers) {
            include = helper(idx + 1, remainingMembers - group[idx], Math.min(currentProfit + profit[idx], minProfit), group, profit, dp, MOD);
        }

        int exclude = helper(idx + 1, remainingMembers, currentProfit, group, profit, dp, MOD);

        return dp[idx][currentProfit] = (include + exclude) % MOD;
    }
}

