    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        long MOD = 1000000007;
        int N = group.length;
        Integer[][] dp = new Integer[N + 1][minProfit + 1];

        for (int i = 0; i <= N; ++i) {
            Arrays.fill(dp[i], -1);
        }

        return helper(0, n, minProfit, group, profit, N, dp, MOD);
    }

    private int helper(int idx, int n, int minProfit, int[] group, int[] profit, int N, Integer[][] dp, long MOD) {
        if (idx == N || n < 0)
            return (n == 0 && minProfit >= 0) ? 1 : 0;

        if (dp[idx][minProfit] != null)
            return dp[idx][minProfit];

        int ways = helper(idx + 1, n - group[idx], Math.max(0, minProfit - profit[idx]), group, profit, N, dp, MOD);

        ways += helper(idx + 1, n, Math.max(0, minProfit - profit[idx]), group, profit, N, dp, MOD);

        return dp[idx][minProfit] = (int) ((ways % MOD));
    }
}

