import java.util.Arrays;

public class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int MOD = (int)1e9 + 7;
        int m = group.length;
        long[][] dp = new long[m+1][minProfit+1];
        for (long[] row : dp) Arrays.fill(row, -1);

        return (int)solve(0, n, minProfit, dp, group, profit, MOD);
    }

    private int solve(int i, int membersLeft, int profitLeft, long[][] dp, int[] group, int[] profit, int MOD){
        if (i == group.length) {
            return profitLeft >= 0 ? 1 : 0;
        }

        if (dp[i][profitLeft] != -1) {
            return (int) dp[i][profitLeft];
        }

        long ways = 0;
        int nGroupRequired = Math.min(membersLeft, group[i]);
        for(int j = 0; j <= nGroupRequired; j++){
            if(profitLeft + profit[i] >= 0){
                ways += solve(i+1, membersLeft - j, profitLeft + profit[i], dp, group, profit, MOD);
                ways %= MOD;
            }
            else{
                break;
            }
        }

        dp[i][profitLeft] = ways;
        return (int)ways;
    }
}

