public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int m = group.length;
        Integer[][] dp = new Integer[m][n + 1];

        return dfs(0, n, minProfit, group, profit, dp);
    }

    private int dfs(int i, int totalMembers, int currentProfit, int[] group, int[] profit, Integer[][] dp) {
        if (i == group.length || totalMembers < 0) {
            return currentProfit >= minProfit ? 1 : 0;
        }

        if (dp[i][totalMembers] != null) {
            return dp[i][totalMembers];
        }

        int schemesWithoutIncludingCurrent = dfs(i + 1, totalMembers, Math.max(currentProfit, profit[i]), group, profit, dp);
        int includingCurrentCrime = 0;
        if (group[i] <= totalMembers) {
            includingCurrentCrime = dfs(i + 1, totalMembers - group[i], Math.min(minProfit, currentProfit + profit[i]), group, profit, dp);
        }

        return dp[i][totalMembers] = (schemesWithoutIncludingCurrent + includingCurrentCrime) % MOD;
    }
}

