import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    public String maskPII(String s) {
        // Remove special characters from email address or phone number
        if (s.contains("@")) {  // Email Address
            Pattern pattern = Pattern.compile("[^a-zA-Z0-9@]");
            Matcher matcher = pattern.matcher(s);
            String maskedEmail = matcher.replaceAll("");

            // Mask the name and domain with lowercase letters and asterisks
            int indexAt = maskedEmail.indexOf('@');
            String name = maskedEmail.substring(0, indexAt).toLowerCase();
            StringBuilder sb = new StringBuilder(name);
            for (int i = 1; i < name.length() - 1; ++i) {
                sb.setCharAt(i, '*');
            }
            String domain = maskedEmail.substring(indexAt + 1).toLowerCase();

            // Return the masked email address
            return sb.toString() + "@" + domain;
        } else {  // Phone Number
            Pattern pattern = Pattern.compile("[^0-9+\\-\\(\\)]");
            Matcher matcher = pattern.matcher(s);
            String maskedPhone = matcher.replaceAll("");

            // Remove country code if it has more than 3 digits
            int countryCodeLength = maskedPhone.length() - 10;
            if (countryCodeLength > 3) {
                maskedPhone = maskedPhone.substring(countryCodeLength + 1);
            }

            // Mask the phone number with asterisks and hyphens
            StringBuilder sb = new StringBuilder(maskedPhone);
            int length = sb.length();
            if (length <= 10) {
                for (int i = 0; i < 5 - length; ++i) {
                    sb.insert(0, '-');
                }
            } else {
                for (int i = 4; i < 7; ++i) {
                    sb.setCharAt(i, '*');
                }
            }

            // Return the masked phone number
            return sb.toString();
        }
    }
}

