public class Solution {
    public String maskPII(String s) {
        if (s.contains("@")) {
            // email address
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c == '@') {
                    sb.append(c);
                } else if (i != 0 && i != s.length() - 1) {
                    // middle letters of the name
                    sb.append("*");
                } else {
                    sb.append(Character.toLowerCase(c));
                }
            }
            return sb.toString().toLowerCase();
        } else {
            // phone number
            String[] parts = s.split("[^0-9]+");
            StringBuilder sb = new StringBuilder();
            for (String part : parts) {
                sb.append(part);
            }
            int countryCodeLength = s.length() - 10;
            if (countryCodeLength >= 4) {
                return "+-" + repeat("-", countryCodeLength - 3) + "XXXX";
            } else if (countryCodeLength == 3) {
                return "+--*" + repeat("-", countryCodeLength - 2) + "XXXX";
            } else if (countryCodeLength == 2) {
                return "+--*-XXXX";
            } else {
                return "-*-XXXX";
            }
        }
    }

    private String repeat(String s, int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(s);
        }
        return sb.toString();
    }
}

