public class Solution {
    public String maskPII(String s) {
        StringBuilder email = new StringBuilder();
        boolean start = true;

        // Email Masking
        for (char c : s.toCharArray()) {
            if (c == '@') {
                start = false;
                continue;
            }
            if (start)
                email.append(Character.isLowerCase(c) ? c : Character.toLowerCase(c));
            else {
                if (!Character.isLetterOrDigit(c)) {
                    break;
                } else
                    email.append(c);
            }
        }

        // Replace '@' with ''
        email.insert(email.indexOf('@'), '');

        // Mask the remaining part of the email (domain)
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i < email.length() - 1; i++) {
            if (Character.isLetterOrDigit(email.charAt(i))) {
                sb.append('*');
            } else
                sb.append(email.charAt(i));
        }
        sb.insert(0, email.charAt(0));
        sb.append(email.charAt(email.length() - 1));

        // Phone Number Masking
        String[] parts = s.split("[^0-9]+");

        if (parts[0].length() > 3) {
            StringBuilder result = new StringBuilder();
            for (int i = 4; i < parts[0].length(); i++) {
                result.append(parts[0].charAt(i));
            }
            return "+---" + result.toString().substring(0, 4);
        } else {
            StringBuilder result = new StringBuilder();
            for (int i = 2; i < parts[0].length(); i++) {
                result.append(parts[0].charAt(i));
            }
            return "+--*" + result.toString().substring(0, 4);
        }

        // Masked Email
        return sb.toString().toLowerCase() + "@" + email.toString().toLowerCase();
    }
}

