        int idxAt = -1, idxDot = -1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '@') {
                idxAt = i;
                isEmail = true;
            }
            if (i > 0 && s.charAt(i) == '.' && idxAt != -1) {
                idxDot = i;
            }
        }

        // Phone number
        boolean isPhone = !isEmail;

        String result = "";
        if (isEmail) {
            String name = s.substring(0, idxAt);
            String domain = s.substring(idxAt + 1);

            StringBuilder sb = new StringBuilder();
            for (char c : name.toCharArray()) {
                if (Character.isUpperCase(c)) {
                    sb.append(Character.toLowerCase(c));
                } else {
                    sb.append('*');
                }
            }

            int startDot = idxDot == -1 ? domain.length() : idxDot;
            result += sb.toString().substring(0, 1).toLowerCase()
                    + sb.toString().substring(1, sb.toString().length() - 1)
                            .replaceFirst(".", "*")
                    + sb.toString().substring(sb.toString().length() - 1).toLowerCase();

            if (idxDot != -1) {
                result += "@" + domain.substring(startDot);
            }

        } else if (isPhone) {
            StringBuilder sb = new StringBuilder();
            for (char c : s.toCharArray()) {
                if (Character.isDigit(c)) {
                    sb.append(c);
                }
            }

            String countryCode = sb.toString().substring(0, Math.min(sb.length(), 4));
            int countryCodeLen = countryCode.length();

            result += getMask(countryCodeLen) + sb.toString().substring(Math.max(sb.length() - 4, 0));

        } else {
            throw new RuntimeException("Invalid input.");
        }

        return result;
    }

    private String getMask(int n) {
        switch (n) {
            case 1:
                return "+-";
            case 2:
                return "+-*";
            case 3:
            default:
                return "+---";
        }
    }
}

