public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDistance = 0, currentDistance = 0;

        // Find the first seat with a person sitting in it from left to right.
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                maxDistance = Math.max(maxDistance, currentDistance);
                currentDistance = 0;
            } else {
                currentDistance++;
            }
        }

        // Find the last seat with a person sitting in it from right to left.
        for (int i = n - 1; i >= 0; i--) {
            if (seats[i] == 1) {
                maxDistance = Math.max(maxDistance, currentDistance);
                currentDistance = 0;
            } else {
                currentDistance++;
            }
        }

        // Find the maximum distance between two people sitting in adjacent seats.
        for (int i = 0; i < n - 1; i++) {
            if (seats[i] == 0 && seats[i + 1] == 0) {
                maxDistance = Math.max(maxDistance, (i + 1) / 2);
            }
        }

        return maxDistance;
    }
}

