public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDistance = 0, currentMax = 0, prevZeroIndex = -1;

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (prevZeroIndex != -1) {
                    currentMax = Math.max(currentMax, (i - prevZeroIndex) / 2);
                }
                maxDistance = Math.max(maxDistance, currentMax);
                prevZeroIndex = i;
                currentMax = 0;
            }
        }

        // Handle the last sequence of zeros
        if (prevZeroIndex != -1 && n - 1 - prevZeroIndex > currentMax) {
            maxDistance = Math.max(maxDistance, (n - 1 - prevZeroIndex));
        }

        return maxDistance;
    }
}

