    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDistance = 0, firstZeroIndex = -1, lastOneIndex = -1;

        for (int i = 0; i < n; ++i) {
            if (seats[i] == 1 && firstZeroIndex == -1) {
                firstZeroIndex = i;
                maxDistance = Math.max(maxDistance, i);
            } else if (seats[i] == 0 && lastOneIndex != -1) {
                int distance = (i - lastOneIndex) / 2;
                maxDistance = Math.max(maxDistance, distance);
            }

            if (seats[i] == 1)
                lastOneIndex = i;
        }

        return n - firstZeroIndex > n - lastOneIndex ? n - lastOneIndex : n - firstZeroIndex;
    }
