public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDist = 0, prevPerson = -1, currDist;

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) { // person found
                if (prevPerson != -1) {
                    maxDist = Math.max(maxDist, (i - prevPerson) / 2);
                }
                maxDist = Math.max(maxDist, i); // update max dist from start of row
                prevPerson = i;
            }
        }

        currDist = n - 1 - prevPerson; // calculate distance to last person
        return Math.max(currDist, maxDist); // return maximum distance found
    }
