public class Solution {
    public double soupServings(int n) {
        if (n >= 5000) return 1;

        int a = (int)Math.ceil((double)n / 25);
        int b = (int)Math.ceil((double)n / 25);

        double[][] dp = new double[a + 1][b + 1];

        for (int i = 1; i <= a; i++) {
            for (int j = 1; j <= b; j++) {
                if (i == j) {
                    dp[i][j] = 0.25;
                } else if (i > j) {
                    double max = Math.min(i - 1, n / 100);
                    double min = Math.max(0, i - 4);

                    for (int k = min; k <= max; k++) {
                        dp[i][j] += 0.25 * (dp[k][j + 3] + dp[Math.min(i - 1, n / 100)][j]);
                    }
                } else {
                    double max = Math.min(j - 1, n / 100);
                    double min = Math.max(0, j - 4);

                    for (int k = min; k <= max; k++) {
                        dp[i][j] += 0.25 * (dp[i + 3][k] + dp[i][Math.min(j - 1, n / 100)]);
                    }
                }
            }
        }

        return dp[a][b];
    }
}

