                if (i - 4 >= 0 && j - 3 >= 0) dp[i][j] += dp[i-4][j-3]/4;
                if (i - 3 >= 0 && j - 2 >= 0) dp[i][j] += dp[i-3][j-2]/4;
                if (i - 2 >= 0 && j - 1 >= 0) dp[i][j] += dp[i-2][j-1]/4;
                if (i - 1 >= 0) dp[i][j] += dp[i-1][j]/4;
            }
        }

        return dp[a][b] * 0.5 + (dp[a][b] < 1 ? 0 : 1);
    }
