public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        // Check if the length of the hand array is a multiple of groupSize
        if (hand.length % groupSize != 0) {
            return false;
        }

        // Sort the hand array in ascending order
        Arrays.sort(hand);

        // Create a HashMap to store the frequency of each card value
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : hand) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        // Iterate over the sorted array and try to form groups of consecutive cards
        for (int i = 0; i < hand.length - groupSize + 1; i++) {
            int minCard = hand[i];
            boolean formedGroup = true;
            for (int j = 0; j < groupSize; j++) {
                if (!freqMap.containsKey(minCard) || freqMap.get(minCard) == 0) {
                    formedGroup = false;
                    break;
                }
                freqMap.put(minCard, freqMap.get(minCard) - 1);
                minCard++;
            }
            if (formedGroup) {
                for (int j = i; j < i + groupSize; j++) {
                    freqMap.put(hand[j], freqMap.get(hand[j]) - 1);
                }
            } else {
                return false;
            }
        }

        // If all groups are formed, return true
        return true;
    }
}

