public class Solution {
    public double new21Game(int n, int k, int w) {
        // Handle edge cases
        if (k == 0 || k > n) return 1.0;

        // Initialize arrays for dp and prefix sum
        double[] dp = new double[n + 1];
        double[] prefixSum = new double[n + 2];

        // Base case: Alice gets exactly i points with probability 1
        dp[0] = 1.0;

        // Compute prefix sum array
        for (int i = 1; i <= n; ++i) {
            if (k > i) { 
                // If k is large, the probability of getting more than k is negligible
                dp[i] += 1.0 / w;
            } else {
                dp[i] += prefixSum[Math.min(k - 1, i - 1)] * (1.0 / w);
            }
            prefixSum[i + 1] = prefixSum[i] + dp[i];
        }

        // Return the probability of getting n or fewer points
        return prefixSum[n + 1] - prefixSum[Math.max(0, n - w)];
    }
}

