        double[] dp = new double[n + 2];
        for (int i = Math.max(k - 1, 0); i <= n; i++) dp[i] = 1.0 / w;

        for (int i = k - 1; i >= 0; i--) {
            dp[i] += dp[i + 1];
            if (i > 0) dp[i] -= dp[i + 1];
        }

        return dp[0];
