public class Solution {
    public int minimumLengthEncoding(String[] words) {
        Map<String, Boolean> wordMap = new HashMap<>();

        // Create a Trie data structure to store the words
        for (String word : words) {
            String revWord = new StringBuilder(word).reverse().toString();
            wordMap.put(revWord, true);
        }

        int length = 0;
        for (Map.Entry<String, Boolean> entry : wordMap.entrySet()) {
            if (!entry.getValue()) continue;

            // If the word is a prefix of another word, skip it
            boolean isPrefix = false;
            for (String otherWord : wordMap.keySet()) {
                if (otherWord.startsWith(entry.getKey())) {
                    isPrefix = true;
                    break;
                }
            }

            if (!isPrefix) length += entry.getKey().length() + 1;
        }

        return length;
    }
}

