import java.util.*;

public class Solution {
    public int minimumLengthEncoding(String[] words) {
        TrieNode root = new TrieNode();

        for (String word : words) {
            insert(root, word);
        }

        String result = "";
        traverse(root, result);

        return result.length();
    }

    private void insert(TrieNode node, String word) {
        int index = 0;
        while (index < word.length()) {
            char c = word.charAt(index++);

            if (!node.children.containsKey(c)) {
                node.children.put(c, new TrieNode());
            }

            node = node.children.get(c);
        }

        node.isWord = true;
    }

    private void traverse(TrieNode node, String result) {
        for (TrieNode child : node.children.values()) {
            if (child.isWord && !result.endsWith("#")) {
                traverse(child, "#");
            } else {
                traverse(child, "");
            }
        }

        if (!node.isWord || result.length() > 0) {
            return;
        }

        result = "#" + ((String) node.children.keySet().toArray()[0]) + result;
    }

    private static class TrieNode {
        boolean isWord = false;
        Map<Character, TrieNode> children = new HashMap<>();
    }
}

