        int n = arr.length;
        if (n < 3) return 0;

        int res = 0;
        for (int i = 1; i < n - 1; i++) {
            boolean increasing = arr[i] > arr[i - 1];
            boolean decreasing = arr[i] > arr[i + 1];

            if (increasing && decreasing) {
                int j = i;
                while (j > 0 && arr[j] > arr[j - 1]) j--;
                while (i < n - 1 && arr[i] > arr[i + 1]) i++;

                res = Math.max(res, i - j + 1);
            }
        }

        return res;
    }
