public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        s = s.substring(1, s.length() - 1);
        List<String> res = new ArrayList<>();
        for (int i = 1; i < s.length(); i++) {
            String left = s.substring(0, i), right = s.substring(i);
            if (!isValid(left) || !isValid(right)) continue;
            for (String l : split(left)) {
                for (String r : split(right)) {
                    res.add(l + ", " + r);
                }
            }
        }
        return res;
    }

    private boolean isValid(String num) {
        int i = 0, j = num.length() - 1;
        while (i < j && num.charAt(i) == '0') i++;
        if (i >= j) return false;
        if (num.charAt(i) == '.') {
            while (++i < j && num.charAt(i) != '.') return false;
            while (++i <= j && num.charAt(i) == '0') i--;
            return true;
        }
        while (i < j && num.charAt(j) == '0') j--;
        return true;
    }

    private List<String> split(String s) {
        if (!s.contains(".")) return List.of(s);
        int i = 0, j = s.indexOf('.');
        String left = s.substring(0, j), right = s.substring(j + 1);
        if (left.length() == 1 || !isValid(left)) return List.of();
        if (right.length() == 1 || !isValid(right)) return List.of();
        return List.of(left + "." + right);
    }
}

