        int n = s.length();
        List<String> res = new ArrayList<>();

        for (int i = 1; i < n - 1; ++i) {
            String left = s.substring(0, i);
            String right = s.substring(i);

            for (String l : getValid(left)) {
                for (String r : getValid(right)) {
                    res.add("(" + l + ", " + r + ")");
                }
            }
        }

        return res;
    }

    private List<String> getValid(String s) {
        if (!s.contains(".")) {
            return split(s);
        }

        int dot = s.indexOf('.');
        String left = s.substring(0, dot), right = s.substring(dot + 1);

        if (left.length() == 1 && !Character.isDigit(left.charAt(0))) {
            return new ArrayList<>();
        }
        if (right.length() == 1 && !Character.isDigit(right.charAt(0))) {
            return new ArrayList<>();
        }

        List<String> res = new ArrayList<>();

        for (String l : split(left)) {
            for (String r : split(right)) {
                res.add(l + "." + r);
            }
        }

        return res;
    }

    private List<String> split(String s) {
        if (!s.contains("0") && !Character.isDigit(s.charAt(0))) {
            return new ArrayList<>();
        }
        if (s.length() == 1 || Character.isDigit(s.charAt(0)) && Character.isDigit(s.charAt(s.length() - 1))) {
            List<String> res = new ArrayList<>();
            res.add(s);
            return res;
        }

        List<String> res = new ArrayList<>();

        for (int i = 1; i < s.length(); ++i) {
            String left = s.substring(0, i), right = s.substring(i);

            if (!Character.isDigit(left.charAt(left.length() - 1)) || !Character.isDigit(right.charAt(0))) {
                continue;
            }

            res.add(left + right);
        }

        return res;
    }
}

