public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        String substring = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();

        // Remove the first and last parenthesis
        for (int i = 1; i < substring.length(); i++) {
            if (substring.charAt(i) == '.') continue;

            String leftStr = substring.substring(0, i);
            String rightStr = substring.substring(i);

            List<String> leftResult = getValidCoordinates(leftStr);
            List<String> rightResult = getValidCoordinates(rightStr);

            for (String left : leftResult) {
                for (String right : rightResult) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }

        return result;
    }

    private List<String> getValidCoordinates(String str) {
        if (!isValidCoordinate(str)) return new ArrayList<>();

        List<String> result = new ArrayList<>();

        for (int i = 1; i < str.length(); i++) {
            String leftStr = str.substring(0, i);
            String rightStr = str.substring(i);

            if (leftStr.charAt(leftStr.length() - 1) == '0' && leftStr.length() > 1) continue;
            if (rightStr.charAt(0) == '0') continue;

            result.add(leftStr + "." + rightStr);
        }

        return result;
    }

    private boolean isValidCoordinate(String str) {
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (!Character.isDigit(c)) return false;
        }

        return true;
    }
}

