import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        char[] str = s.toCharArray();
        List<String> result = new ArrayList<>();

        // Iterate over all possible split positions of string s into two parts
        for (int i=2; i<s.length()-1; i++) {
            String leftStr = new String(str, 1, i-1);
            String rightStr = new String(str, i+1, s.length() - i - 1);

            // Check if the left part can be a valid number
            List<String> leftValidNumbers = getValidNumbers(leftStr);

            // Check if the right part can be a valid number
            List<String> rightValidNumbers = getValidNumbers(rightStr);

            // Iterate over all possible combinations of valid numbers for left and right parts
            for (String leftNum: leftValidNumbers) {
                for (String rightNum : rightValidNumbers) {
                    // Append the original format with one space between the number parts
                    result.add(leftNum + " " + rightNum);
                }
            }
        }

        return result;
    }

    private List<String> getValidNumbers(String str) {
        int sign = 1;
        if (str.charAt(0) == '-') sign = -1;

        List<String> validNumbers = new ArrayList<>();
        StringBuilder curNum = new StringBuilder();

        for (int i=0; i<str.length(); i++) {
            char c = str.charAt(i);

            // If the character is a digit, append it to current number
            if (Character.isDigit(c)) {
                curNum.append(c);

                // Check if a decimal point can be inserted between this and previous digits
                if (i > 0 && i < str.length() - 1) {
                    validNumbers.add(curNum.toString());
                    curNum.setLength(0);
                    curNum.append('.');
                }
            } 
            // If the character is a decimal point, append it to current number
            else if (c == '.') {
                if (curNum.length() > 0) {
                    validNumbers.add(curNum.toString());
                    curNum.append(c);
                }
            } 
            // If the character is a minus sign, update the sign and remove leading zeros from previous number
            else if (c == '-' && i==0) {
                sign = -1;
                curNum.delete(0, 1);
                continue;
            } 
            // If a non-digit character appears, break the loop
            else {
                validNumbers.add(curNum.toString());
                return validNumbers;
            }
        }

        // Append the last number to the list of valid numbers
        validNumbers.add(curNum.toString());

        return validNumbers;
    }
}

