import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize a visited array to keep track of visited cells
        boolean[][] visited = new boolean[m][n];

        // Initialize the result array
        int[] res = new int[hits.length];

        // Function to perform DFS and mark all connected bricks as visited
        void dfs(int i, int j) {
            if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0 || visited[i][j]) return;

            visited[i][j] = true;
            dfs(i - 1, j);
            dfs(i + 1, j);
            dfs(i, j - 1);
            dfs(i, j + 1);
        }

        // Function to calculate the number of bricks that will fall after an erasure
        void countFallingBricks(int i, int j) {
            if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) return;

            int count = 1;
            // Check all four adjacent cells for bricks that will fall
            if (visited[i - 1][j]) {
                dfs(i, j);
                count += countFallingBricks(i + 1, j);
                count += countFallingBricks(i, j + 1);
                count += countFallingBricks(i, j - 1);
            }

            return count;
        }

        // Iterate over the grid and perform DFS to mark all connected bricks as visited
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) dfs(i, j);
            }
        }

        // Iterate over the hits array and calculate the number of bricks that will fall after each erasure
        for (int i = 0; i < hits.length; i++) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (grid[x][y] == 0) continue;

            grid[x][y] = 0;

            // Check all four adjacent cells for bricks that will fall
            if (x > 0 && visited[x - 1][y]) {
                res[i] += countFallingBricks(x, y);
            }
        }

        return res;
    }
}

