import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        List<int[]> bricks = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    bricks.add(new int[]{i, j});
                }
            }
        }

        for (int[] hit : hits) {
            int x = hit[0];
            int y = hit[1];
            if (grid[x][y] == 1) {
                grid[x][y] = 0;
                removeBricks(bricks, visited, m, n, x, y);
            }
        }

        int[] result = new int[hits.length];
        for (int i = hits.length - 1; i >= 0; i--) {
            int x = hits[i][0];
            int y = hits[i][1];
            if (grid[x][y] == 1) {
                grid[x][y] = 0;
                addBricks(bricks, visited, m, n, x, y);
            }
            result[hits.length - i - 1] = bricks.size() - getConnectedCells(visited, m, n);
        }

        return result;
    }

    private void removeBricks(List<int[]> bricks, boolean[][] visited, int m, int n, int x, int y) {
        if (x == 0 || grid[x][y] != 1) {
            return;
        }
        grid[x][y] = 0;
        for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                removeBricks(bricks, visited, m, n, nx, ny);
            }
        }
    }

    private void addBricks(List<int[]> bricks, boolean[][] visited, int m, int n, int x, int y) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] != 1) {
            return;
        }
        for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                addBricks(bricks, visited, m, n, nx, ny);
            }
        }
        bricks.add(new int[]{x, y});
    }

    private int getConnectedCells(boolean[][] visited, int m, int n) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    dfs(visited, m, n, i, j);
                    count++;
                }
            }
        }
        return count;
    }

    private void dfs(boolean[][] visited, int m, int n, int x, int y) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] != 1 || visited[x][y]) {
            return;
        }
        visited[x][y] = true;
        for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            dfs(visited, m, n, nx, ny);
        }
    }
}

