public class Solution {
    int[] dx = {1, 0, -1, 0};
    int[] dy = {0, 1, 0, -1};

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;

        // Create a map to store the bricks' positions
        Map<String, Integer> posMap = new HashMap<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    String key = i + "," + j;
                    posMap.put(key, 1);
                }
            }
        }

        // Initialize the result array
        int[] res = new int[hits.length];

        // Iterate over the hits and perform DFS for each hit
        for (int i = 0; i < hits.length; i++) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (!posMap.containsKey(x + "," + y)) continue;

            int count = dfs(posMap, grid, m, n, x, y);

            res[i] = count;
        }

        return res;
    }

    // DFS function to count the number of bricks that will fall
    private int dfs(Map<String, Integer> posMap, int[][] grid, int m, int n, int x, int y) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] != 1) return 0;

        String key = x + "," + y;
        posMap.remove(key);

        // Perform DFS for adjacent cells
        int count = 1;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (posMap.containsKey(nx + "," + ny)) {
                count += dfs(posMap, grid, m, n, nx, ny);
            }
        }

        return count;
    }
}

