public class Solution {
    private int m, n;
    private int[][] grid;
    private Set<String> hitPoints = new HashSet<>();
    private Map<String, Integer> parentMap = new HashMap<>();

    public int[] hitBricks(int[][] grid, int[][] hits) {
        this.grid = grid;
        this.m = grid.length;
        this.n = grid[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(i, j);
                }
            }
        }

        int[] result = new int[hits.length];
        for (int i = 0; i < hits.length; i++) {
            String hitPoint = hits[i][0] + "," + hits[i][1];
            if (!hitPoints.contains(hitPoint)) continue;
            hitPoints.remove(hitPoint);
            result[i] = getFallenBricks(hits[i]);
        }

        return result;
    }

    private void dfs(int i, int j) {
        String point = i + "," + j;

        if (i == 0 || grid[i][j] != 1) {
            parentMap.put(point, null);
            hitPoints.add(point);
            return;
        }

        grid[i][j] = 2; // mark as visited
        List<String> children = new ArrayList<>();

        for (int x : new int[] {-1, 0, 1}) {
            for (int y : new int[] {-1, 0, 1}) {
                if (x == 0 && y == 0) continue;
                int newX = i + x;
                int newY = j + y;

                if (newX < 0 || newX >= m || newY < 0 || newY >= n) continue;
                String childPoint = newX + "," + newY;
                if (grid[newX][newY] == 1 && !parentMap.containsKey(childPoint)) {
                    children.add(dfs(newX, newY));
                }
            }
        }

        parentMap.put(point, children.size());
    }

    private int getFallenBricks(int[] hit) {
        String hitPoint = hit[0] + "," + hit[1];
        if (!hitPoints.contains(hitPoint)) return 0;

        Set<String> fallenPoints = new HashSet<>();
        dfsForFallenBricks(hit[0], hit[1], fallenPoints);
        int count = 0;
        for (String point : fallenPoints) {
            String[] p = point.split(",");
            if (grid[Integer.parseInt(p[0])][Integer.parseInt(p[1])] == 2) {
                count++;
            }
        }

        return count;
    }

    private void dfsForFallenBricks(int i, int j, Set<String> fallenPoints) {
        String point = i + "," + j;

        if (point.equals(hitPoints.iterator().next())) {
            hitPoints.remove(point);
            fallenPoints.add(point);
            return;
        }

        grid[i][j] = 2; // mark as visited
        List<String> children = new ArrayList<>();
        for (int x : new int[] {-1, 0, 1}) {
            for (int y : new int[] {-1, 0, 1}) {
                if (x == 0 && y == 0) continue;
                int newX = i + x;
                int newY = j + y;

                if (newX < 0 || newX >= m || newY < 0 || newY >= n) continue;
                String childPoint = newX + "," + newY;
                if (grid[newX][newY] == 1 && !parentMap.containsKey(childPoint)) {
                    children.add(dfsForFallenBricks(newX, newY, fallenPoints));
                }
            }
        }

        parentMap.put(point, children.size());
    }
}

