import java.util.*;

public class Solution {
    private int[] dx = {0, 0, -1, 1};
    private int[] dy = {-1, 1, 0, 0};

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    DFS(grid, i, j);
                    count++;
                }
            }
        }

        int[] result = new int[hits.length];
        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];

            grid[row][col] = 2;
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            boolean[][] visited = new boolean[m][n];

            for (int j = 0; j < m; j++) {
                if (!visited[j][0]) {
                    DFS(grid, j, 0, false, pq, visited);
                }
            }

            int res = 0;
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                if (cur[1] == -1) continue;

                grid[cur[0]][cur[1]] = 2;
                res++;

                for (int k = 0; k < 4; k++) {
                    int newX = cur[0] + dx[k];
                    int newY = cur[1] + dy[k];

                    if (newX >= 0 && newX < m && newY >= 0 && newY < n && grid[newX][newY] == 1) {
                        DFS(grid, newX, newY);
                        pq.offer(new int[] {newX, newY});
                    }
                }
            }

            result[i] = res;
        }

        return result;
    }

    private void DFS(int[][] grid, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) {
            return;
        }
        grid[i][j] = -1;

        for (int k = 0; k < 4; k++) {
            int newX = i + dx[k];
            int newY = j + dy[k];

            DFS(grid, newX, newY);
        }
    }

    private void DFS(int[][] grid, int i, int j, boolean isFromTop, PriorityQueue<int[]> pq, boolean[][] visited) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1 || visited[i][j]) {
            return;
        }

        if (!isFromTop && !pq.isEmpty() && pq.peek()[1] <= Math.min(j, pq.peek()[1])) {
            return;
        }

        visited[i][j] = true;

        for (int k = 0; k < 4; k++) {
            int newX = i + dx[k];
            int newY = j + dy[k];

            DFS(grid, newX, newY, isFromTop || pq.isEmpty(), pq, visited);
        }

        if (!pq.isEmpty() && pq.peek()[1] == j) {
            pq.offer(new int[] {i, -1});
        } else {
            pq.offer(new int[] {i, j});
        }
    }
