public class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];

        // Calculate prefix sum array
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        int ans = Integer.MAX_VALUE;
        Deque<Integer> deque = new ArrayDeque<>();

        for (int i = 0; i <= n; i++) {
            // Remove elements from the back of the deque that are greater than the current prefix sum
            while (!deque.isEmpty() && prefixSum[i] >= prefixSum[deque.peekLast()]) {
                deque.pollLast();
            }

            // Add the current index to the front of the deque
            deque.offerFirst(i);

            // If the difference between the current prefix sum and the k-th element in the deque is less than or equal to k, update ans
            while (!deque.isEmpty() && prefixSum[i] - prefixSum[deque.peekFirst()] >= k) {
                ans = Math.min(ans, i - deque.pollFirst());
            }
        }

        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

