public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        List<int[]> result = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];
        int count = 1;
        int currX = x - 1;
        int currY = y - 1;

        while (count != rows * cols) {

            // Move right
            for(int i = currX + 1; i <= Math.min(x + 1, currX + cols); i++) {
                if (!visited[currY][i]) {
                    result.add(new int[] {currY + 1, i});
                    visited[currY][i] = true;
                    count++;
                }
            }

            // Move down
            for(int i = currY + 1; i <= Math.min(y + 1, currY + rows); i++) {
                if (!visited[i][x]) {
                    result.add(new int[] {i, x});
                    visited[i][x] = true;
                    count++;
                }
            }

            // Move left
            for(int i = x - 1; i >= Math.max(x - cols, currX); i--) {
                if (!visited[y][i]) {
                    result.add(new int[] {y, i});
                    visited[y][i] = true;
                    count++;
                }
            }

            // Move up
            for(int i = y - 1; i >= Math.max(y - rows, currY); i--) {
                if (!visited[i][currX]) {
                    result.add(new int[] {i, currX});
                    visited[i][currX] = true;
                    count++;
                }
