public class Solution {
    public boolean backspaceCompare(String s, String t) {
        // Stack to store characters and '#' symbol for backspace operation
        java.util.Stack<Character> stack1 = new java.util.Stack<>();
        java.util.Stack<Character> stack2 = new java.util.Stack<>();

        // Process string 's'
        processString(s, stack1);

        // Process string 't'
        processString(t, stack2);

        // Compare the stacks
        return compareStacks(stack1, stack2);
    }

    private void processString(String str, java.util.Stack<Character> stack) {
        for (char c : str.toCharArray()) {
            if (c == '#') {
                // Remove last character from stack
                if (!stack.isEmpty())
                    stack.pop();
            } else {
                // Push character onto the stack
                stack.push(c);
            }
        }
    }

    private boolean compareStacks(java.util.Stack<Character> stack1, java.util.Stack<Character> stack2) {
        while (true) {
            char c1 = stack1.isEmpty() ? '\0' : stack1.peek();
            char c2 = stack2.isEmpty() ? '\0' : stack2.peek();

            if (c1 == '\0' && c2 == '\0')
                return true;
            else if (c1 != c2)
                return false;

            // Remove characters from stacks
            stack1.pop();
            stack2.pop();
        }
    }
}

