public class Solution {
    public String pushDominoes(String dominoes) {
        StringBuilder sb = new StringBuilder(dominoes);

        int n = sb.length();

        // first pass: detect blocks of R or L
        for (int i = 0; i < n;) {
            char currChar = sb.charAt(i);
            if (currChar == 'R') {

                int j = i + 1;
                while (j < n && sb.charAt(j) == 'R') {
                    sb.setCharAt(j, '.');
                    j++;
                }

                // now we have a block of R, so push all the dominoes to the right
                for (int k = i; k <= j - 1; k++) {
                    if (k + 1 < n) {
                        char nextChar = sb.charAt(k + 1);
                        if (!Character.isDigit(nextChar)) {
                            sb.setCharAt(k, 'R');
                        }
                    } else {
                        break;
                    }
                }

            } else if (currChar == 'L') {

                int j = i + 1;
                while (j < n && sb.charAt(j) == 'L') {
                    sb.setCharAt(j, '.');
                    j++;
                }

                // now we have a block of L, so push all the dominoes to the left
                for (int k = i; k <= j - 1; k++) {

                    if (k - 1 >= 0) {
                        char prevChar = sb.charAt(k - 1);
                        if (!Character.isDigit(prevChar)) {
                            sb.setCharAt(k, 'L');
                        }
                    } else {
                        break;
                    }
                }

            } else {
                // we have encountered a '.'
                i++;
            }

        }

        String result = sb.toString().replace("..", ".").replace(".R", "R").replace("L.", "L");
        return result;

    }
}

