public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;
        int[][] dp = new int[n][n];

        for (int i = 0; i < n - 1; i++) {
            dp[i][i + 1] = Math.max(piles[i], piles[i + 1]);
        }

        for (int len = 3; len <= n; len++) {
            for (int l = 0; l <= n - len; l++) {
                int r = l + len - 1;

                dp[l][r] = Math.max(piles[l] - dp[l + 1][r], piles[r] - dp[l][r - 1]);
            }
        }

        return dp[0][n - 1] > 0;
    }
}

