public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;
        int[][] dp = new int[n][n];

        // Initialize dp table with zeros.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) dp[i][j] = piles[j];
                else dp[i][j] = -1;
            }
        }

        // Fill up the dp table.
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i < n - len + 1; i++) {
                int j = i + len - 1;

                if (dp[i][j] == -1) {
                    dp[i][j] = Math.max(piles[j] - dp[i+1][j], piles[i-1] - dp[i][j-1]);
                }
            }
        }

        // Alice wins if she can get more stones than Bob.
        return dp[0][n-1] > 0;
    }
}

