            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;

                dp[l][r] = Math.max(piles[l] - dp[l+1][r], piles[r] - dp[l][r-1]);
            }
        }

        return dp[0][n-1] > 0;
    }
}

