public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;
        int[] dp = new int[n];

        for (int i = 0; i < n; ++i) {
            if (i == 0 || i == 1) {
                dp[i] = piles[i];
            } else {
                dp[i] = Math.max(piles[i] + dp[i - 2], piles[i] - dp[i - 1]);
            }
        }

        return dp[n - 1] > (int)Math.floor(n / 2.0) * piles[n - 1];
    }
}

