public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;

        // Create a 2D table dp where dp[i][j] represents the maximum Alice can get from piles[i..j]
        int[][] dp = new int[n][n];

        // Fill up the diagonal
        for (int i = 0; i < n; i++) {
            dp[i][i] = piles[i];
        }

        // Fill up the rest of the table in a bottom-up manner
        for (int length = 1; length < n; length++) {
            for (int i = 0; i + length < n; i++) {
                int j = i + length;

                dp[i][j] = Math.max(piles[i] - dp[i+1][j], piles[j] - dp[i][j-1]);
            }
        }

        // The answer is true if the maximum Alice can get is greater than half of the total number of stones
        return dp[0][n-1] > (int) Math.ceil(piles.length * 1.0 / 2);
    }
}

