public class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        // build graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] dislike : dislikes) {
            graph.get(dislike[0] - 1).add(dislike[1] - 1);
            graph.get(dislike[1] - 1).add(dislike[0] - 1);
        }

        // color the nodes
        int[] colors = new int[n];
        Arrays.fill(colors, -1);

        for (int i = 0; i < n; i++) {
            if (colors[i] == -1) {
                if (!dfs(graph, colors, i, 0)) {
                    return false;
                }
            }
        }

        // No need to run on other connected components if one component has failed.
        return true;
    }

    private boolean dfs(List<List<Integer>> graph, int[] colors, int node, int color) {
        if (colors[node] != -1 && colors[node] != color) {
            return false;
        }

        colors[node] = color;

        for (int neighbor : graph.get(node)) {
            if (!dfs(graph, colors, neighbor, 1 - color)) {
                return false;
            }
        }

        return true;
    }
}

