public class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        // Build graph and color each node with -1 (no color yet)
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i + 1, new ArrayList<>());
        }

        for (int[] dislike : dislikes) {
            int a = dislike[0];
            int b = dislike[1];
            graph.get(a).add(b);
            graph.get(b).add(a); // undirected graph
        }

        // Color each node with 0 or 1
        Map<Integer, Integer> color = new HashMap<>();
        for (int i = 1; i <= n; i++) {
            if (!color.containsKey(i) && !dfs(graph, color, i, 0)) {
                return false;
            }
        }

        return true;
    }

    private boolean dfs(Map<Integer, List<Integer>> graph, Map<Integer, Integer> color, int node, int c) {
        // If we've already colored this node with a different color
        if (color.containsKey(node) && color.get(node) != c) {
            return false;
        }

        // Color it and continue DFS on its neighbors
        color.put(node, c);
        for (int neighbor : graph.get(node)) {
            if (!dfs(graph, color, neighbor, 1 - c)) {
                return false;
            }
        }

        return true;
    }
