import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        int curPos = 0;
        int res = 0;
        while (curPos < target) {
            // add current position to priority queue
            pq.offer(stations[curPos][0] - startFuel);

            // if the car can reach the destination, remove all positions from the priority queue and update curPos
            while (!pq.isEmpty() && curPos < stations.length && stations[curPos][0] <= target) {
                int pos = stations[curPos][0];

                // add fuel to current position
                startFuel += pq.poll();

                // if the car can reach the destination, update curPos and res
                if (pos == target) {
                    return res;
                }

                // move to next position
                curPos++;
            }

            // if the car cannot reach the destination, return -1
            if (curPos >= stations.length && startFuel < target) {
                return -1;
            }

            // update res
            res++;
        }

        // if the car can reach the destination, return res
        return res;
    }
}

