public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        int curPos = 0;
        int refuelCount = 0;

        while (curPos < target) {
            // Fill up the gas tank at current position
            while (!stations[stations.length - 1].equals(stations[0]) && curPos >= stations[stations.length - 1][0] 
                    && maxHeap.size() > 0 && startFuel < target - curPos) {
                startFuel += maxHeap.poll();
                refuelCount++;
            }

            // Try to move forward
            if (curPos < stations[stations.length - 1][0]) {
                for (int i = stations.length - 2; i >= 0; i--) {
                    if (stations[i][0] <= curPos) {
                        continue;
                    } else {
                        maxHeap.offer(stations[i][1]);
                    }
                }
            }

            // Move to the next position
            startFuel -= target - curPos;
            curPos = stations[stations.length - 1][0];
        }

        return refuelCount;
    }
}

