public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Sort gas stations by position
        Arrays.sort(stations, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        int curPos = 0;
        int numStops = 0;

        for (int i = 0; i <= stations.length; i++) {
            if (i < stations.length && curPos <= stations[i][0]) {
                // Fill up gas tank
                while (!maxHeap.isEmpty() && (curPos + startFuel) >= stations[i][0]) {
                    startFuel += maxHeap.poll();
                }

                // If we cannot reach the current position, return -1
                if (i < stations.length && curPos > stations[i][0]) {
                    return -1;
                }

                // Move to next station
                curPos = stations[i][0];
            }

            // Add current fuel left in max heap
            startFuel -= (stations[i][0] - curPos);
            if (startFuel < 0) {
                return numStops;
            }

            // Update number of stops and add current fuel to max heap
            numStops++;
            maxHeap.offer(stations[i][1]);
        }

        // Check if we can reach the target position
        if (curPos >= target) {
            return numStops;
        } else {
            return -1;
        }
    }
}

