public class Solution {
    public int consecutiveNumbersSum(int n) {
        long sum = 2 * n;
        int count = 0;

        // Check all possible start numbers from 1 to sqrt(sum)
        for (int i = 1; i <= Math.sqrt(sum); i++) {
            if ((sum - i) % i == 0 && (sum - i) / i > i) {
                count++;
