    public int consecutiveNumbersSum(int n) {
        long sum = 2 * n;
        int count = 0;

        // Check for odd number of terms
        if (sum % 2 == 1) {
            return 0;
        }

        for (int i = 3; ; i += 2) {
            if ((long) i * (i - 1) > sum) {
                break;
            }

            long diff = sum / i;
            if (diff % 2 == 0 && (diff + 1) * i / 2 == n) {
                count++;
            }
        }

        return count;
    }
}

