public class Solution {
    public int consecutiveNumbersSum(int n) {
        Map<Integer, Integer> factors = new HashMap<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                factors.put(i, 2);
                if (i != n / i) {
                    factors.put(n / i, 2);
                }
            }
        }

        int count = 0;
        for (int factor : factors.keySet()) {
            if ((factor - 1) * factor / 2 <= n && (n - (factor - 1) * factor / 2) % factor == 0) {
                count++;
            }
        }

        return count;
    }
}

