public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;

        // Calculate the skyline values from north and south directions
        int[] northSkyline = Arrays.copyOf(grid[0], n);
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > grid[0][j]) {
                    northSkyline[j] = grid[i][j];
                }
            }
        }

        int[] southSkyline = Arrays.copyOf(grid[n - 1], n);
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > grid[n-1][j]) {
                    southSkyline[j] = grid[i][j];
                }
            }
        }

        int[] eastSkyline = Arrays.copyOf(grid[0], n);
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (grid[j][i] > grid[i][0]) {
                    eastSkyline[i] = grid[j][i];
                }
            }
        }

        int[] westSkyline = Arrays.copyOf(grid[n-1], n);
        for (int i = 0; i < n; i++) {
            for (int j = n - 2; j >= 0; j--) {
                if (grid[j][i] > grid[n-1][i]) {
                    westSkyline[i] = grid[j][i];
                }
            }
        }

        int[] skyline = new int[n];

        // Calculate the minimum of each row and column for updating height
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int min = Math.min(Math.min(northSkyline[j], southSkyline[j]), Math.min(eastSkyline[i], westSkyline[i]));
                if (grid[i][j] < min) {
                    skyline[i] += grid[i][j];
                } else {
                    skyline[i] += min;
                }
            }
        }

        int sum = 0;
        for (int height : skyline) {
            sum += height;
        }

        return sum - Arrays.stream(grid).mapToInt(x -> Arrays.stream(x).sum()).sum();
    }
}

