public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        // Sort jobs by difficulty in ascending order
        Pair[] jobs = new Pair[difficulty.length];
        for (int i = 0; i < difficulty.length; i++) {
            jobs[i] = new Pair(difficulty[i], profit[i]);
        }
        java.util.Arrays.sort(jobs);

        int maxProfit = 0, prevJobDifficulty = 0;
        for (Pair job : jobs) {
            if (prevJobDifficulty <= job.difficulty && job.difficulty <= worker[worker.length - 1]) {
                // binary search to find the maximum profit by workers with ability >= current job's difficulty
                int left = 0, right = worker.length - 1;
                while (left < right) {
                    int mid = left + (right - left) / 2;
                    if (worker[mid] < job.difficulty) {
                        left = mid + 1;
                    } else {
                        right = mid;
                    }
                }

                // calculate max profit by workers with ability >= current job's difficulty
                maxProfit += Math.max(0, (left == worker.length ? 0 : left)) * job.profit;

                prevJobDifficulty = job.difficulty;
            }
        }
        return maxProfit;
    }

    static class Pair implements java.util.Comparator<Pair> {
        int difficulty;
        int profit;

        public Pair(int difficulty, int profit) {
            this.difficulty = difficulty;
            this.profit = profit;
        }

        @Override
        public int compare(Pair p1, Pair p2) {
            return Integer.compare(p1.difficulty, p2.difficulty);
        }
    }
}

