import com.github.leetcode.TreeNode;
import java.util.LinkedList;
import java.util.List;

public class Solution {
    private TreeNode lastNode = null;
    public TreeNode increasingBST(final TreeNode root) {
        if (root == null)
            return null;

        // In-order traversal of the tree
        TreeNode left = increasingBST(root.left);
        TreeNode right = increasingBST(root.right);

        // Create a new node with value from current node
        TreeNode newNode = new TreeNode(root.val);

        // Make it's right child as the result of the right subtree
        if (right != null)
            newNode.right = right;

        // If there is any left child, then make it as the root
        if (left != null) {
            newNode.left = left;
        } else {
            // If not, then set this node as the last node
            lastNode = newNode;
        }

        return newNode;
    }
}

