public class Solution {
    public TreeNode increasingBST(final TreeNode root) {
        if (root == null) return null;

        // Build a new tree with in-order traversal
        List<TreeNode> nodes = new LinkedList<>();
        buildInOrder(root, nodes);

        // Rebuild the tree with only one child at each node
        TreeNode dummy = new TreeNode(0);
        TreeNode cur = dummy;
        for (TreeNode node : nodes) {
            cur.right = node;
            cur = node;
        }

        return dummy.right;
    }

    private void buildInOrder(TreeNode root, List<TreeNode> nodes) {
        if (root == null) return;

        buildInOrder(root.left, nodes);
        nodes.add(root);
        buildInOrder(root.right, nodes);
    }
}

