public class Solution {
    public String orderlyQueue(String s, int k) {
        StringBuilder sb = new StringBuilder();
        if (s.length() <= k || k == 0) return s;

        char[] chars = s.toCharArray();
        Arrays.sort(chars);
        for (int i = 0; i < s.length(); i++) {
            if (i >= k && chars[i] != chars[k-1]) break;
            sb.append(chars[i]);
        }

        String result = sb.toString();
        if (s.indexOf(result) == -1 || s.indexOf(result) > s.lastIndexOf(result)) return s;

        StringBuilder finalSb = new StringBuilder(s);
        for (int i = 0; i < k; i++) {
            finalSb.append(s.charAt(i));
        }
        result = finalSb.toString();
        while (result.length() < s.length()) {
            int minIndex = -1;
            for (int j = 0; j < s.length(); j++) {
                if (s.indexOf(result) > s.lastIndexOf(result)) break;
                if (j >= k && s.charAt(j) != result.charAt(k-1)) break;
                char c = s.charAt(j);
                int index = result.indexOf(c);
                if (index == -1 || index < result.length() - 1) {
                    minIndex = j;
                    break;
                }
            }

            if (minIndex != -1) {
                finalSb.append(s.charAt(minIndex));
                result += s.charAt(minIndex);
            } else {
                return s;
            }
        }

        return result;
    }
}

