public class Solution {
    public boolean reorderedPowerOf2(int n) {
        String original = String.valueOf(n);
        Map<Character, Integer> frequencyMapOriginal = original.chars()
                .boxed()
                .collect(Collectors.groupingBy(c -> (char) c, Collectors.summingInt(i -> 1)));

        for (int i = 0; i <= 30; i++) {
            String powerOfTwo = Integer.toBinaryString(1 << i);
            Map<Character, Integer> frequencyMapPowerOfTwo = powerOfTwo.chars()
                    .boxed()
                    .collect(Collectors.groupingBy(c -> (char) c, Collectors.summingInt(i -> 1)));

            if (Objects.equals(frequencyMapOriginal, frequencyMapPowerOfTwo)) {
                return true;
            }
        }

        return false;
    }
}

