import java.util.Objects;

public class Solution {
    public boolean reorderedPowerOf2(int n) {
        String s = Integer.toString(n);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }

        Map<Integer, Integer> map = new HashMap<>();
        for (int digit : digits) {
            map.put(digit, map.getOrDefault(digit, 0) + 1);
        }

        int max = 0;
        while (max <= n) {
            String powerOf2Str = Integer.toString(max << 1);
            int[] powerOf2Digits = new int[powerOf2Str.length()];
            for (int i = 0; i < powerOf2Str.length(); i++) {
                powerOf2Digits[i] = powerOf2Str.charAt(i) - '0';
            }

            Map<Integer, Integer> powerOf2Map = new HashMap<>();
            for (int digit : powerOf2Digits) {
                powerOf2Map.put(digit, powerOf2Map.getOrDefault(digit, 0) + 1);
            }

            boolean isPossible = true;
            for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
                if (!powerOf2Map.containsKey(entry.getKey())
                        || powerOf2Map.get(entry.getKey()) < entry.getValue()) {
                    isPossible = false;
                    break;
                }
            }

            if (isPossible) {
                return true;
            }

            max <<= 1;
        }

        return false;
    }
}

