public class Solution {
    public int expressiveWords(String s, String[] words) {
        return (int)words.stream()
                .filter(word -> canBeStretchy(s, word))
                .count();
    }

    private boolean canBeStretchy(String s, String word) {
        if (s.length() != word.length()) return false;
        int i = 0, j = 0;
        while (i < s.length() && j < word.length()) {
            int countS = getGroupCount(s, i);
            int countW = getGroupCount(word, j);
            if (countS != countW) return false;
            if (countS >= 3 || countS == countW) {
                i += countS;
                j += countW;
            } else {
                while (i < s.length() && j < word.length()) {
                    int nextCountS = getGroupCount(s, i);
                    int nextCountW = getGroupCount(word, j);
                    if (nextCountS != nextCountW) return false;
                    if (nextCountS >= 3 || nextCountS == nextCountW) {
                        i += nextCountS;
                        j += nextCountW;
                    } else {
                        return false;
                    }
                }
            }
        }
        return i == s.length() && j == word.length();
    }

    private int getGroupCount(String str, int index) {
        if (index >= str.length()) return 0;
        char c = str.charAt(index);
        int count = 1;
        while (index + 1 < str.length() && str.charAt(index + 1) == c) {
            index++;
            count++;
        }
