public class Solution {
    public int expressiveWords(String s, String[] words) {
        return (int)words.stream()
                .filter(word -> canTransform(s, word))
                .count();
    }

    private boolean canTransform(String source, String target) {
        if(source.length() != target.length()) return false;

        int i = 0, j = 0;
        while(i < source.length()){
            int count1 = 0, count2 = 0;

            // Count the number of occurrences of the current character in both strings
            while(j < source.length() && source.charAt(i) == source.charAt(j)){
                ++count1;
                ++j;
            }
            while(j < target.length() && target.charAt(i) == target.charAt(j)){
                ++count2;
                ++j;
            }

            // If the counts are not equal or if count1 is less than 3 and greater than count2, return false
            if(count1 != count2 || (count1 < 3 && count1 > count2)) {
                return false;
            }

            i = j; // Move to the next character in both strings
        }

        return true;
    }
}

