            }
        }

        return i == s.length() && j == t.length();
    }

    private int getCount(String s, int index) {
        int count = 1;
        while (index + 1 < s.length() && s.charAt(index) == s.charAt(index + 1)) {
            count++;
            index++;
        }
        return count;
    }
