    }

    private boolean isStretchyWord(String s, String word) {
        int i = 0, j = 0;
        while (i < s.length() && j < word.length()) {
            if (s.charAt(i) != word.charAt(j)) {
                return false;
            }

            int stretchCountS = countConsecutive(s, i);
            int stretchCountW = countConsecutive(word, j);

            if ((stretchCountS == 1 || stretchCountS >= 3) && stretchCountW == 1) {
                i++; j++;
            } else if (stretchCountS < stretchCountW) {
                return false;
            } else {
                i += stretchCountS; j += stretchCountW;
            }
        }

        return i == s.length() && j == word.length();
    }

    private int countConsecutive(String str, int index) {
        if (index >= str.length() - 1) {
            return 0;
        }

        char c = str.charAt(index);
        int stretchCount = 1;

        while (index < str.length() && str.charAt(index + 1) == c) {
            index++; stretchCount++;
        }

        return stretchCount;
    }
