            .filter(this::isStretchy)
            .count();
    }

    private boolean isStretchy(String word){
        int i = 0;
        int j = 0;
        while(i < s.length() && j < word.length()){
            if(s.charAt(i) == word.charAt(j)){
                int len1 = nextLen(s, i);
                int len2 = nextLen(word, j);
                if(len1 != len2){
