        return i == s.length() && j == word.length();
    }

    private int nextLen(String str, int pos) {
        if (pos == str.length() - 1) {
            return 1;
        }
        int count = 0;
        while (pos < str.length() && str.charAt(pos + 1) == str.charAt(pos)) {
            ++count;
            ++pos;
        }
        if (count >= 3) {
            return count;
        } else {
            return 1;
        }
    }
