public class Solution {
    public int kSimilarity(String a, String b) {
        int n = a.length();
        boolean[] visited = new boolean[n];

        Queue<Step> queue = new LinkedList<>();
        queue.offer(new Step(a));

        int ans = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                Step step = queue.poll();

                if (step.s.equals(b)) {
                    return ans;
                }

                for (int j = 0; j < n; j++) {
                    if (!visited[j] && step.s.charAt(j) != b.charAt(j)) {
                        int pos = -1;
                        for (int k = j + 1; k < n; k++) {
                            if (step.s.charAt(k) == b.charAt(j)) {
                                pos = k;
                                break;
                            }
                        }

                        if (pos >= 0) {
                            char[] chars = step.s.toCharArray();
                            swap(chars, j, pos);

                            String t = new String(chars);
                            Step nextStep = new Step(t);
                            nextStep.visited[j] = true;
                            queue.offer(nextStep);
                        }
                    }
                }
            }

            ans++;
        }

        return -1; // if no solution is found
    }

    private static class Step {
        String s;
        boolean[] visited;

        public Step(String s) {
            this.s = s;
            this.visited = new boolean[s.length()];
        }
    }

    private void swap(char[] chars, int i, int j) {
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }
