public class Solution {
    public int minSwap(int[] nums1, int[] nums2) {
        int n = nums1.length;
        boolean[][] dp = new boolean[n][n];

        // Initialize base cases
        dp[0][0] = true;
        if (nums1[0] < nums2[0]) {
            dp[0][1] = true;
        }

        for (int i = 1; i < n; i++) {
            if (nums1[i - 1] < nums2[i - 1] && nums1[i] < nums2[i]) {
                dp[i][0] = dp[i - 1][0];
            }
            if (nums1[i - 1] < nums2[i - 1] && nums1[i] > nums2[i]) {
                dp[i][0] |= dp[i - 1][1];
            }

            if (nums1[i - 1] > nums2[i - 1] && nums1[i] < nums2[i]) {
                dp[i][1] = dp[i - 1][0];
            }
            if (nums1[i - 1] > nums2[i - 1] && nums1[i] > nums2[i]) {
                dp[i][1] |= dp[i - 1][1];
            }
        }

        // Return the minimum number of swaps
        int minSwaps = n;
        for (int i = 0; i < n; i++) {
            if (dp[n - 1][i]) {
                minSwaps = Math.min(minSwaps, i);
            }
        }

        return minSwaps;
    }
