        for (int i = n - 1; i >= 0; --i) {
            prefixSum[i] = shifts[i];
            if (i < n - 1) {
                prefixSum[i] += prefixSum[i + 1];
            }
        }

        StringBuilder result = new StringBuilder();

        // Apply shifts to the string
        for (int i = 0; i < n; ++i) {
            char c = s.charAt(i);
            long shift = prefixSum[i + 1];

            // Calculate the shifted character
            int codePoint = (c - 'a' + shift) % 26;
            result.append((char) ('a' + codePoint));
        }

        return result.toString();
    }
}

