import java.util.*;

public class Solution {
    public int numSimilarGroups(String[] strs) {
        int n = strs.length;
        boolean[][] similar = new boolean[n][n];

        // Check if two strings are similar by swapping characters at each position.
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int diffCount = 0;
                for (int k = 0; k < strs[i].length(); k++) {
                    if (strs[i].charAt(k) != strs[j].charAt(k)) {
                        diffCount++;
                    }
                }
                similar[i][j] = similar[j][i] = diffCount == 2;
            }
        }

        int groups = n;

        // Union find to group similar strings together.
        for (int i = 0; i < n; i++) {
            if (!similar[find(i, similar), i]) continue;
            union(i, similar);
            groups--;
        }

        return groups;
    }

    private int find(int x, boolean[][] similar) {
        while (x != similar[x][x]) {
            x = similar[x][x];
        }
        return x;
    }

    private void union(int x, boolean[][] similar) {
        int rootX = find(x, similar);
        for (int i = 0; i < similar.length; i++) {
            if (!similar[rootX][i]) continue;
            similar[rootX][i] = similar[i][rootX] = false;
            similar[rootX][find(i, similar)] = similar[find(i, similar)][rootX] = true;
        }
    }
}

