import java.util.Arrays;
public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        long[] lastCharIdx = new long[26];
        Arrays.fill(lastCharIdx, -1);
        long[] prevLastCharIdx = new long[26];
        Arrays.fill(prevLastCharIdx, -1);

        long[] count = new long[n + 1];

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int idx = c - 'A';

            if (lastCharIdx[idx] == -1) {
                lastCharIdx[idx] = i;
            } else {
                count[i + 1] += i - prevLastCharIdx[idx];
                prevLastCharIdx[idx] = lastCharIdx[idx];
                lastCharIdx[idx] = i;
            }
        }

        long sum = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int idx = c - 'A';

            if (lastCharIdx[idx] == i) {
                count[i + 1] -= (n - lastCharIdx[idx]);
            }
            sum += count[i + 1];
        }

        return (int) (sum % (long) (10 ** 9) + 1);
    }
}

