            char c = s.charAt(i);
            if (!lastCharIdx.containsKey(c)) {
                lastCharIdx.put(c, i);
            } else {
                // Update prevLastCharIdx
                prevLastCharIdx.put(c, lastCharIdx.get(c));
                // Update count for curr index from index of last char appearance.
                count += (i - lastCharIdx.get(c)) * (lastCharIdx.containsKey(c) ? 1 : 0);
            }
            // Update lastCharIdx
            lastCharIdx.put(c, i);

            // Add count for substrings that overlap [0, prevLastCharIdx] will need count to be discounted.
            if (!prevLastCharIdx.isEmpty()) {
                for (Map.Entry<Character, Integer> entry : prevLastCharIdx.entrySet()) {
                    char key = entry.getKey();
                    int value = entry.getValue();
                    count += (i - value) * (lastCharIdx.get(key) == i ? 1 : 0);
                }
            }
        }

        return count;
    }
