public class Solution {
    public int uniqueLetterString(String s) {
        Map<Character, int[]> seen = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (!seen.containsKey(c)) {
                seen.put(c, new int[] {i});
            } else {
                int[] indices = seen.get(c);

                // Add count for curr index from index of last char appearance.
                indices[0] += i - indices[1];

                // if last char idx is the only appearance of the char from left so far,
                // substrings that overlap [0, lastSeenIdx] will need count to be discounted, as
                // current char will cause duplication.
                if (indices.length == 2) {
                    seen.put(c, new int[] {i, indices[1]});
                } else {
                    indices[2]++;
                    Arrays.sort(indices);
                    seen.put(c, indices);
                }
            }
        }

        int total = 0;

        for (char c : s.toCharArray()) {
            if (!seen.containsKey(c)) continue;

            int[] indices = seen.get(c);

            // Add count of unique substrings for each character
            total += indices[0] + (indices.length == 2 ? indices[1] : indices[2]);
        }

        return total;
    }
}

