public class Solution {
    public int uniqueLetterString(String s) {
        long[] lastCharIdx = new long[26];
        Arrays.fill(lastCharIdx, -1);
        long[][] prevLastCharIdx = new long[26][2];

        int n = s.length();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);

            // Store last index of a character.
            if (lastCharIdx[c - 'A'] != -1) {
                prevLastCharIdx[c - 'A'][0] = lastCharIdx[c - 'A'];
                prevLastCharIdx[c - 'A'][1] = i;
            }
            lastCharIdx[c - 'A'] = i;

            // Add count for curr index from index of last char appearance.
            int count = 0;
            if (prevLastCharIdx[c - 'A'][0] == -1) {
                // If this is the only occurrence, add 1 to count
                count += i + 1;
            } else {
                if (prevLastCharIdx[c - 'A'][1] != -1) {
                    // This character has occurred before, so subtract the number of times it was counted in previous occurrences.
                    int sub = prevLastCharIdx[c - 'A'][0];
                    count += i + 1 - sub;
                } else {
                    // This character has occurred once before, but we don't know where
                    count += i + 1;
                }
            }

            // Now add the count to result
        }
        return (int) Arrays.stream(lastCharIdx).filter(i -> i != -1).count() +
               Arrays.stream(prevLastCharIdx).flatMap(arr -> {
                   for (long val : arr) {
                       if(val != -1)
                           yield 1;
                   }
                   return Stream.empty();
               }).mapToLong(l -> l + 1).sum();

    }

}

