public class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        // Binary search on the eating speed k
        int left = 1;
        int right = getMax(piles);

        while (left < right) {
            int mid = left + (right - left) / 2;

            // Calculate time taken to eat all bananas at the current speed
            long timeTaken = getTimeTaken(mid, piles);

            if (timeTaken <= h) {
                // If we can finish eating within h hours, increase the lower bound of k
                right = mid;
            } else {
                // Otherwise, decrease the upper bound of k
                left = mid + 1;
            }
        }

        return left;
    }

    private int getMax(int[] piles) {
        int max = Integer.MIN_VALUE;
        for (int pile : piles) {
            max = Math.max(max, pile);
        }
        return max;
    }

    private long getTimeTaken(int k, int[] piles) {
        long time = 0;
        for (int pile : piles) {
            time += (pile + k - 1) / k; // Ceiling division
        }
        return time;
    }
}

