        }

        // Flip all the columns which have less than half ones in them
        for (int j = 1; j < n; j++) {
            int count = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) {
                    count++;
                }
            }
            if (count * 2 < m) {
                flipColumn(grid, j);
            }
        }

        // Calculate the score
        int score = 0;
        for (int i = 0; i < m; i++) {
            score += grid[i][0];
            for (int j = 1; j < n; j++) {
                score += (grid[i][j] << (n - j));
            }
        }

        return score;
    }

    private void flipRow(int[][] grid, int row) {
        for (int i = 0; i < grid[0].length; i++) {
            grid[row][i] ^= 1;
        }
    }

    private void flipColumn(int[][] grid, int col) {
        for (int i = 0; i < grid.length; i++) {
            grid[i][col] ^= 1;
        }
    }
}

