public class Solution {
    private int[] answer;
    private List<List<Integer>> graph;
    private boolean[] visited;

    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        answer = new int[n];
        Arrays.fill(answer, -1);
        visited = new boolean[n];

        // build the graph
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // calculate distances from each node to all other nodes
        dfs(0, -1);

        // calculate answer[i] as the sum of distances between i-th node and all other nodes
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    answer[i] += getDistance(i, j);
                    count++;
                }
            }
            // divide by total number of nodes minus one
            answer[i] /= count - 1;
        }

        return answer;
    }

    private int getDistance(int startNode, int endNode) {
        if (startNode == endNode) {
            return 0;
        }

        visited = new boolean[graph.size()];
        dfs(startNode, -1);
        return answer[endNode];
    }

    private void dfs(int node, int parent) {
        visited[node] = true;

        for (int child : graph.get(node)) {
            if (!visited[child]) {
                answer[node] += getDistance(child, node);
                dfs(child, node);
            }
        }
    }
}

