// #2022_03_24_Time_52_ms_(91.09%)_Space_96.7_MB_(75.86%)
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        long[] rootSums = new long[n];
        int[] sizes = new int[n];

        Arrays.fill(rootSums, -1);

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);

            sizes[edge[0]]++;
            sizes[edge[1]]++;
        }

        dfs(graph, 0, -1, rootSums, sizes);

        int[] answer = new int[n];

        dfs2(graph, 0, -1, answer, rootSums, sizes);

        return answer;
    }

    private void dfs(List<Integer>[] graph, int node, int parent, long[] rootSums, int[] sizes) {
        for (int child : graph[node]) {
            if (child != parent) {
                sizes[node]--;
                dfs(graph, child, node, rootSums, sizes);
                rootSums[node] += rootSums[child];

                // update size and sum of current node
                sizes[node]++;
                rootSums[node] += sizes[child];
            }
        }
    }

    private void dfs2(List<Integer>[] graph, int node, int parent, int[] answer, long[] rootSums, int[] sizes) {
        for (int child : graph[node]) {
            if (child != parent) {
                answer[child] = n - sizes[child] - answer[node];

                // update sum of distances from child to other nodes
                answer[child] += (int)(rootSums[child]);
                dfs2(graph, child, node, answer, rootSums, sizes);
            }
        }
    }
}

