import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int rectangleArea(int[][] rectangles) {
        List<int[]> events = new ArrayList<>();

        for (int[] rect : rectangles) {
            events.add(new int[]{rect[0], -1, rect[2] - rect[0], rect[3] - rect[1]});
            events.add(new int[]{rect[1], 1, 0, 0});
        }

        events.sort((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

        long area = 0;
        int x = 0, y = 0;

        for (int[] event : events) {
            if (event[1] < 0) { // rectangle start
                area += (long) Math.abs(event[2]) * Math.abs(event[3]);
                x -= event[2];
                y += event[3];
            } else { // rectangle end
                long add = (long) Math.min(x, -event[2]) * Math.abs(event[3]);
                area -= add;
                x -= event[2];
                y -= event[3];
            }
        }

        return (int) (area % MOD);
    }
}

