public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<TreeNode, List<TreeNode>> graph = new HashMap<>();
        constructGraph(root, null, graph);

        Queue<TreeNode> queue = new LinkedList<>();
        Set<TreeNode> seen = new HashSet<>();
        List<Integer> result = new ArrayList<>();

        queue.offer(target);
        seen.add(target);

        while (!queue.isEmpty() && k > 0) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && !seen.contains(node.left)) {
                    seen.add(node.left);
                    graph.get(node).add(node.left);
                    queue.offer(node.left);
                }

                if (node.right != null && !seen.contains(node.right)) {
                    seen.add(node.right);
                    graph.get(node).add(node.right);
                    queue.offer(node.right);
                }
            }

            k--;
        }

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            result.add(node.val);
        }

        return result;
    }

    private void constructGraph(TreeNode node, TreeNode parent, Map<TreeNode, List<TreeNode>> graph) {
        if (node == null)
            return;

        if (parent != null)
            graph.computeIfAbsent(parent, k -> new ArrayList<>()).add(node);

        if (node.left != null) {
            graph.computeIfAbsent(node, k -> new ArrayList<>()).add(node.left);
            constructGraph(node.left, node, graph);
        }

        if (node.right != null) {
            graph.computeIfAbsent(node, k -> new ArrayList<>()).add(node.right);
            constructGraph(node.right, node, graph);
        }
    }
}

