public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<TreeNode, List<TreeNode>> graph = new HashMap<>();
        populateGraph(root, null, graph);

        return getDistanceNodes(target, k, graph);
    }

    private void populateGraph(TreeNode node, TreeNode parent, Map<TreeNode, List<TreeNode>> graph) {
        if (node == null)
            return;

        if (!graph.containsKey(node))
            graph.put(node, new ArrayList<>());

        if (parent != null)
            graph.get(parent).add(node);

        populateGraph(node.left, node, graph);
        populateGraph(node.right, node, graph);
    }

    private List<Integer> getDistanceNodes(TreeNode target, int k, Map<TreeNode, List<TreeNode>> graph) {
        Set<TreeNode> visited = new HashSet<>();
        Queue<TreeNode> queue = new LinkedList<>();

        visited.add(target);
        queue.offer(target);

        while (!queue.isEmpty() && k > 0) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (k == 1)
                    return getValues(node, graph);

                for (TreeNode neighbor : graph.getOrDefault(node, new ArrayList<>())) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }

            k--;
        }

        return getValues(target, graph);
    }

    private List<Integer> getValues(TreeNode node, Map<TreeNode, List<TreeNode>> graph) {
        List<Integer> values = new ArrayList<>();

        if (!graph.containsKey(node))
            values.add(node.val);

        for (TreeNode child : graph.getOrDefault(node, new ArrayList<>()))
            values.addAll(getValues(child, graph));

        return values;
    }
}

