import com.github.leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.LinkedList;

public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        if (root == null || target == null)
            return new ArrayList<>();

        // First pass: Build adjacency list
        List<TreeNode>[] adjList = buildAdjacencyList(root);

        // Second pass: Perform BFS from the target node
        Queue<TreeNode> queue = new LinkedList<>();
        boolean[] visited = new boolean[adjList.length];

        queue.add(target);
        visited[target.val - 1] = true;
        List<Integer> result = new ArrayList<>();

        while (!queue.isEmpty() && k > 0) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && !visited[node.left.val - 1]) {
                    visited[node.left.val - 1] = true;
                    result.add(node.left.val);
                    queue.offer(node.left);
                }

                if (node.right != null && !visited[node.right.val - 1]) {
                    visited[node.right.val - 1] = true;
                    result.add(node.right.val);
                    queue.offer(node.right);
                }
            }

            k--;
        }

        // If there are still elements in the queue, it means we have reached distance k
        if (!queue.isEmpty()) {
            List<Integer> temp = new ArrayList<>();

            while (true) {
                TreeNode node = queue.poll();
                temp.add(node.val);

                for (TreeNode neighbor : adjList[node.val - 1]) {
                    if (!visited[neighbor.val - 1]) {
                        visited[neighbor.val - 1] = true;
                        queue.offer(neighbor);
                    }
                }

                if (queue.isEmpty()) break;
            }

            // Add nodes at distance k
            result.addAll(temp);
        }

        return result;
    }

    private List<TreeNode>[] buildAdjacencyList(TreeNode root) {
        if (root == null)
            return new ArrayList[0];

        List<TreeNode>[] adjList = new ArrayList[root.val];
        for (int i = 0; i < root.val; i++) {
            adjList[i] = new ArrayList<>();
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        boolean[] visited = new boolean[root.val];

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && !visited[node.left.val - 1]) {
                    visited[node.left.val - 1] = true;
                    adjList[node.val - 1].add(node.left);
                    queue.offer(node.left);
                }

                if (node.right != null && !visited[node.right.val - 1]) {
                    visited[node.right.val - 1] = true;
                    adjList[node.val - 1].add(node.right);
                    queue.offer(node.right);
                }
            }
        }

        return adjList;
    }
}

