                if (diffCount == 2) return false;
                diffCount++;
                diffIndices[diffCount - 1] = i;
            }
        }

        // If there are more than two differences, it's not possible to swap
        if (diffCount > 2) return false;

        // If the strings are equal and we've found at least one pair of different characters,
        // then we can swap them. This is because we're looking for a string that has exactly
        // two pairs of different characters, which would be the case when swapping all
        // occurrences of one character with another.
        if (diffCount == 0) {
            for (int i = 0; i < s.length(); i++) {
                int count = 0;
                for (int j = 0; j < s.length(); j++) {
                    if (s.charAt(i) == s.charAt(j)) count++;
                }
                if (count > 1) return true;
            }
        }

        // If we have exactly two different characters, then swapping them should result in
        // the goal string.
        for (int i = 0; i < diffCount; i++) {
            char temp = s.charAt(diffIndices[i]);
            s = s.substring(0, diffIndices[i]) + s.charAt(diffIndices[diffCount - 1])
                    + s.substring(diffIndices[i] + 1);
            goal = goal.substring(0, diffIndices[i]) + goal.charAt(diffIndices[diffCount - 1])
                    + goal.substring(diffIndices[i] + 1);

            if (s.equals(goal)) return true;
            s = s.substring(0, diffIndices[i]) + temp
                    + s.substring(diffIndices[i] + 1);
            goal = goal.substring(0, diffIndices[i]) + temp
                    + goal.substring(diffIndices[i] + 1);
        }

        // If we've tried swapping all possible pairs of different characters and haven't found
        // a match, then it's not possible to swap the strings.
        return false;
    }
