                if(diffCount > 2) return false;
            }
        }

        // If the number of different characters is not two, 
        // it's impossible to get goal by swapping two characters
        if(diffCount != 2) return false;

        // Check if first and second differences are valid for swapping
        char[] sArray = s.toCharArray();
        char[] goalArray = goal.toCharArray();

        swap(sArray, firstDiffIndex, secondDiffIndex);
        swap(goalArray, firstDiffIndex, secondDiffIndex);

        for (int i=0; i<s.length(); i++) {
            if (sArray[i] != goalArray[i]) return false;
        }

        // If all checks pass, it's possible to get goal by swapping two characters
        return true;
    }

    private void swap(char[] array, int firstIndex, int secondIndex) {
        char temp = array[firstIndex];
        array[firstIndex] = array[secondIndex];
        array[secondIndex] = temp;
    }
