public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        Arrays.sort(nums1);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int num : nums2) {
            pq.offer(new int[]{num, 1});
        }

        int n = nums1.length;
        int[] res = new int[n];

        for (int i = 0; i < n; i++) {
            while (!pq.isEmpty() && pq.peek()[0] <= nums1[i]) {
                pq.poll();
            }

            if (!pq.isEmpty()) {
                int[] temp = pq.poll();
                res[i] = temp[0];
                temp[1]--;
                if (temp[1] > 0) {
                    pq.offer(temp);
                }
            } else {
                throw new RuntimeException("No valid permutation found");
            }
        }

        return res;
    }
