public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        long[] prefixSum = new long[shifts.length + 1];
        for (int i = shifts.length - 1; i >= 0; i--) {
            if (shifts[i][2] == 1) {
                prefixSum[i] = shifts[i][1] - shifts[i][0] + 1;
            } else {
                prefixSum[i] = -(shifts[i][1] - shifts[i][0] + 1);
            }
            prefixSum[i + 1] += prefixSum[i];
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            int shift = (int) prefixSum[getShiftIndex(i, shifts)];
            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') {
                int asciiVal = (int) c;
                asciiVal += shift;
                if (asciiVal > 'z') {
                    asciiVal -= 26;
                } else if (asciiVal < 'a') {
                    asciiVal += 26;
                }
                sb.append((char) asciiVal);
            } else {
                sb.append(c);
            }
        }

        return sb.toString();
    }

    private int getShiftIndex(int index, int[][] shifts) {
        for (int i = 0; i < shifts.length; i++) {
            if (shifts[i][0] <= index && index <= shifts[i][1]) {
                return i;
            }
        }
        return -1;
    }
}

