public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(endPos - startPos);
        if (diff > k) return 0;

        int stepsToDiff = k - diff;
        long mod = (long)Math.pow(10, 9) + 7;

        // Calculate the number of ways to arrange the steps
        long ways = factorial(stepsToDiff + stepsToDiff);
        for (int i = 1; i <= stepsToDiff; i++) {
            ways /= i;
        }

        return (int)(ways % mod);
    }

    private long factorial(int n) {
        if (n == 0 || n == 1) return 1;
        else return n * factorial(n - 1);
    }
}

