public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        final int MOD = (int) 1e9 + 7;

        if ((endPos - startPos) % 2 != 0 || k < Math.abs(endPos - startPos)) {
            return 0;
        }

        long leftSteps = (k - Math.abs(endPos - startPos)) / 2;
        long rightSteps = k - leftSteps;

        int n = (int) leftSteps + 1;
        long res = 1;

        for (long i = 1; i <= n; ++i) {
            res *= i;
            res %= MOD;
        }

        return (int) res;
    }
