        if (pos < 1 || pos > k) return 0;
        String key = pos + "," + k;

        if (!dp.containsKey(key)) {
            long res = calc(dp, pos - 1, k);
            res += calc(dp, pos + 1, k);

            dp.put(key, res % (int)(1e9+7));
