public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        final int MOD = 1000000007;

        List<Integer> pos = new ArrayList<>();
        if (startPos < endPos) {
            for (int i = startPos; i <= endPos + k; i++) {
                pos.add(i);
            }
        } else {
            for (int i = startPos; i >= endPos - k; i--) {
                pos.add(i);
            }
        }

        int totalSteps = pos.get(pos.size() - 1) - pos.get(0);

        if ((totalSteps & 1) != 0) return 0;

        int halfSteps = totalSteps / 2;
        long[][] dp = new long[Math.max(startPos, endPos) + k][halfSteps + 1];
        for (int i = Math.max(startPos, endPos); i <= Math.min(pos.get(0), pos.get(pos.size() - 1)) + k; i++) {
            dp[i][0] = 1;
        }

        for (int i = Math.max(startPos, endPos) + 1; i <= Math.min(pos.get(0), pos.get(pos.size() - 1)) + k; i++) {
            for (int j = halfSteps; j >= 1; j--) {
                dp[i][j] += dp[i - 1][j - 1];
                dp[i][j] %= MOD;
            }
        }

        long ans = 0;
        for (int i = Math.max(startPos, endPos) + k; i <= Math.min(pos.get(0), pos.get(pos.size() - 1)) + k; i++) {
            ans += (dp[i][halfSteps] * dp[i][halfSteps]) % MOD;
