                if (memo.containsKey(prevKey)) {
                    int gcd = gcd(i, Integer.parseInt(prevKey.split(",")[1]));
                    if (gcd != 1) {
                        isDistinct = false;
                        break;
                    }
                } else {
                    boolean hasGap = false;
                    for (int k = 0; k < j - 1; k++) {
                        String prevPrevKey = k + "," + i;
                        if (memo.containsKey(prevPrevKey)) {
                            int gcd = gcd(i, Integer.parseInt(prevPrevKey.split(",")[1]));
                            if (gcd == i) {
