public class Solution {
    public int distinctSequences(int n) {
        final int MOD = (int)(1e9 + 7);
        long[][] dp = new long[n+1][6];

        // Base case: One roll is always possible
        for (int i = 0; i < 6; i++) {
            dp[1][i] = 1;
        }

        // Fill up the dp table in a bottom-up manner
        for (int i = 2; i <= n; i++) {
            Arrays.fill(dp[i], 0);

            // For each possible value of the current roll
            for (int j = 0; j < 6; j++) {
                // If it's not a repeated value, consider all previous rolls
                if (i > 2) {
                    for (int k = 0; k < 6; k++) {
                        if (k != j && gcd(j, k) == 1) {
                            dp[i][j] += dp[i-1][k];
                            dp[i][j] %= MOD;
                        }
                    }
                } else {
                    // If it's the second roll and not a repeated value
                    for (int k = 0; k < 6; k++) {
                        if (k != j && gcd(j, k) == 1) {
                            dp[i][j] += dp[i-1][k];
                            dp[i][j] %= MOD;
                        }
                    }
                }
            }
        }

        // The total number of distinct sequences is the sum of all possible values
        long result = 0;
        for (int i = 0; i < 6; i++) {
            result += dp[n][i];
            result %= MOD;
        }

        return (int)result;
    }

    public int gcd(int a, int b) {
        if (b == 0)
            return a;
        return gcd(b, a % b);
    }
