        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(Integer.bitCount(num));
        }

        long res = 0;
        for (Integer bitCnt1 : set) {
            for (Integer bitCnt2 : set) {
                if (bitCnt1 == bitCnt2) {
