        int orResult = a | b;

        int bitCountAnd = 0;
        while (andResult > 0) {
            bitCountAnd += andResult % 2;
            andResult >>= 1;
        }

        int bitCountOr = 0;
        while (orResult > 0) {
            bitCountOr += orResult % 2;
            orResult >>= 1;
        }

        return bitCountAnd + bitCountOr;
    }
}

