import com_github_leetcode.TreeNode;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) return 0;

        // Initialize a queue for BFS with the starting node
        java.util.Queue<TreeNode> queue = new java.util.LinkedList<>();
        queue.offer(root);
        root.state = TreeNode.State.INFECTED; // Mark the starting node as infected

        int minutes = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.val == start) continue; // Skip the starting node

                for (TreeNode child : node.children) {
                    if (child.state == TreeNode.State.UNINFECTED) { // If the child is uninfected
                        child.state = TreeNode.State.INFECTED;
                        queue.offer(child); // Mark it as infected and add to the queue
                    }
                }
            }

            minutes++;
        }

        return minutes - 1; // Return the number of minutes needed for the entire tree to be infected
    }
}

