public class Solution {
    public long countPairs(int n, int[][] edges) {
        Map<Integer, Integer> parent = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            parent.put(i, i);
        }

        for (int[] edge : edges) {
            int u = find(parent, edge[0]);
            int v = find(parent, edge[1]);

            if (u != v) {
                union(parent, u, v);
            }
        }

        int connectedComponents = parent.size();
        long unreachablePairs = 1L * n * (n - 1) / 2;

        for (int i = 0; i < n; ++i) {
            if (parent.get(i) == i) {
                unreachablePairs -= 1L * (connectedComponents - parent.size()) * (n - connectedComponents);
                break;
            }
        }

        return unreachablePairs;
    }

    private int find(Map<Integer, Integer> parent, int node) {
        while (node != parent.get(node)) {
            parent.put(node, parent.get(parent.get(node)));
            node = parent.get(node);
        }

        return node;
    }

    private void union(Map<Integer, Integer> parent, int u, int v) {
        int rootU = find(parent, u);
        int rootV = find(parent, v);

        if (rootU != rootV) {
            parent.put(rootV, rootU);
        }
    }
