        long sum = 0;
        while (right < n) {
            // add right into the sliding window
            maxHeap.offer(chargeTimes[right]);
            sum += runningCosts[right];

            // update sliding window max and window sum
            while (!maxHeap.isEmpty() && sum * (right - left + 1) > budget) {
