public class Solution {
    // use sliding window to track the largest in a way that the sliding window only grows.
    //   then the maximum size is the size of the sliding window at the end.
    // if condition is met, we just grow the sliding window.
    // if condition is not met, we shift the sliding window with the same size to the next position.
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a,b)->b-a);

        long costSum = 0;
        for (int i = 0; i < n; i++) {
            maxHeap.add(chargeTimes[i]);
            costSum += runningCosts[i];
        }

        int maxRobots = 1, currentChargeMax = chargeTimes[0], currentSum = runningCosts[0];
        int left = 0;

        for (int right = 0; right < n; right++) {
            while (left <= right) {
                // adjust the window size
                if (currentChargeMax + (right - left + 1) * currentSum > budget) {
                    maxHeap.poll();
                    costSum -= runningCosts[left];
                    left++;
                } else {
                    break;
                }
            }

            if (left <= right) {
                // update maximum number of robots
                if (maxRobots < right - left + 1) {
                    maxRobots = right - left + 1;
                }

                currentChargeMax = Math.max(maxHeap.peek(), currentChargeMax);
                currentSum = costSum;
            }
        }

        return maxRobots;
    }
}

