public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        Set<Character> set = new HashSet<>();

        for (char[] mapping : mappings) {
            if (!set.add(mapping[0])) {
                return false; // duplicate old character
            }
            set.add(mapping[1]);
        }

        int n = sub.length();
        int m = s.length();

        boolean[][] dp = new boolean[n + 1][m + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (i == 0) {
                    dp[i][j] = true;
                } else if (j > 0 && set.contains(s.charAt(j - 1))) {
                    char c = s.charAt(j - 1);
                    int idx = sub.indexOf(c, i);
                    if (idx != -1) {
                        dp[i][j] = dp[idx + 1][j - 1];
                    }
                }

                if (!dp[i][j]) {
                    continue;
                }

                char c = sub.charAt(i - 1);
                int idx = s.indexOf(c, j);

                if (idx != -1) {
                    dp[i][j] |= dp[i - 1][idx + 1];
                }
            }
        }

        return dp[n][m];
    }
}

