public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int res = -1;
        int minDist = Integer.MAX_VALUE;

        // For each node in the graph
        for (int i = 0; i < edges.length; i++) {
            // Initialize distances to both nodes as infinity
            Map<Integer, Integer> dist1 = new HashMap<>();
            Map<Integer, Integer> dist2 = new HashMap<>();

            // Calculate distance from node1 to all other nodes
            bfs(edges, node1, i, dist1);

            // If we've reached the target node with node1, skip it for node2
            if (dist1.containsKey(i)) {
                continue;
            }

            // Calculate distance from node2 to all other nodes
            bfs(edges, node2, i, dist2);

            // Find the intersection of distances and update result if needed
            Set<Integer> intersection = new HashSet<>(dist1.keySet());
            intersection.retainAll(dist2.keySet());
            for (int j : intersection) {
                int d1 = dist1.get(j);
                int d2 = dist2.get(j);
                if (Math.max(d1, d2) < minDist) {
                    minDist = Math.max(d1, d2);
                    res = i;
                }
            }
        }

        return res;
    }

    // Helper function to perform a breadth-first search
    private void bfs(int[] edges, int startNode, int targetNode, Map<Integer, Integer> dist) {
        Queue<int[]> queue = new ArrayDeque<>();
        boolean[] visited = new boolean[edges.length];
        queue.offer(new int[] {startNode, 0});

        while (!queue.isEmpty()) {
            int[] nodeDist = queue.poll();

            if (nodeDist[0] == targetNode) {
                dist.put(targetNode, nodeDist[1]);
                return;
            }

            if (visited[nodeDist[0]]) continue;
            visited[nodeDist[0]] = true;

            int nextNode = edges[nodeDist[0]];
            if (nextNode != -1) {
                queue.offer(new int[] {nextNode, nodeDist[1] + 1});
            }
        }
    }
}

