    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long[] dp = new long[n + 2];

        for (int i = 0; i <= n; ++i) {
            if (i >= delay && i - delay < forget) {
                // People who start sharing on this day
                dp[i] += (dp[i - delay] + 1);

                // People who forget on this day
                dp[forget]++;
            } else if (i >= delay) {
                // People who start sharing on this day
                dp[i] += dp[i - delay];
