        int n = start.length();

        // Check if the lengths of both strings are equal
        if (n != target.length()) return false;

        // Initialize two pointers at the beginning of each string
        int i = 0, j = 0;

        while (i < n && j < n) {
            // If the current characters in both strings are '_'
            if (start.charAt(i) == '_' && target.charAt(j) == '_') {
                i++;
                j++;
            }
            // If the current character in start is 'L' and the current character in target is '_'
            else if (start.charAt(i) == 'L' && target.charAt(j) == '_') {
                i++;
            }
            // If the current character in start is '_' and the current character in target is 'R'
            else if (start.charAt(i) == '_' && target.charAt(j) == 'R') {
                j++;
            }
            // If the current characters in both strings are 'L' or 'R'
            else if (start.charAt(i) == 'L' && target.charAt(j) == 'R') return false;
            else if (start.charAt(i) == 'R' && target.charAt(j) == 'L') return false;
            // If the current characters in both strings are not '_' and do not match
            else {
                i++;
                j++;
            }
        }

        // Check if all characters have been processed
        while (i < n && start.charAt(i) == '_') i++;
        while (j < n && target.charAt(j) == '_') j++;

        return i == n && j == n;
    }
