public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();

        // Check if both strings have equal length
        if (n != target.length()) return false;

        // Initialize two pointers at start and end of the string
        int left = 0, right = n - 1;

        while (left <= right) {
            // If '_' is found in start, check if it matches with 'L' or 'R' in target
            if (start.charAt(left) == '_') {
                // Check for 'L' in target and move left pointer forward
                if (target.charAt(left) != 'L')
                    return false;
                else
                    left++;
            }
            // If '_' is found in target, check if it matches with 'L' or 'R' in start
            else if (target.charAt(left) == '_') {
                // Check for 'R' in start and move left pointer forward
                if (start.charAt(left) != 'R')
                    return false;
                else
                    left++;
            }
            // If 'L' is found in start, check if it matches with '_' or 'L' in target
            else if (start.charAt(left) == 'L') {
                // Check for '_' or 'L' in target and move left pointer forward
                if ((target.charAt(left) != '_ && target.charAt(left) != 'L'))
                    return false;
                else
                    left++;
            }
            // If 'R' is found in start, check if it matches with '_' or 'R' in target
            else if (start.charAt(left) == 'R') {
                // Check for '_' or 'R' in target and move left pointer forward
                if ((target.charAt(left) != '_ && target.charAt(left) != 'R'))
                    return false;
                else
                    left++;
            }

            // Repeat the same process for right pointer
            while (right >= 0 && start.charAt(right) == '_' && target.charAt(right) == '_') {
                right--;
            }

            if (start.charAt(right) == '_') {
                if (target.charAt(right) != 'R')
                    return false;
                else
                    right--;
            } else if (target.charAt(right) == '_') {
                if (start.charAt(right) != 'L')
                    return false;
                else
                    right--;
            } else if (start.charAt(right) == 'L') {
                if ((target.charAt(right) != '_' && target.charAt(right) != 'L'))
                    return false;
                else
                    right--;
            } else if (start.charAt(right) == 'R') {
                if ((target.charAt(right) != '_' && target.charAt(right) != 'R'))
                    return false;
                else
                    right--;
            }
        }

        // If both pointers meet in the middle, it means that we have successfully converted start into target
        return left <= right;
    }
}

