public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();

        // Check for empty strings
        if (n == 0 && start.equals(target)) return true;

        int i = 0, j = 0;
        while (i < n || j < n) {
            // Move left pointer in start string until we find a valid position or reach the end of the string.
            while (i < n && !isValid(start.charAt(i), target.charAt(j))) i++;

            // If we reached the end of both strings, return true because there are no more moves to be made.
            if (i >= n && j >= n) return true;

            // Move right pointer in target string until we find a valid position or reach the end of the string.
            while (j < n && !isValid(start.charAt(i), target.charAt(j))) j++;

            // If we reached the end of both strings, return false because there are no more moves to be made and they were not equal.
            if (i >= n && j >= n) return false;

            // Swap the characters at current positions in start and target strings.
            char temp = start.charAt(i);
            start = start.substring(0, i) + target.charAt(j) + start.substring(i+1);
            target = target.substring(0, j) + temp + target.substring(j+1);

            // Move both pointers forward.
            i++;
            j++;
        }

        return start.equals(target);
    }

    private boolean isValid(char c1, char c2) {
        if (c1 == '_' || c2 == '_') return true;
        if (c1 != 'L' && c2 != 'R') return false;
        return c1 == 'L' && c2 == '_' || c1 == '_' && c2 == 'R';
    }
}

