public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();
        int[] startArr = new int[n];
        int[] targetArr = new int[n];

        for (int i = 0; i < n; i++) {
            if (start.charAt(i) == '_')
                startArr[i] = -1;
            else
                startArr[i] = (start.charAt(i) == 'L') ? 1 : -1;

            if (target.charAt(i) == '_')
                targetArr[i] = -1;
            else
                targetArr[i] = (target.charAt(i) == 'R') ? 1 : -1;
        }

        int startPtr = 0, targetPtr = 0;
        while (startPtr < n && targetPtr < n) {
            if (startArr[startPtr] == targetArr[targetPtr]) {
                startPtr++;
                targetPtr++;
            } else if ((targetArr[targetPtr] == -1 || startArr[startPtr] == -1)
                       && startPtr < n && targetPtr < n
                       && Math.abs(startArr[startPtr]) != Math.abs(targetArr[targetPtr])) {
                return false;
            } else if (startArr[startPtr] == targetArr[targetPtr]) {
                // move the pointers forward
                int tempStart = startPtr + 1, tempTarget = targetPtr + 1;

                while (tempStart < n && startArr[tempStart] != targetArr[tempTarget]) {
                    tempStart++;
                    tempTarget++;
                }

                if (tempStart == n) {
                    return true; // reached the end of string
                } else {
                    startPtr = tempStart;
                    targetPtr = tempTarget;
                }
            } else {
                return false;
            }
        }

        return (startPtr == n && targetPtr == n);
    }
}

