public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long ans = 0, max = 1;

        for (int i = n - 2; i >= 0; --i) {
            if (nums[i] <= max) {
                long k = (long) Math.ceil((double) nums[i] / max);
                ans += k - 1;
                max = nums[i] / k;
            }
        }

        return ans;
    }
}

