public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long ans = 0, last = (long)nums[n-1];

        for (int i=n-2; i>=0; --i) {
            if (nums[i] <= last) continue;

            long cnt = 1, need = nums[i]/last;
            while (cnt < need) {
                last = nums[i--];
                ans++;
                cnt++;
            }
        }

        return ans;
    }
}

