import java.util.Arrays;

public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        int[] prefixSum = new int[n+1];
        for (int i = 0; i < n; i++) {
            prefixSum[i+1] = prefixSum[i] + nums[i];
        }

        long minOperations = Long.MAX_VALUE;
        for (int midIndex = n-2; midIndex >= 0; midIndex--) {
            int maxElement = nums[midIndex];
            int k = 0;
            long operations = 0;
            for (int rightIndex = midIndex+1; rightIndex <= n-1; rightIndex++) {
                if (nums[rightIndex] > maxElement) {
                    operations += Math.ceil((double)(prefixSum[n]-prefixSum[midIndex+1]) / (maxElement - k));
                    maxElement = nums[rightIndex];
                    k++;
                }
            }
            minOperations = Math.min(minOperations, operations);
        }

        return minOperations;
    }
}

