public class Solution {
    public int minimumTraining(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int n = energy.length;

        // Initialize variables to keep track of current energy and experience
        int currEnergy = initialEnergy;
        int currExp = initialExperience;

        for (int i = 0; i < n; i++) {
            // If we can't defeat the opponent, return -1
            if (currEnergy >= energy[i] && currExp > experience[i]) {
                currEnergy -= energy[i];
                currExp += experience[i];
            } else {
                // Calculate the minimum training hours required to defeat this opponent
                int minHours = Math.max(0, experience[i] - currExp + 1) + Math.max(0, energy[i] - currEnergy + 1);

                // Update current energy and experience
                currEnergy -= energy[i];
                currExp += experience[i];

                // Return the total minimum training hours required to defeat all opponents
                return i == n - 1 ? minHours : minHours + getMinTraining(energy, experience, i + 1, initialEnergy, initialExperience);
            }
        }

        // If we can defeat all opponents, return 0
        return 0;
    }

    private int getMinTraining(int[] energy, int[] experience, int index, int initialEnergy, int initialExperience) {
        if (index == energy.length) {
            return 0;
        }

        int currEnergy = initialEnergy;
        int currExp = initialExperience;

        for (int i = index; i < energy.length; i++) {
            // If we can't defeat the opponent, return -1
            if (currEnergy >= energy[i] && currExp > experience[i]) {
                currEnergy -= energy[i];
                currExp += experience[i];
            } else {
                // Calculate the minimum training hours required to defeat this opponent
                int minHours = Math.max(0, experience[i] - currExp + 1) + Math.max(0, energy[i] - currEnergy + 1);

                // Update current energy and experience
                currEnergy -= energy[i];
                currExp += experience[i];

                // Return the total minimum training hours required to defeat all opponents
                return minHours + getMinTraining(energy, experience, i + 1, initialEnergy, initialExperience);
            }
        }

        // If we can defeat all opponents, return 0
        return 0;
    }
}

