import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minimumTraining(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        // Calculate total experience and energy required to defeat all opponents
        int totalExp = 0;
        for (int i : experience)
            totalExp += i;

        int totalEn = 0;
        for (int i : energy)
            totalEn += i;

        // Initialize the training hours required
        int trainingHours = 0;

        // Sort opponents based on their experience and energy requirements in descending order
        Opponent[] opponents = new Opponent[energy.length];
        for (int i = 0; i < energy.length; i++) {
            opponents[i] = new Opponent(energy[i], experience[i]);
        }
        Arrays.sort(opponents, Comparator.comparingInt(a -> a.experience).reversed().thenComparingInt(a -> a.energy));

        // Iterate over each opponent
        for (Opponent opponent : opponents) {
            int requiredExp = opponent.experience - initialExperience;
            int requiredEn = opponent.energy - initialEnergy;

            // If required experience or energy is more than total available, increment training hours
            if (requiredExp > totalExp || requiredEn > totalEn) {
                trainingHours += Math.max(requiredExp, requiredEn);
                initialEnergy -= requiredEn;
                initialExperience += requiredExp;
                totalExp = 0;
                totalEn = 0;

                // Update energy and experience for next opponent
                for (int i : energy)
                    totalEn += i;
                for (int i : experience)
                    totalExp += i;
            }

            // Update initial energy and experience after defeating the current opponent
            initialEnergy -= opponent.energy;
            initialExperience += opponent.experience;

            // Update total available energy and experience
            totalEn = 0;
            totalExp = 0;
            for (int i : energy)
                totalEn += i;
            for (int i : experience)
                totalExp += i;
        }

        return trainingHours;
    }

    private static class Opponent {
        int energy;
        int experience;

        public Opponent(int energy, int experience) {
            this.energy = energy;
            this.experience = experience;
        }
    }
}

