public class Solution {
    public int minNumberOfHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int n = energy.length;
        long expNeeded = 0;

        // Calculate needed experience and energy to defeat all opponents
        for (int i = 0; i < n; i++) {
            if (initialExperience >= experience[i]) {
                initialExperience += experience[i];
                initialEnergy -= energy[i];
                expNeeded += experience[i] - initialExperience + experience[i];
            } else {
                int expDiff = experience[i] - initialExperience;
                expNeeded += expDiff;
                initialExperience += expDiff;
                initialEnergy -= energy[i];
            }
        }

        // Return minimum hours required to train
        return (int) Math.max(0, expNeeded / 2 + (expNeeded % 2 == 1 ? 1 : 0));
    }
}

