public class Solution {

    public int minimumTraining(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        // Sort opponents by their required energy and experience in descending order
        int[][] opponents = new int[energy.length][3];
        for (int i = 0; i < energy.length; i++) {
            opponents[i][0] = -experience[i];  // Descending order of experience
            opponents[i][1] = -energy[i];      // Descending order of energy
            opponents[i][2] = i;
        }
        Arrays.sort(opponents, Comparator.comparingInt(a -> a[0]).reversed()
                .thenComparing(Comparator.comparingInt(a -> a[1])).reversed());

        int currExperience = initialExperience, currEnergy = initialEnergy;
        for (int[] opponent : opponents) {
            int requiredExperience = -opponent[0], requiredEnergy = -opponent[1];
            if (currExperience >= requiredExperience && currEnergy >= requiredEnergy) {
                currExperience += opponent[2];  // Increase experience
                currEnergy -= opponent[1];      // Decrease energy
            } else {
                int diff = Math.max(requiredExperience - currExperience, requiredEnergy - currEnergy);
                currExperience += diff;
                currEnergy -= diff;
            }
        }

        return currExperience - initialExperience;
    }
}

