public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i : nums1) sum1 += i;
        for (int i : nums2) sum2 += i;

        long maxEndingHere = Long.MIN_VALUE, minEndingHere = Long.MAX_VALUE;
        long maxSoFar = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            // update maxEndingHere and minEndingHere
            maxEndingHere = Math.max(maxEndingHere + nums1[i], nums2[i]);
            minEndingHere = Math.min(minEndingHere + nums1[i], nums2[i]);

            // update maxSoFar
            long temp = sum1 - (maxEndingHere - nums1[i]) + (sum2 - (minEndingHere - nums1[i]));
            maxSoFar = Math.max(maxSoFar, temp);

            // update sum1 and sum2
            sum1 -= nums1[i];
            sum2 -= nums2[i];

            // update maxEndingHere and minEndingHere
            maxEndingHere = Math.max(maxEndingHere, nums1[i]);
            minEndingHere = Math.min(minEndingHere, nums1[i]);

        }

        return (int) Math.max(sum1, sum2);
    }
}

