                minEndingHere = Math.min(minEndingHere, sum1);

                maxSoFar = Math.max(maxSoFar, (int) maxEndingHere - sum2);
            } else {
                // Case 1: Swap nums1[left...right] with nums2[left...right]
                long tempSum2 = sum2 - nums2[i] + nums1[i];
                maxEndingHere = Math.max(maxEndingHere, tempSum2);
                minEndingHere = Math.min(minEndingHere, tempSum2);

                // Case 2: Do not swap
                maxEndingHere = Math.max(maxEndingHere, sum2);
                minEndingHere = Math.min(minEndingHere, sum2);

