public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0;
        long sum2 = 0;
        for (int i = 0; i < n; ++i) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }

        long maxEndingHere1 = 0, maxEndingHere2 = Long.MIN_VALUE;
        long minEndingHere1 = 0, minEndingHere2 = Long.MAX_VALUE;

        for (int i = n - 1; i >= 0; --i) {
            // Case 1: We include the current element in nums1
            maxEndingHere1 += nums1[i];
            minEndingHere1 += nums1[i];

            // Case 2: We include the current element in nums2
            long temp = Math.max(maxEndingHere2 + nums1[i], sum2 - nums2[i]);
            maxEndingHere2 = Math.max(temp, maxEndingHere2);
            temp = Math.min(minEndingHere2 + nums1[i], sum2 - nums2[i]);
            minEndingHere2 = Math.min(temp, minEndingHere2);

            // Case 3: We swap the current subarray
            long swappedSum1 = sum1 - nums1[i] - minEndingHere1;
            long swappedSum2 = sum2 + nums1[i] - maxEndingHere2;
            if (swappedSum1 >= swappedSum2) {
                temp = Math.max(swappedSum1, sum1);
                maxEndingHere1 = Math.max(temp, maxEndingHere1);
                minEndingHere1 = Math.min(minEndingHere1, temp - nums1[i]);
            } else {
                temp = Math.max(swappedSum2, sum1);
                maxEndingHere1 = Math.max(maxEndingHere1, temp);
                minEndingHere1 = Math.min(temp - nums1[i], minEndingHere1);
            }
        }

        return (int) Math.max(Math.max(maxEndingHere1, sum1), Math.max(sum2 - maxEndingHere2, sum2));
    }
}

