public class Solution {
    public int[][] generateMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        int rowBegin = 0;
        int rowEnd = m - 1;
        int colBegin = 0;
        int colEnd = n - 1;

        int index = 0;
        while (head != null) {
            // Traverse from left to right
            for (int i = colBegin; i <= colEnd && index < m * n; i++) {
                matrix[rowBegin][i] = head.val;
                head = head.next;
                index++;
            }
            rowBegin++;

            // Traverse from top to bottom
            for (int i = rowBegin; i <= rowEnd && index < m * n; i++) {
                matrix[i][colEnd] = head.val;
                head = head.next;
                index++;
            }
            colEnd--;

            // Traverse from right to left
            if (index < m * n) {
                for (int i = colEnd; i >= colBegin && index < m * n; i--) {
                    matrix[rowEnd][i] = head.val;
                    head = head.next;
                    index++;
                }
                rowEnd--;
            }

            // Traverse from bottom to top
            if (index < m * n) {
                for (int i = rowEnd; i >= rowBegin && index < m * n; i--) {
                    matrix[i][colBegin] = head.val;
                    head = head.next;
                    index++;
                }
                colBegin++;
            }
        }

        // Fill remaining empty spaces with -1
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][j] = -1;
                }
            }
        }

        return matrix;
    }
}

