public class Solution {
    public int[][] generateMatrix(int m, int n, ListNode head) {
        if (m == 0 || n == 0) return new int[m][n];

        int[][] matrix = new int[m][n];
        boolean[][] visited = new boolean[m][n];
        int count = 1;
        int[] dx = {0, 1, 0, -1};
        int[] dy = {-1, 0, 1, 0};

        ListNode cur = head;
        int x = 0, y = 0;

        while (cur != null) {
            matrix[x][y] = cur.val;
            visited[x][y] = true;
            cur = cur.next;

            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                    matrix[x][y] = count++;
                    visited[x][y] = true;
                    x += dx[i];
                    y += dy[i];
                    break;
                }
            }
        }

        return matrix;
    }
}

