public class Solution {
    public int[][] generateMatrix(int m, int n, ListNode head) {
        // Initialize the matrix with all elements as -1
        int[][] res = new int[m][n];

        // Initialize directions for DFS (right, down, left, up)
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};

        // Initialize current position and direction
        int x = 0;
        int y = 0;
        int dir = 0;

        // Traverse the linked list
        while (head != null) {
            // Fill the current cell with the value from the linked list
            res[x][y] = head.val;

            // Move to the next position in the current direction
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            // If the next position is out of bounds or already filled, turn right
            if (nx < 0 || nx >= m || ny < 0 || ny >= n || res[nx][ny] != -1) {
                dir = (dir + 1) % 4;
                nx = x + dx[dir];
                ny = y + dy[dir];
            }

            // Update the current position
            x = nx;
            y = ny;

            // Move to the next node in the linked list
            head = head.next;
        }

        return res;
    }
}

