        boolean[][] visited = new boolean[m][n];

        // Calculate total number of nodes in the linked list
        ListNode temp = head;
        int cnt = 0;
        while (temp != null) {
            temp = temp.next;
            cnt++;
        }

        // Generate spiral matrix
        int left = 0, right = n - 1, top = 0, bottom = m - 1;
        temp = head;

        while (cnt > 0) {

            // Left to Right Horizontal traversal
            for (int i = left; i <= right && cnt > 0; i++) {
                if (temp != null) {
                    res[top][i] = temp.val;
                    visited[top][i] = true;
                    temp = temp.next;
                    cnt--;
                }
            }

            // ++ after Left to Right Horizontal traversal
            left++;
            top++;

            // Down to Up vertical traversal
            for (int i = top; i <= bottom && cnt > 0; i++) {
                if (temp != null) {
                    res[i][right] = temp.val;
                    visited[i][right] = true;
                    temp = temp.next;
                    cnt--;
                }
            }

            // -- after Down to Up vertical traversal
            right--;
            bottom--;

            // Right to Left horizontal traversal
            for (int i = right; i >= left && cnt > 0; i--) {
                if (temp != null) {
                    res[bottom][i] = temp.val;
                    visited[bottom][i] = true;
                    temp = temp.next;
                    cnt--;
                }
            }

            // -- after Right to Left horizontal traversal
            bottom++;
            right++;

            // Down to Up vertical traversal
            for (int i = bottom; i >= top && cnt > 0; i--) {
                if (temp != null) {
                    res[i][left] = temp.val;
                    visited[i][left] = true;
                    temp = temp.next;
                    cnt--;
                }
            }

