public class Solution {
    public int distributeCookies(int[] cookies, int k) {
        int n = cookies.length;
        int max = 0;

        // Try each child as a possible maximum cookie holder
        for (int i = 1; i <= Math.min(k, n); i++) {
            int[] dp = new int[i];

            // Initialize the first value in dp to be the number of cookies in the first bag
            dp[0] = cookies[0];
            max = Math.max(max, dp[0]);

            for (int j = 1; j < n; j++) {
                boolean found = false;

                // Try each child as a possible maximum cookie holder for this bag
                for (int l = 0; l < i; l++) {
                    if (dp[l] + cookies[j] <= max) continue;

                    dp[l] += cookies[j];
                    max = Math.max(max, dp[l]);
                    found = true;
                    break;
                }

                // If we couldn't find a place for this bag's cookies, try adding it to the first child
                if (!found) {
                    dp[0] += cookies[j];
                    max = Math.max(max, dp[0]);
                }
            }
        }

        return max;
    }
}

