// #2022_06_16_Time_14_ms_(84.35%)_Space_39.6_MB_(92.46%)
public class Solution {
    public int distributeCookies(int[] c, int k) {
        int n = c.length;
        boolean[] dp = new boolean[10000];
        int max = 0;

        for (int i = 0; i < Math.pow(2, n); i++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    sum += c[j];
                }
            }

            max = Math.max(max, sum);
            dp[(int)i] = true;

            // Check all possible combinations
            for (int mask = 0; mask < Math.pow(2, n); mask++) {
                if ((i & mask) == i && dp[mask]) {
                    int tempSum = 0;
                    boolean isPossible = true;

                    for (int j = 0; j < n; j++) {
                        if (((mask >> j) & 1) != 0) {
                            tempSum += c[j];
                        }
                    }

                    // Check if the current combination is possible
                    for (int child = 0; child < k; child++) {
                        int currSum = 0;
                        for (int j = 0; j < n; j++) {
                            if (((mask >> j) & 1) != 0 && ((child << j) & 1) == 0) {
                                currSum += c[j];
                            }
                        }

                        // If the current combination is not possible, break
                        if (currSum > tempSum) {
                            isPossible = false;
                            break;
                        }
                    }

                    // Update dp array
                    if (isPossible && tempSum < max) {
                        max = tempSum;
                        dp[(int)i] = true;
                    }
                }
            }
        }

        return max;
    }
}

