import java.util.*;

public class Solution {
    public int distributeCookies(int[] c, int k) {
        Arrays.sort(c);
        boolean[] visited = new boolean[c.length];
        int res = Integer.MAX_VALUE;

        // try each child first
        for (int i = 0; i < Math.min(k, c.length); i++) {
            int cur = dfs(c, visited.clone(), 0, i + 1);
            if (cur != -1) {
                res = Math.min(res, cur);
            }
        }

        return res;
    }

    private int dfs(int[] cookies, boolean[] visited, int start, int k) {
        if (k == 1) {
            // only one child left
            return cookies[start];
        }

        for (int i = start; i < cookies.length; i++) {
            if (!visited[i]) {
                visited[i] = true;

                // try place this bag in current child
                int res = dfs(cookies, visited.clone(), i + 1, k - 1);
                if (res != -1) {
                    return Math.max(res, cookies[start]);
                }

                // backtrack and remove current bag from current child
                visited[i] = false;
            }
        }

        // no valid solution found for this child
        return -1;
    }
}

