import java.util.Arrays;

public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int[][] time = new int[3][garbage.length];

        for (int i = 0; i < garbage.length; i++) {
            char[] chars = garbage[i].toCharArray();

            // Count the number of each type of garbage
            for (char c : chars) {
                if (c == 'M') time[0][i]++;
                else if (c == 'P') time[1][i]++;
                else if (c == 'G') time[2][i]++;
            }

            // Add the travel time to each type of garbage
            for (int j = 0; j < 3; j++) {
                time[j][i] += travel[i];
            }
        }

        int[] sums = new int[4];
        for (int i = 1; i < sums.length; i++) {
            sums[i] = sums[i - 1] + time[i - 1][garbage.length - 1];
        }

        // Find the maximum index of non-zero elements in the last row
        int maxIdx = Arrays.asList(time[0], time[1], time[2]).stream()
                .mapToInt(arr -> {
                    for (int j = garbage.length - 1; j >= 0; j--) {
                        if (arr[j] != 0) return j;
                    }
                    return -1;
                })
                .max().getAsInt();

        // Return the maximum of the last row plus the sum of all elements from the beginning to the max index
        return Math.max(time[0][garbage.length - 1], time[1][garbage.length - 1],
                time[2][garbage.length - 1]) + sums[maxIdx];
    }
}

