public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        if (n == 0 || k < 1) return -1;

        // find the maximum value in the array
        int maxNum = Arrays.stream(nums).max().getAsInt();

        // check if the maximum number is greater than or equal to threshold / k
        if (maxNum >= threshold / k) {
            return n;
        }

        // initialize variables for binary search
        int left = 1, right = n;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            // check if it's possible to find a subarray of size mid
