            for (int i = 0; i < n - mid + 1; i++) {
                if (isSubarrayValid(nums, i, mid)) {
                    found = true;
                    break;
                }
            }

            // update the search range
            if (found) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return left == n ? -1 : left;
    }

    private boolean isSubarrayValid(int[] nums, int start, int length) {
        for (int i = start; i < start + length; i++) {
            if (nums[i] <= threshold / length) {
                return false;
            }
        }
        return true;
    }
