public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        // This function is used to find the length of any subarray that satisfies certain conditions.
        // The conditions are as follows: all elements in the subarray must be greater than threshold / k where k is the size of the current subarray.

        // Initialize max variable with Integer.MIN_VALUE. If no such subarray is found, this function will return -1.
        int max = Integer.MIN_VALUE;

        // Iterate over the array from left to right. For each element in the array, we check if it's greater than threshold / k where k is the size of the current subarray.

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > threshold / nums.length) { // Check if the current element is greater than threshold / k.
                max = Math.max(max, findLongestSubarray(nums, i)); // Update max variable with the length of longest subarray that can be formed by including the current element in it. This function will be explained below.
            }
        }

        // Return -1 if no such subarray is found and return max + 1 otherwise.
        return max + 1 == Integer.MIN_VALUE ? -1 : max;
    }

    private int findLongestSubarray(int[] nums, int startIndex) {
        // This function is used to find the length of longest subarray that can be formed by including the current element in it.

        if (startIndex >= nums.length - 1) { // If the start index is equal to or greater than the last index, return -1.
            return -1;
        }

        int maxLength = 1; // Initialize maxLength variable with 1. This will store the length of longest subarray that can be formed by including the current element in it.

        for (int i = startIndex + 1; i < nums.length; i++) {
            if (nums[i] > threshold / (i - startIndex)) { // Check if the current element is greater than threshold / k where k is the size of the current subarray.
                maxLength = Math.max(maxLength, findLongestSubarray(nums, i)); // Update maxLength variable with the length of longest subarray that can be formed by including the current element in it.
            } else {
                break; // If the current element is not greater than threshold / k, we stop searching for longer subarrays because any further elements will also not satisfy the conditions.
            }
        }

        return maxLength;
    }
}

