            for (int j = 0; j < n; j++) {
                if (i > 0)
                    graph[j].add(i - 1);
                if (j > 0)
                    graph[j].add(j - 1);
                if (i < m - 1)
                    graph[j].add(i + 1);
                if (j < n - 1)
                    graph[j].add(j + 1);

                dfs(i, j);
            }
        }

        int res = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++)
                res += dp[i][j][m * n - 1];
        }

        return res % MOD;
    }

    private void dfs(int x, int y) {
        if (visited.contains(x + "," + y))
            return;

        visited.add(x + "," + y);
