        return dfs(grid, memo);
    }

    private int dfs(int[][] grid, Map<String, Integer> memo) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                String key = i + "," + j;
                if (!memo.containsKey(key)) {
                    memo.put(key, solve(grid, i, j));
                }
            }
        }

        int sum = 0;
        for (Integer value : memo.values()) {
            sum += value;
            sum %= MOD;
        }

        return sum % MOD;
    }

    private int solve(int[][] grid, int x, int y) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
            return 0;
        }

        String key = x + "," + y;

        if (!grid[x][y].equals(String.valueOf(grid[x][y]))) {
            return memo.containsKey(key) ? memo.get(key) : 0;
        } else {
            int sum = 1;

            grid[x][y] = "0";

            for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                sum += solve(grid, x + dir[0], y + dir[1]);
                sum %= MOD;
            }

            grid[x][y] = String.valueOf(grid[x][y]);
            memo.put(key, sum % MOD);

            return sum % MOD;
        }
    }
}

