import java.util.PriorityQueue;

public class Solution {
    public long kSum(int[] nums, int k) {
        Arrays.sort(nums);
        PriorityQueue<Long> pq = new PriorityQueue<>((x,y) -> Long.compare(y,x));

        dfs(0, 0, nums.length-1, 0, nums, pq);

        while (pq.size() > k){
            pq.poll();
        }
        long ans = 0;
        if (!pq.isEmpty()){
            ans = pq.peek();
        }
        return ans;
    }

    private void dfs(int start, int sum, int end, long curSum, int[] nums, PriorityQueue<Long> pq){
        if (start > end || start < 0) {
            return;
        }

        if (pq.size() == k) {
            return;
        }

        curSum += nums[start];
        pq.offer(curSum);

        dfs(start+1, sum, end, curSum, nums, pq);

        dfs(start-1, sum + nums[start], end, curSum - nums[start], nums, pq);

        pq.poll();
    }
}

