        }

        int operations = 0;
        while (!uniqueNums.isEmpty()) {
            int smallestNonZero = Integer.MAX_VALUE;
            for (Integer num : uniqueNums) {
                smallestNonZero = Math.min(smallestNonZero, num);
            }

            boolean updated = false;
            for (int i = 0; i < nums.length; i++) {
