public class Solution {
    public int minimumOperations(int[] nums) {
        Set<Integer> set = new HashSet<>();
        int operations = 0;

        // add all elements to the set, this will remove duplicates and also keep track of non-zero elements
        for (int num : nums) {
            if (num != 0) {
                set.add(num);
            }
        }

        while (!set.isEmpty()) {
            int min = Integer.MAX_VALUE;

            // find the minimum element in the set, this will be our x value
            for (Integer i : set) {
                if (i < min && i > 0) {
                    min = i;
                }
            }

            // remove all elements from the set that are greater than or equal to the minimum element
            for (Iterator<Integer> it = set.iterator(); it.hasNext();) {
                int num = it.next();
                if (num >= min) {
                    it.remove();
                } else {
                    // subtract the minimum element from this number
                    it.remove();
                    int result = num - min;
                    if (result > 0) {
                        it.add(result);
                    }
                }
            }

            set.removeAll(set); // reset the set to start fresh for next operation

            operations++;
        }

        return operations;
    }
}

