public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long sum = 0;
        long score = 1;

        for (int i = 0; i < n; i++) {
            sum += nums[i];
            if (sum >= k / i + 1) break;
            score *= (i + 1);
        }

        long count = 0;
        for (int i = 0; i < n; i++) {
            sum -= nums[i];
            int j = i - 1;
            while (j >= 0 && sum * (i - j) < k) {
                count++;
                j--;
            }
        }

        return count + score - n;
    }
