            union(edge[0], edge[1]);
            totalXor ^= nums[edge[0]] ^ nums[edge[1]];
        }

        int minScore = Integer.MAX_VALUE;

        for (int i = 0; i < n - 1; i++) {
            int src = i;
            blocked[i] = true;
            int xor = findXOR(src);
            minScore = Math.min(minScore, getMinScore(xor));
            blocked[i] = false;
        }

        return minScore;
    }

    private void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    private int find(int x) {
        if (parent[x] == x)
            return x;

        parent[x] = find(parent[x]);
        return parent[x];
    }

    private void setBlocked(int x, boolean blocked) {
        this.blocked[x] = blocked;
    }

    private int getMinScore(int xor) {
        int minScore = Integer.MAX_VALUE;

        for (int i = 0; i < totalXor ^ xor; i++) {
            int maxScore = Math.max(xor, Math.max(i, totalXor ^ (xor ^ i)));
            minScore = Math.min(minScore, maxScore - i);
        }

        return minScore;
    }

    private int findXOR(int src) {
        if (blocked[src])
            return 0;

        int xor = nums[src];

        for (int nbr : getNbrs(src)) {
            if (!blocked[nbr]) {
                xor ^= findXOR(nbr);
            }
        }

        return xor;
    }

    private List<Integer> getNbrs(int src) {
        List<Integer> nbrs = new ArrayList<>();

        for (int[] edge : edges) {
            if ((edge[0] == src && edge[1] != parent[src]) || (edge[1] == src && edge[0] != parent[src])) {
                nbrs.add(edge[(edge[0] == src ? 1 : 0)]);
            }
        }

        return nbrs;
    }
}

