    public int minScore(int[] nums, int[][] edges) {
        n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }
        xorValues = new int[n];
        Arrays.fill(xorValues, -1);
        blocked = new boolean[n];

        // 2nd traversal of the tree to find the second edge to be removed
        for (int i = 0; i < n; i++) {
            if (!blocked[i]) {
                dfs(i, i); // src and parent are same in this case
            }
        }

        int minScore = Integer.MAX_VALUE;
        for (int[] edge : edges) {
            blocked[edge[0]] = true;
            blocked[edge[1]] = true;
            int xor1 = 0, xor2 = 0, xor3 = 0;
            for (int i = 0; i < n; i++) {
                if (!blocked[i]) {
                    xorValues[i] = dfs(i, -1);
                    xor1 ^= xorValues[i];
                    if (xorValues[i] == edge[0] || xorValues[i] == edge[1])
                        xor2 ^= xorValues[i];
                }
            }
            for (int i = 0; i < n; i++) {
                if (!blocked[i]) {
                    xor3 ^= dfs(i, -1);
                    if ((xorValues[i] != edge[0] && xorValues[i] != edge[1]) || (xor2 == edge[0] && xorValues[i] == edge[1]) || (xor2 == edge[1] && xorValues[i] == edge[0]))
                        xor3 ^= xorValues[i];
                }
            }
            minScore = Math.min(minScore, Math.max(Math.max(xor1, xor2), xor3) - Math.min(Math.min(xor1, xor2), xor3));
            blocked[edge[0]] = false;
            blocked[edge[1]] = false;
        }

        return minScore;
    }

    private int dfs(int node, int parent) {
        if (xorValues[node] != -1)
            return xorValues[node];

        List<Integer> children = graph[node];
        boolean isLeaf = true;
        for (int child : children) {
            if (child != parent && !blocked[child]) {
                isLeaf = false;
                xorValues[node] ^= dfs(child, node);
            }
        }

        if (!isLeaf)
            return xorValues[node];

        int xor = 0;
        int max = 0;
        for (int child : children) {
            if (child != parent && !blocked[child])
                xor ^= xorValues[child];
        }
        xorValues[node] = xor;

        return xor;
    }
}

