public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        int n = nums.length;
        Arrays.sort(nums);

        for (int i = 0; i < n; i++) {
            if (nums[i] != nums[n - 1]) {
                return n - i;
            }
        }

        PriorityQueue<Integer> q = new PriorityQueue<>();
        long gcd = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            gcd = getGCD(gcd, numsDivide[i]);
        }

        int count = 0;
        for (int num : nums) {
            if (getGCD(num, (int)gcd) != gcd) {
                q.add(num);
            }
        }

        while (!q.isEmpty()) {
            int temp = q.poll();
            count++;
            int newNumsDivide[] = Arrays.copyOf(numsDivide, numsDivide.length + 1);
            newNumsDivide[newNumsDivide.length - 1] = (int)gcd;
            long gcd1 = getGCD(temp, (int)gcd);

            boolean possible = true;

            for (int num : newNumsDivide) {
                if (getGCD(num, (int)gcd) != gcd || !isDivisible(num, gcd)) {
                    possible = false;
                    break;
                }
            }

            if(possible){
                return count;
            }
            int[] numsCopy = Arrays.copyOf(nums, n + 1);
            boolean found = false;

            for(int i=0;i<n;i++){
                if(getGCD(temp,nums[i])!=gcd && getGCD(temp,(int)gcd)!=gcd){
                    continue;
                }

                if(isDivisible(newNumsDivide[numsCopy[i]],(int)gcd)){
                    numsCopy[i] = (int)gcd;
                    found=true;
                    break;
                }
            }

            long gcd2 = getGCD(gcd1, temp);

            for(int i=0;i<n;i++){
                if(numsCopy[i]==temp){
                    nums[i]=(int)gcd;

                    break;
                }
            }

            for (int num : newNumsDivide) {
                q.add(num);
            }
        }

        return -1;
    }

    private long getGCD(long a, long b) {
        if(a == 0)
            return b;
        else
            return getGCD(b % a, a);
    }

    private boolean isDivisible(int num, int gcd){
        while(num%gcd==0)
            num/=gcd;

        return num ==1;
    }
