public class Solution {
    private int n;
    private long[] prefixSum;
    private UF uf;

    public Solution(int n) {
        this.n = n;
        this.prefixSum = new long[n];
        this.uf = new UF(n);
    }

    public void insert(int x, int value) {
        if (x < 0 || x >= n) return;
        prefixSum[x] += value;
        uf.union(x, x + 1);
    }

    private class UF {
        private int[] parent;
        private int[] size;

        public UF(int n) {
            this.parent = new int[n];
            this.size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) return;

            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }

    public long[] maxSegmentSum(int[] nums, int[] removeQueries) {
        for (int i = 0; i < n; i++) {
            insert(i, nums[i]);
        }

        long[] answer = new long[removeQueries.length];

        for (int i = removeQueries.length - 1; i >= 0; i--) {
            int index = removeQueries[i];
            int root = uf.find(index);

            if (root == index) {
                answer[i] = prefixSum[index];
            } else {
                long sum = 0;
                while (true) {
                    int nextIndex = uf.parent[root];
                    if (nextIndex == root) break;

                    sum += prefixSum[nextIndex];
                    root = nextIndex;
                }
                answer[i] = Math.max(sum, prefixSum[index]);
            }

            for (int j = index - 1; j >= 0; j--) {
                uf.union(j, j + 1);
            }
        }

        return answer;
    }
}

