    int[] size;

    public UF(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
        size = new int[n];
        Arrays.fill(size, 1);
    }

    public void insert(int x, int value) {
        if (!isConnected(x)) {
            parent[x] = x;
            size[parent[x]] = 1;
        }
        updateValue(x, value);
    }

    private boolean isConnected(int a) {
        return find(a) == find(parent[a]);
    }

    private void union(int a, int b) {
        int pa = find(a), pb = find(b);
        if (pa != pb) {
            if (size[pa] > size[pb]) {
                parent[pb] = pa;
                size[pa] += size[pb];
            } else {
                parent[pa] = pb;
                size[pb] += size[pa];
            }
        }
    }

    private void updateValue(int x, int value) {
        if (isConnected(x)) {
            return;
        }
        union(x, x - 1);
        union(x + 1, x);
        updateValue(find(parent[x]), value);
    }

    private int find(int a) {
        while (a != parent[a]) {
            parent[a] = parent[parent[a]];
            a = parent[a];
        }
        return a;
    }
}

