    public long[] maxSegmentSum(int[] nums, int[] removeQueries) {
        UF uf = new UF(nums.length);
        long[] answer = new long[nums.length];

        for (int i = 0; i < removeQueries.length; i++) {
            int index = removeQueries[i];
            if (!uf.isConnected(index)) {
                continue;
            }
            long sum = 0;
            int maxVal = Integer.MIN_VALUE;

            while (index >= 0 && uf.isConnected(index)) {
                maxVal = Math.max(maxVal, nums[index]);
                sum += nums[index--];
            }

            answer[i] = sum - maxVal;
            for (int j = index + 1; j < removeQueries.length; j++) {
                if (!uf.isConnected(removeQueries[j])) {
                    continue;
                }
                uf.union(index + 1, removeQueries[j]);
            }
        }
        return answer;
    }
}

