            // do nothing
        }

        public boolean connected(int x, int y) {
            return find(x) == find(y);
        }

        private int find(int x) {
            if (parent[x] != -1 && parent[parent[x]] != -1)
                parent[x] = find(parent[x]);
            return parent[x];
        }
    }

    public int[] maxSumAfterRemoveQueries(int[] nums, int[] removeQueries) {
        UF uf = new UF(nums.length);
        for (int i = 0; i < nums.length; i++) {
            uf.insert(i, nums[i]);
        }

        int n = nums.length;
        int[] answer = new int[n];
        for (int j = n - 1; j >= 0; j--) {
            int index = removeQueries[j];
            if (!uf.connected(index - 1, index)) {
                uf.segmentSum[index - 1] += Math.max(0, uf.segmentSum[index]);
            }
            answer[n - 1 - j] = Math.max(0, uf.segmentSum[index - 1]);

            for (int k = index + 1; k < n; k++) {
                if (uf.connected(index, k)) {
                    uf.segmentSum[k - 1] += Math.max(0, uf.segmentSum[index]);
                    uf.segmentSum[index]--;
                    break;
                }
            }

        }
        return answer;
