public class Solution {
    int[] parent;
    int[] size;
    long[] sum;
    public UF(int n) {
        parent = new int[n];
        size = new int[n];
        sum = new long[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
            sum[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return;

        if (size[rootX] < size[rootY]) {
            int temp = rootX;
            rootX = rootY;
            rootY = temp;
        }

        parent[rootY] = rootX;
        sum[rootX] += sum[rootY];
        size[rootX] += size[rootY];

    }
}

public class Solution {
    public long[] maxSumAfterRemovingOneElement(int[] nums, int[] removeQueries) {
        UF uf = new UF(nums.length);
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (!map.containsKey(nums[i])) {
                map.put(nums[i], 1);
            } else {
                map.put(nums[i], map.get(nums[i]) + 1);
            }
        }

        long[] res = new long[removeQueries.length];
        for (int i = removeQueries.length - 1; i >= 0; i--) {
            int removeIndex = removeQueries[i];

            if (map.get(nums[removeIndex]) == 1) {
                map.remove(nums[removeIndex]);
            } else {
                map.put(nums[removeIndex], map.get(nums[removeIndex]) - 1);
            }

            long currMaxSum = Long.MIN_VALUE;
            for (int j = removeIndex; j >= 0; j--) {
                int root = uf.find(j);

                if (map.containsKey(uf.size[root] + 1)) {
                    int num = uf.size[root] + 1;
                    long sum = map.get(num) * num;

                    currMaxSum = Math.max(currMaxSum, sum);
                }
            }

            res[i] = currMaxSum;
        }

        return res;
    }
}

