public class Solution {
    public String largestPalindromic(String num) {
        // Convert string to char array and sort it in descending order
        char[] chars = num.toCharArray();
        Arrays.sort(chars);

        // Initialize an empty StringBuilder for the result
        StringBuilder sb = new StringBuilder();

        // Iterate over the sorted character array from left to right
        boolean flag = false;
        for (int i = 0; i < chars.length; i++) {
            if (!flag && chars[i] == '0') continue;
            flag = true;

            // Append the current digit to the StringBuilder, but not more than one zero at a time
            sb.append(chars[i]);

            boolean foundZero = false;
            for (int j = chars.length - 1; j > i; j--) {
                if (chars[j] == '0') {
                    foundZero = true;
                    continue;
                }

                // If the current digit is equal to the corresponding rightmost digit, append it to the StringBuilder
                if (chars[i] == chars[j]) {
                    sb.append(chars[j]);
                    break;
                } else {
                    // If not, try to find a smaller digit on the left side that matches with the current digit on the right side
                    for (int k = i + 1; k < j; k++) {
                        if (chars[k] == chars[j]) {
                            sb.append(chars[k]);
                            break;
                        }
                    }
                }
            }
        }

        // Remove trailing zeros from the StringBuilder
        while (sb.length() > 0 && sb.charAt(sb.length() - 1) == '0') {
            sb.deleteCharAt(sb.length() - 1);
        }

        // If the StringBuilder is empty, return "0"
        if (sb.length() == 0) return "0";

        // Return the result as a string
        return sb.toString();
    }
