public class Solution {
    public String largestPalindromic(String num) {
        Map<Character, Integer> freqMap = new HashMap<>();

        // Count frequency of each digit in the string
        for (char c : num.toCharArray()) {
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
        }

        StringBuilder result = new StringBuilder();

        // Place odd-counted digits in the middle to make it a palindrome
        PriorityQueue<Character> oddCountQueue = new PriorityQueue<>((c1, c2) -> Integer.compare(freqMap.get(c1), freqMap.get(c2)));
        for (char c : freqMap.keySet()) {
            if ((freqMap.get(c) & 1) != 0) {
                oddCountQueue.offer(c);
            }
        }

        // Place even-counted digits on the outside
        PriorityQueue<Character> evenCountQueue = new PriorityQueue<>((c1, c2) -> Integer.compare(freqMap.get(c1), freqMap.get(c2)));
        for (char c : freqMap.keySet()) {
            if ((freqMap.get(c) & 1) == 0) {
                evenCountQueue.offer(c);
            }
        }

        // Construct the largest palindromic integer
        while (!oddCountQueue.isEmpty() || !evenCountQueue.isEmpty()) {
            if (result.length() % 2 == 0) {
                result.append(evenCountQueue.poll());
            } else {
                result.append(oddCountQueue.poll());
            }

            // Append the other half of the palindrome
            if (!result.toString().equals(String.valueOf(result.charAt(result.length() - 1)))) {
                result.insert(result.length() / 2, oddCountQueue.poll() + "");
            }
        }

        return "0".equals(result.toString()) ? "0" : result.insert(0, num.length() <= 1 ? "" : "1").toString();
    }
