import java.util.Arrays;

public class Solution {
    static final int MOD = 1000000007;

    public int idealArrays(int n, int maxValue) {
        long[] dp = new long[maxValue + 1];
        Arrays.fill(dp, 1);

        for (int i = 2; i <= maxValue; ++i) {
            for (int j = i; j * i <= maxValue; ++j) {
                dp[i] *= dp[j * i / i];
                dp[i] %= MOD;
            }
        }

        long ans = 0;
        for (long i : dp) {
            ans += i % MOD * factorial(n - 1, MOD);
            ans %= MOD;
        }

        return (int)ans;
    }

    static long factorial(int n, int mod) {
        if (n == 0 || n == 1) {
            return 1;
        } else {
            long result = 1;
            for (int i = 2; i <= n; ++i) {
                result *= i % mod;
                result %= mod;
            }
            return result;
        }
    }
}

