public class Solution {
    public int idealArrays(int n, int maxValue) {
        if (n == 0 || maxValue < 1)
            return 1;

        BigInteger MOD = new BigInteger("1000000007");
        BigInteger[] factorCount = new BigInteger[maxValue + 1];
        Arrays.fill(factorCount, BigInteger.ONE);

        for (int i = 2; i <= maxValue; ++i) {
            for (BigInteger j = i * i; j <= maxValue; j += i) {
                BigInteger count = factorCount.get(j.divide(i.intValue()).intValue());
                factorCount.set(j.intValue(), factorCount.get(j.intValue()).add(count));
