        BigInteger total = factorCount[1];
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; ++i) {
            result = total.multiply(result).mod(MOD);
            total = total.multiply(factorCount[i]).mod(MOD);
        }

        return result.intValue();
    }
}

