import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int fillCups(int[] amount) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int num : amount) {
            if (num > 0) pq.offer(num);
        }

        int seconds = 0;
        while (!pq.isEmpty()) {
            int smallest = pq.poll();

            // If there is still one cup left to fill, we cannot fill two cups.
            if (pq.peek() == null || !pq.contains(1)) {
                break;
            }

            // Fill two cups
            seconds++;
            if (smallest > 0) pq.offer(smallest - 2);
        }

        return seconds + Math.max(amount[0], Math.max(amount[1], amount[2]));
    }
}

