public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;

        // Create a dp array where dp[i] will be true if the subarray from index 0 to i has at least one valid partition.
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // The empty subarray is always valid.

        for (int i = 1; i <= n; i++) {
            if (i > 1 && nums[i - 1] == nums[i - 2]) { // If the current element and its previous one are equal, then we can create a new partition.
                dp[i] |= dp[i - 2];
            }

            if (i >= 2 && nums[i - 1] == nums[i - 2] && nums[i - 2] == nums[i - 3]) { // If the current element and its previous two are equal, then we can create a new partition.
                dp[i] |= dp[i - 3];
            }

            if (i >= 3) {
                boolean increasing = (nums[i - 1] > nums[i - 2] && nums[i - 2] > nums[i - 3]);
                if (increasing) { // If the current element and its previous two are consecutive increasing, then we can create a new partition.
                    dp[i] |= dp[i - 3];
                }
            }
        }

        return dp[n]; // Return true if there is at least one valid partition for the entire array.
    }
}

