public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;

        // Dynamic programming table where dp[i] will store whether we can get a valid partition up to index 'i'
        boolean[] dp = new boolean[n + 1];

        // Base case: empty array is always a valid partition
        dp[0] = true;

        for (int i = 2; i <= n; ++i) {
            if (nums[i-1] == nums[i-2]) {
                // If the current pair of elements are equal, use previous results to see if we can get a valid partition up to index 'i'
                dp[i] |= dp[i - 2];
            }

            if (i >= 3 && nums[i - 1] == nums[i - 2] && nums[i-2] == nums[i-3]) {
                // If the current triplet of elements are equal, use previous results to see if we can get a valid partition up to index 'i'
                dp[i] |= dp[i - 3];
            }

            int prev = i - 1;
            while (prev > 0) {
                if ((nums[i-1] == nums[prev-1]) && (nums[prev-2] == nums[prev-1]-1) && (nums[prev-1] == nums[prev-2]-1)) {
                    // If the current subarray of length at least 3 is a valid consecutive increasing partition, use previous results to see if we can get a valid partition up to index 'i'
                    dp[i] |= dp[prev - 3];
                }
                prev--;
            }
        }

        return dp[n];
    }
}

