public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int[] dist = new int[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, edges, visited, dist);
            }
        }

        int maxCycleLength = -1;

        for (int i = 0; i < n; i++) {
            if (dist[i] != 0) {
                maxCycleLength = Math.max(maxCycleLength, dist[i]);
            }
        }

        return maxCycleLength;
    }

    private void dfs(int node, int[] edges, boolean[] visited, int[] dist) {
        if (visited[node]) {
            if (dist[node] == 0) {
                return; // not a cycle
            } else {
                dist[node] = Math.max(dist[node], dist[edges[node]] + 1);
            }
        }

        visited[node] = true;
        dist[node]++;

        int nextNode = edges[node];
        if (nextNode != -1) {
            dfs(nextNode, edges, visited, dist);
        }
    }
}

