    private void dfs(int[] edges, int node, boolean[] visited, int[] depth, int maxCycleLength) {
        if (depth[node] > 0) {
            int cycleLength = node - depth[node];
            maxCycleLength = Math.max(maxCycleLength, cycleLength);
        }

        visited[node] = true;
        depth[node]++;

        int nextNode = edges[node];
        if (nextNode != -1 && !visited[nextNode]) {
            dfs(edges, nextNode, visited, depth, maxCycleLength);
        } else if (nextNode != -1) {
            return;
        }

        visited[node] = false;
    }
