        // recursively visit that node and mark it as its parent
        if (edges[node] != -1 && !visited[edges[node]]) {
            parent[edges[node]] = node;
            return dfs(edges, adjList, edges[node], visited, parent);
        }

        // If there is no edge from the current node to another node,
        // it means we have encountered a cycle
        if (adjList[node] == 0) {
            return false;
        }

        int nextNode = -1;
        for (int i = edges.length - 1; i >= 0 && nextNode == -1; i--) {
            if (edges[i] != node && adjList[edges[i]] > 0) {
                nextNode = edges[i];
                parent[nextNode] = node;
                break;
            }
        }

        return dfs(edges, adjList, nextNode, visited, parent);
    }

    private int getLongestCycle(int[] parent) {
        if (parent == null || parent.length <= 1) {
            return -1;
        }

        int maxLength = 0;
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] != -1 && parent[parent[i]] == i) {
                int length = 1;
                while (parent[i] != -1) {
                    i = parent[i];
                    length++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }

        return maxLength;
    }
}

