// #Hard #Depth_First_Search #Graph #Topological_Sort
// #2022_08_14_Time_37_ms_(90.19%)_Space_102.8_MB_(72.92%)
public class Solution {
    public int longestCycle(int[] edges) {
        boolean[] visited = new boolean[edges.length];
        for (int i = 0; i < edges.length; i++) {
            if (!visited[i]) {
                int cycleLength = findCycle(i, edges, visited);
                if (cycleLength != -1) {
                    return cycleLength;
                }
            }
        }

        // If no cycle is found, try to form a cycle starting from
        // any node and going back to itself. This can only happen when a 
        // node has an edge pointing back to itself.
        for (int i = 0; i < edges.length; i++) {
            if (edges[i] == i) {
                return 1;
            }
        }

        return -1; // No cycle found
    }

    private int findCycle(int start, int[] edges, boolean[] visited) {
        visited[start] = true;

        for (int i = start;; i = edges[i]) {
            if (!visited[i]) {
                if (findCycle(i, edges, visited) != -1) {
                    return 1 + findCycle(i, edges, visited);
                }
            } else if (i == start && edges[start] != -1) {
                // Found a cycle
                return i - start + 1;
            }

            visited[i] = true;
        }
    }
}

