// #Hard #Depth_First_Search #Graph #Topological_Sort
// #2022_08_14_Time_37_ms_(90.19%)_Space_102.8_MB_(72.92%)
public class Solution {
    private int result = -1;

    public int longestCycle(int[] edges) {
        for (int i = 0; i < edges.length; i++) {
            if (edges[i] == -1) continue;

            boolean[] visited = new boolean[edges.length];
            if (dfs(edges, i, visited)) break;
        }

        return result;
    }

    private boolean dfs(int[] edges, int node, boolean[] visited) {
        if (node == -1 || visited[node]) return false;
        visited[node] = true;

        if (edges[node] != -1 && !dfs(edges, edges[node], visited)) {
            result = Math.max(result, getDistance(edges, node));
            return true;
        }

        return false;
    }

    private int getDistance(int[] edges, int start) {
        boolean[] visited = new boolean[edges.length];
        int count = 0;

        while (start != -1 && !visited[start]) {
            visited[start] = true;
            start = edges[start];

            if (++count > result) return Integer.MAX_VALUE;
        }

        return count;
    }
}

