public class Solution {
    public boolean evaluateTree(TreeNode root) {
        return dfs(root);
    }

    private boolean dfs(TreeNode node) {
        if (node == null) {
            return false;
        }

        // If the node is a leaf, its value represents True or False
        if (node.left == null && node.right == null) {
            return node.val == 1;
        }

        // Evaluate the children and apply the boolean operation of the current node
        boolean left = dfs(node.left);
        boolean right = dfs(node.right);

        switch (node.val) {
            case 2: // OR operation
                return left || right;
            case 3: // AND operation
                return left && right;
            default:
                throw new RuntimeException("Invalid node value");
        }
    }
}

