        for (int count : suitCount.values()) {
            if (count == 5) {
                return true;
            }
        }
        return false;
    }

    private boolean getThreeOfAKind(int[] rankCount) {
        for (int i = 0; i < rankCount.length; i++) {
            if (rankCount[i] >= 3) {
                return true;
            }
        }
        return false;
    }

    private boolean getPair(int[] rankCount) {
        for (int i = 0; i < rankCount.length; i++) {
            if (rankCount[i] == 2) {
                return true;
            }
        }
        return false;
    }
