import java.util.HashMap;

public class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        HashMap<Character, Integer> suitMap = new HashMap<>();

        for (char suit : suits) {
            suitMap.put(suit, suitMap.getOrDefault(suit, 0) + 1);

            if (suitMap.get(suit) == 5) {
                return "Flush";
            }
        }

        HashMap<Integer, Integer> rankMap = new HashMap<>();

        for (int rank : ranks) {
            rankMap.put(rank, rankMap.getOrDefault(rank, 0) + 1);

            if (rankMap.get(rank) >= 4) {
                return "Four of a Kind";
            } else if (rankMap.get(rank) == 3) {
                return "Three of a Kind";
            }
        }

        for (int rank : ranks) {
            if (rankMap.get(rank) == 2) {
                return "Pair";
            }
        }

        boolean hasSameRank = false;

        for (int i = 0; i < ranks.length - 1; i++) {
            if (ranks[i] == ranks[i + 1]) {
                hasSameRank = true;
                break;
            }
        }

        if (!hasSameRank) {
            return "High Card";
        } else {
            return "Pair"; // This is the worst case of pair, where only two pairs exist.
        }
    }
}

