import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        // Calculate absolute differences and store them in an array along with their counts.
        int n = nums1.length;
        int[] diffs = new int[n];
        for (int i = 0; i < n; i++) {
            diffs[i] = Math.abs(nums1[i] - nums2[i]);
        }

        // Sort the differences in descending order.
        Arrays.sort(diffs);
        reverseArray(diffs);

        long totalDifferences = 0;
        for (int diff : diffs) {
            totalDifferences += diff;
        }

        int kSum = k1 + k2;

        if (kSum < totalDifferences) {
            // If we can make all numbers/differences 0s, return the remaining differences.
            long remainingDiffs = totalDifferences - kSum;
            return remainingDiffs * (long) remainingDiffs;
        }

        int i = 0;
        while (kSum > 0 && i < n) {
            if (diffs[i] <= kSum) {
                // If current group has more differences than the totalK, we can only move k of them
                // to the lower level.
                long diffToMove = Math.min(kSum, diffs[i]);
                kSum -= (int) diffToMove;
                totalDifferences -= 2 * diffToMove;
            } else {
                // We can make this whole group one level lower.
                long diffToMove = diffs[i];
                kSum -= (int) diffToMove;
                totalDifferences -= 2 * diffToMove;
            }
            i++;
        }

        return totalDifferences * (long) totalDifferences;
    }

    private void reverseArray(int[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
    }
}

