public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        long totalDifferences = 0;
        for (int i = 0; i < nums1.length; i++) {
            totalDifferences += Math.abs(nums1[i] - nums2[i]);
        }

        PriorityQueue<Integer> diffHeap = new PriorityQueue<>((a, b) -> b - a);
        int[] diffs = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            diffs[i] = Math.abs(nums1[i] - nums2[i]);
            if (diffs[i] > 0) {
                diffHeap.offer(diffs[i]);
            }
        }

        int kSum = k1 + k2;
        while (!diffHeap.isEmpty() && kSum >= diffHeap.peek()) {
            int currentDiff = diffHeap.poll();
            long currentK = Math.min(k1, k2);
            if (currentK > 0) {
                totalDifferences -= currentDiff * 2;
                k1 -= currentK;
                k2 -= currentK;
            } else {
                break;
            }
        }

        return totalDifferences;
    }
}

