public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        int[] diffs = new int[n];

        for (int i = 0; i < n; i++) {
            diffs[i] = Math.abs(nums1[i] - nums2[i]);
        }

        Arrays.sort(diffs);

        PriorityQueue<Integer> pq = new PriorityQueue<>(k1 + k2, (a, b) -> b - a);

        long totalDifferences = 0;
        for (int diff : diffs) {
            totalDifferences += diff * diff;
            if (diff > 0) {
                pq.offer(diff);
            }
        }

        if ((k1 + k2) < totalDifferences) {
            return totalDifferences;
        }

        long remainingK = k1 + k2 - diffs.length;
        for (int i = diffs.length - 1; i >= 0 && remainingK > 0; i--) {
            int groupSize = 0;
            while (!pq.isEmpty() && pq.peek() == diffs[i] && groupSize < Math.min(remainingK, k1 + k2)) {
                pq.poll();
                groupSize++;
                remainingK--;
            }

            if (groupSize > 0) {
                totalDifferences -= groupSize * diffs[i] * diffs[i];
                totalDifferences += (groupSize - 1) * diffs[i] * diffs[i];
                i--;
            }
        }

        return totalDifferences;
    }
}

