public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        Pair[] pairs = new Pair[n];

        for (int i = 0; i < n; i++) {
            pairs[i] = new Pair(nums1[i], nums2[i]);
        }

        Arrays.sort(pairs, Comparator.comparingInt(a -> a.diff));

        int totalDifferences = 0;
        for (Pair pair : pairs) {
            totalDifferences += Math.abs(pair.diff);
        }

        long res = 0;
        k1 -= totalDifferences;
        k2 -= totalDifferences;

        for (int i = n - 1; i >= 0 && k1 + k2 > 0; i--) {
            int diff = pairs[i].diff;
            if (Math.abs(diff) <= Math.min(k1, k2)) {
                res += (long) diff * diff;
                k1 -= Math.abs(diff);
                k2 -= Math.abs(diff);
            } else {
                int min = Math.min(k1, k2);
                res += (long) diff * diff - 2 * (min) * diff + (long) min * min;
                k1 -= min;
                k2 -= min;
            }
        }

        return res;
    }

    static class Pair {
        int num1;
        int num2;
        int diff;

        public Pair(int num1, int num2) {
            this.num1 = num1;
            this.num2 = num2;
            this.diff = Math.abs(num1 - num2);
        }
    }
}

