public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;

        for (int i = 0; i < n; i++) {
            if ((i == 0 || i == n - 1) && !checkFirstLastNonZero(grid, i)) return false;
            if (!checkMiddleElements(grid, i)) return false;
            if (grid[i][i] == 0 || grid[i][n-i-1] == 0) return false;
        }

        return true;
    }

    private boolean checkFirstLastNonZero(int[][] grid, int row) {
        for (int col = 0; col < grid[row].length; col++) {
            if (col != row && col != grid[row].length - row - 1 && grid[row][col] == 0) return false;
        }

        return true;
    }

    private boolean checkMiddleElements(int[][] grid, int row) {
        for (int i = row + 1; i < row + grid.length - 2; i++) {
            if (grid[i][row] == 0 || grid[row][i] == 0 || grid[i][grid.length-1-row] == 0 
                || grid[grid.length-1-row][i] == 0) return false;
        }

        return true;
    }
}

