public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        Map<Integer, Map<Integer, Integer>> memo = new HashMap<>();
        return max(memo, m, n, prices);
    }

    private int max(Map<Integer, Map<Integer, Integer>> memo, int height, int width, int[][] prices) {
        if (memo.containsKey(height) && memo.get(height).containsKey(width)) {
            return memo.get(height).get(width);
        }
        long maxProfit = 0;
        for (int[] price : prices) {
            int h = price[0], w = price[1];
            if (height >= h && width >= w) {
                long cutVertically = max(memo, height - h, width, prices) + price[2];
                long cutHorizontally = max(memo, height, width - w, prices) + price[2];
                maxProfit = Math.max(maxProfit, Math.max(cutVertically, cutHorizontally));
            }
        }
        memo.putIfAbsent(height, new HashMap<>());
        memo.get(height).putIfAbsent(width, (int)maxProfit);
        return (int)maxProfit;
    }
}

