public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        Arrays.sort(prices, (a, b) -> a[0] * a[1] - b[0] * b[1]);

        HashMap<String, Long> dp = new HashMap<>();
        return dfs(m, n, 0, prices, dp);
    }

    private long dfs(int m, int n, int index, int[][] prices, HashMap<String, Long> dp) {
        String key = m + "*" + n;

        if (dp.containsKey(key)) return dp.get(key);

        long maxProfit = 0;

        for (int i = index; i < prices.length; i++) {
            int h = prices[i][0], w = prices[i][1];

            if (h <= m && w <= n) {
                long cutVertical = dfs(m, Math.min(h, n), i + 1, prices, dp);

                // check if we can sell pieces of size h*n
                if (m >= h && n >= w) {
                    long cutHorizontal = dfs(Math.min(m, h), n, i + 1, prices, dp);

                    maxProfit = Math.max(maxProfit,
                            cutVertical + cutHorizontal +
                            prices[i][2]);
                } else {
                    maxProfit = Math.max(maxProfit,
                            cutVertical + prices[i][2]);
                }
            }
        }

        dp.put(key, maxProfit);
        return maxProfit;
    }
}

