public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        Map<Integer, Map<Integer, Long>> dp = new HashMap<>();

        return (long) dfs(m, n, prices, 0, dp);
    }

    private long dfs(int m, int n, int[][] price, long currentMaxProfit, Map<Integer, Map<Integer, Long>> dp){

        if(dp.containsKey(m) && dp.get(m).containsKey(n)){
            return dp.get(m).get(n);
        }

        // base case
        if(m == 1 && n == 1){
            return price[0][2];
        }

        long maxProfit = 0;

        for(int i=1; i<m; i++){

            long leftValue = dfs(i, n, price, currentMaxProfit, dp);
            long rightValue = 0;
            if(m-i > n){
                rightValue = dfs(m-i, n, price, currentMaxProfit+leftValue, dp);
            }else{
                rightValue = dfs(m-i, m-i, price, currentMaxProfit+leftValue, dp);
            }
            maxProfit = Math.max(maxProfit, leftValue + rightValue);
        }

        for(int i=1; i<n; i++){

            long upValue = dfs(m, i, price, currentMaxProfit, dp);
            long downValue = 0;
            if(n-i > m){
                downValue = dfs(m, n-i, price, currentMaxProfit+upValue, dp);
            }else{
                downValue = dfs(m, n-i, price, currentMaxProfit+upValue, dp);
            }
            maxProfit = Math.max(maxProfit, upValue + downValue);
        }

        dp.getOrDefault(m, new HashMap<>()).put(n, (long)maxProfit);
        return (long)maxProfit;
    }
}

