public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Create a boolean array to store whether each column is selected or not
        boolean[] colSelected = new boolean[n];

        // Initialize the count of covered rows
        int maxCoveredRows = 0;

        // Iterate over all possible combinations of numSelect columns
        for (int i = 1; i <= (1 << n); i++) {
            // Check if this combination has exactly numSelect columns selected
            boolean isNumSelect = false;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    colSelected[j] = true;
                    isNumSelect |= colSelected[j];
                }
            }

            // If this combination has exactly numSelect columns selected
            if (isNumSelect && countCoveredRows(matrix, colSelected) > maxCoveredRows) {
                // Update the maximum number of covered rows
                maxCoveredRows = countCoveredRows(matrix, colSelected);
            }

            // Reset the column selection for the next combination
            for (int j = 0; j < n; j++) {
                colSelected[j] = false;
            }
        }

        return maxCoveredRows;
    }

    private int countCoveredRows(int[][] matrix, boolean[] colSelected) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Initialize the count of covered rows
        int coveredRows = 0;

        // Iterate over each row in the matrix
        for (int i = 0; i < m; i++) {
            boolean isRowCovered = true;
            // Check if all cells in this row are covered by the selected columns
            for (int j = 0; j < n; j++) {
                if ((matrix[i][j] == 1) && !colSelected[j]) {
                    isRowCovered = false;
                    break;
                }
            }

            // If this row is covered, increment the count of covered rows
            if (isRowCovered) {
                coveredRows++;
            }
        }

        return coveredRows;
    }
}

