public class Solution {

    public int maximumRows(int[][] matrix, int numSelect) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        boolean[] selectedCols = new boolean[cols];
        int maxCoveredRows = 0;

        for (int mask = 1; mask < (1 << cols); ++mask) {
            int coveredRows = 0;

            boolean isValidMask = true;
            for (int row = 0; row < rows && isValidMask; ++row) {
                int bitMask = 0;
                for (int col = 0; col < cols; ++col) {
                    if ((mask & (1 << col)) > 0 && matrix[row][col] == 1) {
                        bitMask |= (1 << col);
                    }
                }

                if (bitMask != mask) {
                    isValidMask = false;
                } else {
                    coveredRows++;
                }
            }

            if (!isValidMask || coveredRows < numSelect) {
                continue;
            }

            for (int i = 0; i < cols; ++i) {
                if ((mask & (1 << i)) > 0) {
                    selectedCols[i] = true;
                } else {
                    selectedCols[i] = false;
                }
            }

            int coveredRowsWithMask = 0;

            for (int row = 0; row < rows; ++row) {
                boolean isCoveredRow = true;
                for (int col = 0; col < cols && isCoveredRow; ++col) {
                    if ((mask & (1 << col)) > 0 && matrix[row][col] == 1 && !selectedCols[col]) {
                        isCoveredRow = false;
                    }
                }

                if (isCoveredRow) {
                    coveredRowsWithMask++;
                }
            }

            maxCoveredRows = Math.max(maxCoveredRows, coveredRowsWithMask);
        }

        return maxCoveredRows;
    }
}

