public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Create a boolean array to store whether each column is selected or not.
        boolean[] colSelected = new boolean[n];

        // Iterate over each row in the matrix
        for (int i = 0; i < m; i++) {
            // Iterate over each cell in the current row
            for (int j = n - 1; j >= 0; j--) {
                // If the current cell is 1 and we have not yet selected numSelect columns, select this column.
                if (matrix[i][j] == 1 && !colSelected[j]) {
                    colSelected[j] = true;
                    break;
                }
            }
        }

        // Initialize variables to store the maximum number of rows that can be covered and the current number of rows that can be covered.
        int maxRows = 0, currRows = 0;

        // Iterate over each row in the matrix
        for (int i = 0; i < m; i++) {
            // Initialize a variable to store whether all cells in the current row are selected or not.
            boolean rowSelected = true;

            // Iterate over each cell in the current row
            for (int j = n - 1; j >= 0; j--) {
                // If the current cell is 1 and its column is not selected, set rowSelected to false.
                if (matrix[i][j] == 1 && !colSelected[j]) {
                    rowSelected = false;
                    break;
                }
            }

            // If all cells in the current row are selected or we have already selected numSelect columns, increment currRows and update maxRows if necessary.
            if (rowSelected || numSelect > 0) {
                currRows++;

                if (currRows > maxRows) {
                    maxRows = currRows;

                    // If we have already selected numSelect columns, reset currRows to 1
                    if (numSelect > 0 && currRows - maxRows == numSelect) {
                        currRows = 1;
                    }
                }

                // If we have not yet selected numSelect columns and the current row is fully covered, decrement numSelect.
                if (numSelect > 0 && rowSelected && currRows - maxRows == numSelect) {
                    numSelect--;
                }
            }
        }

        return maxRows;
    }
}

