// #2022_09_14_Time_1_ms_(100.00%)_Space_40.7_MB_(93.95%)
public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        boolean[] choose = new boolean[n];
        int res = 0;

        for (int i = 0; i < (1 << n); i++) {
            boolean valid = true;
            int count = 0;

            // choose column by bit
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    count++;
                    choose[j] = true;
                } else {
                    choose[j] = false;
                }

                // check row validity
                boolean allOnes = true;
                for (int k = 0; k < m && allOnes; k++) {
                    if ((i & (1 << matrix[k][j])) == 0) {
                        allOnes = false;
                    }
                }

                valid &= allOnes;
            }

            // update result
            if (valid && count <= numSelect) {
                int coveredRows = 0;
                for (int k = 0; k < m; k++) {
                    boolean covered = true;
                    for (int j = 0; j < n && covered; j++) {
                        if ((i & (1 << j)) == 0 && matrix[k][j] != 0) {
                            covered = false;
                        }
                    }

                    if (covered) {
                        coveredRows++;
                    }
                }

                res = Math.max(res, coveredRows);
            }
        }

        return res;
    }
}

