public class Solution {
    public int maximumXOR(int[] nums) {
        // Initialize a Trie data structure using a Binary Search Tree (BST)
        TrieNode root = new TrieNode();

        for (int num : nums) {
            insert(root, num);
        }

        // Perform DFS to find the maximum XOR value
        int maxRes = 0;
        dfs(root, 0, maxRes);

        return maxRes;
    }

    private class TrieNode {
        TrieNode left;
        TrieNode right;

        public TrieNode() {
            this.left = null;
            this.right = null;
        }
    }

    // Insert a number into the Trie
    private void insert(TrieNode root, int num) {
        TrieNode current = root;

        for (int i = 31; i >= 0; --i) {
            if ((num & (1 << i)) != 0) { // If bit at position 'i' is set in the number
                if (current.right == null) {
                    current.right = new TrieNode();
                }
                current = current.right;
            } else {
                if (current.left == null) {
                    current.left = new TrieNode();
                }
                current = current.left;
            }
        }
    }

    // Perform DFS to find the maximum XOR value
    private void dfs(TrieNode root, int curXOR, int maxRes) {
        if (root == null || root.left == null && root.right == null) return;

        curXOR ^= 1; // Flip the current bit

        // Try both possibilities: left and right child
        dfs(root.left, curXOR, maxRes);
        dfs(root.right, curXOR, maxRes);

        curXOR ^= 1; // Backtrack to original state

        if (root == null || root.left == null && root.right == null) return;

        // Update the maximum result
        maxRes = Math.max(maxRes, curXOR);
    }
}

