public class Solution {
    public int minimumRecolors(String blocks, int k) {
        int minOperations = Integer.MAX_VALUE;

        // Check if there are at least k black blocks in the string
        boolean hasKBlackBlocks = false;
        for (int i = 0; i <= blocks.length() - k; i++) {
            int count = 0;
            for (int j = i; j < i + k; j++) {
                if (blocks.charAt(j) == 'B') {
                    count++;
                }
            }
            if (count >= k) {
                hasKBlackBlocks = true;
                break;
            }
        }

        // If there are no k black blocks, return -1
        if (!hasKBlackBlocks) {
            return -1;
        }

        int left = 0;
        int right = k - 1;

        while (right < blocks.length()) {
            // Count the number of white blocks in the current window
            int count = 0;
            for (int i = left; i <= right; i++) {
                if (blocks.charAt(i) == 'W') {
                    count++;
                }
            }

            minOperations = Math.min(minOperations, count);

            // Move the window to the right
            left++;
            right++;
        }

        return minOperations;
    }
}

