public class Solution {
    public int minimumRecolors(String blocks, int k) {
        int min = Integer.MAX_VALUE;

        // Check if there are enough black blocks at the beginning.
        int leftBlackCount = 0;
        for (int i = 0; i < k; ++i) {
            if (blocks.charAt(i) == 'B') {
                leftBlackCount++;
            }
        }
        min = Math.min(min, k - leftBlackCount);

        // Slide the window to find the minimum number of operations.
        for (int i = 0; i <= blocks.length() - k; ++i) {
            if (blocks.charAt(i) == 'B') {
                leftBlackCount++;
            }

            if (leftBlackCount < k) {
                continue;
            }

            // If there are enough black blocks in the current window, 
            // calculate the number of operations needed to make all blocks in this window black.
            int rightBlackCount = 0;
            for (int j = i; j < i + k; ++j) {
                if (blocks.charAt(j) == 'B') {
                    rightBlackCount++;
                }
            }

            // The number of operations needed is the difference between the total blocks in the window and 
            // the black blocks in the window.
            min = Math.min(min, k - leftBlackCount + k - rightBlackCount);
        }

        return min;
    }
}

