    public int minimumRecolors(String blocks, int k) {
        int minOperations = Integer.MAX_VALUE;

        // Calculate prefix sum of white blocks
        int[] prefixSum = new int[blocks.length()];
        int prefixSumValue = 0;
        for (int i = 0; i < blocks.length(); i++) {
            if (blocks.charAt(i) == 'W') {
                prefixSum[i] = ++prefixSumValue;
            }
        }

        // Calculate minimum operations needed
        for (int i = k - 1; i < blocks.length(); i++) {
            int currentOperations = prefixSum[i];
            if (i >= k) {
