public class Solution {
    public int minimumRecolors(String blocks, int k) {
        if (k > blocks.length()) return -1;

        int left = 0;
        int blackCount = 0;

        for (int right = 0; right < blocks.length(); right++) {
            if (blocks.charAt(right) == 'B') {
                blackCount++;
            }

            if (right >= k - 1) {
                if (blackCount == k) return 0;

                int removeCount = blocks.substring(left, left + k).indexOf('W');
                if (removeCount != -1) blackCount -= removeCount;

                if (left < right && blackCount < k) {
                    left++;
                    blackCount += blocks.charAt(left) == 'B' ? 1 : -1;
                } else {
                    left++;
                }
            }
        }

        return blackCount;
    }
}

