        // Start the topo sort
        List<List<Integer>> result = new ArrayList<>();
        while (!queue.isEmpty()) {
            int node = queue.poll();
            result.add(new ArrayList<>(Arrays.asList(node)));
            for (int neighbor : graph.get(node)) {
                indegrees[neighbor]--;
                if (indegrees[neighbor] == 0) {
                    queue.offer(neighbor);
