        for (int[] pair : colC) {
            map.put(pair[1], map.getOrDefault(pair[1], 0) + 1);
            if (map.get(pair[1]) == 2) return new int[k][k];
        }

        List<int[]> row = new ArrayList<>();
        // Map each number to its corresponding column index
        for (int[] pair : colC) {
            row.add(new int[]{pair[0], map.getOrDefault(pair[1], 0)});
        }

        List<Integer> order = new ArrayList<>();
        // Topological sort
        Queue<Integer> queue = new LinkedList<>();
        int[] indegree = new int[k + 1];
        for (int i = 1; i <= k; ++i) {
