                indegree[i] = 1;
            }
        }

        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int[] pair : row) {
                if (pair[0] == node && (--indegree[pair[1]] == 0)) {
                    order.add(pair[1]);
                    queue.offer(pair[1]);
                }
