        }

        return sb.toString();
    }

    // Find the index of the `k`-th smallest trimmed number in sorted array
    private int findIndex(String s, int k) {
        for (int i = 0; i < s.length(); i++) {
            if (i == k) return nums.indexOf(s.substring(0, Math.min(i + 1, s.length())));
        }

        // If we reach here, it means `k` is greater than the number of unique strings
        throw new RuntimeException("k is out of range");
    }

    // The original array of strings
    private String[] nums;
}

