public class Solution {
    public String smallestNumber(String pattern) {
        StringBuilder sb = new StringBuilder();
        int[] num = new int[10];

        for (int i = 0; i < pattern.length(); i++) {
            if (pattern.charAt(i) == 'D') {
                // find the largest number that is greater than the previous one
                int prev = -1;
                for (int j = 9; j >= 0; j--) {
                    if (num[j] != 1 && (prev == -1 || num[j] > num[prev])) {
                        sb.append((char)('0' + j));
                        num[j] = 1;
                        prev = j;
                        break;
                    }
                }
            } else {
                // find the smallest number that is less than the previous one
                int prev = -1;
                for (int j = 9; j >= 0; j--) {
                    if (num[j] != 1 && (prev == -1 || num[j] < num[prev])) {
                        sb.append((char)('0' + j));
                        num[j] = 1;
                        prev = j;
                        break;
                    }
                }
            }
        }

        // append the remaining numbers
        for (int i = 9; i >= 0; i--) {
            if (num[i] == 0) {
                sb.append((char)('0' + i));
            }
        }

        return sb.toString();
    }
