public class Solution {
    public String smallestNumber(String pattern) {
        StringBuilder sb = new StringBuilder();
        sb.append('1');

        int prev = 9;
        for (char c : pattern.toCharArray()) {
            if (c == 'D') {
                // Find the largest digit that is smaller than the previous number
                int next = findNextDigit(prev, true);
                sb.append(next);
                prev = next;
            } else {
                // Find the smallest digit that is larger than the previous number
                int next = findNextDigit(prev, false);
                sb.append(next);
                prev = next;
            }
        }

        return sb.toString();
    }

    private int findNextDigit(int prev, boolean decreasing) {
        for (int i = 9; i > 0; --i) {
            if ((decreasing && i < prev) || (!decreasing && i > prev)) {
                return i;
            }
        }
        throw new RuntimeException("No valid digit found");
    }
}

