public class Solution {
    public String smallestNumber(String pattern) {
        int n = pattern.length();
        StringBuilder num = new StringBuilder("1");
        List<Integer> availableDigits = new ArrayList<>();
        for (int i = 0; i < 9; ++i) {
            availableDigits.add(i + 2);
        }

        for (char c : pattern.toCharArray()) {
            if (c == 'I') {
                int minIndex = getMinIndex(availableDigits, num.length());
                num.append(minIndex);
                availableDigits.remove((Integer)minIndex);
            } else if (c == 'D') {
                int maxIndex = getMaxIndex(availableDigits, num.length());
                num.append(maxIndex);
                availableDigits.remove((Integer)maxIndex);
            }
        }

        return num.toString();
    }

    private int getMinIndex(List<Integer> availableDigits, int length) {
        Collections.sort(availableDigits);
        for (int i = 0; i < availableDigits.size(); ++i) {
            if ((length + i) >= availableDigits.get(i)) {
                continue;
            } else {
                return availableDigits.get(i);
            }
        }
        return -1;
    }

    private int getMaxIndex(List<Integer> availableDigits, int length) {
        Collections.sort(availableDigits);
        for (int i = 0; i < availableDigits.size(); ++i) {
            if ((length + i) >= availableDigits.get(availableDigits.size() - 1)) {
                return availableDigits.get(availableDigits.size() - 1);
            } else {
                continue;
            }
        }
        return -1;
    }
}

