public class Solution {
    public int countHousePlacements(int n) {
        long MOD = (long) 1e9 + 7;
        long[][] dp = new long[n + 1][2];

        // Base cases
        dp[0][0] = 1; // empty string
        dp[0][1] = 0; // no house

        for(int i = 1; i <= n; i++) {
            // For a string of length i, we can either append '0' or '1'
            // If we append '0', the new string will be of length (i - 1) and it was not ending with '1'
            dp[i][0] = (dp[i - 1][0] + dp[i - 1][1]) % MOD;

            // If we append '1', the new string will be of length (i - 1) and it was ending with '0'
            dp[i][1] = dp[i - 1][0];
        }

        long totalWays = ((dp[n][0] + dp[n][1]) * (dp[n][0] + dp[n][1])) % MOD;
        return (int)totalWays;
    }
}

