            // update the dp array for next iteration
            dp[i][0] = noHousesPlacedOnThisSide;
            dp[i][1] = (housesPlacedOnThisSide + dp[i-1][1]) % MOD;
        }

        long totalWaysToPlaceAllHouses = ((2 * (dp[n][0] + dp[n][1])) % MOD);

        return (int)totalWaysToPlaceAllHouses;
