public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int m = buses.length;
        int n = passengers.length;

        // Binary search on the first bus
        int low = -1;
        int high = 1000000000;

        while (low < high) {
            int mid = low + (high - low) / 2;

            int lastBus = findLastBus(buses, m);
            if (lastBus != -1 && canBoard(lastBus, buses[lastBus], passengers[0], capacity)) {
                // If the first passenger can board on the last bus, it's possible that all
                // passengers can board on a later bus. So we continue searching in the right half.
                int i = 1;
                while (i < n && canBoard(lastBus, buses[lastBus], passengers[i], capacity)) {
                    i++;
                }
                if (i == n) {
                    return mid; 
                } else {
                    // If not all passengers can board on a later bus, we have to search in the left half.
                    high = mid;
                }
            } else {
                // If it's impossible for all passengers to board on this last bus, we have
                // to search in the right half.
                low = mid + 1;
            }
        }

        return -1; 
    }

    private int findLastBus(int[] buses, int m) {
        for (int i = m - 1; i >= 0; i--) {
            if (buses[i] <= 1000000000 / capacity) {
                return i;
            }
        }
        return -1;
    }

    private boolean canBoard(int lastBus, int departureTime, int arrivalTime, int capacity) {
        if (departureTime > arrivalTime || departureTime >= 1000000000) {
            return false;
        }
        for (int i = 1; i <= capacity; i++) {
            if (departureTime + i * (lastBus + 1) > 1000000000 / capacity) {
                break;
            }
            if (arrivalTime <= departureTime + i * (lastBus + 1)) {
                return true;
            }
        }
        return false;
    }
}

