public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        for (int i = 0; i < buses.length - 1; i++) {
            if (buses[i + 1] - buses[i] == 0 && i > 0) {
                return buses[i];
            }
        }

        int lastBusCapacity = 0;
        for (int i = buses.length - 1; i >= 0; i--) {
            if (lastBusCapacity < capacity) {
                break;
            } else {
                lastBusCapacity -= binarySearch(passengers, buses[i]);
            }
        }

        return lastBusCapacity == 0 ? buses[buses.length - 1] : buses[buses.length - 1] - lastBusCapacity + 1;

    }

    private int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] > target) {
                right = mid - 1;
            } else if (arr[mid] < target) {
                left = mid + 1;
            } else {
                return arr.length - mid;
            }
        }

        return arr.length - left;
    }
}

