            if ((level & 1) == 1) {
                for (int i = 0; i < currentLevelValues.size() / 2; i++) {
                    int temp = currentLevelValues.get(i);
                    currentLevelValues.set(i, currentLevelValues.get(currentLevelValues.size() - i - 1));
                    currentLevelValues.set(currentLevelValues.size() - i - 1, temp);
                }
            }

            level++;
        }

        return root;
    }
}

