import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        int n = nums.length;
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                count++;
            }

            int left = 0;
            int right = i - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;

                if (nums[mid] < k && nums[i] > k) {
                    left = mid + 1;
                } else if (nums[mid] >= k || nums[i] <= k) {
                    right = mid - 1;
                }
            }

            int countLeft = i - left;
            map.put(nums[i], map.getOrDefault(nums[i], 0) + countLeft);
        }

        for (int num : nums) {
            if (num == k) {
                count += map.get(num);
            } else {
                count += map.getOrDefault(num, 0);
            }
        }

        return count;
    }
}

