// #Hard #Array #Hash_Table #Prefix_Sum #2023_01_26_Time_24_ms_(72.25%)_Space_51_MB_(99.24%)
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        int n = nums.length;
        long sum = 0;
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                map.put(i, 1);
                count++;
            } else {
                map.put(i, 0);
            }

            sum += map.get(i);

            int leftSmaller = getLeftSum(sum - 1, map);
            int rightLarger = i - leftSmaller;

            if (nums[i] < k) {
                count += leftSmaller + rightLarger;
            } else {
                count += rightLarger;
            }
        }

        return count;
    }

    private int getLeftSum(long sum, Map<Integer, Integer> map) {
        long prefix = 0;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getKey() < map.size() && prefix + entry.getValue() <= sum) {
                prefix += entry.getValue();
            }
        }

        return (int) (prefix);
    }
}

