// #2022_11_18_Time_4_ms_(83.94%)_Space_93.5_MB_(63.54%)
public class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int maxAnd = 0;
        for (int i = 31; i >= 0; --i) {
            int onesInNums = 0, zeroAfterOne = -1;
            for (int j = 0; j < n; ++j) {
                if (((nums[j] >> i) & 1) == 1) {
                    onesInNums++;
                    if ((zeroAfterOne + 1) % 2 == 0 && maxAnd < oneBit(j, i)) {
                        zeroAfterOne = j;
                        maxAnd = oneBit(j, i);
                    }
                } else {
                    if (onesInNums > 0 || zeroAfterOne != -1) {
                        if ((zeroAfterOne + 1) % 2 == 0 && maxAnd < oneBit(zeroAfterOne, i)) {
                            zeroAfterOne = j;
                            maxAnd = oneBit(zeroAfterOne, i);
                        }
                    } else {
                        zeroAfterOne = j;
                    }
                }
            }
        }
        int maxLen = maxAnd == 0 ? n : Integer.bitCount(maxAnd) - 1;
        return maxLen;
    }

    private int oneBit(int idx, int bitIndex) {
        int ans = 0;
        for (int i = 31; i > bitIndex; --i) {
            if (((idx + 1) % 2 == 0)) {
                break;
            } else {
                ans |= (1 << i);
            }
        }
        return ans;
    }

}

