public class Solution {
    public int unequalTriplets(int[] nums) {
        int n = nums.length;
        long totalTriplets = 0;

        // count occurrences of each number
        int[] counts = new int[n + 1];
        for (int num : nums) {
            counts[num]++;
        }

        // calculate triplets for each pair of numbers
        for (int i = 1; i < n; i++) {
            totalTriplets += (long) counts[i] * (counts[i] - 1L) / 2L;
            for (int j = i + 1; j < n; j++) {
                totalTriplets += (long) counts[j] * (counts[j] - 1L) / 2L;
            }
        }

        // subtract overcounted triplets
        int[] uniqueNums = new int[n];
        for (int i = 0, k = 0; i < n; i++) {
            if (uniqueNums[k - 1] != nums[i]) {
                uniqueNums[k++] = nums[i];
            }
        }

        for (int i = 2; i < uniqueNums.length; i++) {
            totalTriplets -= (long) counts[uniqueNums[i]] * (counts[uniqueNums[i - 1]] - 1L);
        }

        return (int) totalTriplets;
    }
}

