public class Solution {
    public int smallestEvenMultiple(int n) {
        // The smallest positive integer that is a multiple of both 2 and n 
        // will be the LCM of 2 and n, which can be calculated as (n * 2) / GCD(n, 2)
        return (n * 2) / greatestCommonDivisor(n, 2);
    }

    private int greatestCommonDivisor(int a, int b) {
        // Calculate the GCD using Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

