public class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize a 2D array to store the sum of each sub-matrix
        int[][] dp = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    // For the top-left corner, just store the value
                    dp[i][j] = grid[i][j];
                } else if (i == 0) {
                    // For the first row, calculate the sum by adding the current value and the previous one
                    dp[i][j] = dp[i][j-1] + grid[i][j];
                } else if (j == 0) {
                    // For the first column, calculate the sum by adding the current value and the previous one
                    dp[i][j] = dp[i-1][j] + grid[i][j];
                } else {
                    // For other positions, calculate the sum by taking the maximum of the top, left and top-left values
                    dp[i][j] = Math.max(Math.max(dp[i-1][j], dp[i][j-1]), dp[i-1][j-1]) + grid[i][j];
                }
            }
        }

        int maxSum = Integer.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // Check if an hourglass can be formed from the current position
                if (i >= 2 && j >= 2) {
                    maxSum = Math.max(maxSum, dp[i][j] - dp[i-1][j] - dp[i][j-1] + dp[i-1][j-1]);
                }
            }
        }

        return maxSum;
    }
}

