public class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize dp array to store maximum sum of hourglass ending at each position
        int[][][] dp = new int[m][n][3];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    // Base case: hourglass with one element
                    dp[i][j][1] = grid[i][j];
                    dp[i][j][2] = grid[i][j];
                    continue;
                }

                // Check if an hour glass can be formed from the current position
                boolean canFormHourGlass = (i > 0 && j > 0) || (i == 0 && j > 1) || (i > 1 && j == 0);

                if (!canFormHourGlass) {
                    // If we cannot form an hour glass from the current row anymore, just move to
                    // the next one
                    continue;
                }

                for (int k = -2; k <= 2; k++) {
                    int x = i + k;
                    if (x < 0 || x >= m) break;

                    for (int l = -2; l <= 2; l++) {
                        int y = j + l;
                        if (y < 0 || y >= n) break;

                        // Once we know an hourglass can be formed, just traverse the value
                        dp[i][j][1] = Math.max(dp[i][j][1], dp[x][y][2] + grid[i][j]);
                        dp[i][j][2] = Math.max(dp[i][j][2], dp[x][y][0] + grid[i][j]);
                    }
                }

                // Traverse the bottom and the top row of the hour glass at the same time
                // Add the middle value
                for (int k = -1; k <= 1; k++) {
                    int x = i + k;
                    if (x < 0 || x >= m) break;

                    dp[i][j][0] = Math.max(dp[i][j][0], dp[x][j][2]);
                }
            }
        }

        // Return the maximum sum of hourglass
        int maxSumHourGlass = Integer.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                maxSumHourGlass = Math.max(maxSumHourGlass, dp[i][j][1]);
            }
        }

        return maxSumHourGlass;
    }
}

