public class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        int result = Integer.MIN_VALUE;

        // Traverse each element in the matrix
        for (int i = 0; i < m - 1; i++) {
            for (int j = 0; j < n - 1; j++) {
                // Check if an hour glass can be formed from the current position
                if (checkHourGlass(grid, i, j)) {
                    result = Math.max(result, getSum(grid, i, j));
                }
            }
        }

        return result;
    }

    private boolean checkHourGlass(int[][] grid, int row, int col) {
        // Check the bottom and top row of the hour glass
        for (int i = 0; i <= 1; i++) {
            for (int j = 0; j <= 1; j++) {
                if (row + i < 0 || row + i >= grid.length || col + j < 0 || col + j >= grid[0].length) {
                    return false;
                }
            }
        }

        // Check the middle value
        int midRow = row;
        int midCol = col;

        if (midRow - 1 >= 0 && midRow + 2 < grid.length && midCol - 1 >= 0 && midCol + 2 < grid[0].length) {
            return true;
        }

        // If the middle value is not in the first or last row or column, then check if it's 
        // on one of the edges
        if (midRow == 0 || midRow == grid.length - 1 || midCol == 0 || midCol == grid[0].length - 1) {
            return true;
        }

        return false;
    }

    private int getSum(int[][] grid, int row, int col) {
        // Traverse the bottom and the top row of the hour glass at the same time
        // Add the middle value
        if (checkHourGlass(grid, row, col)) {
            return grid[row][col] + grid[row - 1][col] + grid[row + 1][col]
                    + grid[row][col - 1] + grid[row][col + 1]
                    - grid[row - 1][col - 1] - grid[row - 1][col + 1]
                    - grid[row + 1][col - 1] - grid[row + 1][col + 1];
        }

        return Integer.MIN_VALUE;
    }
}

