public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        int n = nums.length;
        Arrays.sort(nums);
        Arrays.sort(target);

        int countOdd = 0, countEven = 0;
        for (int i : nums) {
            if (i % 2 == 0) {
                countEven++;
            } else {
                countOdd++;
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int num = Math.abs(nums[i] - target[i]);
            if (num % 2 == 1 && num != 1) {
                if (num > 0) {
                    countEven -= num / 2;
                } else {
                    countOdd += (-num) / 2;
                }
                ans += (-num) / 2 + 1;
            } else if ((nums[i] % 2 == 1 && target[i] % 2 == 0) || (nums[i] % 2 == 0 && target[i] % 2 == 1)) {
                if (nums[i] % 2 == 0) {
                    countEven--;
                } else {
                    countOdd--;
                }
            }
        }

        ans += Math.abs(countOdd - countEven) / 2;
        return ans;
    }
}

