import java.util.Map;

public class Solution {
    Map<Integer, Integer> heightMap = new HashMap<>();
    Map<TreeNode, Integer> subtreeSizeMap = new HashMap<>();

    public int[] treeQueries(TreeNode root, int[] queries) {
        dfs(root);

        int m = queries.length;
        int[] ans = new int[m];

        for (int i = 0; i < m; i++) {
            TreeNode node = findNode(root, queries[i]);
            int h = heightMap.get(node);
            int subtreeSize = subtreeSizeMap.get(node);

            if (subtreeSize == root.val) {
                ans[i] = h;
            } else {
                int n = getNodes(root, node);
                ans[i] = h + Math.max(n - 1, 0);
            }
        }

        return ans;
    }

    private void dfs(TreeNode node) {
        if (node == null) return;

        subtreeSizeMap.put(node, 1);

        for (TreeNode child : new TreeNode[]{node.left, node.right}) {
            if (child != null) {
                subtreeSizeMap.put(node, subtreeSizeMap.get(node) + subtreeSizeMap.get(child));
                heightMap.put(child, heightMap.get(node) + 1);
                dfs(child);
            }
        }
    }

    private int getNodes(TreeNode root, TreeNode target) {
        if (root == null || root == target) return 0;

        int left = getNodes(root.left, target);
        int right = getNodes(root.right, target);

        return left + right + (root == target ? 1 : 0);
    }

    private TreeNode findNode(TreeNode node, int val) {
        if (node == null || node.val == val) return node;

        for (TreeNode child : new TreeNode[]{node.left, node.right}) {
            if (child != null && child.val == val) return child;
        }

        return null;
    }
}

