    private void dfs(TreeNode node, TreeNode parent) {
        if (node == null)
            return;

        subtreeSizeMap.put(node.val, 1 + subtreeSizeMap.getOrDefault(parent != null ? parent.val : -1, 0));

        heightMap.put(node.val, Math.max(heightMap.getOrDefault(parent != null ? parent.val : -1, 0), 1));
        dfs(node.left, node);
        dfs(node.right, node);

        if (parent == null) {
            int maxHeight = 0;
            for (TreeNode child : new TreeNode[]{node.left, node.right}) {
                if (child != null)
                    maxHeight = Math.max(maxHeight, heightMap.get(child.val));
            }
            heightMap.put(node.val, 1 + maxHeight);
        }

    }

    private int getHeight(TreeNode node) {
        return heightMap.getOrDefault(node.val, 0);
    }

    private TreeNode findNode(TreeNode root, int value) {
        if (root == null)
            return null;

        if (value == root.val) {
            subtreeSizeMap.put(root.val, 0);
            return root;
        }

        TreeNode left = findNode(root.left, value);
        if (left != null)
            return left;

        TreeNode right = findNode(root.right, value);
        if (right != null)
            return right;

        return null;
    }
