        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            TreeNode node = findNode(root, queries[i]);
            answer[i] = getNewHeight(node);
        }
        return answer;
    }

    private int dfs(TreeNode root) {
        if (root == null) return 0;

        root.height = Math.max(dfs(root.left), dfs(root.right)) + 1;
        height = Math.max(height, root.height);

        map.put(root.val, root.height);
        return root.height;
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null || root.val == val) return root;

        int leftHeight = dfsLeft(root.left);
        int rightHeight = dfsRight(root.right);

        if (leftHeight + 1 > rightHeight) {
            return findNode(root.left, val);
        } else {
            return findNode(root.right, val);
        }
    }

    private int dfsLeft(TreeNode root) {
        if (root == null) return -1;
        if (map.getOrDefault(root.val, -1) != -1) return map.get(root.val);

        return Math.max(dfsLeft(root.left), dfsLeft(root.right)) + 1;
    }

    private int dfsRight(TreeNode root) {
        if (root == null) return -1;
        if (map.getOrDefault(root.val, -1) != -1) return map.get(root.val);

        return Math.max(dfsRight(root.right), dfsRight(root.left)) + 1;
    }

    private int getNewHeight(TreeNode node) {
        height = 0;

        if (node == null) return 0;

        int leftHeight = dfsLeft(node);
        int rightHeight = dfsRight(node);

        if (leftHeight > rightHeight) {
            dfs(node.left);
            return leftHeight;
        } else {
            dfs(node.right);
            return rightHeight;
        }
    }
}

