            }
        }

        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            if (entry.getValue() != 0) {
                String key = entry.getKey().split(",")[0];

                for (String str : w) {
                    if ((str.charAt(0) - 'a') % 26 == Integer.parseInt(key)) {
                        return str;
                    }
                }
            }
        }

        return "";
    }
