        long totalDistance = 0;
        int currentFactoryIndex = 0, currentRobotIndex = robotArray.length - 1;

        while (currentRobotIndex >= 0) {

            // find the most optimal destination factory for the current robot
            int lastFactoryFilledCapacity = f[currentFactoryIndex][1];
            long distanceToCurrentFactory = Math.abs(robotArray[currentRobotIndex] - f[currentFactoryIndex][0]);
            totalDistance += distanceToCurrentFactory;

            if (lastFactoryFilledCapacity > 0) {
                // assign the current robot to the current factory
                lastFactoryFilledCapacity--;
                f[currentFactoryIndex][1] = lastFactoryFilledCapacity;
                currentRobotIndex--;
            } else if (currentFactoryIndex < f.length - 1 && f[currentFactoryIndex + 1][1] > 0) {
                // move any non-fit robots to the right
                long distanceToNextFactory = Math.abs(robotArray[currentRobotIndex] - f[currentFactoryIndex + 1][0]);
                if (distanceToCurrentFactory < distanceToNextFactory) {
                    totalDistance += distanceToNextFactory;
                    currentFactoryIndex++;
                } else {
                    // move to the next factory
                    totalDistance -= distanceToCurrentFactory;
                    currentRobotIndex--;
                }
            } else {
                // we reached the end and cannot fit our robot to the current factory
                break;
            }

        }

        return totalDistance;
    }
}

