                result += Math.abs(f[factoryIndex][0]);
                result -= Math.abs(robotArray[robotIndex]);
                factoryIndex--;
            } else {
                long cost = f[factoryIndex][0] - robotArray[robotIndex];
                result += cost;
                f[factoryIndex][1]--;
                // move non-fit robots to the right
                while (robotIndex >= 0 && f[factoryIndex][1] == 0) {
