public class Solution {
    public int minGroups(int[][] intervals) {
        // Sort the intervals based on their end points
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));

        // Initialize the count of groups and the end point of the last group
        int groups = 0;
        int lastEnd = Integer.MIN_VALUE;

        for (int[] interval : intervals) {
            if (interval[0] >= lastEnd) {
                // If the current interval does not intersect with the previous one, 
                // it can be in a new group. So increment the count of groups and update 
                // the end point of the last group.
                groups++;
                lastEnd = interval[1];
            }
        }

        return groups;
    }
}

