public class Solution {
    public int deleteString(String s) {
        Map<String, Integer> map = new HashMap<>();
        int n = s.length();
        int ans = 0;

        for (int i = 1; i <= n / 2; i++) {
            String substr = s.substring(0, i);

            if (!map.containsKey(substr)) {
                map.put(substr, 1);
            } else {
                int count = map.get(substr) + 1;

                if (count == i) {
                    ans++;
                    for (int j = i; j < n; j++) {
                        substr += s.charAt(j);

                        if (!map.containsKey(substr)) {
                            map.put(substr, 1);
                        } else {
                            int count2 = map.get(substr) + 1;

                            if (count2 == j - i + 1) {
                                ans++;
                            }
                        }
                    }
                } else {
                    map.put(substr, count);
                }
            }
        }

        return n - ans * (ans + 1) / 2;
    }
}

