public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        HashMap<String, Integer> map = new HashMap<>();

        for (int i = 1; i <= n / 2; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);

            if (right.startsWith(left)) {
                map.put(left + "R", i);
            }
        }

        int max = 0;
        for (int i = 1; i <= n / 2; i++) {
            String left = s.substring(0, i);
