public class Solution {
    public int daysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        // Convert strings to Calendar objects for easy date manipulation
        Calendar aliceStart = getCalendar(arriveAlice);
        Calendar aliceEnd = getCalendar(leaveAlice);

        Calendar bobStart = getCalendar(arriveBob);
        Calendar bobEnd = getCalendar(leaveBob);

        // Find the maximum and minimum dates between Alice's and Bob's stay periods
        int maxDate = Math.max(aliceStart.get(Calendar.DAY_OF_YEAR), bobStart.get(Calendar.DAY_OF_YEAR));
        int minDate = Math.min(aliceEnd.get(Calendar.DAY_OF_YEAR), bobEnd.get(Calendar.DAY_OF_YEAR));

        // If there is no overlap, return 0
        if (maxDate < minDate) {
            return 0;
        }

        // Calculate the total days of overlap by subtracting the minimum date from the maximum date and adding 1
        int totalDays = maxDate - minDate + 1;

        // Subtract any non-overlapping dates at the start or end of each period
        if (aliceStart.get(Calendar.DAY_OF_YEAR) < bobStart.get(Calendar.DAY_OF_YEAR)) {
            totalDays -= aliceStart.get(Calendar.DAY_OF_YEAR);
        } else {
            totalDays -= bobStart.get(Calendar.DAY_OF_YEAR);
        }

        if (aliceEnd.get(Calendar.DAY_OF_YEAR) > bobEnd.get(Calendar.DAY_OF_YEAR)) {
            totalDays -= aliceEnd.get(Calendar.DAY_OF_YEAR);
        } else {
            totalDays -= bobEnd.get(Calendar.DAY_OF_YEAR);
        }

        return totalDays;
    }

    private Calendar getCalendar(String dateStr) {
        String[] parts = dateStr.split("-");
        int month = Integer.parseInt(parts[0]) - 1; // Months are 0-based
        int day = Integer.parseInt(parts[1]);

        Calendar calendar = Calendar.getInstance();
        calendar.set(Calendar.YEAR, 2024); // Any non-leap year will work here
        calendar.set(Calendar.MONTH, month);
        calendar.set(Calendar.DAY_OF_MONTH, day);
        return calendar;
    }
