import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Arrays;

public class Solution {
    public int daysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        // Convert date strings to LocalDate objects
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MM-dd");
        LocalDate aliceFrom = LocalDate.parse(arriveAlice, formatter);
        LocalDate aliceTo = LocalDate.parse(leaveAlice, formatter);
        LocalDate bobFrom = LocalDate.parse(arriveBob, formatter);
        LocalDate bobTo = LocalDate.parse(leaveBob, formatter);

        // Find overlapping dates
        int daysTogether = 0;
        for (int i = Math.max(aliceFrom.getMonthValue(), bobFrom.getMonthValue()); 
             i <= Math.min(aliceTo.getMonthValue(), bobTo.getMonthValue());
             i++) {
            if (i == aliceFrom.getMonthValue()) {
                aliceFrom = aliceFrom.plusMonths(1).minusDays(i - aliceFrom.getMonthValue() + 1);
            } else if (i == aliceTo.getMonthValue()) {
                aliceTo = aliceTo.minusMonths(1).plusDays((31 - i) * 28 - (aliceTo.getDayOfMonth()));
            }
            if (i == bobFrom.getMonthValue()) {
                bobFrom = bobFrom.plusMonths(1).minusDays(i - bobFrom.getMonthValue() + 1);
            } else if (i == bobTo.getMonthValue()) {
                bobTo = bobTo.minusMonths(1).plusDays((31 - i) * 28 - (bobTo.getDayOfMonth()));
            }

            int overlap = Math.min(aliceTo.getYear(), bobTo.getYear()) 
                         - Math.max(aliceFrom.getYear(), bobFrom.getYear());
            if (overlap > 0) {
                if (aliceFrom.isAfter(bobFrom)) {
                    daysTogether += (31 + 28 + 31 + 30 + 31 + 30 + 31 + 31 + 30 + 31 + 30 + 31) * overlap;
                } else {
                    int diff = Math.abs(aliceFrom.getYear() - bobFrom.getYear());
                    daysTogether += (bobFrom.getDayOfMonth() - aliceFrom.getDayOfMonth()) 
                                   + (28 - aliceTo.getDayOfMonth()) 
                                   + ((31 - i) * 28) * (diff - 1);
                }
            }

            // Count overlapping days in the same month
            if (i >= Math.max(aliceFrom.getMonthValue(), bobFrom.getMonthValue())
                && i <= Math.min(aliceTo.getMonthValue(), bobTo.getMonthValue())) {
                int diff = Math.abs(aliceFrom.getYear() - bobFrom.getYear());
                if (aliceFrom.isAfter(bobFrom)) {
                    daysTogether += (31 + 28 + 31 + 30 + 31 + 30 + 31 + 31 + 30 + 31 + 30 + 31) * diff;
                } else {
                    daysTogether += Math.min(aliceTo.getDayOfMonth(), bobTo.getDayOfMonth());
                }
            }
        }

        return daysTogether;
    }
}

