public class Solution {
    public int[] findMinMax(TreeNode root, int[] queries) {
        Map<Integer, Integer> map = new HashMap<>();
        List<Integer> list = new ArrayList<>();

        inOrder(root, map);
        for (int query : queries) {
            if (!map.containsKey(query)) {
                list.add(-1);
                list.add(-1);
            } else {
                int min = -1;
                int max = -1;
                Integer lower = map.get(Math.min(1000000, query));
                while (lower != null && lower < query) {
                    min = Math.max(min, lower);
                    lower = map.get(lower + 1);
                }
                if (min == -1) {
                    list.add(-1);
                    continue;
                }

                Integer higher = map.get(query);
                while (higher != null && higher > query) {
                    max = Math.min(max, higher);
                    higher = map.get(higher - 1);
                }
                list.add(min);
                list.add(max);
            }
        }
        int[] ans = new int[queries.length * 2];
        for (int i = 0; i < queries.length; i++) {
            ans[i * 2] = list.get(i * 2);
            ans[i * 2 + 1] = list.get(i * 2 + 1);
        }
        return ans;
    }

    private void inOrder(TreeNode root, Map<Integer, Integer> map) {
        if (root == null)
            return;

        inOrder(root.left, map);

        map.put(root.val, map.getOrDefault(root.val - 1, -1000000));
        map.put(root.val + 1, map.getOrDefault(root.val + 1, 1000000));

        inOrder(root.right, map);
    }
}

