            } else {
                if (q <= inorder.get(inorder.size()-1)) {
                    minI = q;
                    maxI = q;
                }
            }

            ans[i][0] = minI;
            ans[i][1] = maxI;
        }

        return ans;
    }

    private void dfs(TreeNode root, List<Integer> inorder) {
        if (root == null) return;
        dfs(root.left, inorder);
        inorder.add(root.val);
