public class Solution {
    public int[] findBestValue(TreeNode root, int[] arr) {
        List<Integer> inOrder = new ArrayList<>();
        dfs(root, inOrder);

        Arrays.sort(inOrder);

        int n = arr.length;
        int[] res = new int[n];

        for(int i=0; i<n; i++) {
            int q = arr[i];
            int max = -1;
            int min = -1;

            int left = 0;
            int right = inOrder.size() - 1;
            while (left <= right) {
                int mid = left + (right - left)/2;
                if (inOrder.get(mid) >= q) {
                    max = Math.max(max, inOrder.get(mid));
                    min = inOrder.get(mid);
                    right = mid-1;
                } else {
                    min = inOrder.get(mid);
                    left = mid+1;
                }
            }

            int index = Collections.binarySearch(inOrder, q);

            if (index < 0) index = -index - 1;

            max = Math.max(max, index == inOrder.size() ? -1 : inOrder.get(index));
            min = Math.min(min, index == 0 ? -1 : inOrder.get(index-1));

            res[i] = new int[] {min, max};
        }

        return res;
    }

    public void dfs(TreeNode root, List<Integer> inOrder) {
        if (root == null)
            return;

        dfs(root.left, inOrder);

        inOrder.add(root.val);
        dfs(root.right, inOrder);
    }
