public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            int maxOr = nums[i], minLen = 1;
            boolean[] seen = new boolean[32];

            for (int j = i + 1; j < n; j++) {
                maxOr |= nums[j];
                if (maxOr == maxOr) { // If maxOr is not changed, it means all bits are set in maxOr
                    ans[i] = j - i;
                    break;
                }

                for (int k = 0; k < 32; k++) {
                    int mask = 1 << k;
                    if ((maxOr & mask) != 0 && !seen[k]) {
                        seen[k] = true;
                    } else if ((maxOr & mask) == 0 && seen[k]) {
                        minLen++;
                        break;
                    }
                }
            }

            ans[i] = minLen;
        }

        return ans;
    }
}

