public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        PriorityQueue<Integer> left = new PriorityQueue<>(Comparator.comparingInt(a -> a));
        PriorityQueue<Integer> right = new PriorityQueue<>(Comparator.comparingInt(a -> a));

        for (int i = 0; i < costs.length; i++) {
            if (i < candidates) {
                left.offer(costs[i]);
            } else if (i >= costs.length - candidates) {
                right.offer(costs[i]);
            }
        }

        long totalCost = 0;
        int count = k;

        while (!left.isEmpty() && !right.isEmpty()) {
            if (count == 1) break;

            if (left.peek() < right.peek()) {
                totalCost += left.poll();
                count--;
                for (int i = costs.length - candidates; i >= 0; i--) {
                    if (costs[i] == left.peek()) {
                        if (i + 1 < candidates) {
                            right.offer(costs[i]);
                        }
                        break;
                    } else if (costs[i] > left.peek() && i + 1 < costs.length - candidates) {
                        right.offer(costs[i]);
                    }
                }
            } else {
                totalCost += right.poll();
                count--;
                for (int i = 0; i < candidates; i++) {
                    if (costs[i] == right.peek()) {
                        if (i > 0) {
                            left.offer(costs[i]);
                        }
                        break;
                    } else if (costs[i] > right.peek() && i > costs.length - candidates) {
                        left.offer(costs[i]);
                    }
                }
            }
        }

        while (!left.isEmpty()) {
            totalCost += left.poll();
            count--;
        }

        while (!right.isEmpty()) {
            totalCost += right.poll();
            count--;
        }

        return totalCost;
    }
}

