import java.util.*;

public class Solution {
    public int minScore(int n, int[][] roads) {
        List<List<int[]>> adjList = new ArrayList<>();

        // Initialize adjacency list with n empty lists
        for (int i = 0; i < n + 1; i++) {
            adjList.add(new ArrayList<>());
        }

        // Populate adjacency list
        for (int[] road : roads) {
            int u = road[0], v = road[1];
            adjList.get(u).add(new int[]{v, road[2]});
            adjList.get(v).add(new int[]{u, road[2]});  // For bidirectional graph
        }

        // Dijkstra's algorithm to find shortest distance from node 1 to all other nodes
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        boolean[] visited = new boolean[n + 1];
        int[] dist = new int[n + 1];

        // Initialize distances as infinity and add node 1 to priority queue with distance 0
        Arrays.fill(dist, Integer.MAX_VALUE);
        pq.offer(new int[]{1, 0});
        dist[1] = 0;

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int u = top[0], d = top[1];

            if (visited[u]) continue; // Skip visited nodes

            visited[u] = true;

            for (int[] neighbor : adjList.get(u)) {
                int v = neighbor[0], w = neighbor[1];

                if (!visited[v] && dist[v] > d + w) {  // Update distance only if shorter path is found
                    dist[v] = d + w;
                    pq.offer(new int[]{v, dist[v]});
                }
            }
        }

        return dist[n]; // Return shortest distance from node 1 to node n
    }
}

