        if (node == n && dist < min) {
            min = dist;
        }
        visited[node] = true;

        for (int i = 0; i < graph.get(node).size(); i++) {
            int nextNode = graph.get(node).get(i).get(0);
            int currDist = graph.get(node).get(i).get(1);

            if (!visited[nextNode] && nextNode != parent) {
                dfs(graph, n, nextNode, node, Math.min(dist, currDist), min, visited);
            }
        }

        visited[node] = false;
    }
