import java.util.*;

public class Solution {
    public int minScore(int n, int[][] roads) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] road : roads) {
            graph.get(road[0]).add(Arrays.asList(road[1], road[2]));
            graph.get(road[1]).add(Arrays.asList(road[0], road[2])); // Note the symmetric edge
        }

        int[][] visited = new int[n + 1][2];
        boolean[] visitedNodes = new boolean[n + 1];

        return bfs(graph, n, visitedNodes, visited);
    }

    private int bfs(List<List<Integer>> graph, int startNode, boolean[] visitedNodes, int[][] visited) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startNode, -1});

        while (!queue.isEmpty()) {
            int[] nodeInfo = queue.poll();

            if (nodeInfo[0] == n) return nodeInfo[2];

            for (int i = 0; i < graph.get(nodeInfo[0]).size(); ++i) {
                int neighbor = graph.get(nodeInfo[0]).get(i).get(0);

                if (!visitedNodes[neighbor]) {
                    visitedNodes[neighbor] = true;

                    // Update the minimum distance value
                    if (nodeInfo[2] < 0 || nodeInfo[2] > graph.get(nodeInfo[0]).get(i).get(1)) {
                        visited[neighbor][0] = nodeInfo[0];
                        visited[neighbor][1] = nodeInfo[2];
                        queue.offer(new int[]{neighbor, nodeInfo[2]});
                    } else if (nodeInfo[2] == graph.get(nodeInfo[0]).get(i).get(1)) {
                        // Update the parent for this neighbor
                        visited[neighbor][0] = nodeInfo[0];
                        visited[neighbor][1] = nodeInfo[2];
                        queue.offer(new int[]{neighbor, nodeInfo[2]});
                    }
                } else if (nodeInfo[2] < graph.get(nodeInfo[0]).get(i).get(1) && nodeInfo[2] != -1) {
                    // Update the minimum distance value
                    visited[neighbor][0] = nodeInfo[0];
                    visited[neighbor][1] = nodeInfo[2];
                    queue.offer(new int[]{neighbor, nodeInfo[2]});
                }
            }
        }

        return -1; // No path found
    }
}

