        }
        // Distances between nodes
        for (int k = 1; k <= n; k++) {
            for (int i = 1; i <= n; i++) {
                for (int[] neighbor : adjList.get(i)) {
                    if (dist[i][k] + neighbor[1] < dist[k][neighbor[0]]) {
                        dist[k][neighbor[0]] = Math.min(dist[k][neighbor[0]], dist[i][k] + neighbor[1]);
                    }
                }
            }
        }

        int min = Integer.MAX_VALUE;
        for (int i = 2; i <= n; i++) {
            if (dist[1][i] != Integer.MAX_VALUE / 2) {
                min = Math.min(min, dist[1][i]);
            }
        }

        return min == Integer.MAX_VALUE / 2 ? -1 : min;
