public class Solution {
    private Map<String, Integer> trie = new HashMap<>();

    public Solution() {}

    public int[] sumPrefixScores(String[] words) {
        int n = words.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            String word = words[i];
            TrieNode node = buildTrie(word);
            ans[i] = getScore(node, word);
        }
        return ans;
    }

    private TrieNode buildTrie(String word) {
        TrieNode node = trie.get(word);
        if (node == null) {
            node = new TrieNode();
            trie.put(word, node);
        }
        for (int i = 1; i < word.length(); i++) {
            String prefix = word.substring(0, i);
            node.children.put(prefix, buildTrie(prefix));
        }
        return node;
    }

    private int getScore(TrieNode node, String word) {
        if (node == null) return 0;
        int score = 1;
        for (Map.Entry<String, TrieNode> entry : node.children.entrySet()) {
            String prefix = entry.getKey();
            if (word.startsWith(prefix)) {
                score += getScore(entry.getValue(), word);
            }
        }
        return score;
    }

    private static class TrieNode {
        Map<String, TrieNode> children = new HashMap<>();
    }
}

