public class Solution {
    private Map<String, Integer> trie;

    public Solution() {
        this.trie = new HashMap<>();
        this.trie.put("", 0);
    }

    public int[] sumPrefixScores(String[] words) {
        int[] result = new int[words.length];

        for (int i = 0; i < words.length; i++) {
            String word = words[i];

            int count = 0;
            for (String prefix : getPrefixes(word, trie)) {
                count += trie.get(prefix);
            }

            result[i] = count;
        }

        return result;
    }

    private Set<String> getPrefixes(String word, Map<String, Integer> map) {
        TrieNode node = new TrieNode();
        for (char ch : word.toCharArray()) {
            if (!node.children.containsKey(ch)) {
                node.children.put(ch, new TrieNode());
            }
            node = node.children.get(ch);
        }

        Set<String> set = new HashSet<>();
        dfs(set, "", node);
        return set;
    }

    private void dfs(Set<String> set, String prefix, TrieNode node) {
        if (!node.isEndOfWord) {
            for (Map.Entry<Character, TrieNode> entry : node.children.entrySet()) {
                char ch = entry.getKey();
                TrieNode child = entry.getValue();
                dfs(set, prefix + ch, child);
            }
        } else {
            set.add(prefix);
        }
    }

    private class TrieNode {
        Map<Character, TrieNode> children;
        boolean isEndOfWord;

        public TrieNode() {
            this.children = new HashMap<>();
            this.isEndOfWord = false;
        }
    }
}

