public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            map.put(creators[i], map.getOrDefault(creators[i], 0) + views[i]);
        }

        PriorityQueue<Map.Entry<String, Integer>> maxHeap = new PriorityQueue<>((a, b) -> a.getValue() == b.getValue()
                ? a.getKey().compareTo(b.getKey())
                : b.getValue() - a.getValue());
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            maxHeap.offer(entry);
        }

        String[] result = new String[2];
        Map<String, String> resMap = new HashMap<>();
        while (!maxHeap.isEmpty()) {
            Map.Entry<String, Integer> entry = maxHeap.poll();
            if (result[0] == null || entry.getValue() > result[1]) {
                result[0] = entry.getKey();
                result[1] = ids[Arrays.asList(creators).indexOf(entry.getKey())];
                resMap.put(result[0], result[1]);
            } else if (entry.getValue().equals(result[1])) {
                String temp = ids[Arrays.asList(creators).indexOf(entry.getKey())];
                if (temp.compareTo(result[1]) < 0) {
                    resMap.put(result[0], temp);
                }
            }
        }

        List<List<String>> ans = new ArrayList<>();
        for (String key : resMap.keySet()) {
            ans.add(Arrays.asList(key, resMap.get(key)));
        }
        return ans;
    }
}

