import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        Map<Integer, Integer> freqMap = new HashMap<>();

        for (int num : nums) {
            int remainder = num % space;

            if (!freqMap.containsKey(remainder)) {
                freqMap.put(remainder, 1);
            } else {
                freqMap.put(remainder, freqMap.get(remainder) + 1);
            }
        }

        Map<Integer, Integer> maxCountMap = new HashMap<>();

        for (int num : nums) {
            int remainder = num % space;

            if (!maxCountMap.containsKey(num)) {
                maxCountMap.put(num, freqMap.get(remainder));
            } else {
                maxCountMap.put(num, Math.max(maxCountMap.get(num), freqMap.get(remainder)));
            }
        }

        int maxValue = Integer.MIN_VALUE;

        for (int num : nums) {
            int remainder = num % space;

            if (maxCountMap.containsKey(num)) {
                maxValue = Math.max(maxValue, maxCountMap.get(num));
            } else if (freqMap.containsKey(remainder)) {
                maxValue = Math.max(maxValue, freqMap.get(remainder));
            }
        }

        for (int num : nums) {
            int remainder = num % space;

            if (maxCountMap.containsKey(num) && maxCountMap.get(num) == maxValue) {
                return num;
            } else if (freqMap.containsKey(remainder) && freqMap.get(remainder) == maxValue) {
                return num;
            }
        }

        return -1; // If no solution is found
    }
}

