                subtreeSize[node]++;
                dfs(graph, parent, subtreeSize, neighbor);
            }
        }
    }

    private long calculateFuel(int[] subtreeSizes, int seats) {
        long totalFuel = 0;
        for (int size : subtreeSizes) {
            totalFuel += (size + seats - 1) / seats;
        }
        return totalFuel;
    }
