        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                ans += dfs(i, adj, seats, parent, visited);
            }
        }

        return ans;
    }

    private long dfs(int node, ArrayList<ArrayList<Integer>> adj,
                      int seats, int[] parent, boolean[] visited) {

        long sum = 1;

        for (int child : adj.get(node)) {
            if (child != parent[node] && !visited[child]) {
                visited[child] = true;
                sum += dfs(child, adj, seats, parent, visited);
            }
        }

        if (parent[node] == -1) return sum;

        long extraPeople = sum % seats;
        if (extraPeople > 0)
            ans += extraPeople;

        return sum / seats;
    }

    private long ans;
}

