public class Solution {
    private int capital;
    private long totalFuel = 0;

    public long minimumFuelCost(int[][] roads, int seats) {
        List<List<Integer>> graph = new ArrayList<>();
        boolean[] visited = new boolean[roads.length];
        for (int i = 0; i < roads.length; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] road : roads) {
            graph.get(road[0]).add(road[1]);
            graph.get(road[1]).add(road[0]);
        }

        capital = findCapital(graph, visited);

        dfs(graph, visited, -1);
        return totalFuel;
    }

    private int findCapital(List<List<Integer>> graph, boolean[] visited) {
        for (int i = 0; i < graph.size(); i++) {
            if (!visited[i]) {
                if (dfsCapital(graph, visited, i)) {
                    return i;
                }
            }
        }
        return -1;
    }

    private boolean dfsCapital(List<List<Integer>> graph, boolean[] visited, int node) {
        visited[node] = true;

        for (int child : graph.get(node)) {
            if (!visited[child]) {
                if (dfsCapital(graph, visited, child)) {
                    return true;
                }
            } else {
                long people = countPeople(graph, visited, node);
                totalFuel += people - 1;
            }
        }

        return false;
    }

    private void dfs(List<List<Integer>> graph, boolean[] visited, int parent) {
        for (int child : graph.get(parent)) {
            if (!visited[child]) {
                visited[child] = true;
                dfs(graph, visited, child);
                long people = countPeople(graph, visited, parent);
                totalFuel += people - 1;
            }
        }
    }

    private long countPeople(List<List<Integer>> graph, boolean[] visited, int node) {
        List<Long> peoples = new ArrayList<>();
        for (int child : graph.get(node)) {
            if (!visited[child]) {
                peoples.add(countPeople(graph, visited, child));
            } else {
                peoples.add(1L);
            }
        }

        long sum = 0;
        for (long p : peoples) {
            sum += (p - 1) / seats + 1;
        }
        return sum;
    }
}

