public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null)
            return 0;

        Map<Integer, List<Integer>> levelValues = new HashMap<>();
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();

        queue.add(root);
        levelValues.put(0, Arrays.asList(root.val));

        int operations = 0;
        int currentLevel = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> valuesAtCurrentLevel = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null) {
                    levelValues.computeIfAbsent(currentLevel + 1, k -> new ArrayList<>()).add(node.left.val);
                    queue.add(node.left);
                }
                if (node.right != null) {
                    levelValues.computeIfAbsent(currentLevel + 1, k -> new ArrayList<>()).add(node.right.val);
                    queue.add(node.right);
                }

                valuesAtCurrentLevel.add(node.val);
            }

            // sort the values and compare with the previous sorted list
            Collections.sort(valuesAtCurrentLevel);

            if (currentLevel > 0) {
                List<Integer> prevValues = levelValues.get(currentLevel - 1);
                int i = 0;
                for (; i < Math.min(prevValues.size(), valuesAtCurrentLevel.size()); i++) {
                    if (prevValues.get(i) != valuesAtCurrentLevel.get(i))
                        break;
                }
                operations += prevValues.size() - i + (valuesAtCurrentLevel.size() - i);
            }

            currentLevel++;
        }

        return operations;
    }
}

