public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        Map<Integer, Integer> sum = new HashMap<>();
        for (int value : nodeValues) sum.put(value, 0);
        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[1] - b[1]);

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            int valU = nodeValues[u], valV = nodeValues[v];

            sum.put(valU, sum.getOrDefault(valU, 0) + valV);
            queue.offer(new int[]{valU, sum.get(valU)});
        }

        for (int i = 0; i < maxNumberOfEdges && !queue.isEmpty(); i++) {
            int[] top = queue.poll();
            if (!sum.containsKey(top[0])) continue;
            sum.put(top[0], 0);
            queue.offer(new int[]{top[0], Math.max(0, sum.get(top[0]) - top[1] + nodeValues[top[0]])});
        }

        return queue.isEmpty() ? 0 : queue.peek()[1];
    }
}

