        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);

        for (int i = 0; i < edges.length; i++) {
            if (pq.size() <= maxNumberOfEdges) {
                pq.offer(new int[]{edges[i][0], nodeValues[edges[i][0]], 0});
                pq.offer(new int[]{edges[i][1], nodeValues[edges[i][1]], 0});
            }
        }

        int result = Integer.MIN_VALUE;
        while (pq.size() > maxNumberOfEdges) {
            int[] temp = pq.poll();
            nodeValues[temp[0]] -= temp[2];
            pq.offer(new int[]{temp[0], temp[1], temp[2] + 1});
        }

        while (!pq.isEmpty()) {
            result = Math.max(result, pq.peek()[1]);
            pq.poll();
        }

        return result;
    }
}

