public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] dp = new long[m][n];
        Map<Long, Long> memo = new HashMap<>();

        return (int) dfs(0, 0, 0, grid, dp, memo, k);
    }

    private long dfs(int i, int j, long sum, int[][] grid, long[][] dp, Map<Long, Long> memo, int k) {
        if (i == grid.length - 1 && j == grid[0].length - 1) {
            return sum % k == 0 ? 1 : 0;
        }

        if (dp[i][j] != 0) {
            return dp[i][j];
        }

        long ways = 0;

        // right
        if (j < grid[0].length - 1) {
            ways += dfs(i, j + 1, sum + grid[i][j + 1], grid, dp, memo, k);
        }
        // down
        if (i < grid.length - 1) {
            ways += dfs(i + 1, j, sum + grid[i + 1][j], grid, dp, memo, k);
        }

        long key = i * n + j;
        memo.put(key, ways % MOD);

        return dp[i][j] = ways % MOD;
    }
}

