import java.util.Map;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize dp array with all ones
        long[][] dp = new long[m][n];
        for (long[] row : dp) Arrays.fill(row, 1);

        // Calculate prefix sum of each cell in the dp array
        for (int i = 1; i < m; ++i)
            for (int j = 0; j < n; ++j)
                dp[i][j] += dp[i - 1][j];

        // Calculate suffix sum of each cell in the dp array
        for (int i = 0; i < m; ++i)
            for (int j = 1; j < n; ++j)
                dp[i][j] += dp[i][j - 1];

        Map<Long, Long> memo = new HashMap<>();
        return (int) dfs(0, 0, grid, k, MOD, dp, memo);
    }

    private long dfs(int i, int j, int[][] grid, int k, int mod, long[][] dp, Map<Long, Long> memo) {
        if (i == grid.length - 1 && j == grid[0].length - 1)
            return dp[i][j] % mod;

        long key = ((long)i << 32) | j;
        if (memo.containsKey(key))
            return memo.get(key);

        long ans = 0;
        int sum = grid[i][j];
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj) {
                if (i + di < 0 || i + di >= grid.length || j + dj < 0 || j + dj >= grid[0].length
                        || Math.abs(di) == 1 && Math.abs(dj) == 1)
                    continue;

                int ni = i + di, nj = j + dj;
                long tempSum = sum + grid[ni][nj];
                if (tempSum % k == 0)
                    ans += dfs(ni, nj, grid, k, mod, dp, memo);
            }

        memo.put(key, ans % mod);
        return ans % mod;
    }
}

