public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        long[][] dp = new long[m][n];
        long[][] sum = new long[m][n];

        for (int i = 0; i < m; ++i) {
            Arrays.fill(sum[i], 0);
        }

        dp[0][0] = grid[0][0] % k;
        sum[0][0] = grid[0][0];

        for (int i = 1; i < n; ++i) {
            dp[0][i] = ((dp[0][i - 1] + sum[0][i - 1]) % MOD * pow(grid[0][i], k)) % MOD;
            sum[0][i] = (sum[0][i - 1] + grid[0][i]) % MOD;
        }

        for (int i = 1; i < m; ++i) {
            dp[i][0] = ((dp[i - 1][0] + sum[i - 1][0]) % MOD * pow(grid[i][0], k)) % MOD;
            sum[i][0] = (sum[i - 1][0] + grid[i][0]) % MOD;
        }

        for (int i = 1; i < m; ++i) {
            for (int j = 1; j < n; ++j) {
                long currSum = (sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1] + grid[i][j]) % MOD;
                dp[i][j] = ((currSum * pow(grid[i][j], k)) % MOD + dp[i - 1][j] + dp[i][j - 1]) % MOD;
                sum[i][j] = (sum[i - 1][j] + sum[i][j - 1] + grid[i][j]) % MOD;
            }
        }

        return (int) ((dp[m - 1][n - 1] * pow(grid[m - 1][n - 1], k)) % MOD);
    }

    private long pow(long x, int y) {
        if (y == 0) return 1;
        long temp = pow(x, y / 2);
        if ((y & 1) != 0) return (((temp * temp) % MOD) * x) % MOD;
        else return (temp * temp) % MOD;
    }
}

