public class Solution {
    public int numberOfPaths(int[][] grid, int k) {
        final int MOD = 1000000007;
        int rows = grid.length;
        int cols = grid[0].length;

        long[][] dpSum = new long[rows][cols];
        long[][] dpCount = new long[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == 0 && j == 0) {
                    dpSum[i][j] = grid[i][j];
                    dpCount[i][j] = 1;
                } else {
                    long sum = 0;
                    int count = 0;
                    if (i > 0) {
                        sum += dpSum[i - 1][j];
                        count += dpCount[i - 1][j];
                    }
                    if (j > 0) {
                        sum += dpSum[i][j - 1];
                        count += dpCount[i][j - 1];
                    }

                    long temp = sum + grid[i][j];
                    long remainder = temp % k;
                    long multiple = BigInteger.valueOf(k).divide(BigInteger.valueOf(remainder))
                            .multiply(BigInteger.valueOf(count)).longValue();

                    if (remainder == 0) {
                        dpSum[i][j] = temp;
                        dpCount[i][j] = count + multiple;
                    } else if ((temp - remainder) % k == 0) {
                        dpSum[i][j] = temp - remainder;
                        dpCount[i][j] = multiple;
                    } else {
                        dpSum[i][j] = temp;
                        dpCount[i][j] = 0;
                    }
                }

                dpSum[i][j] %= MOD;
            }
        }

        return (int)dpCount[rows - 1][cols - 1];
    }
}

