public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        if (n <= 2) return 0;

        int left = 0, right = n - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            int jumpLength = stones[mid] - stones[left];
            int maxStoneJumped = getFarthest(stones, mid, jumpLength);
            if (maxStoneJumped >= right) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return stones[right] - stones[0];
    }

    private int getFarthest(int[] stones, int start, int jumpLength) {
        int farthest = start;
        for (int i = start + 1; i < stones.length && stones[i] - stones[start] <= jumpLength; i++) {
            farthest = Math.max(farthest, i);
        }
        return farthest;
    }
}

