public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        if (n <= 2) return 0;

        int maxReachable = stones[0];
        int farthestReachable = stones[0];

        for (int i = 1; i < n - 1; i++) {
            int currStone = stones[i];

            // If we can reach here, update maxReachable
            if (currStone <= maxReachable) {
                maxReachable = Math.max(maxReachable, currStone + (stones[n - 1] - currStone));
            }

            // Update farthest reachable stone and maxReachable
            else if (farthestReachable < currStone) {

                farthestReachable = currStone;
                maxReachable = Math.max(maxReachable, stones[n-1]-currStone);
            }
        }

        return (int) Math.ceil((double)(stones[n - 1] - farthestReachable)/2.0);
    }
}

