public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        int n = nums.length;
        List<Integer> res = new ArrayList<>();

        boolean[] increasing = new boolean[n];
        boolean[] decreasing = new boolean[n];

        for (int i = 0; i < k; i++) {
            if (i == 0 || nums[i] >= nums[i - 1]) {
                increasing[i] = true;
            }
            if (i == 0 || nums[n - i - 1] <= nums[n - i]) {
                decreasing[n - i - 1] = true;
            }
        }

        for (int i = k; i < n - k; i++) {
            if (increasing[i - 1] && decreasing[i + 1]) {
                res.add(i);
            } else if (i > k) {
                int len = Math.min(i, k);
                if (nums[i - 1] >= nums[i - len - 1]) {
                    increasing[i] = true;
                }
                if (nums[n - i - 1] <= nums[n - i + len]) {
                    decreasing[n - i - 1] = true;
                }
            }
        }

        for (int i = n - k; i < n; i++) {
            int len = Math.min(i, k);
            if (nums[i - 1] >= nums[i - len - 1]) {
                increasing[i] = true;
            }
            if (nums[n - i - 1] <= nums[n - i + len]) {
                decreasing[n - i - 1] = true;
            }
        }

        for (int i = k; i < n - k; i++) {
            if (increasing[i - 1] && decreasing[i + 1]) {
                res.add(i);
            }
        }

        return res;
    }
}

