public class Solution {
    public int longestContinuousSubstring(String s) {
        int maxLen = 0;
        int start = 0;

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) - 'a' != s.charAt(i-1) - 'a' + 1) {
