            adjList[edge[1]].add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] depth = new int[n];

        dfs(0, -1, 0, adjList, parent, depth);

        long[][] dp = new long[n][2];
        for (int i = 0; i < n; i++) {
            if (amount[i] >= 0) {
                dp[i][0] = amount[i];
            } else {
                dp[i][1] = -amount[i];
            }
        }

        int bobDepth = depth[bob];

        for (int i = 0; i < n; i++) {
            if (depth[i] > bobDepth) {
                long sum = 0;
                long maxSum = Long.MIN_VALUE;
                int curr = i;
                while (curr != -1) {
                    sum += dp[curr][0];
                    maxSum = Math.max(maxSum, sum);
                    curr = parent[curr];
                }
                dp[i][0] = maxSum;
            }
        }

        long ans = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if (amount[i] >= 0) {
                ans = Math.max(ans, dp[i][0]);
            } else {
                ans = Math.max(ans, -dp[i][1]);
            }
        }

        return (int)ans;
    }

    private int dfs(int node, int par, int depth, List<Integer>[] adjList, int[] parent, int[] depthArr) {
        parent[node] = par;
        depthArr[node] = depth;

        for (int child : adjList[node]) {
            if (child != par) {
                dfs(child, node, depth + 1, adjList, parent, depthArr);
            }
        }

        return depthArr[node];
    }
}

