public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        parent[bob] = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(bob);

        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int neighbor : graph.get(node)) {
                if (parent[neighbor] == -1) {
                    parent[neighbor] = node;
                    queue.offer(neighbor);
                }
            }
        }

        long[] dp = new long[n];
        Arrays.fill(dp, Long.MIN_VALUE);
        dfs(graph, amount, 0, bob, parent, dp);

        int maxProfit = (int) dp[0];
        for (long profit : dp) {
            if (profit > maxProfit) {
                maxProfit = (int) profit;
            }
        }

        return maxProfit;
    }

    private long dfs(List<List<Integer>> graph, int[] amount, int node, int bob, int[] parent, long[] dp) {
        if (node == 0 || dp[node] != Long.MIN_VALUE) {
            return dp[node];
        }

        int price = Math.abs(amount[node]);
        int reward = amount[node];
        long maxProfit = -price;

        for (int neighbor : graph.get(node)) {
            if (neighbor != bob && parent[neighbor] == node) {
                long profit = dfs(graph, amount, neighbor, bob, parent, dp);
                profit += price / 2; // If we open the gate here

                if (profit > maxProfit) {
                    maxProfit = profit;
                }

                profit -= reward / 2; // If we receive a reward here
                if (profit > maxProfit) {
                    maxProfit = profit;
                }
            }
        }

        dp[node] = maxProfit;
        return dp[node];
    }
}

