import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        // Create an adjacency list to represent the graph
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        // Initialize a visited set and a memoization map
        Set<Integer> visited = new HashSet<>();
        Map<String, Integer> memo = new HashMap<>();

        // Perform DFS from the current position of Bob
        int maxProfit = dfs(graph, 0, bob, amount, visited, memo);

        return maxProfit;
    }

    private int dfs(List<Integer>[] graph, int node, int bob, int[] amount, Set<Integer> visited, Map<String, Integer> memo) {
        // If the current node is already visited or if it's Bob's position, return 0
        if (visited.contains(node)) {
            return 0;
        }

        // Mark the current node as visited
        visited.add(node);

        // Create a key for memoization
        String key = node + "," + bob;

        // If the result is already in the memo map, return it directly
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int profit;
        int[] nodeAmount = {amount[node], 0};
        if (node == bob) {
            // Bob's turn, he can move freely
            for (int child : graph[node]) {
                nodeAmount[1] += dfs(graph, child, bob, amount, visited, memo);
            }
            profit = Math.max(nodeAmount[0], -nodeAmount[1]);
        } else {
            // Alice's turn, she must move towards the leaf
            int minChildProfit = Integer.MAX_VALUE;
            for (int child : graph[node]) {
                if (!visited.contains(child)) {
                    int childProfit = dfs(graph, child, bob, amount, visited, memo);
                    minChildProfit = Math.min(minChildProfit, childProfit);
                }
            }
            profit = Math.max(nodeAmount[0], -minChildProfit / 2 + nodeAmount[1]);
        }

        // Store the result in the memo map
        memo.put(key, profit);

