import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    public int countTime(String time) {
        Pattern pattern = Pattern.compile("(\\?\\d):\\d\\d");
        Matcher matcher = pattern.matcher(time);

        if (!matcher.matches()) {
            return 1; // If the input string does not contain '?' then it is a valid time
        }

        int totalCombinations = countFirstHour(matcher, "0") + countFirstHour(matcher, "1");

        return totalCombinations;
    }

    private int countFirstHour(Matcher matcher, String firstDigit) {
        if (firstDigit.equals("2")) {
            return 0; // If the first digit is '2' then it will be invalid time
        }

        boolean found = false;
        while (matcher.find()) {
            String hourStr = matcher.group(1);
            for (int i = 0; i <= 9; i++) {
                if (!hourStr.equals("?") && !hourStr.equals(firstDigit)) {
                    break;
                }

                String newTime = hourStr.replace("?", firstDigit + "" + i);
                Pattern timePattern = Pattern.compile("^([0-2][0-3]):[0-5][0-9]$");
                Matcher timeMatcher = timePattern.matcher(newTime);
                if (timeMatcher.matches()) {
                    found = true;
                    break;
                }
            }

            if (!found) {
                return 0; // If no valid combinations are found for the current hour then stop
            }
        }

        return 1;
    }
}

