public class Solution {
    public int countTime(String time) {
        return solve(time);
    }

    private int[] getValidTimes(int hour, int minute, String time) {
        if (time.equals("hh")) {
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < 2 - String.valueOf(hour).length(); i++) {
                result.append('0');
            }
            return new int[]{Integer.parseInt(result.toString() + hour)};
        } else if (time.equals("mm")) {
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < 2 - String.valueOf(minute).length(); i++) {
                result.append('0');
            }
            return new int[]{Integer.parseInt(result.toString() + minute)};
        }

        return null;
    }

    private int solve(String time) {
        if (!time.contains("?")) {
            return 1;
        }

        for (int possibleHours = 0; possibleHours < 24; possibleHours++) {
            String firstPart = getValidTimes(possibleHours, -1, "hh")[0] + ":";

            for (int minute = 0; minute < 60; minute++) {
                if ((firstPart + String.format("%02d", minute)).equals(time)) {
                    return 2;
                }

                int[] validMinutes = getValidTimes(-1, minute, "mm");
                if (validMinutes != null) {
                    for (int i : validMinutes) {
                        if ((firstPart + String.valueOf(i)).equals(time)) {
                            return 2;
                        }
                    }
                }
            }
        }

        return 0;
    }
}

