public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        boolean[][] palindrome = new boolean[n][n];

        // Create a 2D array to store whether each substring is a palindrome or not
        for (int i = 0; i < n; i++) {
            palindrome[i][i] = true;
        }

        int count = 0;

        // Iterate over the string from left to right
        for (int length = 2; length <= k; length++) {
            for (int i = 0; i <= n - length; i++) {
                int j = i + length - 1;

                if (length == 2) {
                    palindrome[i][j] = s.charAt(i) == s.charAt(j);
                } else {
                    palindrome[i][j] = s.charAt(i) == s.charAt(j) && palindrome[i+1][j-1];
                }
            }
        }

        // Count the maximum number of non-overlapping palindromes
        int maxCount = 0;
        for (int i = 0; i < n - k + 1; i++) {
            if (palindrome[i][i+k-1]) {
                maxCount++;

                // If a palindrome is found, mark the remaining part as false to avoid counting overlapping palindromes
                for (int j = i; j <= i+k-2; j++) {
                    palindrome[j][j+k-1] = false;
                }
            }
        }

        return maxCount;
    }
