public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final Set<Character> PRIME_DIGITS = new HashSet<>(Arrays.asList('2', '3', '5', '7'));

    public int beautifulPartitions(String s, int k, int minLength) {
        long[] dp = new long[s.length() + 1];
        dp[0] = 1;
        for (int i = 1; i <= s.length(); i++) {
            char c = s.charAt(i - 1);
            if (!PRIME_DIGITS.contains(c)) {
                for (int j = Math.max(0, i - minLength + 1); j < i; j++) {
                    dp[i] += dp[j];
                    dp[i] %= MOD;
                }
            } else {
                int prevPrimeIndex = getPrevPrimeIndex(s, i);
                if (prevPrimeIndex != -1) {
                    for (int j = Math.max(0, i - minLength + 1); j <= prevPrimeIndex; j++) {
                        dp[i] += dp[j];
                        dp[i] %= MOD;
                    }
                }
            }
        }
        return (int) (dp[s.length()] % MOD);
    }

    private int getPrevPrimeIndex(String s, int i) {
        for (int j = i - 1; j >= 0; j--) {
            if (!PRIME_DIGITS.contains(s.charAt(j))) {
                return j;
            }
        }
        return -1;
    }
}

