public class Solution {
    private Map<String, Integer> memo = new HashMap<>();
    private final int MOD = 1000000007;

    public int beautifulPartitions(String s, int k, int l) {
        return dp(s, k, l, 0);
    }

    private int dp(String s, int k, int minLength, long prefix) {
        if (memo.containsKey(s + "," + k + "," + minLength + "," + prefix)) {
            return memo.get(s + "," + k + "," + minLength + "," + prefix);
        }
        if (k == 0 || s.length() < minLength) {
            return 1;
        }

        int count = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            // Check if the current character is a prime digit
            boolean isPrime = "275".indexOf(c) != -1;

            String remainingString = s.substring(0, i) + s.substring(i + 1);
            long newPrefix = prefix * 10 + (isPrime ? 0 : 1);

            // Recursively calculate the number of beautiful partitions for the remaining string
            count += dp(remainingString, k - 1, minLength, newPrefix);

            if (count >= MOD) {
                count -= MOD;
            }
        }

        memo.put(s + "," + k + "," + minLength + "," + prefix, count);
        return count;
    }
}

