        return dfs(s, k, minLength, 0, memo);
    }

    private int dfs(String str, int k, int minLength, int start, Map<String, Integer> memo) {
        if (memo.containsKey(str + "#" + start)) {
            return memo.get(str + "#" + start);
        }
        if (k == 1 && str.length() >= minLength) {
            return 1;
        }
        if (str.isEmpty()) {
            return 0;
        }

        int res = 0;
        for (int i = start; i < str.length(); i++) {
            char c = str.charAt(i);
            if (!PRIMES.contains(c)) {
                continue;
            }
            String rest = str.substring(0, i) + str.substring(i + 1);
            int curr = dfs(rest, k - 1, minLength, i + 1, memo);
            res += curr;
        }

        res %= MOD;
        memo.put(str + "#" + start, res);
        return res;
    }
}

