import java.util.*;

public class Solution {
    private final int MOD = (int) 1e9 + 7;
    private final Set<Character> primeDigits = new HashSet<>(Arrays.asList('2', '3', '5', '7'));
    public int beautifulPartitions(String s, int k, int minLength) {
        Map<String, Integer> dp = new HashMap<>();
        dfs(s, 0, k, minLength, dp);
        return dp.getOrDefault("", 0);
    }

    private void dfs(String s, int i, int count, int minLen, Map<String, Integer> dp) {
        if (count < 1) {
            return;
        }
        if (i == s.length()) {
            if (count == 1) {
                dp.put("", 1);
            } else {
                dp.put("", 0);
            }
            return;
        }

        int ways = 0;

        boolean isPrimeStart = primeDigits.contains(s.charAt(i));
        boolean isValidPartition = isPrimeStart && !primeDigits.contains(s.charAt(i + minLen - 1));

        if (isValidPartition) {
            dfs(s, i + 1, count - 1, minLen, dp);
            ways += dp.getOrDefault("", 0);
        }

        for (int len = minLength; len <= s.length() - i; len++) {
            isValidPartition = isPrimeStart && !primeDigits.contains(s.charAt(i + len));

            if (isValidPartition) {
                dfs(s, i + len, count, minLen, dp);
                ways += dp.getOrDefault("", 0);
            }
        }

        String key = String.valueOf(count) + ":" + i;
        dp.put(key, ways % MOD);
    }
}

