    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] size = new int[n];

        dfs(0, -1, graph, parent, size);

        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (!map.containsKey(size[i])) {
                map.put(size[i], 0);
            }
            map.put(size[i], map.get(size[i]) + nums[i]);
        }

        int max = Collections.max(map.values());
        return edges.length - (int) Arrays.stream(nums).sum() / max;
    }

    private void dfs(int node, int parent, List<Integer>[] graph, int[] parentArr, int[] sizeArr) {
        for (int child : graph[node]) {
            if (child != parent) {
                parentArr[child] = node;
                sizeArr[child] = 1 + dfs(child, node, graph, parentArr, sizeArr);
            }
        }
        return sizeArr[node];
    }
}

