            if (!visited[i]) {
                res += dfs(i, graph, visited, nums, targetSum);
            }
        }

        return res;
    }

    private int dfs(int node, List<Integer>[] graph, boolean[] visited, int[] nums, int targetSum) {
        visited[node] = true;
        int sum = nums[node];

        for (int neighbor : graph[node]) {
            if (!visited[neighbor]) {
                sum += dfs(neighbor, graph, visited, nums, targetSum);
            }
        }

        return sum == targetSum ? 1 : 0;
    }
