    public int componentValue(int[] nums, int[][] edges) {
        n = nums.length;
        // Create the adjacency list
        graph = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            graph.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // Initialize the parent array and visited array
        parent = new int[n];
        Arrays.fill(parent, -1);
        visited = new boolean[n];

        // Find the total sum of all values in the tree
        long totalSum = 0;
        for (int value : nums) {
            totalSum += value;
        }

        // Perform DFS to find the maximum number of edges that can be deleted
        int maxEdgesDeleted = 0;
        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                long componentSum = dfs(i, totalSum);
                if (componentSum != -1 && componentSum * 2 <= totalSum) {
                    maxEdgesDeleted++;
                }
            }
        }

        return maxEdgesDeleted;
    }

    private long dfs(int node, long totalSum) {
        visited[node] = true;

        // Find the sum of values in the subtree rooted at node
        long componentSum = nums[node];
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                long subTreeSum = dfs(neighbor, totalSum);
                if (subTreeSum != -1) {
                    componentSum += subTreeSum;
                }
            } else if (parent[node] == -1 && parent[neighbor] != node) { // If neighbor is a root and not the parent of node
                return -1; // This means we have found a cycle in the tree, so it's impossible to split the tree into components with equal values
            }
        }

        return componentSum;
    }
