import java.util.*;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        List<Integer>[] graph = new List[nums.length];
        for (int i = 0; i < nums.length; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            graph[u].add(v);
            graph[v].add(u); // since it's an undirected tree
        }

        int n = nums.length;
        long[] subtreeValues = new long[n];

        for (int i = 0; i < n; i++) {
            if (subtreeValues[i] == 0) {
                dfs(graph, subtreeValues, i);
            }
        }

        // The maximum number of edges we can delete is equal to the total sum
        // of all node values minus the minimum value of any connected component.
        long maxEdges = 0;
        for (long v : subtreeValues) {
            maxEdges += nums.length * nums[nums.length - 1] - v;
        }

        return (int) (maxEdges / (nums.length * nums[nums.length - 1]));
    }

    private void dfs(List<Integer>[] graph, long[] subtreeValues, int node) {
        if (subtreeValues[node] != 0) return; // already processed
        subtreeValues[node] = nums[node];

        for (int neighbor : graph[node]) {
            dfs(graph, subtreeValues, neighbor);
            subtreeValues[node] += subtreeValues[neighbor];
        }
    }
}

