import java.util.*;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i : nums) {
            map.put(i, map.getOrDefault(i, 0) + 1);
        }

        List<Set<Integer>> groups = new ArrayList<>();
        boolean[] visited = new boolean[nums.length];
        int groupNum = 0;
        for (int i = 0; i < nums.length; ++i) {
            if (!visited[i]) {
                Set<Integer> set = new HashSet<>();
                dfs(i, visited, map.get(nums[i]), set);
                groups.add(set);
                ++groupNum;
            }
        }

        int targetSize = groupNum * map.values().stream().mapToInt(Integer::intValue).sum() / groupNum;
        // if the total number of nodes is not perfectly divisible by the group size,
        // then we need to make at least one group smaller, so return -1
        if (groupNum > 0 && targetSize != map.values().stream().mapToInt(Integer::intValue).sum() / groupNum) {
            return -1;
        }

        int maxEdges = 0;
        for (int i = 0; i < edges.length; ++i) {
            int[] edge = edges[i];
            // we need to delete an edge if and only if doing so will not cause the size of a group
            // to be less than targetSize, which is true if the two nodes in this edge are both
            // in the same group or in different groups and together they make up at least 2*targetSize nodes
            boolean canDelete = (groups.get(edge[0]).size() < targetSize) || (groups.get(edge[1]).size() < targetSize);
            if (canDelete && map.get(nums[edge[0]]) >= 2 * targetSize && map.get(nums[edge[1]]) >= 2 * targetSize) {
                maxEdges++;
            }
        }

        return edges.length - maxEdges;
    }

    private void dfs(int node, boolean[] visited, int size, Set<Integer> set) {
        if (node < 0 || size <= 0) {
            return;
        }
        // mark this node as visited
        visited[node] = true;

        for (int i = 0; i < size; ++i) {
            int[] edge = edges[i];
            if (!visited[edge[1]]) {
                set.add(edge[0]);
                dfs(edge[1], visited, size - 1, set);
            }
        }
    }
}

