import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        Map<Integer, Integer> penaltyMap = new HashMap<>();

        // Initialize a prefix sum array of length n+1 to keep track of the minimum penalty up to each hour
        int[] minPenaltySum = new int[n + 1];
        int totalN = 0;

        for (int i = 0; i < customers.length(); i++) {
            char c = customers.charAt(i);

            // If the customer comes at this hour, increment the total number of Ns and adjust minPenaltySum accordingly
            if (c == 'Y') {
                penaltyMap.put(i - totalN + 1, penaltyMap.getOrDefault(i - totalN + 1, 0) + totalN);
                totalN++;
            } 
            // If the customer does not come at this hour, keep track of the number of Ns
            else {
                minPenaltySum[i + 1] = minPenaltySum[i] + (totalN - penaltyMap.getOrDefault(i, 0));
            }
        }

        int minPenalty = Integer.MAX_VALUE;
        int closestJ = 0;

        // Find the hour at which the shop must be closed to incur a minimum penalty
        for (int j = 0; j <= n; j++) {
            int penalty = penaltyMap.getOrDefault(j, 0) + minPenaltySum[j];

            if (penalty < minPenalty) {
                minPenalty = penalty;
                closestJ = j;
            }
        }

        return closestJ;
    }
}

