import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public int equalizeArray(int[] nums, int[] cost) {
        int n = nums.length;
        long totalCost = 0;

        // Sort the array based on the cost
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (cost[i] > cost[j]) {
                    int temp = nums[i];
                    nums[i] = nums[j];
                    nums[j] = temp;

                    int tempCost = cost[i];
                    cost[i] = cost[j];
                    cost[j] = tempCost;
                }
            }
        }

        // Find the median of the array
        long median = getMedian(nums, n);

        // Calculate the total cost
        for (int i = 0; i < n; i++) {
            int diff = Math.abs(nums[i] - median);
            totalCost += (long)diff * cost[i];
        }

        return (int)(totalCost % (int)(1e9 + 7));
    }

    private long getMedian(int[] nums, int n) {
        if (n % 2 == 0) {
            // If the length is even
            int mid1 = nums[n / 2 - 1];
            int mid2 = nums[n / 2];

            return (long)(mid1 + mid2) / 2;
        } else {
            // If the length is odd
            return nums[(n - 1) / 2];
        }
    }
}

