public class Solution {
    public int equalizeArray(int[] nums, int[] cost) {
        if (nums.length == 0 || cost.length == 0) return 0;

        int max = Integer.MIN_VALUE;
        for (int i : cost) {
            max = Math.max(max, i);
        }

        int n = nums.length;
        List<Integer> list = new ArrayList<>();
        for (int num : nums) {
            list.add(num);
        }

        list.sort(Comparator.naturalOrder());
        long totalCost = 0;
        for (int i = 0; i < n / 2; i++) {
            int diff = list.get(n - i - 1) - list.get(i);
            if (diff == 0) continue;

            int minCost = Integer.MAX_VALUE;
            for (int j = 0; j < cost.length; j++) {
                if (nums[j] == list.get(n - i - 1)) {
                    minCost = Math.min(minCost, cost[j]);
                }
                if (nums[j] == list.get(i)) {
                    minCost = Math.min(minCost, cost[j]);
                }
            }

            totalCost += (long) minCost * diff;
        }

        return (int)totalCost;
    }
}

