public class Solution {
    public int equalizeArray(int[] nums, int[] cost) {
        int n = nums.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; ++i) {
            indices[i] = i;
        }
        java.util.Arrays.sort(indices, Comparator.comparingInt(i -> cost[i]));
        long totalCost = 0;
        int currentNum = nums[indices[0]];
        for (int i = 1; i < n; ++i) {
            if (nums[indices[i]] > currentNum) {
                int operations = nums[indices[i]] - currentNum;
                totalCost += (long) operations * cost[indices[i]];
                currentNum = nums[indices[i]];
            } else {
                int operations = currentNum - nums[indices[i]];
                totalCost += (long) operations * cost[indices[i]];
                currentNum = nums[indices[i]];
            }
        }
        return (int) totalCost;
    }
}

