    public long makeIntegerBeautiful(long n, int target) {
        String strN = Long.toString(n);
        StringBuilder sb = new StringBuilder(strN);

        // remove trailing zeros before processing
        while (sb.length() > 1 && sb.charAt(sb.length() - 1) == '0') {
            sb.deleteCharAt(sb.length() - 1);
        }

        long sum = 0;
        for (int i = sb.length() - 1; i >= 0; i--) {
            int digit = Character.getNumericValue(sb.charAt(i));
            if (sum + digit > target) {
                // subtract the current digit from the sum
                sum -= digit;
                // add one to the next digit in the string, effectively incrementing it
                sb.setCharAt(i, (char) ((Character.getNumericValue(sb.charAt(i)) - 1) % 10 + '0'));
            } else {
                sum += digit;
            }
        }

        return Long.parseLong(sb.toString());
    }
}

