    public long makeIntegerBeautiful(long n, int target) {
        String strN = Long.toString(n);

        // Calculate sum of digits of 'n'
        int sumOfDigits = 0;
        for (int i = 0; i < strN.length(); i++) {
            sumOfDigits += Character.getNumericValue(strN.charAt(i));
        }

        long x = n;

        while (sumOfDigits > target) {
            // Decrease 'x' by 1 in each iteration
            x--;

            // Remove last digit from 'n'
            String strLastDigit = String.valueOf(n % 10);
            String strRemainingN = Long.toString(n / 10);

            // Update 'sumOfDigits' and 'n'
            sumOfDigits -= Character.getNumericValue(strLastDigit.charAt(0));
