public class Solution {
    private int[] nums;
    private int k;
    private int n;

    public int longestSubsequence(int[] nums, int k) {
        this.nums = nums;
        this.k = k;
        this.n = nums.length;
        return dfs(0);
    }

    private int dfs(int idx) {
        if (idx == n) {
            return 0;
        }
        if (memo[idx] != -1) {
            return memo[idx];
        }
        int val = nums[idx];
        int res = 1 + dfs(idx + 1);
        for (int i = idx + 1; i < n; ++i) {
            if (nums[i] > val && nums[i] - val <= k) {
                res = Math.max(res, 1 + dfs(i));
            }
        }
        memo[idx] = res;
        return res;
    }

    private int[] memo;

    public Solution() {
        this.memo = new int[n];
        Arrays.fill(this.memo, -1);
    }
}

