            int len = query(i, nums.length - 1);
            if (len > maxLen) {
                maxLen = len;
            }
        }

        return maxLen;
    }

    private int query(int l, int r) {
        if (l == r)
            return 1;

        int mid = (l + r) / 2;
        int left = query(l, mid);
        int right = query(mid + 1, r);

        if (nums[mid] - nums[l] > k) {
            if (left < right)
                return right;
            else
                return left;
        } else
            return Math.max(left, right);
    }
}

