public class Solution {
    public int distinctAverages(int[] nums) {
        Arrays.sort(nums);

        Set<Double> averages = new HashSet<>();

        while (nums.length > 0) {
            double min = nums[0];
            double max = nums[nums.length - 1];

            int minIndex = 0;
            int maxIndex = nums.length - 1;

            for (int i = 1; i < nums.length; i++) {
                if (nums[i] == min) {
                    minIndex = i + 1;
                }
                else if (nums[nums.length - i - 1] == max) {
                    maxIndex = nums.length - i - 2;
                }
            }

            int index1 = Math.min(minIndex, maxIndex);
            int index2 = Math.max(minIndex, maxIndex);

            double average = (min + max) / 2.0;

            averages.add(average);

            if (index1 > index2) {
                index1--;
            }

            for (int i = minIndex; i <= index1; i++) {
                nums[i - (index1 - minIndex)] = nums[i];
            }
            for (int i = maxIndex; i >= index2; i--) {
                nums[i + (maxIndex - index2)] = nums[i];
            }

            nums = Arrays.copyOfRange(nums, 0, Math.min(index1, index2) + 2);
        }

        return averages.size();
    }
}

