public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        Arrays.sort(vals);

        UnionFind uf = new UnionFind(n);
        Map<Integer, List<Integer>> map = new HashMap<>();

        for (int i = 0; i < n; i++) {
            map.putIfAbsent(vals[i], new ArrayList<>());
            map.get(vals[i]).add(i);
        }

        int count = 0;
        for (int[] edge : edges) {
            int u = uf.find(edge[0]);
            int v = uf.find(edge[1]);

            if (vals[u] <= vals[v]) {
                uf.union(u, v);
            } else {
                uf.union(v, u);
            }
        }

        for (int i = 0; i < n; i++) {
            List<Integer> list = map.get(vals[i]);
            int size = list.size();

            for (int j = 1; j < size; j++) {
                int rootU = uf.find(list.get(j - 1));
                int rootV = uf.find(list.get(j));

                if (rootU == rootV) {
                    count += j;
                }
            }
        }

        return count;
    }

    class UnionFind {
        private int[] parent;
        private int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }
    }
}

