        int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            Arrays.fill(parent, -1);
            rank = new int[n];
        }

        public int find(int x) {
            if (parent[x] < 0) return x;
            parent[x] = find(parent[x]);
            return parent[x];
        }

        public void union(int x, int y) {
            x = find(x);
            y = find(y);
            if (x != y) {
                if (rank[x] > rank[y]) {
                    parent[y] = x;
                    rank[x] += rank[y];
                } else {
                    parent[x] = y;
                    rank[y] += rank[x];
                }
            }
        }
    }
