public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        Arrays.sort(vals);

        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.putIfAbsent(vals[i], new ArrayList<>());
        }

        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            graph.get(Math.min(vals[a], vals[b])).add(Math.max(vals[a], vals[b]));
        }

        int count = 0;
        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            if (entry.getValue().isEmpty()) continue;

            int curValue = entry.getKey();
            Stack<Integer> stack = new Stack<>();
            stack.push(curValue);

            while (!stack.isEmpty() && !graph.containsKey(stack.peek())) {
                int top = stack.pop();
                for (int neighbor : graph.get(top)) {
                    if (neighbor > curValue) continue;
                    count++;
                    if (neighbor == curValue) {
                        stack.push(neighbor);
                    }
                }
            }

            while (!stack.isEmpty()) {
                int top = stack.pop();
                for (int neighbor : graph.get(top)) {
                    if (neighbor > curValue) continue;
                    count++;
                    if (neighbor == curValue) {
                        stack.push(neighbor);
                    }
                }
            }
        }

        return count / 2; // Count each path twice
    }
}

