public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        Arrays.sort(vals);

        List<int[]>[] adjList = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            adjList[u].add(new int[]{v, vals[v]});
            adjList[v].add(new int[]{u, vals[u]});
        }

        int count = 0;
        Set<Integer> maxValSet = new HashSet<>();
        for (int i = n - 1; i >= 0; i--) {
            int[] curNode = {i, vals[i]};

            maxValSet.add(vals[i]);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));

            boolean visited = false;
            while (!pq.isEmpty() || !adjList[i].isEmpty()) {
                if (visited) break;

                while (!adjList[i].isEmpty() && adjList[i].get(0)[0] != curNode[0]) {
                    int[] next = adjList[i].remove(0);
                    pq.offer(next);
                }

                while (!pq.isEmpty() && !maxValSet.contains(pq.peek()[1])) {
                    pq.poll();
                }

                if (!pq.isEmpty()) {
                    int[] next = pq.poll();

                    if (next[0] == curNode[0]) visited = true;
                    else if (Math.max(curNode[1], next[1]) <= vals[i]) count++;
                } else break;
            }
        }

        return count;
    }
}

