    public int[] secondGreaterElement(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();
        int n = nums.length;
        int[] result = new int[n];

        // First pass: find first greater element for each number
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[i] > nums[stack.peekLast()]) {
                result[stack.pollLast()] = nums[i];
            }
            stack.offerLast(i);
        }

        // Second pass: find second greater element for each number
        Arrays.fill(result, -1);  // Reset the result array
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[i] > nums[stack.peekLast()]) {
                int j = stack.pollLast();
                if (result[j] == -1) {  // If first greater element is not found, set second greater element to current number
                    result[j] = nums[i];
                }
            }
        }

        return result;
    }
}

