public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // Sort all meetings by their start time
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        // Initialize the priority queue to store available rooms and the number of times each room is used
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] != b[1] ? b[1] - a[1] : a[0] - b[0]);
        for (int i = 0; i < n; i++) {
            pq.offer(new int[] {i, 0});
        }

        // Initialize the map to store the number of times each room is used
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int i = 0; i < n; i++) {
            cnt.put(i, 0);
        }

        // Initialize a set to store all delayed meetings
        Set<int[]> delayedMeetings = new HashSet<>();

        int curTime = 0;
        while (!pq.isEmpty() || !delayedMeetings.isEmpty()) {

            // If there are available rooms and the current time is less than or equal to the start time of the next meeting, 
            // assign a room to the next meeting
            if (!pq.isEmpty() && (curTime <= meetings[0][0] || !delayedMeetings.isEmpty())) {
                int[] room = pq.poll();
                int roomId = room[0];
                cnt.put(roomId, cnt.get(roomId) + 1);

                // If there are delayed meetings and their start time is less than or equal to the current time, 
                // assign a room to the first delayed meeting
                if (!delayedMeetings.isEmpty() && ((curTime <= meetings[0][0] || delayedMeetings.iterator().next()[0] <= curTime))) {
                    int[] delayedMeeting = delayedMeetings.iterator().next();
                    delayedMeetings.remove(delayedMeeting);
                    pq.offer(new int[] {delayedMeeting[1], -cnt.get(delayedMeeting[1])});
                }
            }

            // Move to the next meeting
            while (!pq.isEmpty() && meetings[0][0] <= curTime) {
                int[] room = pq.poll();
                int roomId = room[0];
                pq.offer(new int[] {roomId, -cnt.get(roomId)});
                curTime++;
            }
            if (meetings.length > 0 && meetings[0][0] == curTime) {
                delayedMeetings.add(meetings[0]);
                meetings = Arrays.copyOfRange(meetings, 1, meetings.length);
            }

        }

        // Find the room with the most bookings
        int maxCnt = Collections.max(cnt.values());
        for (int roomId : cnt.keySet()) {
            if (cnt.get(roomId) == maxCnt) return Math.min(roomId, Collections.min(cnt.keySet()));
        }
        throw new RuntimeException("No such case should happen.");
    }
}

