public class Solution {

    public int mostBooked(int n, int[][] meetings) {
        // Sort all the meetings by their start time
        Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] == b[0] ? b.length - a.length : b[0] - a[0]);
        // Add all the meetings with start time of 0 as they are the earliest ones
        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{i, 0});
        }

        int[] rooms = new int[n];
        Arrays.fill(rooms, -1);
        TreeMap<Integer, Integer> roomUsed = new TreeMap<>();
        TreeMap<Integer, Integer> totalMeetings = new TreeMap<>();

        for (int[] meeting : meetings) {
            int start = meeting[0], end = meeting[1];

            // While there's an available room that is not being used
            while (!roomUsed.isEmpty() && rooms[pq.peek()[0]] == -1 && pq.peek()[1] <= start) {
                int r = pq.poll();
                roomUsed.put(r[0], r[1]);
                totalMeetings.put(r[0], totalMeetings.getOrDefault(r[0], 0) + 1);
            }

            // If there are no available rooms, delay the meeting
            if (pq.isEmpty()) {
                int[] newMeeting = {start, end - start};
                pq.offer(newMeeting);

                roomUsed.put(pq.peek()[0], pq.peek()[1]);
                totalMeetings.put(pq.peek()[0], totalMeetings.getOrDefault(pq.peek()[0], 0) + 1);
            } else {
                // Allocate the meeting to an available room with the smallest number
                int r = pq.poll();
                roomUsed.remove(r[0]);

                rooms[r[0]] = end;
                pq.offer(new int[]{r[0], r[1] + (end - start)});
            }
        }

        return totalMeetings.firstKey();
    }
