        boolean foundMin = false, foundMax = false;

        for (int i = 0; i < nums.length; i++) {
            int j = i;

            while (j < nums.length && (nums[j] <= maxK || nums[j] >= minK)) {
                if (!foundMin && nums[j] == minK) {
                    foundMin = true;
                }

                if (!foundMax && nums[j] == maxK) {
                    foundMax = true;
                }

                while (j < nums.length - 1 && (nums[j + 1] <= maxK || nums[j + 1] >= minK)) {
                    j++;

                    if (foundMin && foundMax && nums[j] != minK && nums[j] != maxK) {
                        count += i;
                        break;
                    }
                }

                if (foundMin && foundMax && nums[i] != minK && nums[i] != maxK) {
                    count++;
                }

                j++;
            }

            foundMin = false;
            foundMax = false;
        }

        return count;
    }
}

