import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        int n = nums.length;
        long res = 0;
        Deque<Integer> dequeMin = new LinkedList<>();
        Deque<Integer> dequeMax = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            while (!dequeMin.isEmpty() && nums[i] <= nums[dequeMin.peekLast()]) {
                dequeMin.removeLast();
            }
            while (!dequeMax.isEmpty() && nums[i] >= nums[dequeMax.peekLast()]) {
                dequeMax.removeLast();
            }

            while (!dequeMin.isEmpty() && dequeMin.peekFirst() < i - minK) {
                dequeMin.removeFirst();
            }
            while (!dequeMax.isEmpty() && dequeMax.peekFirst() < i - maxK) {
                dequeMax.removeFirst();
            }

            if (nums[i] <= maxK && nums[i] >= minK) {
                res += ((long) Math.min(dequeMin.size(), dequeMax.size()) + 1);
            }
            dequeMin.addLast(i);
            dequeMax.addLast(i);
        }

        return res;
    }
}

