import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int MOD = 1000000007;

    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        while (n > 0) {
            int i = findLSB(n);
            powers.add(1 << i);
            n -= 1 << i;
        }

        long[] prefixProduct = new long[powers.size()];
        prefixProduct[0] = powers.get(0);
        for (int i = 1; i < powers.size(); i++) {
            prefixProduct[i] = (prefixProduct[i - 1] * powers.get(i)) % MOD;
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0], right = queries[i][1];
            long product = prefixProduct[right];
            if (left > 0) {
                product = (product * modInverse(prefixProduct[left - 1], MOD)) % MOD;
            }
            answers[i] = (int) product;
        }

        return answers;
    }

    private int findLSB(int n) {
        int i = 0;
        while ((n & (1 << i)) == 0) {
            i++;
        }
        return i;
    }

    private long modInverse(long a, long m) {
        long t = 0, newt = 1;
        long r = m, newr = a;
        while (newr != 0) {
            long quotient = r / newr;
            long temp = newt;
            newt = t - quotient * newt;
            t = temp;
            temp = newr;
            newr = r - quotient * newr;
            r = temp;
        }
        if (r > 1) {
            throw new RuntimeException("Modular inverse does not exist");
        }
        if (t < 0) {
            t += m;
        }
        return t;
    }
}

