import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        long MOD = 1000000007;
        while (n > 0) {
            int bit = (int) (Math.log(n) / Math.log(2));
            powers.add((int) Math.pow(2, bit));
            n -= (int) Math.pow(2, bit);
        }

        long[] prefixSum = new long[powers.size()];
        long product = 1;
        for (int i = 0; i < powers.size(); i++) {
            if (i == 0)
                prefixSum[i] = powers.get(i);
            else
                prefixSum[i] = (prefixSum[i - 1] * powers.get(i)) % MOD;
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long left = queries[i][0], right = queries[i][1];
            answers[i] = (int) ((prefixSum[(int)right] * getPrefixDiff(prefixSum, (int)left - 1)) % MOD);
        }

        return answers;
    }

    private long getPrefixDiff(long[] prefixSum, int index) {
        if (index < 0)
            return 0;
        return ((prefixSum[prefixSum.length - 1] * pow(2, index + 1)) - prefixSum[index]) % 1000000007;
    }

    private long pow(int base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1)
                result = (result * base) % 1000000007;
            base = (base * base) % 1000000007;
            exponent >>= 1;
        }
        return result;
    }
}

