import java.util.Arrays;

public class Solution {
    public int[] productQueries(int n, int[][] queries) {
        // convert n to binary form
        String binary = Integer.toBinaryString(n);

        List<Integer> powers = new ArrayList<>();
        for (int i = 0; i < binary.length(); i++) {
            if (binary.charAt(i) == '1') {
                powers.add(1 << (binary.length() - 1 - i));
            }
        }

        int mod = (int) Math.pow(10, 9) + 7;
        long[] prefixProduct = new long[powers.size()];
        prefixProduct[0] = powers.get(0);
        for (int i = 1; i < powers.size(); i++) {
            prefixProduct[i] = (prefixProduct[i - 1] * powers.get(i)) % mod;
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long left = queries[i][0];
            long right = queries[i][1];

            if (left == 0) {
                answers[i] = (int) prefixProduct[(int) right];
            } else {
                int index = Arrays.binarySearch(powers.stream().mapToInt(x -> x).boxed().toArray(), left);

                if (index < 0) index = -index - 2;
                long product = prefixProduct[index - 1];
                for (int j = index; j <= right; j++) {
                    product *= powers.get(j);
                    product %= mod;
                }
                answers[i] = (int) product;
            }
        }

        return answers;
    }
}

