    public int[] findArray(int[] pref) {
        int n = pref.length;
        int[] arr = new int[n];

        // Find arr[0] by XOR of all numbers from 1 to n (inclusive)
        arr[0] = 0;
        for (int i = 2; i <= n; ++i) {
            arr[0] ^= i;
        }

        // Now, pref[i] is the XOR of first 'i+1' elements in arr
        for (int i = 1; i < n; ++i) {
            // Calculate arr[i] by XORing arr[0] with pref[i]
