public class Solution {
    public boolean sumOfNumberAndReverse(int num) {
        int original = num;
        while (num > 0) {
            int digit = num % 10;
            if (original - digit < 0 || original - digit != reverse(digit)) {
                return false;
            }
            original -= digit;
            num /= 10;
        }
        return true;
    }

    private int reverse(int n) {
        int result = 0;
        while (n > 0) {
            result = result * 10 + n % 10;
            n /= 10;
        }
        return result;
    }
}

