import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<String> findAndReplaceStringArray(String[] queries, String[] dictionary) {
        Map<String, Integer> dictMap = new HashMap<>();
        for (int i = 0; i < dictionary.length; i++) {
            dictMap.put(dictionary[i], i);
        }

        List<String> result = new ArrayList<>();
        for (int i = 0; i < queries.length; i++) {
            String query = queries[i];
            int minEdits = Integer.MAX_VALUE;

            for (String word : dictMap.keySet()) {
                if (word.equals(query)) continue;

                int edits = getEditDistance(word, query);
                if (edits <= 2 && edits < minEdits) {
                    result.add(queries[i]);
                    minEdits = edits;
                }
            }
        }

        return result;
    }

    public int getEditDistance(String s1, String s2) {
        int m = s1.length();
        int n = s2.length();

        if (m > n) {
            String temp = s1;
            s1 = s2;
            s2 = temp;
            m = s1.length();
            n = s2.length();
        }

        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0) {
                    dp[i][j] = j;
                } else if (j == 0) {
                    dp[i][j] = i;
                } else if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;
                }
            }
        }

        return dp[m][n];
    }
}

