public class Solution {
    public boolean equalFrequency(String word) {
        // Store frequency of each character in a map
        Map<Character, Integer> freqMap = new HashMap<>();
        for (char c : word.toCharArray()) {
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
        }

        // If all characters have the same frequency, return true
        if (freqMap.values().stream().distinct().count() == 1) {
            return true;
        }

        // Calculate the target frequency for each character
        int[] targetFrequencies = new int[26];
        for (int i = 0; i < 26; i++) {
            targetFrequencies[i] = freqMap.get((char) ('a' + i));
        }
        for (int i = 0; i < 26; i++) {
            if (targetFrequencies[i] != 0) {
                targetFrequencies[i]--;
            } else {
                targetFrequencies[(i + 1) % 26]++;
            }
        }

        // Check if it's possible to remove one character so that the frequency of all characters is equal
        for (Map.Entry<Character, Integer> entry : freqMap.entrySet()) {
            int currentFrequency = entry.getValue();
            if (currentFrequency == targetFrequencies[entry.getKey() - 'a']) {
                return true;
            }
            if (currentFrequency != 0 && currentFrequency + 1 == targetFrequencies[entry.getKey() - 'a']) {
                return true;
            }
        }

        // If no such character is found, return false
        return false;
    }
}

