public class Solution {
    public int countPalindromes(String s) {
        long MOD = (long) 1e9 + 7;
        int n = s.length();

        // Create a frequency array to store the frequency of each digit in the string.
        int[] freq = new int[10];
        for(char c : s.toCharArray()) {
            freq[c - '0']++;
        }

        long ans = 1;

        // Calculate the number of palindromic subsequences for each possible length from 1 to n.
        for(int len = 1; len <= n / 2 + 1; len++) {
            if(n % 2 == 0 && len == (n >> 1)) continue;

            long ways = 1;
            boolean oddLen = false;
            if(len != 1) {
                // Calculate the number of palindromic subsequences that can be formed with length 'len' and an even number of occurrences of each digit.
                for(int i = 0; i <= 9; i++) {
                    int freq_i = (int)(freq[i] % MOD);
                    ways *= comb(freq_i, len / 2 * 2 + len % 2);
                    ways %= MOD;
                }

                // If the length is odd and there are at least two occurrences of a digit, 
                // then we can form a palindromic subsequence with an odd number of occurrences of that digit.
                if(len % 2 == 1) {
                    int minFreq = Integer.MAX_VALUE;
                    for(int i = 0; i <= 9; i++) {
                        minFreq = Math.min(minFreq, freq[i]);
                    }

                    // If there are at least two occurrences of a digit and it is the only occurrence of that digit in the string, 
                    // then we can form a palindromic subsequence with an odd number of occurrences of that digit.
                    if(minFreq >= 2) {
                        for(int i = 0; i <= 9; i++) {
                            int freq_i = (int)(freq[i] % MOD);
                            ways *= comb(freq_i, len / 2 * 2 + len % 2);
                            ways %= MOD;
                        }
                    } else {
                        oddLen = true;
                    }
                }
            } else {
                // Calculate the number of palindromic subsequences that can be formed with length 'len' and an even number of occurrences of each digit.
                for(int i = 0; i <= 9; i++) {
                    int freq_i = (int)(freq[i] % MOD);
                    ways *= comb(freq_i, len / 2 * 2 + len % 2);
                    ways %= MOD;
                }
            }

            // Add the number of palindromic subsequences with length 'len' to the total answer.
            ans += ways;
            ans %= MOD;
        }

        return (int)ans;
    }

    private long comb(int n, int k) {
        if(k > n - k) k = n - k;
        long result = 1;
        for(int i = 0; i < k; i++) {
            result = result * (n - i) / (i + 1);
        }
        return result % ((long)1e9 + 7);
    }
}

