import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int countPalindromes(String s) {
        long MOD = (long)(1e9 + 7);
        Set<String> set = new HashSet<>();
        int n = s.length();

        for(int i = 0; i < n; i++) {
            for(int j = i + 1; j <= n; j++) {
                String subString = s.substring(i, j);

                // Check if the substring is a palindrome
                StringBuilder sb = new StringBuilder(subString);
                if(sb.reverse().toString().equals(subString)) {
                    set.add(subString);

                    // Generate all possible palindromes by inserting characters into the middle of the palindrome
                    for(int k = 0; k <= j - i; k++) {
                        String temp = subString.substring(0, j - i - k) + s.charAt(i + j - 1 - k) 
                                        + subString.substring(j - i - k, j);

                        // Check if the newly generated palindrome is in the set
                        StringBuilder tempSb = new StringBuilder(temp);
                        if(tempSb.reverse().toString().equals(temp)) {
                            set.add(temp);
                        }
                    }
                }
            }
        }

        int count = 0;
        for(String str : set) {
            count += helper(str, s.length());
            count %= MOD;
        }

        return (int)(count % MOD);
    }

    private long helper(String str, int length) {
        if(length == 1 || str.equals("") || str.length() > length) {
            return 0;
        } else if(str.length() == length) {
            return 1;
        }

        StringBuilder sb = new StringBuilder(str);
        String tempStr = sb.reverse().toString();

        long count = helper(tempStr.substring(1), length - 1)
                + (str.charAt(0) == str.charAt(length - 1)) ? helper(str.substring(1, length - 1), length - 2) : 0;

        return count % ((int)(1e9 + 7));
    }
}

