        Set<Character> setZero = new HashSet<>();
        for (int i = 0; i < zero; ++i)
            setZero.add('0');
        Set<Character> setOne = new HashSet<>();
        for (int i = 0; i < one; ++i)
            setOne.add('1');

        dp[0] = 1;
        int curZero = 0, curOne = 0;
        for (int length = 1; length <= high; ++length) {
            if (setZero.contains(curZero))
                curZero = (curZero + 1) % zero;
            else
                curZero = (curZero - 1 + zero) % zero;

            if (setOne.contains(curOne))
                curOne = (curOne + 1) % one;
            else
