public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        int count = 0;

        for (int num : nums) {
            if (num == k) {
                count++;
            } else {
                int lcm = getLcm(num, k);
                if (lcm == k) {
                    count++;
                }

                if (!map.containsKey(lcm)) {
                    map.put(lcm, 1);
                } else {
                    map.put(lcm, map.get(lcm) + 1);
                }
            }
        }

        for (int num : nums) {
            int temp = k;
            while (temp > 0) {
                if (!map.containsKey(temp)) {
                    break;
                }

                count += map.get(temp);
                temp /= getGcd(num, temp);
            }
        }

        return count;
    }

    private int getLcm(int a, int b) {
        return Math.abs(a * b) / getGcd(a, b);
    }

    private int getGcd(int a, int b) {
        if (b == 0) {
            return a;
        }

        return getGcd(b, a % b);
    }
}

