public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        int n = nums.length;
        Set<Integer> numSet = new HashSet<>();
        Map<Integer, Integer> numCount = new HashMap<>();

        for (int i : nums) {
            numSet.add(i);
            if (!numCount.containsKey(i)) {
                numCount.put(i, 1);
            } else {
                numCount.put(i, numCount.get(i) + 1);
            }
        }

        long lcm = k;
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (numSet.contains(k)) {
                count++;
            }

            for (int j = i + 1; j < n; j++) {
                int newLcm = findLCM(nums[i], nums[j]);
                if (newLcm == lcm) {
                    count++;
                }
            }

            for (Map.Entry<Integer, Integer> entry : numCount.entrySet()) {
                int currNum = entry.getKey();
                int countCurrNum = entry.getValue();

                int newLcm = findLCM(lcm, currNum);
                if (newLcm == lcm) {
                    count++;
                }
            }

            for (int currNum : numSet) {
                int countCurrNum = numCount.get(currNum);

                while (countCurrNum > 0 && !numSet.contains(findLCM(lcm, currNum))) {
                    count++;
                    countCurrNum--;

                    if (!numSet.contains(currNum)) {
                        break;
                    }
                }
            }

            for (int j = i; j < n; j++) {
                int leftLcm = nums[j];
                int rightLcm = nums[i];

                while (!numSet.contains(leftLcm) || !numSet.contains(rightLcm)) {
                    if (numSet.contains(leftLcm) && numSet.contains(rightLcm)) {
                        break;
                    }

                    if (!numSet.contains(leftLcm)) {
                        leftLcm = findLCM(nums[j], nums[i]);
                    }

                    if (!numSet.contains(rightLcm)) {
                        rightLcm = findLCM(nums[i], nums[j]);
                    }
                }

                int newLcm = findLCM(leftLcm, rightLcm);
                if (newLcm == lcm) {
                    count++;
                }
            }
        }

        return count;
    }

    private int findLCM(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return b * a / gcd(a, b);
        }
    }

    private int gcd(int a, int b) {
        if (a < b) {
            int temp = a;
            a = b;
            b = temp;
        }

        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

