import java.util.Stack;
import java.util.PriorityQueue;

public class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        // Initialize a stack to store characters that are smaller than or equal to the last character in t.
        Stack<Character> stack = new Stack<>();

        // Initialize a priority queue to store characters that can be appended to t.
        PriorityQueue<Character> pq = new PriorityQueue<>();

        for (char c : chars) {
            pq.offer(c);
        }

        StringBuilder sb = new StringBuilder();
        int i = n - 1;

        while (!pq.isEmpty() || !stack.isEmpty()) {

            // If the stack is not empty and its top element is smaller than or equal to the last character in t,
            // append it to t.
            if (!stack.isEmpty() && stack.peek() <= pq.peek()) {
                sb.append(stack.pop());
            } else {
                // Otherwise, pop a character from the priority queue and append it to t.
                char c = pq.poll();
                sb.append(c);
            }

            // If the last character in s is smaller than or equal to the last character in t,
            // push it into the stack.
            if (i >= 0 && chars[i] <= sb.charAt(sb.length() - 1)) {
                stack.push(chars[i--]);
            }
        }

        return sb.toString();
    }
}

