        char[] chars = s.toCharArray();

        // Build min heap for t
        PriorityQueue<Character> minHeap = new PriorityQueue<>();

        // Initialize stack to store characters from s in order
        Stack<Character> stack = new Stack<>();

        // Iterate over string s and build stack and min heap
        for (int i = 0; i < n; i++) {
            minHeap.offer(chars[i]);
            stack.push(chars[i]);

            if (!minHeap.isEmpty() && chars[i] == minHeap.peek()) {
                while (!stack.isEmpty() && stack.peek() == minHeap.peek()) {
                    char c = stack.pop();
                    minHeap.poll();
                    s = s.replace(String.valueOf(c), "");
