            minHeap.offer(chars[i]);
            stack.push(chars[i]);

            // If current character is smaller than the last character in the min heap, pop from the min heap and push to the stack
            while (!minHeap.isEmpty() && chars[i] <= minHeap.peek()) {
                char c = minHeap.poll();
                stack.push(c);
            }
        }

        StringBuilder sb = new StringBuilder();

