        int j = 0;

        for (int i = 0; i < n; i++) {
            // If the first character of string s is smaller than or equal to the last character in the stack, append it to string t and remove from string s
            if (chars[i] == stack.peek()) {
                sb.append(stack.pop());
                chars[j++] = ' ';
            }
        }

        return sb.toString().substring(0, n - j);
    }
