public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null) return null;

        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prevMax = head, curr = head;

        while (curr != null) {
            if (prevMax.val < curr.val) {
                prevMax = curr;
                curr = curr.next;
            } else {
                removeNode(prevMax);
                prevMax = curr;
                curr = curr.next;
            }
        }

        return dummy.next;
    }

