import com_github_leetcode.ListNode;

public class Solution {
    public ListNode removeNodes(ListNode head) {
        // Initialize two stacks, one for storing nodes and another to keep track of min value seen so far
        Deque<Integer> stack = new LinkedList<>();
        Deque<Integer> minStack = new LinkedList<>();

        // Traverse the linked list from head to tail
        while (head != null) {
            // While the current node's value is less than or equal to the top element in minStack, pop elements from minStack until we find a node with greater value or the stack becomes empty
            while (!minStack.isEmpty() && head.val <= minStack.peekLast()) {
                minStack.pollLast();
            }

            // Push the current node's value onto both stacks
            stack.push(head.val);
            minStack.push(head.val);

            // Move to next node in linked list
            head = head.next;
        }

        // Initialize a dummy node and a pointer to it
        ListNode dummy = new ListNode(0);
        ListNode curr = dummy;

        // Traverse the sorted stack from bottom to top, creating nodes as we go
        while (!stack.isEmpty()) {
            int val = stack.pop();
            ListNode newNode = new ListNode(val);

            // Link the current node to its next node in the modified linked list
            curr.next = newNode;
            curr = curr.next;  // Move pointer to newly added node
        }

        // Return the second element of dummy's next, which is the head of the modified linked list
        return dummy.next;
    }
}

