public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        return dp(m, n, 0, 0, new int[m][n], new int[m][n]);
    }

    private int dp(int m, int n, int i, int j, int[][] memoIntro, int[][] memoExtro) {
        if (i >= m || j >= n) return 0;
        if (memoIntro[i][j] != 0 && memoExtro[i][j] != 0) return memoIntro[i][j];

        int max = Integer.MIN_VALUE;

        // Place introvert
        for (int k = i; k < m; k++) {
            for (int l = j; l < n; l++) {
                if (k == i && l == j) continue;
                int happinessIntro = 120 - 30 * countNeighbors(memoIntro, memoExtro, k, l);
                max = Math.max(max, happinessIntro + dp(m, n, k, l, memoIntro, memoExtro));
            }
        }

        // Place extrovert
        for (int k = i; k < m; k++) {
            for (int l = j; l < n; l++) {
                if (k == i && l == j) continue;
                int happinessExtro = 40 + 20 * countNeighbors(memoIntro, memoExtro, k, l);
                max = Math.max(max, happinessExtro + dp(m, n, k, l, memoIntro, memoExtro));
            }
        }

        if (i == m - 1 && j == n - 1) {
            memoIntro[i][j] = max;
            memoExtro[i][j] = max;
        } else {
            memoIntro[i][j] = Integer.MIN_VALUE;
            memoExtro[i][j] = Integer.MIN_VALUE;
        }

        return max;
    }

    private int countNeighbors(int[][] memoIntro, int[][] memoExtro, int i, int j) {
        int count = 0;

        if (i > 0 && memoIntro[i - 1][j] != 0) count++;
        if (j > 0 && memoIntro[i][j - 1] != 0) count++;
        if (i < memoIntro.length - 1 && memoIntro[i + 1][j] != 0) count++;
        if (j < memoIntro[0].length - 1 && memoIntro[i][j + 1] != 0) count++;

        if (i > 0 && memoExtro[i - 1][j] != 0) count++;
        if (j > 0 && memoExtro[i][j - 1] != 0) count++;
        if (i < memoExtro.length - 1 && memoExtro[i + 1][j] != 0) count++;
        if (j < memoExtro[0].length - 1 && memoExtro[i][j + 1] != 0) count++;

        return count;
    }
}

