public class Solution {
    private static final int NOT_PLACE = 1;
    private static final int INTROVERTS = 2;
    private static final int EXTROVERTS = 3;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        return dp(m, n, introvertsCount, extrovertsCount);
    }

    private int dp(int m, int n, int i, int e) {
        if (i == 0 && e == 0) {
            return 0;
        }
        int[][][] memo = new int[m + 1][n + 1][2];
        for (int j = 0; j <= m; j++) {
            for (int k = 0; k <= n; k++) {
                for (int p = 0; p < 2; p++) {
                    memo[j][k][p] = -1;
                }
            }
        }

        return helper(m, n, i, e, memo);
    }

    private int helper(int m, int n, int i, int e, int[][][] memo) {
        if (i == 0 && e == 0) {
            return 0;
        }
        if (memo[m][n][0] != -1) {
            return memo[m][n][0];
        }

        int max = Integer.MIN_VALUE;
        for (int j = 0; j <= m; j++) {
            for (int k = 0; k <= n; k++) {
                if (j == 0 || k == 0) {
                    continue;
                }
                for (int p1 = 0; p1 < 4; p1++) {
                    int x = j + (p1 & 1) - 1;
                    int y = k + ((p1 >> 1) & 1) - 1;

                    if (x >= 1 && x <= m && y >= 1 && y <= n) {
                        int happiness = 0;
                        if (i > 0) {
                            happiness += 120;
                            i--;
                            happiness -= 30 * (getNeighbors(x, y, m, n));
                        }
                        if (e > 0) {
                            happiness += 40;
                            e--;
                            happiness += 20 * (getNeighbors(x, y, m, n));
                        }

                        max = Math.max(max, happiness + helper(m, n, i, e, memo));
                    }
                }
            }
        }
        memo[m][n][0] = max;
        return max;
    }

    private int getNeighbors(int x, int y, int m, int n) {
        int count = 0;
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                int nx = x + i;
                int ny = y + j;

                if (nx >= 1 && nx <= m && ny >= 1 && ny <= n) {
                    count++;
                }
            }
        }
        return count;
    }
}

