import java.util.Arrays;
import java.util.Random;

public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        // Create a memoization table to store intermediate results
        int[][][] dp = new int[m + 1][n + 1][1 << (introvertsCount + extrovertsCount + 2)];

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }

        return dfs(m, n, introvertsCount, extrovertsCount, dp);
    }

    private int dfs(int m, int n, int introvertsCount, int extrovertsCount, int[][][] dp) {
        if (introvertsCount + extrovertsCount == 0) {
            return 0;
        }

        // Create a bitmask to represent the current state
        int bitmask = (introvertsCount << 1) | (extrovertsCount << 2);

        if (dp[m][n][bitmask] != -1) {
            return dp[m][n][bitmask];
        }

        // Try all possible placements of introverts and extroverts
        int maxHappiness = 0;
        for (int i = 0; i <= m * n && i < introvertsCount + extrovertsCount; i++) {
            Random random = new Random();
            int x, y;
            do {
                x = random.nextInt(m);
                y = random.nextInt(n);
            } while ((x == 0 || x == m - 1 || y == 0 || y == n - 1) && (introvertsCount > 0 || extrovertsCount > 0));

            int newBitmask;
            if (i < introvertsCount) {
                newBitmask = bitmask | (1 << i);
                maxHappiness = Math.max(maxHappiness, dfs(m, n, introvertsCount - 1, extrovertsCount, dp) + happiness(x, y, m, n, i));
            } else if (i < introvertsCount + extrovertsCount) {
                newBitmask = bitmask | (2 << (introvertsCount));
                maxHappiness = Math.max(maxHappiness, dfs(m, n, introvertsCount, extrovertsCount - 1, dp) + happiness(x, y, m, n, i));
            }
        }

        // Store the maximum happiness in the memoization table
        dp[m][n][bitmask] = maxHappiness;

        return maxHappiness;
    }

    private int happiness(int x, int y, int m, int n, int count) {
        if (count == 0) {
            return 0;
        }
        int happiness = 0;
        for (int i = Math.max(0, x - 1); i <= Math.min(m - 1, x + 1); i++) {
            for (int j = Math.max(0, y - 1); j <= Math.min(n - 1, y + 1); j++) {
                if ((i != x || j != y) && (count > 0)) {
                    happiness += count == 1 ? 120 : 40;
                    happiness -= count == 1 ? 30 : 20;
                }
            }
        }

        return happiness;
    }
}

