// #Hard #Dynamic_Programming #Bit_Manipulation #Bitmask #Memoization
// #2022_04_23_Time_95_ms_(75.00%)_Space_53.1_MB_(58.33%)
public class Solution {
    private static final int MAX = 200;
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        return (int)(dp(m, n, introvertsCount, extrovertsCount) * 100);
    }

    private double dp(int m, int n, int introverts, int extroverts){
        if((introverts + extroverts) == 0)
            return 0;

        long[][] memo = new long[2][MAX];

        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < MAX; j++)
                memo[i][j] = -1;
        }

        return (double)dp(1, m, n, introverts, extroverts, 0, memo);
    }

    private double dp(int row, int m, int n, int introverts, int extroverts, long state, long[][] memo){

        if((introverts + extroverts == 0))
            return 0;

        if(row > m)
            return 0;

        if(memo[(int)state][introverts + extroverts] != -1)
            return memo[(int)state][introverts + extroverts];

        double max = Double.NEGATIVE_INFINITY;
        for(int i=0; i<2; i++){
            for (int j = 0; j < MAX; j++) {
                if(i == 0 && j > introverts)
                    continue;
                if(i == 1 && j > extroverts)
                    continue;

                double temp = dp(row+1, m, n, introverts - i + j, extroverts - (2-i) + j, state|(i<<8)|j, memo);
                max = Math.max(max,temp);

            }
        }

        return memo[(int)state][introverts + extroverts] = max;
    }
}

