import java.util.Arrays;

public class Solution {
    private static final int MAX = 100005;
    private static final int INF = Integer.MAX_VALUE / 3;
    private int dp[][];
    private int[][] dir = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        if (m == 0 || n == 0)
            return 0;

        dp = new int[n + 2][MAX];
        Arrays.fill(dp[0], -1);
        Arrays.fill(dp[n + 1], -1);

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < MAX; ++j)
                dp[i][j] = INF;
        }

        int[][] next = new int[4][MAX];
        int[] used = new int[MAX];
        Arrays.fill(used, -1);

        return helper(m, n, introvertsCount, extrovertsCount, 0, 0, used, next);
    }

    private int helper(int m, int n, int introvertsCount, int extrovertsCount, int mask, int index, int[] used, int[][] next) {
        if (index == introvertsCount + extrovertsCount)
            return 0;

        if (dp[index][mask] != INF)
            return dp[index][mask];

        for (int i = 1; i <= n; ++i) {
            boolean ok = true;
            int cnt = 0;
            for (int j = index + 1; j < introvertsCount + extrovertsCount; ++j)
                if ((mask & next[j][i]) == next[j][i])
                    ok = false;

            if (!ok) continue;

            for (int j = index; j < introvertsCount + extrovertsCount; ++j) {
                boolean canPlaceIntrovertHere = true, canPlaceExtrovertHere = true;

                int neighborMask = 0;
                for (int k = 0; k < dir.length; ++k)
                    if (i + dir[k][1] > 0 && i + dir[k][1] <= n && used[i + dir[k][1]] == j) {
                        canPlaceIntrovertHere &= (used[i + dir[k][1]] & 1) != 1;
                        neighborMask |= next[j][i + dir[k][1]];
                    }

                if (canPlaceIntrovertHere)
                    cnt++;

                if ((mask & next[j][i]) == next[j][i] && used[i] != j) {

                    canPlaceExtrovertHere = true;
                    for (int k = 0; k < dir.length; ++k)
                        if (used[i + dir[k][1]] == j)
                            canPlaceExtrovertHere &= (used[i + dir[k][1]] & 1) != 2;

                    if (canPlaceExtrovertHere)
                        cnt++;
                }
            }

            int res = helper(m, n, introvertsCount, extrovertsCount, mask, index + cnt, used, next);

            for (int j = index; j < introvertsCount + extrovertsCount; ++j) {
                if ((mask & next[j][i]) == next[j][i])
                    res += helper(m, n, introvertsCount, extrovertsCount, mask ^ next[j][i], index + 1, used, next);

                int placeIntrovertHere = (used[i] != j) ? 2 : 0;
                if (j < introvertsCount)
                    placeIntrovertHere += 120 - 30 * cnt;

                int placeExtrovertHere = (used[i] != j) ? 3 : 0;
                if (j >= extrovertsCount)
                    placeExtrovertHere -= 40 + 20 * cnt;

                if ((mask & next[j][i]) == next[j][i])
                    res += Math.max(helper(m, n, introvertsCount, extrovertsCount, mask ^ next[j][i], index + 1, used, next), 
                            helper(m, n, introvertsCount, extrovertsCount, mask | next[j][i], index, used, next));
                else
                    res += Math.max(helper(m, n, introvertsCount, extrovertsCount, mask ^ next[j][i], index + 1, used, next), 
                            helper(m, n, introvertsCount, extrovertsCount, mask | next[j][i], index, used, next));

                if (used[i] == j) {
                    res += Math.max(placeIntrovertHere, placeExtrovertHere);
                    used[i] = -1;
                }
            }

            dp[index][mask] = Math.min(dp[index][mask], res);
        }

        return dp[index][mask];
    }
}

