        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                pq.offer(new int[]{boxes[i][0], i});
            }
        }

        int ans = 0;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int port = cur[0];
            int idx = cur[1];

            visited[idx] = true;

            if (port == boxes[idx][0]) {
