                        pq.offer(new int[]{boxes[i][0], i});
                        visited[i] = true;
                        count++;
                        weight += boxes[i][1];
                    }
                }

                ans++;

                // If the ship is already at the correct port, no trip is needed
                if (pq.isEmpty()) continue;

                cur = pq.poll();
                port = cur[0];

                // The ship makes a return trip to storage to take more boxes from the queue.
                for (int i = idx + 1; i < n && !visited[i]; i++) {
