                        pq.offer(new int[]{boxes[i][0], i});
                        visited[i] = true;
                        count++;
                        weight += boxes[i][1];
                    }
                }

                ans++;
            } else {
                // The ship makes a trip to the port the box needs to be delivered to and deliver it.
                for (int i = idx + 1; i < n && !visited[i]; i++) {
                    if (!visited[i] && count < maxBoxes && weight + boxes[i][1] <= maxWeight) {
                        pq.offer(new int[]{boxes[i][0], i});
                        visited[i] = true;
                        count++;
