                // The ship makes a return trip to storage to take more boxes from the queue.
                for (int i = idx + 1; i < n && !visited[i]; i++) {
                    if (!visited[i] && count < maxBoxes && weight + boxes[i][1] <= maxWeight) {
                        pq.offer(new int[]{boxes[i][0], i});
                        visited[i] = true;
                        count++;
                        weight += boxes[i][1];
