import java.util.*;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        if (n == 0) return 0;

        // Create a graph with weights and count of edges
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        int[] weight = new int[n];
        int[] inDegree = new int[n];

        for (int i = 0; i < n; i++) {
            if (boxes[i][1] > maxWeight || boxes[i][0] >= portsCount) continue;

            // Add edges to the graph
            for (int j = i + 1; j < n; j++) {
                if (boxes[j][0] == boxes[i][0]) {
                    graph.get(i).add(new int[]{j, boxes[j][1]});
                    inDegree[j]++;
                    weight[j] += boxes[j][1];
                }
            }

            // Add edge from storage to current box
            graph.get(0).add(new int[]{i, 0});
        }

        // Initialize variables for dijkstra's algorithm
        boolean[] visited = new boolean[n];
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);

        // Dijkstra's algorithm to find the minimum number of trips
        pq.offer(new int[]{0, 0});
        dist[0] = 0;

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int u = curr[0];
            long d = curr[1];

            if (visited[u]) continue;
            visited[u] = true;

            for (int[] neighbor : graph.get(u)) {
                int v = neighbor[0];
                int w = neighbor[1];

                // If the current box is at storage, increment the trip count
                if (u == 0) dist[v] = Math.min(dist[v], d + 1);

                // Update distance and push to priority queue
                else {
                    long newDist = d + 1;
                    if (newDist < dist[v]) {
                        dist[v] = newDist;
                        pq.offer(new int[]{v, newDist});
                    }
                }
            }
        }

        // Find the minimum number of trips
        long minTrips = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) continue;

            // If the current box is at storage, increment the trip count
            if (i == 0) minTrips = Math.min(minTrips, dist[i] + 1);

            // Update minimum number of trips
            else {
                long newMinTrips = dist[i];
                if (newMinTrips < minTrips) {
                    minTrips = newMinTrips;
                }
            }
        }

        return (int) Math.min(minTrips, Long.MAX_VALUE);
    }
}

