import java.util.*;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        // Create a list to store the weights of each port
        List<Integer>[] portWeights = new List[n];
        for (int i = 0; i < n; i++) {
            if (portWeights[boxes[i][0]] == null) {
                portWeights[boxes[i][0]] = new ArrayList<>();
            }
            portWeights[boxes[i][0]].add(boxes[i][1]);
        }

        // Initialize the count of trips
        int tripCount = 0;

        int currentPort = -1;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
        for (int i = 0; i < n; i++) {
            // Add the current box to the priority queue
            pq.offer(new int[] {boxes[i][0], boxes[i][1]});
            if (pq.size() > maxBoxes) {
                pq.poll();
            }
            while (!pq.isEmpty()) {
                int[] top = pq.peek();
                if (top[0] != currentPort && portWeights[currentPort] == null || portWeights[currentPort].size() == 0) {
                    tripCount++;
                    currentPort = top[0];
                    continue;
                }
                // Deliver the box at the top of the priority queue
                pq.poll();
                if (portWeights[top[0]] != null && !portWeights[top[0]].isEmpty()) {
                    portWeights[top[0]].remove(portWeights[top[0]].size() - 1);
                }
            }

        }

        return tripCount + 1;
    }
}

