public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        // Add a dummy port to simplify some edge cases in our algorithm.
        boolean[] portVisited = new boolean[portsCount + 1];

        // Calculate the total weight of each box and add it to the boxes array
        for (int i = 0; i < n; i++) {
            boxes[i][2] += boxes[i][1];
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        // Add all boxes to the priority queue
        for (int[] box : boxes) {
            pq.offer(new int[]{box[0], box[1], box[2]});
        }

        int trips = 0;
        boolean first = true;
        while (!pq.isEmpty()) {
            List<int[]> tripBoxes = new ArrayList<>();

            // Try to fill a trip with maxBoxes boxes
            while (!pq.isEmpty() && tripBoxes.size() < maxBoxes) {
                int[] box = pq.poll();

                // If the current port is not visited before, mark it as visited.
                if (first || !portVisited[box[0]]) {
                    portVisited[box[0]] = true;

                    // Add the current box to the trip
                    tripBoxes.add(box);

                    first = false;
                } else {
                    pq.offer(box);
                    break;  // If we've already visited this port, try a new port.
                }
            }

            if (tripBoxes.size() == 0) break;

            // Update trips and add the delivery and return trip to each box
            int totalWeight = 0;
            for (int[] box : tripBoxes) {
                totalWeight += box[2];
            }

            if (totalWeight > maxWeight) break;  // If this trip exceeds maxWeight, stop.

            trips++;
            for (int[] box : tripBoxes) {
                pq.offer(new int[]{box[0], 0, box[2] - box[1]});
            }
        }

        // Remove the dummy port
        for (int i = 0; i < portsCount; i++) {
            if (portVisited[i]) portVisited[i + 1] = true;
        }

        return trips;
    }
}

