import java.util.*;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        List<int[]> boxList = new ArrayList<>();
        for (int[] box : boxes) {
            boxList.add(box);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int result = 0;
        boolean[][] visited = new boolean[boxes.length][2];

        // step1: Insert all the ports into priority queue
        for (int i = 0; i < boxList.size(); i++) {
            pq.offer(new int[]{boxList.get(i)[0], i});
        }

        while (!pq.isEmpty()) {
            result++;
            // step2: Get the ship to the destination port, and deliver boxes in order
            int[] currentBox = pq.poll();
            if (currentBox[1] < boxList.size() - 1) pq.offer(new int[]{boxList.get(currentBox[1] + 1)[0], currentBox[1] + 1});

            while (!pq.isEmpty()) {
                int[] portInfo = pq.peek();
                if (portInfo[1] != currentBox[1]) break;

                boolean isVisited = visited[portInfo[1]][0];
                if (!isVisited) {
                    // step3: If we can carry more boxes or deliver the last box, return it to storage
                    int numBoxesCarry = maxBoxes - 1;
                    int totalWeight = maxWeight;

                    for (int i = portInfo[1]; i < currentBox[1]; i++) {
                        if (!visited[i][0]) {
                            if (numBoxesCarry == 0 || boxList.get(i)[1] > totalWeight) break;
                            numBoxesCarry--;
                            totalWeight -= boxList.get(i)[1];
                            visited[i][0] = true;
                        }
                    }

                    // step4: If we can carry more boxes, skip the current port
                    if (numBoxesCarry != 0) continue;
                }

                int[] shipBoxInfo = pq.poll();
                if (!visited[shipBoxInfo[1]][0]) {
                    visited[shipBoxInfo[1]][0] = true;
                    // step5: If we cannot deliver the current box, skip it and move to next port
                    while (pq.peek()[1] == shipBoxInfo[1]) pq.poll();
                }
            }

            // step6: Update the status of visited
            for (int i = 0; i < boxList.size(); i++) {
                if (!visited[i][0]) {
                    if (i != currentBox[1]) {
                        visited[i][1] = true;
                    } else {
                        visited[i][0] = true;
                    }
                }
            }
        }

        // step7: If we have not visited all ports, add one more trip
        for (boolean[] isVisited : visited) {
            if (!isVisited[0]) return result + 1;
        }

        return result;
    }
}

