        List<Boolean> answer = new ArrayList<>();

        for (int i = 0; i < l.length; i++) {
            int subArray[] = getSubArray(nums, l[i], r[i]);
            boolean isArithmetic = isArithmeticSequence(subArray);
            answer.add(isArithmetic);
        }

        return answer;
    }

    public int[] getSubArray(int[] nums, int left, int right) {
        int[] subArray = new int[right - left + 1];
        for (int i = 0; i <= right - left; i++) {
            subArray[i] = nums[left + i];
        }
        return subArray;
    }

    public boolean isArithmeticSequence(int[] arr) {
        if (arr.length < 2) {
            return true;
        }

        int diff = arr[1] - arr[0];
        for (int i = 2; i < arr.length; i++) {
            if (diff != arr[i] - arr[i-1]) {
                return false;
            }
        }
        return true;
    }
}

