import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minEquity(int[] nums, int k) {
        Arrays.sort(nums);
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }

        if (map.size() < k) return -1;

        long[] dp = new long[k];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;

        for (int num : nums) {
            Map<Integer, Integer> tempMap = new HashMap<>(map);
            int index = k - 1;
            while (index >= 0 && dp[index] == Long.MAX_VALUE / 2) index--;

            if (tempMap.get(num) > 0) {
                for (int i = index; i >= 0; i--) {
                    long minVal = Math.min(dp[i], tempMap.getOrDefault(num, 0));
                    int maxVal = Math.max(i + 1 == k ? num : dp[i + 1], tempMap.getOrDefault(num, 0));

                    if (minVal != Long.MAX_VALUE / 2 && maxVal - minVal > dp[i]) {
                        dp[i] = maxVal - minVal;
                        break;
                    }
                }
            }

            for (int i = index; i >= 0; i--) {
                tempMap.put(num, tempMap.getOrDefault(num, 0) - 1);
                if (tempMap.get(num) > 0) continue;

                long minVal = Math.min(dp[i], tempMap.getOrDefault(num + 1, 0));
                int maxVal = Math.max(i + 1 == k ? num : dp[i + 1], tempMap.getOrDefault(num + 1, 0));

                if (minVal != Long.MAX_VALUE / 2 && maxVal - minVal > dp[i]) {
                    dp[i] = maxVal - minVal;
                    break;
                }
            }
        }

        long result = Long.MAX_VALUE;
        for (long val : dp) {
            result = Math.min(result, val);
        }

        return result == Long.MAX_VALUE / 2 ? -1 : (int)result;
    }
}

