public class Solution {
    public int minEqual(int[] nums, int k) {
        Arrays.sort(nums);
        long sum = 0;
        for (int i : nums)
            sum += i;

        if (sum % k != 0) return -1;
        int n = nums.length;
        int target = (int)(sum / k);

        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = i - 1; j >= 0; j--) {
                if (nums[j] > nums[i - 1]) continue;

                int curr = dp[j];
                if (curr + nums[i - 1] < dp[i]) {
                    dp[i] = curr + nums[i - 1];

                    // Check if current subset size is equal to target
                    if (i - j == target) {
                        int minVal = Integer.MAX_VALUE, maxVal = Integer.MIN_VALUE;

                        for (int idx = j; idx < i; idx++) {
                            minVal = Math.min(minVal, nums[idx]);
                            maxVal = Math.max(maxVal, nums[idx]);
                        }

                        sum -= dp[i];
                        sum += maxVal - minVal;
                    }
                }
            }
        }

        return (int)sum;
    }
}

