        long targetSum = sum / k;

        boolean[] dp = new boolean[(int)sum + 1];
        dp[0] = true;

        for (int num : nums) {
            for (long i = (int)targetSum; i >= num; i--) {
                if (dp[(int)i - num]) {
                    dp[(int)i] = true;
