        long minDiff = Long.MAX_VALUE;
        for (int i = 0; i <= sum / k; i++) {
            if (dp[i] && dp[targetSum - i]) {
                int max = Arrays.stream(nums).boxed().mapToInt(Integer::intValue).max().getAsInt();
                int min = Arrays.stream(nums).boxed().mapToInt(Integer::intValue).min().getAsInt();

                long diff = max - min;
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        return minDiff == Long.MAX_VALUE ? -1 : (int)minDiff;
    }
