    private boolean helper(String a, String b) {
        int i = 0;
        while (i < Math.min(a.length(), b.length()) && a.charAt(i) == b.charAt(a.length() - 1 - i)) {
            i++;
        }

        if (i >= Math.min(a.length(), b.length())) return true;

        i = 1;
        while (a.length() > i && b.length() > i && a.charAt(a.length() - i) == b.charAt(b.length() - i)) {
