public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> countMap = new HashMap<>();

        // Count occurrences of each number in the array
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        Arrays.sort(quantity);
        int n = quantity.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        // Iterate over each customer
        for (int i = 0; i < n; i++) {
            // Iterate over each number in the array
            for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
                int num = entry.getKey();
                int count = entry.getValue();

                // If we have enough occurrences of this number to satisfy the current customer
                if (count >= quantity[i]) {
                    // Update dp[i + 1] to true if it was already true or if we can satisfy the current customer and the previous customers
                    dp[i + 1] = dp[i + 1] || dp[i];

                    // Decrement the count of this number by the amount needed for the current customer
                    count -= quantity[i];
                    countMap.put(num, count);
                }
            }
        }

        return dp[n];
    }
}

