public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> map = new HashMap<>();

        // count occurrences of each number in nums
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }

        Arrays.sort(quantity);

        int n = quantity.length;
        long[] dp = new long[n];

        for (int i = 0; i < n; ++i) {
            // if current customer's order is greater than the number of available numbers
            if (map.getOrDefault(quantity[i], -1) < quantity[i]) {
                return false;
            }

            // for each previous customer, calculate dp[i] as max(dp[j] + map.get(quantity[j]), 0)
            for (int j = i; j >= 0; --j) {
                if (quantity[j] == quantity[i]) {
                    long sum = Math.max(0, dp[j] + (long)map.getOrDefault(quantity[i], -1));
                    dp[i] = Math.max(dp[i], sum);

                    // subtract the numbers allocated to previous customers
                    map.put(quantity[i], map.getOrDefault(quantity[i], 0) - quantity[j]);
                }
            }
        }

        return dp[n-1] >= (long)map.values().stream().max(Integer::compareTo).orElse(0l);
    }
}

