import java.util.*;

public class Solution {
    public int createSortedArray(int[] instructions) {
        long ans = 0;
        int n = instructions.length;
        int[] bit = new int[n + 1];

        for (int i = 0; i < n; i++) {
            int left = query(bit, instructions[i]);
            int right = n - queryRange(bit, instructions[i], n);

            update(bit, instructions[i], 1);
            ans += Math.min(left, right);
            ans %= 1000000007;
        }

        return (int)ans;
    }

    private void update(int[] bit, int i, int val) {
        while (i < bit.length) {
            bit[i] += val;
            i = i | (i - 1);
        }
    }

    private int query(int[] bit, int i) {
        int ans = 0;
        while (i > 0) {
            ans += bit[i];
            i = i & (i - 1);
        }
        return ans;
    }

    private int queryRange(int[] bit, int l, int r) {
        return query(bit, r) - query(bit, l - 1);
    }
}

