public class Solution {
    private static final int MOD = 1000000007;

    public int createSortedArray(int[] instructions) {
        long totalCost = 0L;

        int[] lessCount = new int[instructions.length];
        int[] greaterCount = new int[instructions.length];

        for (int i = 0; i < instructions.length; i++) {
            int num = instructions[i];

            // add all smaller numbers count
            totalCost += getLessOrEqual(lessCount, 0, i - 1, num);

            // subtract all equal numbers count
            totalCost -= getEqual(lessCount, i);

            // add all greater numbers count
            totalCost += getGreaterOrEqual(greaterCount, i + 1, instructions.length - 1, num);

            // subtract all equal numbers count
            totalCost -= getEqual(greaterCount, i);

            updateLessOrEqual(lessCount, i, num);
            updateGreaterOrEqual(greaterCount, i + 1, instructions.length - 1, num);
        }

        return (int) (totalCost % MOD);
    }

    private int getLessOrEqual(int[] count, int l, int r, int target) {
        if (l > r)
            return 0;

        int left = l, right = r + 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (count[mid] < target)
                left = mid + 1;
            else
                right = mid - 1;
        }

        return left;
    }

    private int getGreaterOrEqual(int[] count, int l, int r, int target) {
        if (l > r)
            return 0;

        int left = l, right = r + 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (count[mid] >= target)
                right = mid - 1;
            else
                left = mid + 1;
        }

        return l + count.length - right;
    }

    private int getEqual(int[] count, int index) {
        return count[index];
    }

    private void updateLessOrEqual(int[] count, int i, int num) {
        int j = getLessOrEqual(count, 0, i, num);

        if (j < i)
            count[i]++;
    }

    private void updateGreaterOrEqual(int[] count, int l, int r, int target) {
        if (l > r || target <= count[r])
            return;

        int j = getGreaterOrEqual(count, l, r, target);

        if (j >= l)
            count[j]--;
    }
}

