public class Solution {
    public int maximumUniqueSubarray(int[] nums) {
        int n = nums.length;
        int left = 0, right = 0; // Define two pointers for sliding window
        boolean[] seenNums = new boolean[10001]; // Assume the max number in nums is less than 10K
        int currSum = 0;
        int maxSum = Integer.MIN_VALUE;

        while (right < n) {
            if (!seenNums[nums[right]]) { // If not seen before, add to sum and move right pointer
                currSum += nums[right];
                seenNums[nums[right]] = true; // Mark as seen
                right++; // Move the window to the right
            } else { // If seen before, subtract from sum and move left pointer
                maxSum = Math.max(maxSum, currSum);
                while (left < right && nums[left] == nums[right]) {
                    currSum -= nums[left]; // Subtract duplicate number from sum
                    seenNums[nums[left]] = false; // Mark as unseen
                    left++; // Move the window to the left
                }
            }
        }

        maxSum = Math.max(maxSum, currSum); // Handle case when right pointer reaches end of array

        return maxSum;
    }
}

