public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        if (k == n) return nums;

        int[] res = new int[k];
        int index = 0;

        for (int i = 0; i < n; i++) {
            while (index > 0 && nums[i] < res[index - 1] && k + index - 1 < n) {
                index--;
            }
            if (index < k) {
                res[index++] = nums[i];
            }
        }

        return Arrays.copyOf(res, index);
    }
}

