public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        if (k == n) return nums;

        int[] ans = new int[k];
        int lastIndex = n - 1;

        for (int i = 0; i < k; i++) {
            while (lastIndex >= 0 && nums[lastIndex] >= nums[i]) {
                lastIndex--;
            }
            if (i != 0) {
                while (lastIndex > i - 1 && ans[lastIndex - 1] <= nums[lastIndex]) {
                    lastIndex--;
                }
            }
            ans[lastIndex--] = nums[i];
        }

        return ans;
    }
