public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        if (k == n) return nums;

        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[i] < stack.peek() && stack.size() + n - i > k) {
                stack.pop();
            }
            if (stack.size() < k) {
                stack.push(nums[i]);
            }
        }

        int[] res = new int[k];
        for (int i = 0; i < k; i++) {
            res[i] = stack.pop();
        }

        return res;
    }
}

