                if (i > 0 && values.get(i - 1) >= node.val) return false;

                if (level % 2 != 0) {
                    values.add(-node.val);
                } else {
                    values.add(node.val);
                }

                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }

            level++;
        }

        return true;
    }
