        int n = arr.length;
        int removeCount = (int)(n * 0.05); // 5% of elements

        for (int i = 0; i < removeCount; i++) {
            arr[0] = arr[i];
        }
        for (int i = n - 1; i >= n - removeCount; i--) {
            arr[n - 1] = arr[i];
        }

        int sum = 0;
        for (int num : arr) {
            if (num != arr[0] && num != arr[n - 1]) {
                sum += num;
            }
        }

        return (double)sum / (n - removeCount * 2);
    }
}

