        Map<Integer, Integer> pieceMap = new HashMap<>();

        // Store each piece's length and value in a map for O(1) lookup
        for (int[] piece : pieces) {
            pieceMap.put(piece[0], piece.length);
        }

        // Check if we can form the array by concatenating all pieces
        int i = 0;
        while (i < arr.length) {
            boolean foundPiece = false;

            // Iterate over each piece to see if it matches the current part of arr
            for (int[] piece : pieces) {
                if (pieceMap.containsKey(arr[i]) && pieceMap.get(arr[i]) == arr.length - i) {
                    int j = 0;

                    // If a match is found, check if the rest of the array matches as well
                    while (j < piece.length) {
                        if (arr[i + j] != piece[j]) {
                            break;
                        }
                        j++;
                    }

                    if (j == piece.length) {
                        i += pieceMap.get(arr[i]);
                        foundPiece = true;
                        break;
                    }
                }
            }

            // If no matching piece is found, return false
            if (!foundPiece) {
                return false;
            }
        }

        // If we can form the array by concatenating all pieces, return true
        return true;
    }
}

