public class Solution {
    public int countSubstrings(String s, String t) {
        int m = s.length();
        int n = t.length();

        if (m * 2 > n) return 0;

        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 || j == 0) {
                    dp[i][j] = 0;
                } else if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        int res = 0;
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (dp[i][j] > 0) {
                    int temp = Math.max(i, j) - Math.min(i, j);
                    res += temp * (temp + 1) / 2;
                }
            }
        }

        return res;
    }
}

