// #2022_04_21_Time_1_ms_(100.00%)_Space_43.3_MB_(20.97%)
public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < col; i++) {
            sb.append("H");
        }
        while (row > col) {
            int movesToMake = row - col;
            int hMovesToMake = getCombinations(movesToMake + col, col);
            if (k <= hMovesToMake) {
                for (int j = 0; j < movesToMake; j++) {
                    sb.append("V");
                }
                while (!sb.toString().contains("H")) {
                    sb.insert(0, "H");
                }
                break;
            } else {
                k -= hMovesToMake;
                col++;
                for (int i = 0; i < col - col; i++) {
                    sb.append("H");
                }
            }
        }

        return sb.toString();
    }

    private int getCombinations(int n, int r) {
        if (r > n / 2) {
            r = n - r;
        }
        long result = 1;
        for (int i = n; i >= n - r + 1; i--) {
            result *= i;
        }
        for (int i = 1; i <= r; i++) {
            result /= i;
        }
        return (int)result;
    }
}

