    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        Map<Integer, Integer> map = new HashMap<>();
        Map<Integer, List<int[]>> graph = new HashMap<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = matrix[i][j];
                if (!map.containsKey(val)) {
                    map.put(val, map.size() + 1);
                }

                graph.computeIfAbsent(map.get(val), k -> new ArrayList<>()).add(new int[] {i, j});
            }
        }

        int[][] ans = new int[m][n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int val : map.keySet()) {
            pq.offer(new int[] {map.get(val), val});
        }

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();

            int rank = cur[0];
            int val = cur[1];

            List<int[]> list = graph.get(rank);

            for (int[] pair : list) {
                ans[pair[0]][pair[1]] = rank;

                if (matrix[pair[0]][pair[1]] == val) {
                    pq.offer(new int[] {rank + 1, val});
                }
            }
        }

        return ans;
    }
}

