                if (index / n == row && res[index / n][index % n] != -1) {
                    nextSet.add(index + 1);
                }
            }
            set = nextSet;
        }

        return cnt;
    }

    private int getColRank(int col, Map<Integer> map) {
        Set<Integer> set = new HashSet<>();
        for (int i : map.keySet()) {
            if ((i % n == col)) {
                set.add(i);
            }
        }

        int cnt = 0;
        while (!set.isEmpty()) {
            cnt++;
            Set<Integer> nextSet = new HashSet<>();
            for (int num : set) {
                int index = map.get(num);
                if (index % n == col && res[index / n][index % n] != -1) {
                    nextSet.add(index + 1);
                }
            }
            set = nextSet;
        }

        return cnt;
    }

    private static final int n = 1000;
}

