public class Solution {
    public int maxOperations(int[] nums, int k) {
        Arrays.sort(nums);
        Map<Integer, Integer> map = new HashMap<>();

        int left = 0, right = nums.length - 1;
        int operations = 0;

        while (left < right) {
            if (nums[left] + nums[right] == k) {
                int count = Math.min(map.getOrDefault(nums[left], 0), map.getOrDefault(nums[right], 0));
                operations += count;
                map.put(nums[left], map.getOrDefault(nums[left], 0) - count);
                left++;
                right--;
            } else if (nums[left] + nums[right] < k) {
                left++;
            } else {
                right--;
            }
        }

        return operations;
    }
}

