import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        boolean[] visited = new boolean[n + 1];
        List<List<Integer>> graph = new ArrayList<>();

        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the graph
        for (int i = threshold + 1; i <= n; i++) {
            int num = i;
            List<Integer> factors = new ArrayList<>();

            while (num > 1) {
                int factor = getFactor(num);
                factors.add(factor);
                num /= factor;
            }

            Integer prev = null;
            for (int factor : factors) {
                if (prev != null) {
                    graph.get(prev).add(factor);
                    graph.get(factor).add(prev);
                }
                prev = factor;
            }
        }

        List<Boolean> res = new ArrayList<>();

        for (int[] query : queries) {
            int a = query[0];
            int b = query[1];

            if (a == b) {
                res.add(true);
                continue;
            }

            // Use Union-Find to check connectivity
            boolean connected = unionFind(graph, visited, a, b);
            res.add(connected);
        }

        return res;
    }

    private int getFactor(int num) {
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0)
                return i;
        }
        return num;
    }

    private boolean unionFind(List<List<Integer>> graph, boolean[] visited, int a, int b) {
        // Find the root of each node
        int ra = find(graph, visited, a);
        int rb = find(graph, visited, b);

        if (ra == rb)
            return true;

        // Union the two nodes
        union(graph, visited, ra, rb);
        return false;
    }

    private void union(List<List<Integer>> graph, boolean[] visited, int u, int v) {
        for (int i : graph.get(v)) {
            if (!visited[i]) {
                visited[i] = true;
                union(graph, visited, i, u);
            }
        }
    }

    private int find(List<List<Integer>> graph, boolean[] visited, int node) {
        if (node == graph.get(node).get(0))
            return node;

        return graph.get(node).set(0, find(graph, visited, graph.get(node).remove(0)));
    }
}

