public class Solution {
    public int numWays(String[] words, String target) {
        Map<Character, Integer>[] map = new Map[26];
        for (int i = 0; i < 26; i++) {
            map[i] = new HashMap<>();
        }

        for (String word : words) {
            for (int j = 0; j < word.length(); j++) {
                char c = word.charAt(j);
                map[c - 'a'].put(j, map[c - 'a'].getOrDefault(j, 0) + 1);
            }
        }

        int n = target.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (!map[c - 'a'].containsKey(i)) continue;

            int count = map[c - 'a'].get(i);
            long ways = dp[i];
