import java.util.*;

public class Solution {
    public int numWays(String[] words, String target) {
        Map<Character, Integer>[] charMap = new HashMap[26];
        for (int i = 0; i < 26; i++) {
            charMap[i] = new HashMap<>();
        }

        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                char c = word.charAt(i);
                charMap[c - 'a'][i]++;
            }
        }

        long[][] dp = new long[target.length() + 1][target.length()];
        int mod = 1000000007;
        dp[0][0] = 1;

        for (int i = 1; i <= target.length(); i++) {
            char c = target.charAt(i - 1);
            if (!charMap[c - 'a'].isEmpty()) {
                long count = charMap[c - 'a'].getOrDefault(0, 0);
                for (int j = 0; j < i; j++) {
                    dp[i][j] += dp[i - 1][j] * count;
                    dp[i][(i - 1) % (j + 1)] += dp[i - 1][j] * count;
                    charMap[c - 'a'].put(0, charMap[c - 'a'].getOrDefault(0, 0) - 1);
                }
            }

            for (int j = 0; j < i; j++) {
                dp[i][j] %= mod;
                dp[i][(i - 1) % (j + 1)] %= mod;
            }
        }

        return (int) (dp[target.length()][target.length() - 1] + dp[target.length()][target.length()]);
    }
}

