public class Solution {
    public int numWays(String[] words, String target) {
        Map<Character, Integer>[] charCounts = new Map[26];

        for (int i = 0; i < 26; ++i) {
            charCounts[i] = new HashMap<>();
        }

        for (String word : words) {
            for (int i = 0; i < word.length(); ++i) {
                char c = word.charAt(i);
                charCounts[c - 'a'][i]++;
            }
        }

        long ways = 1;
        int n = target.length();
        long[] prevWays = new long[n + 1];

        for (int i = 0; i < n; ++i) {
            char c = target.charAt(i);

            if (charCounts[c - 'a'].getOrDefault(i, 0L) == 0L) return 0;

            ways = (ways * prevWays[i]) % 1000000007;
            long nextWays = (prevWays[i] * charCounts[c - 'a'].get(i)) % 1000000007;
            charCounts[c - 'a'].put(i, charCounts[c - 'a'].get(i) - 1);

            for (int j = i + 1; j <= n; ++j) {
                ways = (ways * charCounts[target.charAt(j) - 'a'].getOrDefault(j, 0L)) % 1000000007;
                nextWays = (nextWays + prevWays[j] * charCounts[target.charAt(j) - 'a'].getOrDefault(j, 0L)) % 1000000007;
                charCounts[target.charAt(j) - 'a'].put(j, charCounts[target.charAt(j) - 'a'].getOrDefault(j, 0L) - 1);
            }

            prevWays[i + 1] = nextWays;
        }

        return (int) ways;
    }
}

