public class Solution {
    public int numWays(String[] words, String target) {
        final int MOD = (int) 1e9 + 7;
        Map<Character, Integer>[] charIdxMap = new Map[26];
        for (int i = 0; i < 26; ++i) {
            charIdxMap[i] = new HashMap<>();
        }

        for (String word : words) {
            for (int j = 0; j < word.length(); ++j) {
                char c = word.charAt(j);
                charIdxMap[c - 'a'].put(j, charIdxMap[c - 'a'].getOrDefault(j, 0) + 1);
            }
        }

        int n = target.length();
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            if (target.charAt(i) == target.charAt(0)) {
                dp[i][i] = charIdxMap[target.charAt(0) - 'a'].getOrDefault(0, 0);
            }
        }

        for (int length = 2; length <= n; ++length) {
            for (int i = 0; i + length - 1 < n; ++i) {
                int j = i + length - 1;
                char c = target.charAt(i);
                if (c == target.charAt(j)) {
                    dp[i][j] += dp[i + 1][j];
                    for (int k = 0; k <= i && k < charIdxMap[c - 'a'].getOrDefault(0, 0); ++k) {
                        int idx = i - k;
                        if (idx >= 0) {
                            dp[i][j] += dp[idx + 1][j];
                        }
                    }
                } else {
                    c = target.charAt(j);
                    for (int k = 0; k <= j && k < charIdxMap[c - 'a'].getOrDefault(0, 0); ++k) {
                        int idx = i;
                        if (idx >= 0) {
                            dp[i][j] += dp[idx][j + 1];
                        }
                    }
                }
                dp[i][j] %= MOD;
            }
        }

        return (int) dp[0][n - 1];
    }
}

