        dp[0] = 1;

        for (int i = 1; i <= target.length(); ++i) {
            char c = target.charAt(i - 1);
            int currCharIndex = c - 'a';

            // For each character in the current position, find number of ways
            long numWaysForCurrChar = 0;
            for (int wordIndex = 0; wordIndex < words.length && i - 1 < words[wordIndex].length(); ++wordIndex) {
                if (words[wordIndex].charAt(i - 1) == c) {
                    numWaysForCurrChar += charFreq[currCharIndex][wordIndex];
                    // If we have used character at this index, do not use from other strings
                    charFreq[currCharIndex][wordIndex] = 0;
                }
            }

            dp[i] = (numWaysForCurrChar * dp[i - 1]) % MOD;
        }

        return (int) dp[target.length()];
    }
}

