public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] res = new int[n - 1];
        boolean[][] visited = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            Arrays.fill(visited[i], false);
        }

        for (int i = 0; i < n; i++) {
            dfs(graph, visited, res, i, 1);
        }

        return res;
    }

    private void dfs(List<Integer>[] graph, boolean[][] visited, int[] res, int node, int dist) {
        if (!visited[node][node]) {
            visited[node][node] = true;

            for (int neighbor : graph[node]) {
                if (!visited[neighbor][node]) {
                    dfs(graph, visited, res, neighbor, dist + 1);
                }
            }

            int maxDist = 0;
            for (int i = 0; i < graph.length; i++) {
                if (i != node && visited[node][i] && visited[i][node]) {
                    maxDist = Math.max(maxDist, dist(graph, node, i));
                }
            }

            res[maxDist - 1]++;
        }
    }

    private int dist(List<Integer>[] graph, int u, int v) {
        boolean[] visited = new boolean[graph.length];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{u, 0});
        visited[u] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            if (curr[0] == v) return curr[1];

            for (int neighbor : graph[curr[0]]) {
                if (!visited[neighbor]) {
                    queue.offer(new int[]{neighbor, curr[1] + 1});
                    visited[neighbor] = true;
                }
            }
        }

        return -1; // unreachable
    }
}

