            if (child != parent) {
                dfs(child, node, graph, dp);
                max = Math.max(max, dp.getOrDefault(child, 0));
            }
        }

        int diameter = max + 1;
        if (!dp.containsKey(diameter)) {
            dp.put(diameter, 1);
        } else {
            dp.put(diameter, dp.get(diameter) + 1);
        }
    }
