public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; ++i)
            graph.add(new ArrayList<>());

        for (int[] edge : edges)
            graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);

        int[][] dp = new int[n][n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j)
                dp[i][j] = -1;
        }

        int[] result = new int[n-1];

        for (int startNode = 0; startNode < n; ++startNode) {
            if (dp[startNode][startNode] == -1) 
                dfs(graph, dp, startNode);
        }

        for (int i = 0; i < n; ++i)
            for (int j = 0; j <= 30; ++j)
                if ((dp[i][i] & (1 << j)) > 0)
                    result[j-1]++;

        return result;
    }

    private void dfs(List<List<Integer>> graph, int[][] dp, int node) {
        for (int child : graph.get(node))
            if (child != -1 && dp[node][child] == -1) 
                dfs(graph, dp, child);
        dp[node][node] = 0;

        for (int i = 0; i < graph.size(); ++i)
            dp[node][i] |= dp[i][node];

        for (int child : graph.get(node)) {
            if (child != -1) {
                int maxDist = getMaximumDistance(graph, dp, node, child);

                if (maxDist > dp[node][node])
                    dp[node][node] = maxDist;
            }

            if (graph.get(node).contains(child))
                graph.set(node, new ArrayList<>());
        }

    }

    private int getMaximumDistance(List<List<Integer>> graph, int[][] dp, int node1, int node2) {
        for(int i = 0; i < 30; ++i)
            if ((dp[node1][node2] & (1 << i)) > 0)
                return i+1;

        return 0;
    }
}

