import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minDeletions(String s) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each character
        for (char c : s.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        // Initialize a variable to store the minimum deletions required
        int minDeletionsRequired = 0;

        // Iterate over the frequency map and find characters that have same frequency
        for (int freq : frequencyMap.values()) {
            boolean duplicateFrequencyFound = false;

            // If there is already a character with this frequency, increment the deletions count
            if (frequencyMap.containsValue(freq + 1) || frequencyMap.containsValue(freq)) {
                duplicateFrequencyFound = true;
            } else {
                int i = freq - 1;

                while (i > 0 && !duplicateFrequencyFound) {
                    // Check each character with lower frequency to see if we can find a duplicate
                    if (frequencyMap.containsValue(i)) {
                        // If we found a duplicate, increment the deletions count
                        minDeletionsRequired += i - freq;
                        duplicateFrequencyFound = true;
                    } else {
                        i--;
                    }
                }
            }

            // If we still haven't found any duplicates, then this frequency is unique and no deletions are needed for it
            if (!duplicateFrequencyFound) {
                continue;
            }

            // Now we know that there are duplicates with this frequency. We need to decrement the frequency until we find a duplicate or we reach 1.
            while (freq > 0 && !duplicateFrequencyFound) {
                if (frequencyMap.containsValue(freq - 1)) {
                    minDeletionsRequired += freq - 1;
                    duplicateFrequencyFound = true;
                } else {
                    freq--;
                }
            }

            // If we still haven't found any duplicates, then this frequency is unique and no deletions are needed for it
            if (!duplicateFrequencyFound) {
                continue;
            }
        }

        return minDeletionsRequired;
    }
}

