public class Solution {
    public int maxResult(int[] nums, int k) {
        Deque<Integer> deque = new ArrayDeque<>();
        int n = nums.length;
        int[] dp = new int[n];

        for (int i = 0; i < n; i++) {
            if (i - k >= 0) {
                while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[i]) {
                    deque.pollLast();
                }
            }

            if (!deque.isEmpty()) {
                dp[i] += nums[deque.peekFirst()];
            } else {
                dp[i] = 0;
            }

            deque.offerLast(i);
        }

        return dp[n - 1];
    }
