            deque.offerLast(i);

            if (i == nums.length - 1 || i >= k) {
                int res = 0;
                while (!deque.isEmpty()) {
                    res += nums[deque.pollFirst()];
                }
                return res;
            }
        }

        return 0; // unreachable
    }
}

