public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Find the node before 'a' and after 'b'
        ListNode prevA = getPrev(list1, a);
        ListNode nextB = getNext(list1, b);

        // Connect list2 to between 'prevA' and 'nextB'
        if (list1 == null || list2 == null) {
            return list1;
        }
        prevA.next = list2;
        while (list2.next != null && list2.next != nextB) {
            ListNode temp = list2.next;
            list2.next = temp.next;
            temp.next = null;
