        }
        // Connect 'nextB' to the end of list2
        list2.next = nextB;

        return list1;
    }

    private ListNode getPrev(ListNode head, int pos) {
        ListNode prev = null;
        ListNode current = head;
        while (current != null && current.val != pos) {
            prev = current;
            current = current.next;
        }
        if (current == null) {
            return null;  // Return null if the position is out of bounds
        }
        return prev;
    }

    private ListNode getNext(ListNode head, int pos) {
        ListNode next = null;
        ListNode current = head;
        while (current != null && current.val != pos) {
            next = current;
            current = current.next;
        }
        if (current == null) {
            return null;  // Return null if the position is out of bounds
        }
        return current;
    }
