import com_github_leetcode.ListNode;

public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Find the node before the start of the range in list1
        ListNode prevStart = findPredecessor(list1, a);

        // If we have reached the end of the list, return null
        if (prevStart == null)
            return null;

        // Find the node after the end of the range in list1
        ListNode nextEnd = findSuccessor(prevStart, b);

        // Link list2 to the start and end of the range in list1
        prevStart.next = list2;
        while (list2.next != null)
            list2 = list2.next;
        list2.next = nextEnd;

        return list1;
    }

    private ListNode findPredecessor(ListNode node, int step) {
        // Move to the start of the range
        for (int i = 0; i < step - 1; ++i)
            if (node == null)
                return null;
            else
                node = node.next;

        return node;
    }

    private ListNode findSuccessor(ListNode node, int step) {
        // Move to the end of the range in list1
        for (int i = 0; i < step - 1; ++i)
            if (node == null)
                return null;
            else
                node = node.next;

        ListNode successor = node.next;
        while (successor.next != null)
            successor = successor.next;

        return successor;
    }
}

