public class Solution {
    public String getSmallestString(String s, int a, int b) {
        char[] chars = s.toCharArray();
        Set<String> set = new HashSet<>();

        // Generate all possible strings by adding 'a' to odd indices
        for (int i = 0; i < chars.length; i++) {
            if ((i & 1) == 1) { // Check if index is odd
                int temp = Integer.parseInt(String.valueOf(chars[i])) + a;
                chars[i] = (char)(temp % 10 + '0');
            }
        }

        // Generate all possible strings by rotating to the right by b positions
        for (int i = 0; i < Math.min(b, chars.length); i++) {
            String temp = new StringBuilder(String.valueOf(chars)).reverse().toString();
            System.arraycopy(temp.toCharArray(), temp.length() - b + i, chars, i, b);
            System.arraycopy(temp.toCharArray(), 0, chars, temp.length() - b + i, temp.length() - (b + i));
        }

        // Add all generated strings to the set
        for (int i = 0; i < Math.pow(2, s.length()); i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < chars.length; j++) {
                if ((i & (1 << j)) != 0) { // Check if bit is set
                    sb.append(chars[j]);
                }
            }
            set.add(sb.toString());
        }

        // Find the lexicographically smallest string in the set
        String result = "";
        for (String str : set) {
            if (str.compareTo(result) < 0) {
                result = str;
            }
        }

        return result;
    }
}

