public class Solution {

    public String getSmallestString(String s, int a, int b) {
        Queue<String> queue = new LinkedList<>();
        Set<String> set = new HashSet<>();

        // Add initial string to queue and set
        queue.offer(s);
        set.add(s);

        while (!queue.isEmpty()) {
            String str = queue.poll();
            if (str.length() == 0) continue;

            // Get the smallest string by adding a to odd indices of s
            String tmpStr = addA(str, a);
            if (!set.contains(tmpStr)) {
                set.add(tmpStr);
                queue.offer(tmpStr);
            }

            // Rotate string to the right by b positions
            String rotatedStr = rotateString(str, b);
            if (!set.contains(rotatedStr)) {
                set.add(rotatedStr);
                queue.offer(rotatedStr);
            }
        }

        // Get the smallest string from set and return it
        String minStr = Collections.min(set);
        int index = 0;
        while (index < minStr.length() - 1 && minStr.charAt(index) == '9') {
            index++;
        }
        if (index != minStr.length() - 1 && minStr.charAt(minStr.length() - 1) > '9' + a % 10) {
            index = minStr.length();
        }

        return minStr.substring(0, index) + String.valueOf((int)(minStr.charAt(index) - '0' + a % 10)) +
               minStr.substring(index + 1);
    }

    private String addA(String str, int a) {
        char[] arr = str.toCharArray();
        for (int i = 1; i < arr.length; i += 2) {
            if (arr[i] == '9') arr[i] = '0';
            else arr[i] = (char)(arr[i] + 1);
        }
        return new String(arr).replace('9', '0');
    }

    private String rotateString(String str, int b) {
        StringBuilder sb = new StringBuilder(str);
        for (int i = 0; i < b % str.length(); i++) {
            char temp = sb.charAt(sb.length() - 1);
            sb.setLength(sb.length() - 1);
            sb.append(temp);
        }
        return sb.toString();
    }
}

