public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        if (points == null || points.isEmpty()) return 0;

        int n = points.size();
        double[] angles = new double[n];
        int maxCount = 0;
        int sameLocationCount = 0;

        for (int i = 0; i < n; i++) {
            List<Integer> point = points.get(i);
            if (point.get(0).equals(location.get(0)) && point.get(1).equals(location.get(1))) {
                angles[i] = Double.POSITIVE_INFINITY;
                sameLocationCount++;
            } else {
                double angleInDegrees = Math.toDegrees(Math.atan2(point.get(1) - location.get(1), point.get(0) - location.get(0)));
                if (angleInDegrees < 0) angleInDegrees += 360;
                angles[i] = angleInDegrees;
            }
        }

        Collections.sort(angles);

        for (int i = 0; i < n; i++) {
            int count = 1;
            double startAngle = angles[i];
            if (i > 0) startAngle = Math.max(startAngle, angles[i - 1] + angle);
            for (int j = i + 1; j < n; j++) {
                if (angles[j] <= startAngle + angle && angles[j] >= startAngle) count++;
            }
            maxCount = Math.max(maxCount, count);
        }

        return maxCount + sameLocationCount;
    }
}

