        double[] angles = new double[n];

        for (int i = 0; i < n; i++) {
            int x1 = location.get(0);
            int y1 = location.get(1);
            int x2 = points.get(i).get(0);
            int y2 = points.get(i).get(1);

            angles[i] = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
        }

        Collections.sort(angles);

        int maxPoints = 0;
        for (int i = 0; i < n; i++) {
            double angleStart = angles[i];
            int j = binarySearch(angles, angleStart + angle);

            maxPoints = Math.max(maxPoints, j - i + 1);
        }

        return maxPoints;
    }

    private int binarySearch(double[] array, double target) {
        int left = 0;
        int right = array.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (array[mid] == target) return mid;
            else if (array[mid] < target) left = mid + 1;
            else right = mid - 1;
        }

        return left;
    }
}

