public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        if (points == null || points.isEmpty()) return 0;

        // get all x and y coordinates
        ArrayList<Integer> xs = new ArrayList<>();
        ArrayList<Integer> ys = new ArrayList<>();
        for (List<Integer> point : points) {
            xs.add(point.get(0));
            ys.add(point.get(1));
        }

        int n = points.size();
        if (location.get(0).equals(xs.get(0)) && location.get(1).equals(ys.get(0))) n--; // exclude the point at the location

        ArrayList<Integer> angles = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x2 = xs.get(i) - location.get(0);
            int y2 = ys.get(i) - location.get(1);
            int angleTemp = getAngle(x2, y2);
            angles.add(angleTemp);
        }

        Collections.sort(angles);

        int maxPoints = 0;
        for (int i = 0; i < n; i++) {
            int j = binarySearch(angles, i, n - 1, angle + angles.get(i));
            maxPoints = Math.max(maxPoints, j - i + 1);
        }

        return maxPoints;
    }

    private int getAngle(int x2, int y2) {
        if (x2 == 0) {
            return y2 < 0 ? 270 : 90;
        } else if (y2 == 0) {
            return x2 > 0 ? 0 : 180;
        }

        double angle = Math.atan2(y2, x2);
        angle *= 180 / Math.PI;
        if (angle < 0) angle += 360;
        return (int) angle;
    }

    private int binarySearch(ArrayList<Integer> list, int low, int high, int targetAngle) {
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (list.get(mid) >= targetAngle) high = mid - 1;
            else low = mid + 1;
        }

        return list.size() - low;
    }
}

