public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int n = points.size();
        int[] dist = new int[n];
        int maxCount = 0;

        for (int i = 0; i < n; ++i) {
            if (location.get(0) == points.get(i).get(0) && location.get(1) == points.get(i).get(1)) {
                dist[i] = 360;
            } else {
                int dx = points.get(i).get(0) - location.get(0);
                int dy = points.get(i).get(1) - location.get(1);

                if (dx < 0)
                    dx += 180;
                else
                    dist[i] = (int)(Math.toDegrees(Math.atan2(dx, dy)) % 180);
            }
        }

        for (int i = 0; i < n; ++i) {
            int j = n - 1;

            while (j > i) {
                if (dist[j] == dist[i]) {
                    dist[j--] = Integer.MAX_VALUE;
                } else
                    break;
            }

            for (int k = 0; k < n; ++k) {
                if (i != k && dist[k] <= dist[i] + angle)
                    maxCount++;
                if (dist[k] == Integer.MAX_VALUE)
                    break;
            }

            maxCount = Math.max(maxCount, i + 1);
        }

        return maxCount;
    }

