public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        k %= n; // Handle cases where n divides k
        int[] result = new int[n];

        if (k == 0) {
            for (int i = 0; i < n; i++) {
                result[i] = 0;
            }
            return result;
        }

        int prefixSum = 0;
        for (int i = 0; i < Math.abs(k); i++) {
            prefixSum += code[i];
        }

        if (k > 0) {
            for (int i = 0; i < n; i++) {
                result[i] = prefixSum;
                prefixSum -= code[(i + k) % n] - code[i];
            }
        } else {
            for (int i = n - 1; i >= 0; i--) {
                result[i] = prefixSum;
                prefixSum -= code[(n + i - k) % n] - code[i];
            }
        }

        return result;
    }
}

