public class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        Map<String, Integer> map = new HashMap<>();

        // For each tower, calculate its maximum signal quality at any coordinate within the given radius.
        for (int[] tower : towers) {
            int x = tower[0];
            int y = tower[1];
            int q = tower[2];

            // Calculate the range of coordinates that this tower can reach.
            int minX = x - radius;
            int maxX = x + radius;
            int minY = y - radius;
            int maxY = y + radius;

            for (int i = minX; i <= maxX; i++) {
                for (int j = minY; j <= maxY; j++) {
                    // Calculate the distance between this coordinate and the tower.
                    double dist = Math.sqrt(Math.pow(i - x, 2) + Math.pow(j - y, 2));

                    // If the distance is within the given radius, calculate the signal quality at this coordinate.
                    if (dist <= radius) {
                        int sigQuality = q / (1 + (int) dist);
                        map.put(i + "," + j, Math.max(map.getOrDefault(i + "," + j, 0), sigQuality));
                    }
                }
            }
        }

        // Find the maximum network quality and its corresponding coordinate.
        String maxKey = null;
        int maxSigQual = -1;
        for (String key : map.keySet()) {
            int sigQual = map.get(key);
            if (sigQual > maxSigQual) {
                maxSigQual = sigQual;
                maxKey = key;
            } else if (sigQual == maxSigQual && (maxKey == null || key.compareTo(maxKey) < 0)) {
                maxKey = key;
            }
        }

        // Extract the x and y coordinates from the maximum key.
        String[] parts = maxKey.split(",");
        return new int[] { Integer.parseInt(parts[0]), Integer.parseInt(parts[1]) };
    }
