public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        // calculate longest increasing subsequence
        List<Integer> lis = new ArrayList<>();
        int n = nums.length;
        for (int i : nums) {
            if (lis.isEmpty() || i > lis.get(lis.size() - 1)) {
                lis.add(i);
            } else {
                int idx = Collections.binarySearch(lis, i);
                if (idx < 0) {
                    idx = ~idx;
                }
                lis.set(idx, i);
            }
        }

        // calculate longest decreasing subsequence
        List<Integer> lds = new ArrayList<>();
        for (int i : nums) {
            if (lds.isEmpty() || i > lds.get(lds.size() - 1)) {
                lds.add(i);
            } else {
                int idx = Collections.binarySearch(lds, i);
                if (idx < 0) {
                    idx = ~idx;
                }
                lds.set(idx, i);
            }
        }

        // find the minimum number of elements to remove
        int minRemovals = n;
        for (int i = 1; i < n - 1; i++) {
            if (lis.get(i) > lis.get(0) && lds.get(n - 1 - i) > lds.get(lds.size() - 1)) {
                int removals = i + (n - 1 - i);
                minRemovals = Math.min(minRemovals, removals);
            }
        }

        return minRemovals;
    }
}

