import java.util.PriorityQueue;

public class Solution {
    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;

        // Create a distance matrix and initialize it with infinity
        int[][] dist = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                dist[i][j] = Integer.MAX_VALUE;
            }
        }

        // Create a priority queue to store cells
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);

        // Add the starting cell (0, 0) with distance 0
        pq.offer(new int[]{0, 0, 0});
        dist[0][0] = 0;

        // Define the possible movements (up, down, left, right)
        int[][] moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            int[] cell = pq.poll();

            // If this is the destination cell, return the distance
            if (cell[0] == rows - 1 && cell[1] == cols - 1) {
                return cell[2];
            }

            // Explore all possible movements from the current cell
            for (int[] move : moves) {
                int newRow = cell[0] + move[0];
                int newCol = cell[1] + move[1];

                // Check if the new position is within bounds and not visited before
                if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && dist[newRow][newCol] == Integer.MAX_VALUE) {
                    int effort = Math.max(Math.abs(heights[cell[0]][cell[1]] - heights[newRow][newCol]), cell[2]);

                    // Update the distance and add the new cell to the priority queue
                    dist[newRow][newCol] = effort;
                    pq.offer(new int[]{newRow, newCol, effort});
                }
            }
        }

        // If there is no path to the destination, return -1
        return -1;
    }
}

