        // Create a distance matrix and initialize all distances to infinity except for the top-left cell which is 0
        int[][] dist = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == 0 && j == 0) {
                    dist[i][j] = 0;
                } else {
                    dist[i][j] = Integer.MAX_VALUE;
                }
            }
        }

        // Create a priority queue to store cells to be processed
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);

        // Add the top-left cell to the priority queue
        pq.offer(new int[]{0, 0, dist[0][0]});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();

            // If this is the bottom-right cell, return its distance
            if (curr[0] == rows - 1 && curr[1] == cols - 1) {
                return curr[2];
            }

            // Process all neighbors of the current cell
            for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                int x = curr[0] + dir[0];
                int y = curr[1] + dir[1];

                // Check if the neighbor is within bounds
                if (x >= 0 && x < rows && y >= 0 && y < cols) {
                    // Calculate the effort required to move from the current cell to the neighbor
                    int effort = Math.max(Math.abs(heights[x][y] - heights[curr[0]][curr[1]]), curr[2]);

                    // If this path is shorter than the previously known shortest path, update it
                    if (effort < dist[x][y]) {
                        dist[x][y] = effort;
                        pq.offer(new int[]{x, y, effort});
                    }
                }
            }
        }

        // If there's no path to the bottom-right cell, return -1
        return -1;
    }
