                if (isValidCoordinate(heights, newRow, newCol)) {
                    int newDistance = Math.max(currentNode.distance, calculateEffort(heights[currentNode.row][currentNode.col], heights[newRow][newCol]));

                    if (!distanceMap.containsKey(getNodeId(newRow, newCol)) || newDistance < distanceMap.get(getNodeId(newRow, newCol))) {
                        Node newNode = createNode(newRow, newCol, newDistance);
                        priorityQueue.add(newNode);

                        distanceMap.put(getNodeId(newRow, newCol), newDistance);
                    }
                }
            }
        }

        return -1;
    }

    private boolean isValidCoordinate(int[][] matrix, int row, int col) {
        if (row >= 0 && row < matrix.length && col >= 0 && col < matrix[0].length) {
            return true;
        }

        return false;
    }

    private String getNodeId(int row, int col) {
        return row + "," + col;
    }

    private Node createNode(int row, int col, int distance) {
        return new Node(row, col, distance);
    }

    private class Node {
        int row;
        int col;
        int distance;

        public Node(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    private int calculateEffort(int height1, int height2) {
        return Math.abs(height1 - height2);
    }
}

