import java.util.PriorityQueue;

public class Solution {
    int[][] directions = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    public int minimumEffortPath(int[][] heights) {
        boolean[][] visited = new boolean[heights.length][heights[0].length];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        pq.offer(new int[]{0, 0, Math.abs(heights[0][0])});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            if (curr[0] == heights.length - 1 && curr[1] == heights[0].length - 1) return curr[2];

            for (int[] dir : directions) {
                int nextI = curr[0] + dir[0];
                int nextJ = curr[1] + dir[1];

                if (nextI < 0 || nextI >= heights.length || nextJ < 0 || nextJ >= heights[0].length
                        || visited[nextI][nextJ]) continue;

                visited[nextI][nextJ] = true;
                int maxEffort = Math.max(Math.abs(heights[curr[0]][curr[1]] - heights[nextI][nextJ]), curr[2]);
                pq.offer(new int[]{nextI, nextJ, maxEffort});
            }
        }

        return 0; // This will never be reached
    }
}

