public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfSets(int n, int k) {
        long[][] dp = new long[n + 1][k + 1];

        for (int i = 2; i <= n; ++i) {
            dp[i][0] = 1;
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= Math.min(i, k); ++j) {
                long ways = 0;

                if (i - 2 >= 0) {
                    ways += dp[i - 2][j];
                }

                if (i - 1 >= 0) {
                    ways += dp[i - 1][j - 1];
                }

                dp[i][j] = ways % MOD;
            }
        }

        return (int) dp[n][k];
    }
}

