public class Solution {
    public int numberOfSets(int n, int k) {
        long mod = 1000000007;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= Math.min(i, k); j++) {
                dp[i] += dp[i - j] * C(j + j - 1, j - 1);
                dp[i] %= mod;
            }
        }
        return (int) ((dp[n] % mod + mod) % mod);
    }

    public long C(long n, long r) {
        if (n < r)
            return 0;
        long res = 1;
        for (long i = 2; i <= r; i++) {
            res *= i;
            res %= 1000000007;
        }
        for (long i = n - r + 1; i >= 2; i--) {
            res *= i;
            res %= 1000000007;
        }
        return res % 1000000007;
    }
}

