public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        long[] dp = new long[n];
        long[] preSum = new long[n + 1];

        // Preprocess prefix sum array
        for (int i = 0; i < n; i++) {
            preSum[i + 1] = preSum[i] + stones[i];
        }

        // Initialize dp array with initial values
        for (int i = 0; i < n; i++) {
            dp[i] = Math.min(preSum[n] - preSum[i + 1], stones[i]);
        }

        // Iterate over the stones and fill up the dp table
        for (int i = 1; i < n; i++) {
            int j = i;
            while (j < n) {
                long maxVal = Math.max(dp[j - 1] + preSum[n] - preSum[j], stones[j]);
                if (maxVal > dp[i - 1]) {
                    dp[i] = maxVal;
                }
                j += i & (-i);
            }
        }

        // The difference of the Alice's and Bob's score is dp[n-1]
        return (int) (dp[n - 1]);
    }
}

