public class Solution {
    private int[] prefix;
    private int n;

    public int stoneGameVII(int[] stones) {
        this.n = stones.length;
        prefix = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + stones[i];
        }
        return dfs(0, n - 1);
    }

    private int dfs(int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == r) {
            return Math.max(prefix[r + 1] - prefix[l], 0);
        }
        // Try to maximize the difference
        int maxDiff = Integer.MIN_VALUE;
        for (int i = l; i <= r; ++i) {
            // Calculate the score of player who takes stone at position i
            int leftScore = dfs(l, i - 1);
            int rightScore = prefix[r + 1] - prefix[i + 1] - dfs(i + 1, r);
            maxDiff = Math.max(maxDiff, Math.abs(leftScore - rightScore));
        }
        return maxDiff;
    }
}

