public class Solution {
    int[] dp;
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        dp = new int[n];

        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stones[i];
        }

        return helper(0, n - 1, prefixSum);
    }

    private int helper(int l, int r, long[] prefixSum) {
        if (l > r) return 0;

        if (dp[l] != 0) return dp[l];

        // Alice plays first
        int alice = prefixSum[r + 1] - prefixSum[l];
        int bob = Math.max(helper(l + 1, r, prefixSum), 
                          helper(l, r - 1, prefixSum));

        dp[l] = Math.max(alice - bob, alice);
        return dp[l];
    }
}

