    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        long[] dp = new long[n];
        dp[0] = stones[0];

        long[] prefSum = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            prefSum[i] = prefSum[i - 1] + stones[i - 1];
        }

        int ans = 0;
        for (int i = 1; i < n; i++) {
            dp[i] = Math.max(dp[i], prefSum[n] - prefSum[i] + stones[i]);
            if (i >= 2) {
                dp[i] = Math.max(dp[i], dp[i - 1] + stones[i]);
            }
            ans = Math.max(ans, dp[i] - (prefSum[n] - prefSum[i]));
        }

        return (int) ans;
    }
