                if (server.busyTime == -1) {
                    count[server.id]++;
                }
                servers[server.id] = new Server(server.id, -1);
            }

            int nextServerId = i % k;
            while (!servers[nextServerId].isAvailable()) {
                nextServerId = (nextServerId + 1) % k;
            }

            if (servers[nextServerId].busyTime == -1 || servers[nextServerId].busyTime > arrival[i]) {
                servers[nextServerId] = new Server(nextServerId, arrival[i]);
                pq.offer(servers[nextServerId]);
                count[nextServerId]++;
            } else {
                int end = arrival[i] + load[i];
                while (!pq.isEmpty() && pq.peek().busyTime <= end) {
                    Server server = pq.poll();
                    if (server.busyTime != -1) {
                        servers[server.id] = new Server(server.id, -1);
                        count[server.id]++;
                        pq.offer(new Server(server.id, end));
                    }
                }
            }
        }

        int maxCount = 0;
        for (int i = 0; i < k; i++) {
            if (count[i] > maxCount) {
                maxCount = count[i];
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (count[i] == maxCount) {
                result.add(i);
            }
        }
