                if (servers[(pair.id + i) % k].getBusyTime() > 0) {
                    available.add(pair.id);
                }
            }
            if (!available.isEmpty()) {
                int serverId = available.first();
                available.remove(serverId);
                servers[serverId].arrive(arrival[i]);
                count++;
            } else {
                break;
            }
        }
        PriorityQueue<Pair> pq1 = new PriorityQueue<>(Comparator.comparingInt(p -> -p.count));
        for (Server s : servers) {
            if (!pq1.isEmpty() && pq1.peek().count > s.getBusyTime()) {
                continue;
            }
            Pair pair = new Pair(s.getId(), s.getBusyTime());
            pq1.offer(pair);
        }
        List<Integer> result = new ArrayList<>();
        while (pq1.size() > 0) {
            if (pq1.peek().count == pq1.peekLast().count) {
                result.add(pq1.poll().id);
                pq1.pollLast();
            } else {
                break;
            }
        }
        return result;
    }

    private class Pair {
        int id, count;

        public Pair(int id, int count) {
            this.id = id;
            this.count = count;
        }
    }
