        Server[] servers = new Server[k];
        for (int i = 0; i < k; i++) {
            servers[i] = new Server(i, -1);
        }

        PriorityQueue<Server> pq = new PriorityQueue<>(Comparator.comparingInt(s -> s.busyTime));

        int[] requests = new int[n];
        for (int i = 0; i < n; i++) {
            if (servers[(i % k)].busyTime == -1) {
                servers[(i % k)].busyTime = arrival[i];
                pq.add(servers[(i % k)]);
            } else {
                requests[i]++;
                int index = ((i + load[i]) % k);
                while (!pq.isEmpty() && pq.peek().id != index) {
                    pq.poll();
                }
                if (pq.isEmpty()) continue;
                Server server = pq.poll();
                server.busyTime = arrival[i];
                pq.add(server);
            }
        }

        int maxRequests = 0;
        for (int i = 0; i < k; i++) {
            maxRequests = Math.max(maxRequests, requests[(i % n)]);
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (requests[i % n] == maxRequests) {
                result.add(i);
            }
        }
        return result;
    }

