public class Solution {

    public int[] busiestServers(int k, int[] arrival, int[] load) {
        TreeSet<Server> availableServers = new TreeSet<>((a, b) -> a.availableTime - b.availableTime);
        PriorityQueue<Server> busyServers = new PriorityQueue<>(Comparator.comparingInt(a -> a.busyTime));
        Server[] servers = new Server[k];
        for (int i = 0; i < k; i++) {
            availableServers.add(new Server(i, arrival[i]));
            servers[i] = new Server(i, arrival[i]);
        }
        int n = arrival.length;
        for (int time = 0; time < n; time++) {
            while (!availableServers.isEmpty() && availableServers.first().availableTime <= arrival[time]) {
                busyServers.offer(availableServers.pollFirst());
            }
            if (!busyServers.isEmpty()) {
                Server server = busyServers.poll();
                int newArrivalTime = Math.max(arrival[time], server.availableTime);
                PriorityQueue<Integer> queue = server.pq;
                while (!queue.isEmpty() && queue.peek() <= arrival[time]) {
                    queue.poll();
                }
                if (newArrivalTime < arrival[n - 1] || !server.pq.isEmpty()) {
                    availableServers.add(server);
                } else {
                    int numLoad = load[time];
                    for (int i = 0; i < Math.min(numLoad, server.pq.size()); i++) {
                        queue.poll();
                        totalTime++;
                    }
                    server.busyTime += numLoad;
                    server.load -= numLoad;
                    server.availableTime = newArrivalTime + numLoad;
                }
            }
        }
        int maxTotalTime = 0;
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            maxTotalTime = Math.max(maxTotalTime, servers[i].totalTime);
            if (servers[i].totalTime == maxTotalTime) {
                result.add(i);
            }
        }
        return result.stream().mapToInt(x -> x).toArray();
    }
}

