import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        // Sort the tasks based on the difference between actual and minimum effort in descending order.
        Arrays.sort(tasks, Comparator.comparingInt(t -> t[0] - t[1]));

        int energy = 0;
        for (int[] task : tasks) {
            // If the current energy is less than the minimum required to start a task,
            // update the energy to be the maximum of the current energy and the minimum required.
            if (energy < task[1]) {
                energy = Math.max(energy, task[1]);
            }
            // Subtract the actual effort from the updated energy to get the remaining energy after completing the task.
            energy -= task[0];
        }

        return energy;
    }
}

