        int n = stoneValue.length;
        int[] prefixSums = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + stoneValue[i];
        }

        int aliceScore = 0;
        PriorityQueue<Integer> queue = new PriorityQueue<>((a, b) -> b - a);
        for (int i = n - 1; i >= 0; i--) {
            if (i == n - 1) {
                aliceScore += prefixSums[n] - stoneValue[i];
                queue.offer(prefixSums[n] - stoneValue[i]);
            } else {
                int bestChoice = Math.max(stoneValue[i], prefixSums[i + 1] - stoneValue[i]);
                aliceScore += bestChoice;
                queue.offer(bestChoice);
            }
        }

        return (queue.size() == 0) ? 0 : (aliceScore > queue.peek()) ? 1 : -1;
    }
}

