    public Dsu(int n) {
        this.parent = new int[n];
        this.size = new int[n];

        Arrays.fill(parent, -1);
        Arrays.fill(size, 1);

        this.edgeList = new ArrayList<>();
    }

    public void addEdge(int u, int v, int dis) {
        edgeList.add(new int[]{u, v, dis});
    }

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        Arrays.sort(edgeList, (a, b) -> a[2] - b[2]);
        Arrays.sort(queries, (a, b) -> a[2] - b[2]);

        boolean[] answer = new boolean[queries.length];

        for (int i = 0; i < queries.length; i++) {
            int p = queries[i][0];
            int q = queries[i][1];
            int limit = queries[i][2];

            int edgeIndex = Arrays.binarySearch(edgeList, new int[]{p, q, Integer.MAX_VALUE}, Comparator.comparingInt(a -> a[2]));
            if (edgeIndex < 0) {
                edgeIndex = -edgeIndex - 1;
            }

            while (edgeIndex < edgeList.size() && edgeList.get(edgeIndex)[2] < limit) {
                int u = edgeList.get(edgeIndex)[0];
                int v = edgeList.get(edgeIndex)[1];

                if (!union(u, q)) {
                    break;
                }
                edgeIndex++;
            }

            answer[i] = find(p) == find(q);
        }

        return answer;
    }

    private int find(int num) {
        if (parent[num] < 0) {
            return num;
        }
        parent[num] = find(parent[num]);
        return parent[num];
    }

    private boolean union(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU == rootV) {
            return false;
        }

        if (size[rootU] < size[rootV]) {
            int temp = rootU;
            rootU = rootV;
            rootV = temp;
        }
        parent[rootV] = rootU;
        size[rootU] += size[rootV];
        return true;
    }
}

