                continue;
            }
            boolean flag = false;
            for (int[] query : map.get(curE[2])) {
                Integer[] pqr = fromHash(query);
                if (pqr != null) {
                    int px = pqr[0], py = pqr[1];
                    if (!flag && find(px) == find(py)) {
                        res.set(Arrays.hashCode(new int[]{px, py}), true);
                        flag = true;
                    }
                }
            }
            idxEdge++;
        }

        return res;
    }

    private Integer[] fromHash(int hash) {
        int[] arr = new int[hash];
        for (int i = 0; i < arr.length; i++) {
            if ((hash & (1 << i)) == 0) continue;
            arr[i] = i;
        }
        return Arrays.stream(arr).boxed().toArray(Integer[]::new);
