        int[] count = new int[n];
        return backtrack(requests, 0, count);
    }

    private int backtrack(int[][] requests, int index, int[] count) {
        if (index == requests.length) {
            for (int i : count) {
                if (i != 0) {
                    return 0;
                }
            }
            return requests.length;
        }

        int[] newCount = Arrays.copyOf(count, n);
        boolean[] visited = new boolean[requests.length];

        visited[index] = true;

        for (int j = index + 1; j < requests.length; j++) {
            if (!visited[j]) {
                newCount[requests[index][0]]--;
                newCount[requests[index][1]]++;
                int result = backtrack(requests, j, newCount);
                if (result != 0) {
                    return result;
                }
                newCount[requests[index][0]]++;
                newCount[requests[index][1]]--;
            }
        }

        return 0;
    }
