public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int[] count = new int[n];
        Arrays.fill(count, 0);

        return backtrack(requests, 0, count, 0);
    }

    private int backtrack(int[][] requests, int index, int[] count, int size) {
        if (index == size) {
            // Check all buildings have net change zero
            if (isNetChangeZero(count)) {
                return size;
            }
            return 0;
        }

        for (int i = 0; i < n; i++) {
            if (count[i] > 0) continue;

            count[i]++;
            int result = backtrack(requests, index + 1, count, size);
            if (result != 0) return result;
            count[i]--;
        }

        // Try to exclude this request
        for (int i = 0; i < n; i++) {
            if (count[i] > 0) continue;

            count[i]--;
            int result = backtrack(requests, index + 1, count, size);
            if (result != 0) return result;
            count[i]++;
        }

        return 0;
    }

    private boolean isNetChangeZero(int[] count) {
        for (int i : count) {
            if (i != 0) return false;
        }
        return true;
    }
}

