public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int count = 0;
        int[] netChanges = new int[n];

        for (int i = 0; i < n; ++i)
            netChanges[i] = 0;

        backtrack(requests, 0, 0, netChanges);

        return count;
    }

    private void backtrack(int[][] requests, int index, int count, int[] netChanges) {
        // Base case
        if (index == requests.length) {
            for (int i = 0; i < n; ++i)
                if (netChanges[i] != 0) return;

            count = Math.max(count, index);
            return;
        }

        int from = requests[index][0];
        int to = requests[index][1];

        netChanges[from]--;
        netChanges[to]++;

        backtrack(requests, index + 1, count, netChanges);

        // Backtrack
        netChanges[from]++;
        netChanges[to]--;

        backtrack(requests, index + 1, count, netChanges);
    }
}

