import java.util.LinkedList;
public class Solution {
    public int minimumOneBitOperations(int n) {
        LinkedList<Integer> dp = new LinkedList<>();
        dp.add(0);
        while (n > 0) {
            if ((n & 1) == 1) {
                n >>= 1;
                dp.add(dp.get(dp.size() - 1) ^ n);
            } else {
                n >>= 1;
            }
        }
        return dp.get(dp.size() - 1);
    }
}

