import java.util.LinkedList;

public class Solution {
    public int minimumOneBitOperations(int n) {
        return getMinOps(n, new LinkedList<>());
    }

    private int getMinOps(int num, LinkedList<Integer> memo) {
        if (num == 0) {
            return 0;
        }
        if (memo.contains(num)) {
            return memo.get(memo.indexOf(num));
        }

        int minOps = Integer.MAX_VALUE;
        for (int i = 31; i >= 0; i--) {
            if (((1 << i) & num) != 0) {
                int ops = getMinOps((num ^ (1 << i)), memo);
                if (ops < minOps) {
                    minOps = ops + 1;
                }
            }
        }

        memo.add(num, minOps);
        return minOps;
    }
}

