import java.util.LinkedList;
public class Solution {
    public int minimumOneBitOperations(int n) {
        return helper(n, new LinkedList<>());
    }

    private int helper(int n, LinkedList<Integer> cache) {
        if (cache.contains(n)) return 0;

        cache.addLast(n);
        int leftMost = n & (~n + 1);
        int operations = 1 + helper(leftMost, cache);

        return operations;
    }
}

