public class Solution {
    public int minOperations(int[] nums, int x) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum < x) {
            return -1;
        }

        int maxLength = -1;
        int currentSum = 0;

        // Start sliding window from both ends of the array
        for (int i = 0, j = nums.length - 1; i <= j; ) {
            if (currentSum < x) { // Expand right side
                if (i == j) {
                    break;
                }
                currentSum += nums[j--];
            } else if (currentSum > x) { // Shrink left side
                currentSum -= nums[i++];
            } else { // We found a subarray that sums up to total array sum - x
                maxLength = Math.max(maxLength, j - i + 1);
                currentSum -= nums[j--];
            }
        }

        return nums.length - maxLength;
    }
}

