public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();

        // Initialize variables to keep track of the number of deletions needed for 'a' and 'b'
        int a = 0, b = 0;

        // Iterate over the string from left to right
        for (char c : s.toCharArray()) {
            if (c == 'b') {
                // If we encounter a 'b', increment the count of deletions needed for 'a' and reset 'b'
                a += b;
                b = 0;
            } else {
                // If we encounter an 'a', increment the count of deletions needed for 'b'
                b++;
            }
        }

        return Math.min(a, b);
    }
}

