import java.util.Arrays;

public class Solution {
    public int bestTeamScore(int[] scores, int[] ages) {
        // Combine the two arrays into a single array of Player objects
        Player[] players = new Player[scores.length];
        for (int i = 0; i < scores.length; i++) {
            players[i] = new Player(ages[i], scores[i]);
        }

        Arrays.sort(players);

        int maxScore = Integer.MIN_VALUE;
        boolean[] dp = new boolean[players.length];

        // Iterate over all players
        for (int i = 0; i < players.length; i++) {
            // Initialize the dynamic programming array for this player to false
            dp[i] = false;

            // Check if any previous player has a smaller age and same or higher score
            int j = i - 1;
            while (j >= 0 && players[j].age < players[i].age) {
                if (players[j].score <= players[i].score) {
                    dp[i] = true;
                    break;
                }
                j--;
            }

            // If this player is part of a team with higher score, update maxScore
            if (dp[i]) {
                maxScore = Math.max(maxScore, players[i].score);
            } else {
                // Otherwise, try to form a new team with this player as the youngest member
                int sum = 0;
                for (int k = i; k >= 0; k--) {
                    if (players[k].age == players[i].age) {
                        dp[i] = true;
                        break;
                    }
                    if (players[k].score <= players[i].score && !dp[k]) {
                        sum += players[k].score;
                        dp[i] = true;
                    }
                }

                // Update maxScore if this player is part of a team with higher score
                if (dp[i]) {
                    maxScore = Math.max(maxScore, sum + players[i].score);
                }
            }
        }

        return maxScore;
    }

    private static class Player implements Comparable<Player> {
        int age;
        int score;

        public Player(int age, int score) {
            this.age = age;
            this.score = score;
        }

        @Override
        public int compareTo(Player other) {
            if (this.age == other.age) {
                return Integer.compare(this.score, other.score);
            }
            return Integer.compare(this.age, other.age);
        }
    }
}

