public class Solution {
    public int bestTeamScore(int[] scores, int[] ages) {
        // Combine the two arrays into one array of Pair objects
        int n = scores.length;
        Integer age[] = new Integer[n];
        for (int i = 0; i < n; ++i)
            age[i] = ages[i];

        int score[] = scores;

        Pair[] team = new Pair[n];
        for (int i = 0; i < n; ++i) {
            team[i] = new Pair(ages[i], scores[i]);
        }

        // Sort the combined array based on both age and score
        Arrays.sort(team, Comparator.comparingInt(o -> o.age).thenComparingInt(o -> o.score));

        int maxScore = 0;
        boolean[] dp = new boolean[n];

        for (int i = 0; i < n; ++i) {
            // Iterate over all the previous teams
            for (int j = 0; j < i; ++j)
                if (team[i].age >= team[j].age && team[i].score >= team[j].score)
                    dp[i] = dp[i] || dp[j];

            maxScore = Math.max(maxScore, team[i].score + (dp[i] ? team[i].score : 0));
        }

        return maxScore;
    }

    // Define a class for Pair
    private static class Pair {
        int age;
        int score;

        public Pair(int age, int score) {
            this.age = age;
            this.score = score;
