public class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<LocalTime>> map = new HashMap<>();

        for (int i = 0; i < keyName.length; i++) {
            LocalTime time = LocalTime.parse(keyTime[i], DateTimeFormatter.ofPattern("HH:mm"));
            if (!map.containsKey(keyName[i])) {
                map.put(keyName[i], new ArrayList<>());
            }
            map.get(keyName[i]).add(time);
        }

        List<String> result = new ArrayList<>();

        for (Map.Entry<String, List<LocalTime>> entry : map.entrySet()) {
            Collections.sort(entry.getValue());

            int count = 1;
            LocalTime prevTime = entry.getValue().get(0);

            for (int i = 1; i < entry.getValue().size(); i++) {
                if (entry.getValue().get(i).isAfter(prevTime.plusHours(1))) {
                    count = 1;
                } else if (entry.getValue().get(i).isAfter(prevTime.plusMinutes(59))) {
                    count++;

                    if (count >= 3) {
                        result.add(entry.getKey());
                        break;
                    }
                } else {
                    count++;
                }

                prevTime = entry.getValue().get(i);
            }
        }

        Collections.sort(result);

        return result;
    }
}

