public class Solution {
    public int maxHeight(int[][] arr) {
        // Sort each cuboid by width, length and height in descending order
        for (int[] cuboid : arr) {
            Arrays.sort(cuboid);
        }

        // Sort the array of cuboids based on their dimensions
        Arrays.sort(arr, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                if (a[0] == b[0]) {
                    if (a[1] == b[1]) {
                        return Integer.compare(b[2], a[2]);
                    }
                    return Integer.compare(a[1], b[1]);
                }
                return Integer.compare(a[0], b[0]);
            }
        });

        // Initialize an array to store the maximum height of cuboids
        int[] maxHeights = new int[arr.length];

        // Iterate over each cuboid and calculate its maximum height
        for (int i = 0; i < arr.length; i++) {
            maxHeights[i] = arr[i][2];
            for (int j = 0; j < i; j++) {
                if (arr[j][0] >= arr[i][0] && arr[j][1] >= arr[i][1] && arr[j][2] >= arr[i][2]) {
                    maxHeights[i] = Math.max(maxHeights[i], maxHeights[j] + arr[i][2]);
                }
            }
        }

        // Return the maximum height of all cuboids
