public class Solution {
    public String reformatNumber(String number) {
        StringBuilder sb = new StringBuilder();
        int count = 0;

        // Remove all spaces and dashes from the string
        for (char c : number.toCharArray()) {
            if (c != ' ' && c != '-') {
                sb.append(c);
                count++;
            }
        }

        if (count <= 3) {
            return sb.toString();
        } else if (count == 4) {
            return sb.substring(0, 2) + "-" + sb.substring(2);
        } else {
            int remainder = count % 3;
            StringBuilder result = new StringBuilder();

            for (int i = 0; i < count - remainder; i += 3) {
                if ((i / 3) == 1) {
                    result.append("-");
                }
                result.append(sb.substring(i, i + 3)).append("-");
            }

            // Handle the last block of digits
            if (remainder == 2) {
                result.deleteCharAt(result.length() - 1);
                result.append(sb.substring(count - 2));
            } else if (remainder == 1) {
                result.deleteCharAt(result.length() - 4).deleteCharAt(result.length() - 3);
                result.append(sb.substring(count - 1)).append("-");
                result.append(sb.substring(count - 2, count - 1));
            }

            return result.toString();
        }
    }
}

