            if (c != ' ') {
                sb.append(c);
                count++;
            }

            if ((count == 3 || count == 6) && number.length() - count > 4) {
                sb.append('-');
                count = 0;
            }
        }

        if (sb.charAt(sb.length() - 1) == '-') {
            sb.deleteCharAt(sb.length() - 1);
        }

        int len = sb.toString().length();

        if (len < 7) return sb.toString();

        for (int i = 3; i < len && i <= len / 2; i += 2) {
            sb.insert(i, '-');
        }

        return sb.toString();
    }
}

