import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String reformatNumber(String number) {
        // Remove spaces and dashes from the string
        StringBuilder sb = new StringBuilder(number.replace("-", "").replace(" ", ""));

        List<String> groups = new ArrayList<>();

        while (sb.length() > 4) {
            // Add blocks of length 3 to the list until there are less than 4 digits left
            if (sb.length() >= 6) {
                groups.add(sb.substring(0, 3));
                sb.delete(0, 3);
            } else {
                groups.add(sb.toString());
                break;
            }
        }

        // If there's only one digit, remove it
        if (groups.size() == 1 && groups.get(0).length() == 1) {
            groups.remove(0);
        }

        // Add the remaining digits to the list as blocks of length 2 or 3
        int idx = sb.length();
        while (idx > 0) {
            if (sb.length() >= 4) {
                groups.add(sb.substring(idx - 4, idx));
                idx -= 4;
                continue;
            }

            // Add the remaining digits as blocks of length 2
            groups.add(sb.substring(0, Math.min(idx, 2)));
            break;
        }

        // Reverse the list to get the correct order
        Collections.reverse(groups);

        StringBuilder result = new StringBuilder();
        for (String group : groups) {
            result.append(group).append("-");
        }

        // Remove the last dash if it exists
        return result.deleteCharAt(result.length() - 1).toString();
    }
}

