import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long mod = (long) 1e9 + 7;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int i : inventory) {
            pq.offer(new int[] {i, i});
        }

        long ans = 0;
        while (!pq.isEmpty() && orders > 0) {
            int[] top = pq.poll();
            int value = top[1];
            int count = top[0] - value + 1;

            if (count <= orders) {
                ans += ((long) value * (value - count + 1)) % mod * count / 2;
                orders -= count;
            } else {
                ans += ((long) value * (orders)) % mod;
                pq.offer(new int[] {value - orders, value});
                break;
            }
        }

        return (int) (ans % mod);
    }
}

