public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        long mod = 1000000007;
        Arrays.sort(inventory);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : b[0] - a[0]);

        for (int i = 0; i < inventory.length; i++) {
            if (i > 0 && inventory[i] == inventory[i-1]) continue;
            pq.offer(new int[]{inventory[i], i});
        }

        long totalValue = 0;
        while (!pq.isEmpty() && orders > 0) {
            int[] top = pq.poll();
            int color = top[0];
            int count = top[1];

            if (color * 2 <= orders) {
                totalValue += (long) (color * (color + 1)) / 2 * (count - 1);
                orders -= color * (count - 1);
            } else {
                long remaining = orders;
                long value = color * count;
                while (remaining > 0 && value >= color) {
                    int sellCount = Math.min(remaining, count);
                    totalValue += value * sellCount;
                    remaining -= sellCount;
                    count -= sellCount;
                    value--;
                }
                if (count != 0) pq.offer(new int[]{color, count});
            }
        }

        return (int) (totalValue % mod);
    }
}

