public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long result = 0;
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(b[1], a[1]));

        for (int i = 0; i < inventory.length - 1; i++) {
            if (inventory[i] == 0)
                continue;

            int count = inventory[i + 1] - inventory[i];
            heap.offer(new int[] {inventory[i], Math.min(orders, count)});
        }

        while (!heap.isEmpty()) {
            int[] topBall = heap.poll();
            long value = topBall[0];
            int count = topBall[1];

            if (count > 0) {
                result += (((long)value * (value - count + 1)) % (1000000007));
                orders -= count;
                if (!heap.isEmpty()) {
                    int[] nextBall = heap.peek();
                    heap.poll();
                    heap.offer(new int[]{nextBall[0], nextBall[1] + count});
                }
            } else {
                result += (((long)value * value) % (1000000007));
            }
        }

        return (int)(result % 1000000007);
    }
}

