        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i : inventory) {
            queue.offer(new int[]{i, i});
        }

        while (!queue.isEmpty() && orders > 0) {
            int[] ball = queue.poll();
            long value = ball[0] + (ball[1] - ball[0]) / 2;
            sum += value * (ball[1] - ball[0]);
            orders -= ball[1] - ball[0];
            if (orders > 0) {
                queue.offer(new int[]{(int)value, ball[1]});
            } else {
                queue.offer(new int[]{ball[0], (int)(long)ball[1] - orders});
            }
        }

        sum = sum % (1000000007);
        return (int)sum;
    }
}

