public class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        boolean[] visited = new boolean[n];
        int maxRank = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                visited[i] = true;
                int rank = getConnectedRoads(i, roads);
                maxRank = Math.max(maxRank, rank);

                for (int j = i + 1; j < n; j++) {
                    if (!visited[j]) {
                        visited[j] = true;
                        rank += getCommonRoads(i, j, roads);
                        maxRank = Math.max(maxRank, rank);
                    }
                }
            }
        }

        return maxRank;
    }

    private int getConnectedRoads(int city, int[][] roads) {
        int count = 0;
        for (int[] road : roads) {
            if ((road[0] == city || road[1] == city) && road[0] != road[1]) {
                count++;
            }
        }
        return count;
    }

    private int getCommonRoads(int i, int j, int[][] roads) {
        for (int[] road : roads) {
            if ((road[0] == i && road[1] == j) || (road[0] == j && road[1] == i)) {
                return 1;
            }
        }
        return 0;
    }
}

