public class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        boolean[] visited = new boolean[n];

        int maxCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (hasEdge(i, j, roads)) {
                    maxCount = Math.max(maxCount, countEdges(i) + countEdges(j) - 1);
                } else {
                    maxCount = Math.max(maxCount, countEdges(i) + countEdges(j));
                }
            }
        }

        return maxCount;
    }

    private boolean hasEdge(int i, int j, int[][] roads) {
        for (int[] road : roads) {
            if ((road[0] == i && road[1] == j) || (road[0] == j && road[1] == i)) {
                return true;
            }
        }

        return false;
    }

    private int countEdges(int node, int[][] roads) {
        int count = 0;

        for (int[] road : roads) {
            if ((road[0] == node || road[1] == node) && !visited[road[0]]) {
                visited[road[0]] = true;
                count++;
            }
        }

        return count;
    }
}

