            int b = road[1];
            if (!graph.get(a).contains(b)) {
                graph.get(a).add(b);
                graph.get(b).add(a);
            }
        }

        int maxRank = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int rank = graph.get(i).size() + graph.get(j).size();
                if (graph.get(i).contains(j)) {
                    rank--;
                }
                maxRank = Math.max(maxRank, rank);
            }
        }

        return maxRank;
    }
}

