import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minMoves(int[] nums, int limit) {
        Map<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < nums.length / 2; i++) {
            int sum = nums[i] + nums[nums.length - 1 - i];

            if (sum <= limit) {
                map.put(sum, map.getOrDefault(sum, 0) + 1);
            } else {
                map.put(nums[i] + nums[nums.length - 1 - i], map.getOrDefault(nums[i] + nums[nums.length - 1 - i], 0) + 1);
            }
        }

        int minMoves = Integer.MAX_VALUE;

        for (int sum : map.keySet()) {
            int moves = map.get(sum);

            if (sum <= limit) {
                moves += Math.max(0, map.getOrDefault(limit * 2 - sum, 0) - map.getOrDefault(sum, 0));
            } else {
                moves += Math.max(0, map.getOrDefault((limit + 1) * 2 - sum, 0) - map.getOrDefault(sum, 0));
            }

            minMoves = Math.min(minMoves, moves);
        }

        return minMoves;
    }
}

