        for (int i = 1; i <= limit / 2; i++) {
            int left = 0;
            int right = 0;
            for (int j = 0; j < n / 2; j++) {
                if (nums[j] + nums[n - 1 - j] == i) {
                    left++;
                } else if (nums[j] + nums[n - 1 - j] == limit - i + 1) {
                    right++;
