public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int maxSum = 2 * limit;
        long[] prefixSums = new long[maxSum + 1];

        for (int i = 0; i < n / 2; i++) {
            int currentSum = nums[i] + nums[n - i - 1];
            if (currentSum <= maxSum) {
                prefixSums[(int) currentSum]++;
            }
        }

        long moves = Long.MAX_VALUE;
        for (long sum = 1; sum <= limit; sum++) {
            long countForSum = prefixSums[(int) (2 * sum - 1)];
            if (sum <= limit / 2) {
                countForSum += prefixSums[(int) (maxSum + 1 - 2 * sum)];
            }

            moves = Math.min(moves, n / 2 - countForSum);
        }

        return (int) moves;
    }
}

