    public int countBinarySubstrings(String s) {
        int n = s.length();
        int[] groupCounts = new int[n + 1];
        int currentGroup = 0;
        int previousGroup = 0;

        for (int i = 0; i < n; i++) {
            if (i == 0 || s.charAt(i) != s.charAt(i - 1)) {
                currentGroup++;
                groupCounts[currentGroup] = 0;
            }

            groupCounts[currentGroup]++;
        }

        int result = 0;

        for (int i = 1; i < n; i++) {
            if (currentGroup > previousGroup && s.charAt(i) != s.charAt(i - 1)) {
                result += Math.min(previousGroup, currentGroup);
            }

            groupCounts[previousGroup] -= 1;
            if (groupCounts[previousGroup] == 0) {
                currentGroup--;
                previousGroup--;
            } else {
                previousGroup++;
            }
        }

        return result;
    }
}

