import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        HashMap<Character, HashSet<Integer>> map = new HashMap<>();

        for (int i = 0; i < stickers.length; i++) {
            char[] chars = stickers[i].toCharArray();
            for (char c : chars) {
                if (!map.containsKey(c)) {
                    map.put(c, new HashSet<>());
                }
                map.get(c).add(i);
            }
        }

        int n = target.length();
        long[][] dp = new long[n + 1][1 << 26];

        for (int i = 0; i <= n; i++) {
            for (long mask = 0; mask < (1L << 26); mask++) {
                if ((mask & (1L << (target.charAt(i) - 'a'))) != 0) {
                    dp[i][mask] = Long.MAX_VALUE;
                }
            }
        }

        dp[0][(1 << 26) - 1] = 0;

        for (int i = 1; i <= n; i++) {
            char c = target.charAt(i - 1);
            long mask = (1L << (c - 'a'));

            if ((dp[i - 1][(1 << 26) - 1] & mask) != 0) {
                dp[i][(1 << 26) - 1] = Math.min(dp[i][(1 << 26) - 1], dp[i - 1][(1 << 26) - 1]);
            }

            for (int j = 0; j < (1 << 26); j++) {
                if ((j & mask) != 0 && (dp[i - 1][j] != Long.MAX_VALUE)) {
                    long newMask = j ^ mask;

                    if (!map.containsKey(c)) {
                        dp[i][newMask] = Math.min(dp[i][newMask], dp[i - 1][j]);
                    } else {
                        for (int k : map.get(c)) {
                            int newSticker = ((1 << 26) + k);
                            long newMask2 = newMask | newSticker;

                            if (dp[i - 1][j] != Long.MAX_VALUE && dp[i][newMask2] == Long.MAX_VALUE) {
                                dp[i][newMask2] = dp[i - 1][j] + 1;
                            }
                        }
                    }
                }
            }
        }

        long ans = dp[n][(1 << 26) - 1];

        return (ans == Long.MAX_VALUE) ? -1 : (int) ans;
    }
}

