import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        HashMap<String, Integer> memo = new HashMap<>();
        return dfs(stickers, target, memo);
    }

    private int dfs(String[] stickers, String target, HashMap<String, Integer> memo) {
        if (target.isEmpty()) return 0;
        if (memo.containsKey(target)) return memo.get(target);

        int min = Integer.MAX_VALUE;

        for (String sticker : stickers) {
            boolean flag = true;
            for (int i = 0; i < target.length(); i++) {
                if (!sticker.contains(String.valueOf(target.charAt(i)))) {
                    flag = false;
                    break;
                }
            }

            if (!flag) continue;

            String newTarget = target;
            int count = 0;
            while (newTarget.indexOf(sticker) != -1) {
                newTarget = newTarget.replaceFirst(sticker, "");
                count++;
            }

            min = Math.min(min, dfs(stickers, newTarget, memo) + count);
        }

        memo.put(target, min == Integer.MAX_VALUE ? -1 : min);
        return min;
    }
}

