public class Solution {
    public int minStickers(String[] stickers, String target) {
        // count the characters of every sticker
        Map<Character, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < stickers.length; i++) {
            char[] chars = stickers[i].toCharArray();
            Arrays.sort(chars);
            final String temp = new String(chars);
            if (!map.containsKey(temp)) {
                map.put(temp, new ArrayList<>());
            }
            map.get(temp).add(i);
        }

        // create a dp array to store the minimum number of stickers needed
        int len = target.length();
        int[] dp = new int[1 << len];
        Arrays.fill(dp, Integer.MAX_VALUE);

        // initialize the base case where the target string is empty
        dp[0] = 0;

        for (int mask = 0; mask < (1 << len); ++mask) {
            if (dp[mask] == Integer.MAX_VALUE) continue;
            char[] chars = new char[len];
            int cnt = 0;
            for (int i = 0; i < len; ++i) {
                if ((mask & (1 << i)) != 0) {
                    chars[cnt++] = target.charAt(i);
                }
            }

            Arrays.sort(chars, 0, cnt);

            final String temp = new String(chars, 0, cnt);
            if (!map.containsKey(temp)) continue;

            for (int sticker : map.get(temp)) {
                int nextMask;
                // generate the next mask by adding the character of the current sticker
                for (int i = 0; i < len; ++i) {
                    if ((mask & (1 << i)) != 0 && target.charAt(i) == stickers[sticker].charAt(0)) {
                        nextMask = mask ^ (1 << i);
                        break;
                    }
                }

                // update the dp array with the minimum number of stickers needed
                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
            }
        }

        return dp[(1 << len) - 1] == Integer.MAX_VALUE ? -1 : dp[(1 << len) - 1];
    }
}

