public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        Map<Character, List<Integer>> map = new HashMap<>();

        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                if (!map.containsKey(c)) {
                    map.put(c, new ArrayList<>());
                }
                map.get(c).add(i);
            }
        }

        int n = target.length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            char c = target.charAt(i - 1);

            if (!map.containsKey(c)) {
                continue;
            }

            List<Integer> indices = map.get(c);

            for (int index : indices) {
                dp[i] = Math.min(dp[i], dp[i - 1]);

                for (char d = 'a'; d <= 'z'; d++) {
                    if (!map.containsKey(d)) {
                        continue;
                    }

                    List<Integer> otherIndices = map.get(d);

                    for (int otherIndex : otherIndices) {
                        if (otherIndex == index) {
                            continue;
                        }

                        long temp = dp[i - 1];
                        int j = i;

                        while (j <= n && target.charAt(j - 1) == d) {
                            temp++;
                            j++;
                        }

                        dp[j] = Math.min(dp[j], temp);
                    }
                }
            }
        }

        return dp[n + 1] > Long.MAX_VALUE / 2 ? -1 : (int) (dp[n + 1] / 2);
    }
}

