import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        HashMap<Character, HashSet<Integer>> map = new HashMap<>();

        for (int i = 0; i < stickers.length; i++) {
            char[] chars = stickers[i].toCharArray();

            for (char c : chars) {
                if (!map.containsKey(c)) {
                    map.put(c, new HashSet<>());
                }

                map.get(c).add(i);
            }
        }

        int n = target.length();

        // create a bitmap to represent the characters in the target string
        int[] bitmap = new int[n];

        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);

            if (!map.containsKey(c)) {
                return -1;
            }

            bitmap[i] = map.get(c).size();
        }

        // using bitmask dp to solve the problem
        int max = (int) Math.pow(2, n + 1);

        int[][] dp = new int[max][n];

        for (int i = 0; i < max; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }

        dp[0][0] = 0;

        for (int i = 0; i < target.length(); i++) {
            int newBitmap = bitmap[i];

            for (int j = max - 1; j >= 0; j--) {
                if (dp[j][i] != -1) {
                    for (int k = 0; k <= n; k++) {
                        if ((j & (1 << k)) == 0 || dp[j][k] == -1) {
                            continue;
                        }

                        int tmpBitmap = j | newBitmap;

                        // check if the current character can be covered by the sticker
                        if (tmpBitmap != newBitmap && (tmpBitmap >> i & 1 << k) > 0) {
                            dp[tmpBitmap][k] = Math.max(dp[tmpBitmap][k], dp[j][i] + 1);
                        }
                    }
                }
            }
        }

        int result = -1;

        for (int i = max - 1; i >= 0; i--) {
            if (dp[i][n] != -1) {
                result = Math.max(result, dp[i][n]);
            }
        }

        return result == -1 ? -1 : result - 1;
    }
}

