public class Solution {
    public double findMaxAverage(int[] nums, int k) {
        // Initialize sum of first window of size 'k'
        double total = 0;
        for (int i = 0; i < k; i++) {
            total += nums[i];
        }

        // Calculate sum of all windows of size 'k' and find max average
        double maxSum = total;
        int n = nums.length;
        for (int i = k; i < n; i++) {
            total -= nums[i - k];  // Subtract the leftmost element and add new element
            total += nums[i];
            maxSum = Math.max(maxSum, total);
        }

        return maxSum / k;
    }
}

