public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSums = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + nums[i];
        }

        long[][] maxSum = new long[3][n - k + 1];
        int[] startIndices = new int[3];

        for (int i = 0; i <= n - k; i++) {
            long currentMax = Long.MIN_VALUE;
            for (int j = i; j < Math.min(i + k, n); j++) {
                long sum = prefixSums[j + 1] - prefixSums[i];
                if (sum > currentMax) {
                    currentMax = sum;
                    maxSum[0][i] = sum;
                    startIndices[0] = i;
                }
            }

            for (int j = 0; j < 3; j++) {
                long currentMax2 = Long.MIN_VALUE;
                int index = -1;
                for (int l = startIndices[j] + k; l <= n - k; l++) {
                    if (maxSum[j][startIndices[j]] + maxSum[(j + 1) % 3][l - k] > currentMax2) {
                        currentMax2 = maxSum[j][startIndices[j]] + maxSum[(j + 1) % 3][l - k];
                        index = l;
                    }
                }

                if (index != -1) {
                    maxSum[(j + 1) % 3][index] = currentMax2;
                    startIndices[(j + 1) % 3] = index;
                }
            }
        }

        int[] result = new int[3];
        for (int i = 0; i < 3; i++) {
            result[i] = startIndices[i];
        }
        return result;
    }
}

