    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        long[][] dp = new long[3][n];
        int[][] prev = new int[3][n];

        // Initialize the maximum sum of subarray of length k
        for (int i = k - 1; i < n; i++) {
            long maxSum = Long.MIN_VALUE;
            for (int j = i - k + 1; j <= i; j++) {
                if (prefixSum[i + 1] - prefixSum[j] > maxSum) {
                    maxSum = prefixSum[i + 1] - prefixSum[j];
                    dp[0][i] = maxSum;
                    prev[0][i] = j;
                }
            }
        }

        // Initialize the maximum sum of subarray of length 2k
        for (int i = k * 2 - 1; i < n; i++) {
            long maxSum = Long.MIN_VALUE;
            int prevIndex = -1;
            for (int j = i - k + 1; j <= i; j++) {
                if (dp[0][j] != 0 && prefixSum[i + 1] - prefixSum[j] > maxSum) {
                    maxSum = prefixSum[i + 1] - prefixSum[j];
                    dp[1][i] = maxSum;
                    prevIndex = j;
                }
            }

            // Update the maximum sum of subarray of length k
            if (prevIndex != -1 && dp[0][prevIndex] != 0) {
                long newMaxSum = dp[0][prevIndex] + maxSum;
                for (int j = prevIndex - k + 1; j <= prevIndex; j++) {
                    if (newMaxSum > dp[0][j]) {
                        dp[0][j] = newMaxSum;
                        prev[0][j] = i;
                    }
                }
            }
        }

        // Initialize the maximum sum of subarray of length 3k
        for (int i = k * 3 - 1; i < n; i++) {
            long maxSum = Long.MIN_VALUE;
            int prevIndex = -1;
            for (int j = i - k + 1; j <= i; j++) {
                if (dp[1][j] != 0 && prefixSum[i + 1] - prefixSum[j] > maxSum) {
                    maxSum = prefixSum[i + 1] - prefixSum[j];
                    dp[2][i] = maxSum;
                    prevIndex = j;
                }
            }

            // Update the maximum sum of subarray of length 2k
            if (prevIndex != -1 && dp[1][prevIndex] != 0) {
                long newMaxSum = dp[1][prevIndex] + maxSum;
                for (int j = prevIndex - k + 1; j <= prevIndex; j++) {
                    if (newMaxSum > dp[1][j]) {
                        dp[1][j] = newMaxSum;
                        prev[1][j] = i;
                    }
                }
            }

            // Update the maximum sum of subarray of length k
            if (prevIndex != -1 && dp[0][prevIndex] != 0) {
                long newMaxSum = dp[0][prevIndex] + maxSum;
                for (int j = prevIndex - k + 1; j <= prevIndex; j++) {
                    if (newMaxSum > dp[0][j]) {
                        dp[0][j] = newMaxSum;
                        prev[0][j] = i;
                    }
                }
            }
        }

        // Find the maximum sum of three non-overlapping subarrays
        int maxSum = Long.MIN_VALUE;
        int[] result = new int[3];
        for (int i = k - 1; i < n; i++) {
            if (dp[0][i] != 0 && dp[1][i] != 0 && dp[2][i] != 0) {
                long sum = dp[0][i] + dp[1][i] + dp[2][i];
                if (sum > maxSum) {
                    maxSum = sum;
                    result[0] = prev[0][i - k + 1];
                    result[1] = prev[1][i - k * 2 + 1];
                    result[2] = i;
                }
            }
        }

        return result;
    }
}

