                for (int l = Math.max(0, (i - k + 1)); l < i; ++l) {
                    max = Math.max(max, dp[1 % 3][l]);
                }
                preMax[i][Math.max(0, ((i - k + 1))] = max + temp[i];
            }
        }

        int[] res = new int[3];

        for (int i = n * 2; i >= 0; --i) {
            if (preSum[0][i] != preSum[0][Math.max(0, ((i - k))]) && preMax[i][Math.max(0, ((i - k))] != preMax[Math.max(0, ((i - 2 * k)]]][Math.max(0, ((i - 3 * k)])]]) {
