import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Queue;

public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);

        for (int i = 0; i < forest.size(); i++) {
            for (int j = 0; j < forest.get(i).size(); j++) {
                if (forest.get(i).get(j) > 1) {
                    pq.offer(new int[] {i, j, forest.get(i).get(j)});
                }
            }
        }

        int startRow = 0;
        int startCol = 0;
        int steps = 0;

        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int endRow = tree[0];
            int endCol = tree[1];

            steps += bfs(forest, startRow, startCol, endRow, endCol);
            if (steps == -1) return -1;
            startRow = endRow;
            startCol = endCol;
        }

        return steps;
    }

    private int bfs(List<List<Integer>> forest, int startRow, int startCol, int endRow, int endCol) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];
        queue.offer(new int[] {startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int row = current[0];
            int col = current[1];

            if (row == endRow && col == endCol) return forest.get(row).get(col) - 1;

            for (int[] dir : directions) {
                int newRow = row + dir[0];
                int newCol = col + dir[1];

                if (newRow >= 0 && newRow < forest.size() && newCol >= 0
                        && newCol < forest.get(0).size() && !visited[newRow][newCol]
                        && forest.get(newRow).get(newCol) > 1) {
                    queue.offer(new int[] {newRow, newCol});
                    visited[newRow][newCol] = true;
                }
            }
        }

        return -1;
    }

    private static final int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
}

