            int endRow = tree[0];
            int endCol = tree[1];

            if (endRow < 0 || endRow >= forest.size() || endCol < 0 || endCol >= forest.get(0).size()) continue;

            steps += bfs(forest, startRow, startCol, endRow, endCol);

            if (steps == Integer.MAX_VALUE) return -1;
            startRow = tree[0];
            startCol = tree[1];
        }

        return steps;
    }

    private int bfs(List<List<Integer>> forest, int sr, int sc, int er, int ec) {
        Queue<int[]> q = new LinkedList<>();
        boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];
        int rows = forest.size();
        int cols = forest.get(0).size();

        q.offer(new int[] {sr, sc});
        visited[sr][sc] = true;

        int steps = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int[] curr = q.poll();

                if (curr[0] == er && curr[1] == ec) return steps;

                for (int[] dir : directions) {
                    int nr = curr[0] + dir[0];
                    int nc = curr[1] + dir[1];

                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) continue;

                    q.offer(new int[] {nr, nc});
                    visited[nr][nc] = true;
                }
            }

            steps++;
        }

        return Integer.MAX_VALUE;
    }

    private static final int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
