import java.util.*;

public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.isEmpty()) return 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        int startRow = 0, startCol = 0, endRow = forest.size() - 1, endCol = forest.get(0).size() - 1;
        int steps = 0;

        for (int r = 0; r < forest.size(); r++) {
            for (int c = 0; c < forest.get(r).size(); c++) {
                if (forest.get(r).get(c) > 1) {
                    pq.offer(new int[] {r, c, forest.get(r).get(c)});
                }
            }
        }

        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int r = tree[0], c = tree[1];
            int height = tree[2];

            if (r < 0 || r >= forest.size() || c < 0 || c >= forest.get(0).size() || forest.get(r).get(c) != 1) continue;

            steps++;
            dfs(forest, r, c);

            if (!pq.isEmpty()) {
                int[] nextTree = pq.peek();
                if (nextTree[2] == height) continue;
            }
        }

        return endRow < startRow || endCol < startCol ? -1 : steps;
    }

    private void dfs(List<List<Integer>> forest, int row, int col) {
        if (row < 0 || row >= forest.size() || col < 0 || col >= forest.get(0).size()) return;

        if (forest.get(row).get(col) > 1) {
            forest.get(row).set(col, 1);
            dfs(forest, row - 1, col); // north
            dfs(forest, row + 1, col); // south
            dfs(forest, row, col - 1); // west
            dfs(forest, row, col + 1); // east
        }
    }
}

