public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        int totalSteps = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        for (List<Integer> row : forest) {
            for (int height : row) {
                if (height > 1) {
                    pq.offer(new int[] {row.indexOf(height), height, height});
                }
            }
        }

        int prevX = 0, prevY = 0;
        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int x = tree[0], y = forest.size() - 1 - tree[1];

            // find the shortest path from (prevX, prevY) to (x, y)
            totalSteps += bfs(forest, prevX, prevY, x, y);

            if (totalSteps == -1) {
                return -1;
            }

            prevX = x;(prevY = y;
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sx, int sy, int tx, int ty) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];
        queue.offer(new int[] {sx, sy});
        visited[sx][sy] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            if (current[0] == tx && current[1] == ty) return forest[current[0]][current[1]] - 1;

            for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                int newX = current[0] + dir[0];
                int newY = current[1] + dir[1];

                if (newX >= 0 && newX < forest.size() && newY >= 0
                        && newY < forest.get(0).size() && !visited[newX][newY]
                        && forest.get(newX).get(newY) > 1) {
                    queue.offer(new int[] {newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }

        return -1; // no path found
    }
}

