        int currX = 0;
        int currY = 0;

        int steps = 0;

        while (!pq.isEmpty()) {
            int[] tree = pq.poll();

            if (forest.get(tree[0]).get(tree[1]) != 1) {
                int dist = bfs(forest, currX, currY, tree[0], tree[1]);

                if (dist == -1) return -1;

                steps += dist;

                currX = tree[0];
                currY = tree[1];
            }
        }

        return forest.get(currX).get(currY) == 1 ? steps : -1;
    }

    private int bfs(List<List<Integer>> forest, int startx, int starty, int endx, int endy) {
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[] {startx, starty});

        visited[startx][starty] = true;

        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                int[] curr = queue.poll();

                if (curr[0] == endx && curr[1] == endy) return steps;

                for (int[] dir : directions) {
                    int newX = curr[0] + dir[0];
                    int newY = curr[1] + dir[1];

                    if (newX >= 0 && newX < forest.size() &&
                        newY >= 0 && newY < forest.get(newX).size() &&
                        !visited[newX][newY] && forest.get(newX).get(newY) != 0) {

                        queue.offer(new int[] {newX, newY});
                        visited[newX][newY] = true;
                    }
                }
            }

            steps++;
        }

        return -1;
    }
