        // Initialize diagonal elements as true (single character substrings are always palindromes)
        for (int i = 0; i < n; i++) {
            dp[i][i] = true;
        }

        int count = 0;

        // Check for other substrings
        for (int length = 2; length <= n; length++) {
            for (int start = 0; start < n - length + 1; start++) {
                int end = start + length - 1;

                if (length == 2) { // Check for two character substrings
                    dp[start][end] = s.charAt(start) == s.charAt(end);
                } else {
                    dp[start][end] = s.charAt(start) == s.charAt(end) && dp[start + 1][end - 1];
                }

                if (dp[start][end]) {
                    count++;
                }
            }
        }

        return count;
    }
}

