public class Solution {
    public int maximumProduct(int[] nums) {
        Arrays.sort(nums);

        // If there are three negative numbers, their product will be the largest.
        if (nums[0] < 0 && nums[1] < 0 && nums[nums.length - 1] < 0) {
            return nums[nums.length - 1] * nums[nums.length - 2] * nums[nums.length - 3];
        }

        // If there are two negative numbers, their product will be the largest.
        if (nums[0] < 0 && nums[1] < 0) {
            return Math.max(nums[nums.length - 1] * nums[nums.length - 2], nums[0] * nums[1] * nums[nums.length - 1]);
        }

        // If there are no negative numbers, the product of the three largest numbers will be the largest.
        return nums[nums.length - 1] * nums[nums.length - 2] * nums[nums.length - 3];
    }
}

