                double num2 = nums[j];

                res.add(num1 * num2);
                if (!backtrack(nums, res, n - 2)) {
                    res.remove(res.size() - 1);
                }

                res.add((double) (num1 + num2));
                if (!backtrack(nums, res, n - 2)) {
