                // add
                cards[cards.length - 2] = (int)num1;
                cards[cards.length - 1] = (int)num2;

                backtrack(set, currentVal + num1 / num2, Arrays.copyOf(cards, cards.length));
                backtrack(set, currentVal + num2 / num1, Arrays.copyOf(cards, cards.length));

                // subtract
                cards[cards.length - 2] = (int)num1;
                cards[cards.length - 1] = (int)num2;

                backtrack(set, currentVal - num1 / num2, Arrays.copyOf(cards, cards.length));
                backtrack(set, currentVal - num2 / num1, Arrays.copyOf(cards, cards.length));

                // multiply
                cards[cards.length - 2] = (int)num1;
                cards[cards.length - 1] = (int)num2;

                backtrack(set, currentVal * num1 / num2, Arrays.copyOf(cards, cards.length));
                backtrack(set, currentVal * num2 / num1, Arrays.copyOf(cards, cards.length));

                // divide
                cards[cards.length - 2] = (int)num1;
                cards[cards.length - 1] = (int)num2;

                if(num2 != 0){
                    double temp = num1;
                    num1 = num2;
                    num2 = temp;
                }

                backtrack(set, currentVal / num1 * num2, Arrays.copyOf(cards, cards.length));
            }
        }
    }
