        // Our answer list
        List<Integer> ans = new ArrayList<>();
        ans.add(0);

        // Global Max
        int globalMax = 0;

        // coordinate compression lookup
        for (int[] position : positions) {
            int x1 = Collections.binarySearch(list, position[0]);
            if (x1 < 0) {
                x1 = -x1 - 1;
            }
            int x2 = Collections.binarySearch(list, position[0] + position[1]);
            if (x2 < 0) {
                x2 = -x2 - 1;
            }

            // get the current max for the interval between x1 and x2
            int currMax = globalMax;
            for (int i = x1; i <= x2; i++) {
                currMax = Math.max(currMax, height[i]);
            }

            // add the new square on the top
            currMax += position[1];

            // update the interval with the new value
            for (int i = x1; i <= x2; i++) {
                height[i] = currMax;
            }

            // recalculate the global max
            globalMax = Math.max(globalMax, currMax);

            // add to answer list
            ans.add(globalMax);
        }
        return ans;
    }
