public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        TreeSet<Integer> xCompressed = new TreeSet<>();
        for (int[] pos : positions) {
            xCompressed.add(pos[0]);
            xCompressed.add(pos[0] + pos[1]);
        }

        int n = xCompressed.size();
        List<Integer> compressedXCoordinates = new ArrayList<>(xCompressed);
        int[] heights = new int[n];
        for (int i = 0; i < positions.length; i++) {
            int left = positions[i][0], sideLength = positions[i][1];
            int xLow = Collections.binarySearch(compressedXCoordinates, left) + 1;
            int xHigh = Collections.binarySearch(compressedXCoordinates, left + sideLength);
            for (int j = xLow; j < xHigh; j++) {
                heights[j] += sideLength;
            }
        }

        int[] compressedHeights = new int[n];
        for (int i = 0; i < n; i++) {
            int maxHeight = 0;
            int start = i, end = -1;
            for (int j = i; j < n && end == -1; j++) {
                if (heights[j] > maxHeight) {
                    start = j;
                    maxHeight = heights[j];
                }
                if (compressedXCoordinates.get(j).equals(compressedXCoordinates.get(i))) {
                    end = j + 1;
                }
            }

            compressedHeights[i] = maxHeight - (start != i ? compressedXCoordinates.get(start) : 0);
        }

        List<Integer> result = new ArrayList<>();
        int globalMax = 0;
        for (int height : heights) {
            globalMax = Math.max(globalMax, height);
        }
        result.add(globalMax);

        for (int j = 1; j < positions.length; j++) {
            for (int i = 0; i < n; i++) {
                if (compressedXCoordinates.get(i).equals(positions[j][0])) {
                    globalMax -= compressedHeights[i];
                }
                if (compressedXCoordinates.get(i).equals(positions[j][0] + positions[j][1])) {
                    globalMax += compressedHeights[i];
                }
            }

            result.add(globalMax);
        }

        return result;
    }
}

