import java.util.Arrays;

public class Solution {
    public int strangePrinter(String s) {
        char[] str = s.toCharArray();
        int n = str.length;

        // Create a memoization table to store the results of subproblems
        int[][][] memo = new int[n][n][26];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }

        return dfs(str, 0, n - 1, memo);
    }

    public int dfs(char[] str, int left, int right, int[][][] memo) {
        // If the subproblem has been solved before, return the result from the table
        if (memo[left][right][str[left]] != -1) {
            return memo[left][right][str[left]];
        }

        // Base case: If there are two or less characters in the string, 
        // it can be printed in one turn.
        if (left == right || str[right] == str[left]) {
            memo[left][right][str[left]] = 1;
            return 1;
        }

        int minTurns = Integer.MAX_VALUE;

        for (int i = left + 1; i <= right; i++) {
            // If the current character is different from the first and last characters,
            // we can either print all characters in one turn or divide them into two parts.
            if (str[i] != str[left]) {
                int turns = dfs(str, left, i - 1, memo) + dfs(str, i, right, memo);
                minTurns = Math.min(minTurns, turns);
            }
        }

        // If the current character is the same as the first character, 
        // we can print all characters in one turn.
        if (str[right] == str[left]) {
            int turns = dfs(str, left + 1, right - 1, memo) + 1;
            minTurns = Math.min(minTurns, turns);
        }

        memo[left][right][str[left]] = minTurns;
        return minTurns;
    }
}

