        // Create a Trie data structure to store the roots from the dictionary
        Node root = new Node();
        for (String word : dictionary) {
            insert(root, word);
        }

        StringBuilder result = new StringBuilder();
        int index = 0;
        while (index < sentence.length()) {
            String substr = "";
            // Try to find a valid replacement starting from each position in the string
            for (int i = index; i < sentence.length(); ++i) {
                char ch = sentence.charAt(i);
                substr += ch;

                // Check if the current substring is a valid root
                if (check(root, substr)) {
                    result.append(substr);

                    // If we found a valid replacement, move to the next character in the string
                    index = i + 1;
                    break;
                }
            }

            // If no valid replacement was found, just append the original character to the result
            if (index == sentence.length()) {
                result.append(sentence.charAt(index - 1));
                break;
            } else if (result.length() > 0) {
                result.append(" ");
            }
        }

        return result.toString().trim();
    }

    private boolean check(Node root, String word) {
        for (char ch : word.toCharArray()) {
            int index = ch - 'a';
            if (!root.children[index].isEnd && !root.children[index].word.isEmpty())
                root = root.children[index];
            else
