public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int kInversePairs(int n, int k) {
        Map<Integer, Integer>[] dp = new HashMap[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new HashMap<>();
        }
        dp[0].put(0, 1);

        for (int m = 1; m <= n; m++) {
            for (int pairs = 0; pairs <= k; pairs++) {
                int ways = dp[m - 1].getOrDefault(pairs, 0);

                if (pairs >= m) {
                    long add = 0;
                    for (int i = 1; i <= Math.min(m - 1, k - pairs); i++) {
                        add += ways * dp[i - 1].getOrDefault(m - i, 0);
                    }
                    dp[m].put(pairs, (int) ((add % MOD + MOD) % MOD));
                } else {
                    dp[m].put(pairs, ways);
                }
            }
        }

        return dp[n].getOrDefault(k, 0);
    }
}

