public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int kInversePairs(int n, int k) {
        long[][] dp = new long[n + 1][k + 1];

        for (int i = 1; i <= n; ++i) {
            Arrays.fill(dp[i], -1);
        }

        return (int) solve(n, k, dp);
    }

    private int solve(int n, int k, long[][] dp) {
        if (k == 0) {
            return 1;
        }

        if (n <= 0 || k < 0) {
            return 0;
        }

        if (dp[n][k] != -1) {
            return (int) dp[n][k];
        }

        long ans = solve(n, k - n, dp);

        for (int i = Math.max(1, n - k), j = n; i <= Math.min(n, k); ++i) {
            int left = (int) solve(i - 1, k - i, dp);
            int right = (int) solve(n - i, n - i, dp);

            ans += left * right;

            if (ans >= MOD) {
                ans -= MOD;
            }
        }

        return dp[n][k] = ans % MOD;
    }
}

