import java.util.Arrays;

public class Solution {
    static final int MOD = 1000000007;
    static int[][] dp;

    public int kInversePairs(int n, int k) {
        if (n == 0 || k < 0)
            return 0;

        // Initialize dp array
        dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1);
        }

        return dfs(n, k) % MOD;
    }

    private int dfs(int n, int k) {
        // Base case
        if (n == 0 && k == 0)
            return 1;

        if (k < 0 || dp[n][k] != -1)
            return dp[n][k];

        for (int i = 0; i <= Math.min(n, k); i++) {
            // Recursive case
            dp[n][k] += dfs(n - 1, k - i) * choose(n, n - i);
            dp[n][k] %= MOD;
        }

        return dp[n][k];
    }

    private int choose(int n, int r) {
        int res = 1;
        for (int i = 0; i < r; i++) {
            res = res * (n - i) / (i + 1);
            res %= MOD;
        }
        return res % MOD;
    }

}

