public class Solution {
    public int flipLights(int n, int m) {
        if (n >= 4 && m >= 3) return 8;
        if (n >= 3 && m >= 2) return 8;
        if (n == 1 || n == 2) return 2;

        int[] bulbs = new int[8];
        for (int i = 0; i < 4; i++) {
            switch (i) {
                case 0:
                    // Button 1: Flips the status of all the bulbs.
                    flipAll(bulbs);
                    break;
                case 1:
                    // Button 2: Flips the status of all the bulbs with even labels.
                    flipEven(bulbs);
                    break;
                case 2:
                    // Button 3: Flips the status of all the bulbs with odd labels.
                    flipOdd(bulbs);
                    break;
                default:
                    // Button 4: Flips the status of all the bulbs with a label j = 3k + 1 where k = 0, 1, 2, ...
                    flipThird(bulbs);
            }
        }

        int count = 0;
        for (int i = 0; i < 8; i++) {
            if (m == 1) {
                // If m is 1, we only need to check the first button press.
                count++;
            } else if (m == 2) {
                // If m is 2, we need to check all possible combinations of two button presses.
                int j = i;
                for (int k = 0; k < 4; k++) {
                    if ((j & (1 << k)) != 0) {
                        count++;
                    }
                }
            } else if (m == 3) {
                // If m is 3, we need to check all possible combinations of three button presses.
                int j = i;
                for (int k = 0; k < 4; k++) {
                    if ((j & (1 << k)) != 0) {
                        count++;
                    }
                }
            } else if (m == 4) {
                // If m is 4, we need to check all possible combinations of four button presses.
                int j = i;
                for (int k = 0; k < 4; k++) {
                    if ((j & (1 << k)) != 0) {
                        count++;
                    }
                }
            } else {
                // If m is greater than 4, we can't have more different statuses.
                break;
            }
        }

        return count;
    }

    private void flipAll(int[] bulbs) {
        for (int i = 0; i < 8; i++) {
            bulbs[i] ^= 1;
        }
    }

    private void flipEven(int[] bulbs) {
        for (int i = 0; i < 4; i += 2) {
            bulbs[i] ^= 1;
        }
    }

    private void flipOdd(int[] bulbs) {
        for (int i = 1; i < 8; i += 2) {
            bulbs[i] ^= 1;
        }
    }

    private void flipThird(int[] bulbs) {
        for (int i = 0; i < 8; i++) {
            if ((i & 1) == 0) {
                bulbs[i] ^= 1;
            }
        }
    }
}

