public class Solution {
    public int flipLights(int n, int m) {
        if (n == 1 && m >= 1) return 2;
        if (m > 5) return 4;

        int[] lights = {0x0001, 0x00FF, 0xFF00, 0xFFFF};
        int status = 0;

        for(int i=0; i<lights.length; ++i){
            switch(m){
                case 1:
                    status |= lights[i];
                    break;
                case 2:
                    if(status == 0 || (status & (lights[0] | lights[1])) != 0) {
                        status |= lights[i];
                    } else {
                        status |= ~lights[i];
                    }
                    break;
                default:
                    for(int j=3; j<=m; ++j){
                        int temp = status | lights[i];
                        if((temp & (status | lights[j%(lights.length)])) != 0) {
                            status |= lights[i];
                        } else {
                            status |= ~lights[i];
                        }
                    }
            }
        }

        return Integer.bitCount(status);
    }
}

