    private Map<String, TreeNode> memo = new HashMap<>();

    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        List<TreeNode> duplicates = new ArrayList<>();

        traverse(root, duplicates);

        return duplicates;
    }

    private String traverse(TreeNode node, List<TreeNode> duplicates) {
        if (node == null)
            return "#";

        String serializedNode = serialize(node);

        memo.put(serializedNode, node);

        String leftSerialized = traverse(node.left, duplicates);
        String rightSerialized = traverse(node.right, duplicates);

        // check for duplicate subtrees
        if (leftSerialized.equals("#") && rightSerialized.equals("#")) {
            TreeNode duplicateRoot = memo.get(serializedNode);

            if (!duplicates.contains(duplicateRoot)) {
                duplicates.add(duplicateRoot);
            }
        } else if (leftSerialized.equals(rightSerialized) || 
                   leftSerialized.equals(serializedNode) || 
                   rightSerialized.equals(serializedNode)) {
            TreeNode duplicateRoot = memo.get(serializedNode);

            if (!duplicates.contains(duplicateRoot)) {
                duplicates.add(duplicateRoot);
            }
        }

        return serializedNode;
    }

    private String serialize(TreeNode node) {
        if (node == null)
            return "#";

        return node.val + "," +
               serialize(node.left) + "," +
               serialize(node.right);
    }
}

