public class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    private TreeNode build(int[] nums, int start, int end) {
        if (start > end) {
            return null;
        }

        // Find the index of the maximum value in the current subarray
        int maxIndex = findMax(nums, start, end);

        // Create a new TreeNode with the maximum value as its root
        TreeNode node = new TreeNode(nums[maxIndex]);

        // Recursively build the left subtree on the subarray prefix to the left of the maximum value
        node.left = build(nums, start, maxIndex - 1);

        // Recursively build the right subtree on the subarray suffix to the right of the maximum value
        node.right = build(nums, maxIndex + 1, end);

        return node;
    }

    private int findMax(int[] nums, int start, int end) {
        int maxIndex = start;
        for (int i = start; i <= end; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }
        return maxIndex;
    }
}

