        Employee employee = new Employee();
        employee.id = id;
        employee.importance = importance;
        employee.subordinates = subordinates;
        employeeMap.put(id, employee);
    }

    public int getImportance(List<Employee> employees, int id) {
        for (Employee employee : employees) {
            addEmployee(employee.id, employee.importance, employee.subordinates);
        }

        Employee targetEmployee = employeeMap.get(id);

        if (targetEmployee == null) {
            return 0;
        } else {
            return getImportance(targetEmployee);
        }
    }

    private int getImportance(Employee employee) {
        int importance = employee.importance;

        for (Integer subordinateId : employee.subordinates) {
            Employee subordinate = employeeMap.get(subordinateId);

            if (subordinate != null) {
                importance += getImportance(subordinate);
            }
        }

        return importance;
    }
}

