public class Solution {
    public int minSteps(int n) {
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                dp[i] = Math.min(dp[i], dp[i / 2] + 1);
            }

            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    int k = i - j;
                    dp[i] = Math.min(dp[i], dp[j] + dp[k]);
                }
            }
        }

        return dp[n];
    }
}

