            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0 && dp[j] != Integer.MAX_VALUE) {
                    dp[i] = Math.min(dp[i], dp[j] + 1 + (j * j != i ? 1 : 0));
                }
            }
        }

        return dp[n];
    }
}

