public class Solution {
    private int[] memo;

    public int minSteps(int n) {
        memo = new int[n + 1];
        for (int i = 0; i <= n; ++i)
            memo[i] = -1;

        return dp(1, n);
    }

    private int dp(int curr, int target) {
        if (curr == target)
            return 0;
        if (memo[curr] != -1)
            return memo[curr];

        for (int i = 2; curr * i <= target; ++i) {
            int temp = dp(i, target / i) + 1;
            if ((target % i == 0) && (temp < memo[curr]))
                memo[curr] = temp;
        }

        return memo[curr];
    }
}

