public class Solution {
    public int minSteps(int n) {
        // Initialize a dp array of size n+1, all initialized as 0.
        int[] dp = new int[n + 1];

        // The minimum number of operations to get 'A' exactly i times on the screen.
        for (int i = 2; i <= n; i++) {
            if (i % 2 != 0) {
                // If i is odd, then we must have i-1 as a multiple of 2. So we can copy 
                // i-1 and paste once to get i.
                dp[i] = dp[i - 1] + 1;
            } else {
                int j = 2;
                while (j <= Math.sqrt(i)) {
                    if (i % j == 0) {
                        // If we can divide i by a factor, then we can copy 'A' exactly that 
                        // factor times and paste the remaining to get i.
                        int k = i / j;
                        dp[i] = Math.min(dp[Math.max(k - 1, 0)] + dp[j], dp[i]);
                    }
                    j++;
                }
            }
        }

        return dp[n];
    }
}

