public class Solution {
    public String solveEquation(String equation) {
        int xPlus = 0;
        int xMinus = 0;
        int constant = 0;

        // Split the equation into parts based on '+', '-', '=' signs
        boolean equalsFound = false;
        for (int i = 0; i < equation.length(); i++) {
            char c = equation.charAt(i);

            if (c == '=') {
                equalsFound = true;
            } else if (!Character.isDigit(c) && !Character.isLetter(c)) {
                // If we encounter a '+' or '-' sign, update xPlus and xMinus accordingly
                if (i > 0 && c == '+') {
                    int coefficient = getNumber(equation, i - 1);
                    xPlus += coefficient;
                } else if (i > 0 && c == '-') {
                    int coefficient = getNumber(equation, i - 1);
                    xMinus -= coefficient;
                }
            } else if (equalsFound) {
                // If we encounter a number after the '=' sign, update constant accordingly
                int num = getNumber(equation, i);
                constant += num;
            }
        }

        // Calculate the result based on the values of xPlus, xMinus, and constant
        if (xPlus == xMinus && constant == 0) {
            return "Infinite solutions";
        } else if ((constant - xMinus) % (xPlus - xMinus) != 0) {
            return "No solution";
        } else {
            int result = (constant - xMinus) / (xPlus - xMinus);
            return "x=" + result;
        }
    }

    private int getNumber(String equation, int index) {
        int num = 0;
        while (index < equation.length() && Character.isDigit(equation.charAt(index))) {
            num = num * 10 + (equation.charAt(index++) - '0');
        }
        return num;
    }
}

