public class Solution {
    public String solveEquation(String equation) {
        int leftVal = 0;
        int rightVal = 0;
        boolean sign = true;

        // Parse the left side of the equation
        int i = 0;
        while (i < equation.length()) {
            if (equation.charAt(i) == '+') {
                sign = true;
                ++i;
            } else if (equation.charAt(i) == '-') {
                sign = false;
                ++i;
            } else if (Character.isDigit(equation.charAt(i))) {
                int num = 0;
                while (i < equation.length() && Character.isDigit(equation.charAt(i))) {
                    num = num * 10 + equation.charAt(i++) - '0';
                }
                leftVal += sign ? num : -num;
            } else if (equation.charAt(i) == 'x') {
                leftVal += sign ? 1 : -1;
                ++i;
            }
        }

        // Parse the right side of the equation
        i = equation.length() - 1;
        while (i >= 0) {
            if (equation.charAt(i) == '+') {
                sign = true;
                --i;
            } else if (equation.charAt(i) == '-') {
                sign = false;
                --i;
            } else if (Character.isDigit(equation.charAt(i))) {
                int num = 0;
                while (i >= 0 && Character.isDigit(equation.charAt(i))) {
                    num = num * 10 + equation.charAt(i--) - '0';
                }
                rightVal += sign ? num : -num;
            } else if (equation.charAt(i) == 'x') {
                rightVal += sign ? 1 : -1;
                --i;
            }
        }

        // Solve the equation
        int leftCoeff = leftVal;
        int leftConst = 0;
        int rightCoeff = rightVal;
        int rightConst = 0;

        // Separate coefficients and constants from both sides
        while (true) {
            if (leftCoeff == 1 && leftConst == 0) break;
            else if (rightCoeff == -1 && rightConst == 0) break;
            else if (leftCoeff < 0 || rightCoeff > 0) break;

            // Subtract the smaller coefficient and constant from both sides
            int minCoeff = Math.min(leftCoeff, rightCoeff);
            leftCoeff -= minCoeff;
            leftConst -= minCoeff * leftVal;
            rightCoeff += minCoeff;
            rightConst += minCoeff * rightVal;
        }

        // Check for infinite solutions and no solution cases
        if (rightCoeff == 0 && rightConst != 0) return "No solution";
        else if (leftCoeff == 0 && leftConst != 0) return "Infinite solutions";

        // Solve the equation, x = C / B
        int x = leftConst - rightConst;
        if (x % leftCoeff != 0) return "No solution";

        // Return the value of 'x' in the form of a string
        return "x=" + (x / leftCoeff);
    }
}

