public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;

        // Find the first parent for each node
        Map<Integer, List<Integer>> parents = new HashMap<>();
        boolean hasTwoParents = false;
        int[] twoParentNode = null;
        int[] twoParentEdge = null;
        for (int[] edge : edges) {
            if (!parents.containsKey(edge[1])) {
                parents.put(edge[1], new ArrayList<>());
            }
            parents.get(edge[1]).add(edge[0]);
            if (parents.get(edge[1]).size() > 1) {
                hasTwoParents = true;
                twoParentNode = edge[1];
                twoParentEdge = edge;
            }
        }

        // If there is a node with two parents, try to remove the last one
        if (hasTwoParents) {
            int[] result = new int[]{twoParentNode, twoParentEdge[0]};
            return result;
        }

        // Union-Find algorithm to detect cycle
        boolean[] parent = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            parent[i] = true;
        }
        int[] rank = new int[n + 1];

        for (int[] edge : edges) {
            if (!hasCycle(edge[0], edge[1], parent, rank)) {
                return edge;
            }
        }

        // If no cycle is found, the last edge must be removed
        return twoParentEdge;
    }

    private boolean hasCycle(int node, int parent, boolean[] parentArray, int[] rank) {
        if (parent == node) {
            return false;
        }
        if (!parentArray[node]) {
            parentArray[node] = true;
            return false;
        }
        if (rank[node] < rank[parent]) {
            return false;
        }
        if (rank[node] > rank[parent]) {
            rank[parent]++;
        }
        rank[node] = parent;
        return true;
    }
}

