public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        List<int[]> parentOfChild = new ArrayList<>();
        List<int[]> duplicateParent = new ArrayList<>();

        // Step 1: Find the first redundant edge
        for (int i = 0; i < n; i++) {
            if (edges[i].length == 2) {
                int child = edges[i][1];
                int parent1 = edges[i][0];

                boolean foundChildWithDifferentParent = false;
                for (int j = 0; j < n; j++) {
                    if (j != i && edges[j].length == 2
                            && edges[j][1] == child) {
                        int parent2 = edges[j][0];
                        if (!parent1.equals(parent2)) {
                            foundChildWithDifferentParent = true;
                        }
                    }
                }

                if (foundChildWithDifferentParent) {
                    duplicateParent.add(new int[]{child, parent1});
                    for (int[] edge : edges) {
                        if (edge[0] == child && !Arrays.equals(edge, edges[i])) {
                            parentOfChild.add(edge);
                        }
                    }
                    break;
                } else {
                    parentOfChild.add(edges[i]);
                }
            }
        }

        // Step 2: Find the cycle
        boolean[] visited = new boolean[n + 1];
        int[] indegree = new int[n + 1];

        for (int i = 0; i < n; i++) {
            if (edges[i].length == 2) {
                indegree[edges[i][0]]++;
            }
        }

        List<int[]> cycle = new ArrayList<>();
        boolean foundRedundantEdge = false;
        for (int[] edge : parentOfChild) {
            int child = edge[1];
            if (!visited[child]) {
                Queue<Integer> queue = new LinkedList<>();
                queue.add(child);
                visited[child] = true;

                while (!queue.isEmpty()) {
                    int node = queue.poll();
                    cycle.add(edge);

                    for (int[] e : edges) {
                        if (e.length == 2 && !Arrays.equals(e, edge)
                                && e[0] == node) {
                            indegree[e[1]]--;
                            if (!visited[e[1]]) {
                                visited[e[1]] = true;
                                queue.add(e[1]);
                            }
                        }
                    }
                }

                int parentNode = 0;
                for (int[] edge : edges) {
                    if (edge.length == 2 && !Arrays.equals(edge, edge)
                            && edge[0] != child
                            && indegree[edge[0]] <= 0) {
                        parentNode = edge[0];
                        break;
                    }
                }

                cycle.add(new int[]{child, parentNode});
                foundRedundantEdge = true;
                break;
            }
        }

        // Step 3: Return the redundant edge
        if (foundRedundantEdge) {
            return cycle.get(cycle.size() - 1);
        } else if (!duplicateParent.isEmpty()) {
            for (int[] edge : edges) {
                if (Arrays.equals(edge, duplicateParent.get(0))) {
                    return edge;
                }
            }
        }

        // If no redundant edge is found
        return new int[]{};
    }
}

