    public int[] findRedundantDirectedConnection(int[][] edges) {
        n = edges.length + 1;
        graph = new List[n];
        for (int i = 0; i < n; ++i)
            graph[i] = new ArrayList<>();

        tempGraph = Arrays.copyOf(graph, n);

        int[] parent = findParents(edges);
        if (parent[0] != -1) {
            return parent;
        }

        Arrays.fill(visited, false);
        for (int i = 0; i < edges.length && !foundCycleSet.contains(Arrays.asList(parent))); ++i
        {
            List<Integer> currEdge = new ArrayList<>(Arrays.asList(edges[i][0], edges[i][1]));
            graph[edges[i][0]].add(edges[i][1]);
            boolean hasCycle = dfs(edges[i][0]);
            if (hasCycle) {
                foundCycleSet.add(currEdge);
            } else
            {
                // reset the tempGraph for next edge
                graph = Arrays.copyOf(tempGraph, n);
            }
        }

        int[] ans = null;
        for (int i = 0; i < edges.length && !foundCycleSet.contains(Arrays.asList(1, parent[1])); ++i)
        {
            List<Integer> currEdge = new ArrayList<>(Arrays.asList(edges[i][0], edges[i][1]));
            if (!graph[edges[i][0]].contains(edges[i][1]))
                continue;
            graph = Arrays.copyOf(tempGraph, n);
            boolean hasCycle = dfs(edges[i][0]);
            if (hasCycle) {
                ans = currEdge.stream().mapToInt(x -> x).toArray();
                break;
            }
        }

        return ans;
    }

    boolean dfs(int v) {
        visited[v] = true;

        for (int u : graph[v]) {
            if (!visited[u]) {
                if (dfs(u)) return true;
            } else if (u != 1 && !foundCycleSet.contains(Arrays.asList(v, u))) {
                foundCycleSet.add(Arrays.asList(v, u));
                return true;
            }
        }

        return false;
    }

    int[] findParents(int[][] edges) {
        n = edges.length + 1;
        int parent[] = new int[n];
        Arrays.fill(parent, -1);
        for (int i = 0; i < edges.length; ++i)
        {
            if (parent[edges[i][1]] != -1) return new int[]{parent[edges[i][1]], edges[i][1]};
            parent[edges[i][1]] = edges[i][0];
        }
        return parent;
    }
