    public int[] findErrorNums(int[] nums) {
        int n = nums.length;
        boolean[] visited = new boolean[n + 1];
        int duplicate = 0, missing = 0;

        // Find duplicate number
        for (int num : nums) {
            if (visited[num]) {
                duplicate = num;
            }
            visited[num] = true;
        }

        // Find missing number
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                missing = i;
                break;
            }
        }

        return new int[] {duplicate, missing};
    }
}

