import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int[] findErrorNums(int[] nums) {
        Set<Integer> set = new HashSet<>();

        for (int num : nums) {
            if (!set.add(num)) {
                // If the number is already in the set, it's a duplicate
                return new int[]{num, getMissingNumber(nums.length, num)};
            }
        }

        return new int[]{-1, -1}; // Return an empty array if no duplicates or missing numbers are found
    }

    private int getMissingNumber(int n, int duplicate) {
        int sum = (n + 1) * n / 2;
        return sum - duplicate;
    }
}

