        // count occurrences of each task
        for (char task : tasks) {
            taskCount.put(task, taskCount.getOrDefault(task, 0) + 1);
        }

        // find maximum count and total load
        int maxCount = 0;
        int totalLoad = 0;

        for (int count : taskCount.values()) {
            if (count > maxCount) {
                maxCount = count;
            }

            totalLoad += count - 1; // subtract 1 because we don't need to idle for the last occurrence of each task
