public class Solution {
    public int repeatedStringMatch(String a, String b) {
        StringBuilder builder = new StringBuilder();

        // Append string a to the builder until we have enough characters in 'builder' 
        // to check if 'b' is a substring of it.
        while (builder.length() < b.length()) {
            builder.append(a);

            // Check if 'b' is a substring of the current 'builder'.
            if (builder.toString().contains(b)) {
                return 1;
            }

            // If not, append string a again and repeat the check.
            builder.append(a);
        }

        // Now 'builder' contains at least as many characters as 'b'. Check one last time 
        // to see if we can find 'b' in 'a'.
        if (builder.toString().contains(b)) {
            return 1;
        }

        // If not, check if 'b' is a substring of 'a' repeated once.
        while (!builder.toString().contains(b)) {
            builder.append(a);

            // Check again
            if (builder.toString().contains(b)) {
                break;
            }
        }

        // If we can't find 'b', it's impossible to repeat string a so that string b is 
        // a substring of it. Return -1.
        return -1;
    }    
}

