import com_github_leetcode.TreeNode;

public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        double min = Double.POSITIVE_INFINITY;
        double secondMin = Double.POSITIVE_INFINITY;

        traverse(root, min, secondMin);

        if (secondMin == Double.POSITIVE_INFINITY)
            return -1;
        else
            return (int) secondMin;
    }

    private void traverse(TreeNode node, double min, double secondMin) {
        if (node == null)
            return;

        if (node.val < min) {
            secondMin = min;
            min = node.val;
        } else if (node.val < secondMin && node.val != min)
            secondMin = node.val;

        traverse(node.left, min, secondMin);
        traverse(node.right, min, secondMin);
    }
}

