import com.github.leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        if (root == null || (root.left == null && root.right == null)) return -1;

        PriorityQueue<Integer> queue = new PriorityQueue<>();
        Set<Integer> set = new HashSet<>();

        dfs(root, queue, set);

        int secondMin = Integer.MAX_VALUE;
        for (int value : set) {
            if (value != root.val && value < secondMin) {
                secondMin = value;
            }
        }

        return secondMin == Integer.MAX_VALUE ? -1 : secondMin;
    }

    private void dfs(TreeNode node, PriorityQueue<Integer> queue, Set<Integer> set) {
        queue.offer(node.val);
        set.add(node.val);

        if (node.left != null && node.right != null) {
            int left = node.left.val;
            int right = node.right.val;

            if (left < node.val && !set.contains(left)) {
                dfs(node.left, queue, set);
            }

            if (right < node.val && !set.contains(right)) {
                dfs(node.right, queue, set);
            }
        } else if (node.left != null) {
            int left = node.left.val;
            if (left < node.val && !set.contains(left)) {
                dfs(node.left, queue, set);
            }
        } else if (node.right != null) {
            int right = node.right.val;
            if (right < node.val && !set.contains(right)) {
                dfs(node.right, queue, set);
            }
        }
    }
}

