public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        long min = Long.MAX_VALUE;
        long secondMin = Long.MAX_VALUE;

        dfs(root, -1, min, secondMin);

        if (secondMin == Long.MAX_VALUE)
            return -1;
        else
            return (int) secondMin;
    }

    private void dfs(TreeNode node, long parentValue, long min, long secondMin) {
        if (node == null)
            return;

        if (parentValue != -1 && node.val >= parentValue) {
            if (secondMin == Long.MAX_VALUE || node.val < secondMin)
                secondMin = node.val;
        } else
            min = Math.min(min, node.val);

        dfs(node.left, node.val, min, secondMin);
        dfs(node.right, node.val, min, secondMin);
    }
}

