public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        long[] min = new long[2];
        dfs(root, min);
        return (int)(min[1] == Long.MAX_VALUE ? -1 : min[1]);
    }

    private long dfs(TreeNode node, long[] min) {
        if(node == null || node.val >= min[0]) {
            return Long.MAX_VALUE;
        }
        min[1] = Math.min(min[1], (long)node.val);
        return Math.min(dfs(node.left, min), dfs(node.right, min));
    }
}

