public class Solution {
    public double knightProbability(int n, int k, int row, int column) {
        long[][][] dp = new long[n][n][k + 1];
        dp[row][column][0] = 1;

        int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};

        for (int i = 0; i < k; i++) {
            int[][] temp = new int[n][n];

            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (dp[x][y][i] == 0) continue;

                    for (int[] move : moves) {
                        int newX = x + move[0];
                        int newY = y + move[1];

                        if (newX >= 0 && newX < n && newY >= 0 && newY < n) {
                            temp[newX][newY] += dp[x][y][i];
                        }
                    }
                }
            }

            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (temp[x][y] > 0) {
                        dp[x][y][i + 1] = temp[x][y];
                    }
                }
            }
        }

        double total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dp[i][j][k] > 0) {
                    total += dp[i][j][k];
                }
            }
        }

        return total / Math.pow(n * n, k);
    }
}

