public class Solution {
    public double knightProbability(int n, int k, int row, int column) {
        // Create a memoization table
        double[][][] dp = new double[n][n][k + 1];

        // Initialize the base case (0 moves)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == row && j == column) {
                    dp[i][j][0] = 1;
                }
            }
        }

        // Calculate the probability of remaining on the board after k moves
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int move = 1; move <= k; move++) {
                    if (i >= 0 && i < n && j >= 0 && j < n) {
                        // Calculate the probability of moving to each adjacent cell
                        for (int[] dir : new int[][]{{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}}) {
                            int newRow = i + dir[0];
                            int newCol = j + dir[1];

                            // Update the memoization table
                            dp[i][j][move] += (dp[newRow][newCol][move - 1] * 0.125);
                        }
                    }
                }
            }
        }

        // Return the probability of remaining on the board after k moves
        return dp[row][column][k];
    }
