    public double knightProbability(int n, int k, int row, int column) {
        // Ensure that the starting cell and the number of moves are valid.
        if (k < 0 || row < 0 || column < 0 || row >= n || column >= n) {
            return 0.0;
        }

        // Initialize a memoization table to store the probabilities for each cell.
        double[][][] memo = new double[n][n][k + 1];

        // Initialize the probability of staying on the board after k moves.
        double result = knightProbability(n, k, row, column, memo);

        return result;
    }

    private double knightProbability(int n, int k, int row, int column, double[][][] memo) {
        // If there are no more moves left, return 1.0 as the probability of staying on the board.
        if (k == 0) {
            return 1.0;
        }

        // Ensure that the current cell and the number of remaining moves are valid.
        if (row < 0 || column < 0 || row >= n || column >= n) {
            return 0.0;
        }

        // If the probability for the current cell and number of remaining moves is already calculated, return it.
        if (memo[row][column][k] != 0.0) {
            return memo[row][column][k];
        }

        // Calculate the probabilities of moving to neighboring cells.
        double totalProbability = 0.0;
        int[] dr = {-2, -2, -1, -1, 1, 1, 2, 2};
        int[] dc = {-1, 1, -2, 2, -2, 2, -1, 1};

        for (int i = 0; i < 8; ++i) {
            totalProbability += knightProbability(n, k - 1, row + dr[i], column + dc[i], memo);
        }

        // Store the calculated probability and return it.
        memo[row][column][k] = totalProbability / 8.0;
        return memo[row][column][k];
    }
}

