        }

        while (!countMap.isEmpty()) {
            boolean foundSubsequence = false;

            // Try to find a subsequence of length 3 or more
            Map<Integer, Integer> newCountMap = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
                int num = entry.getKey();
                int freq = entry.getValue();

                if (freq >= 2) {
                    // Try to find a subsequence of length 3 or more
                    int nextNum = num + 1;
                    while (countMap.containsKey(nextNum)) {
                        newCountMap.put(nextNum, newCountMap.getOrDefault(nextNum, 0) + 1);
                        freq -= 2;
                        if (freq == 0) break;
                        nextNum++;
                    }

                    // If a subsequence of length 3 or more is found, remove it from the count map
                    if (newCountMap.containsKey(num)) {
                        newCountMap.put(num, newCountMap.get(num) - 1);
                        if (newCountMap.get(num) == 0) newCountMap.remove(num);
                        foundSubsequence = true;
                    }
                } else if (freq >= 3) {
                    // If a subsequence of length 3 or more is found, remove it from the count map
                    int nextNum = num + 1;
                    while (countMap.containsKey(nextNum)) {
                        newCountMap.put(nextNum, newCountMap.getOrDefault(nextNum, 0) + 1);
                        freq -= 3;
                        if (freq == 0) break;
                        nextNum++;
                    }

