// #Medium #Array #Hash_Table #Greedy #Heap_Priority_Queue
// #2022_03_21_Time_4_ms_(95.88%)_Space_72.5_MB_(21.48%)
public class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();

        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        while (!countMap.isEmpty()) {
            int key = getMinKey(countMap);

            if (key == -1) {
                return false;
            }

            int count = countMap.get(key);
            if (count < 3) {
                return false;
            }

            int nextNum = key + 2;
            int nextCount = countMap.getOrDefault(nextNum, 0);
            if (nextCount == 0) {
                // split the current number into two subsequences
                countMap.put(key, count - 1);
                countMap.put(key + 1, countMap.getOrDefault(key + 1, 0) + 1);
                countMap.put(nextNum, nextCount + 3);
            } else if (nextCount < 2) {
                // split the current number into two subsequences
                countMap.put(key, count - 1);
                countMap.put(key + 1, countMap.getOrDefault(key + 1, 0) + 1);
                int remaining = 3 - nextCount;
                countMap.put(nextNum, nextCount + remaining);
            } else {
                // merge the current number into one subsequence
                countMap.put(nextNum, nextCount + 2);
                countMap.remove(key);
                countMap.remove(key + 1);
            }
        }

        return true;
    }

    private int getMinKey(Map<Integer, Integer> map) {
        int min = Integer.MAX_VALUE;
        for (int key : map.keySet()) {
            if (key < min) {
                min = key;
            }
        }
        if (min == Integer.MAX_VALUE) {
            return -1; // all numbers are used up
        }
        return min;
    }
}

