// #2022_03_21_Time_4_ms_(95.88%)_Space_72.5_MB_(21.48%)
public class Solution {
    public boolean isPossible(int[] nums) {
        int n = nums.length;
        if (n < 3) return false;

        // Count the frequency of each number
        int[] freq = new int[n + 1];
        for (int num : nums) {
            freq[num]++;
        }

        for (int num : nums) {
            // If current number is a start of subsequence
            if (freq[num] > 0) {
                // Check if we can form subsequences of length 3, 4 or more
                int nextNum = num + 1;
                int currFreq = freq[num];

                while (currFreq >= 2 && freq[nextNum] > 0) {
                    // If current number and next number is available, consume one from each
                    if (freq[nextNum] == 1) {
                        freq[nextNum]--;
                        break;
                    }

                    freq[nextNum]--;
                    currFreq -= 2;

                    nextNum++;
                }

                // Check for remaining numbers which can be part of a subsequence of length 3 or more
                while (currFreq >= 2 && freq[nextNum] > 0) {
                    if (freq[nextNum] == 1) break;
                    freq[nextNum]--;
                    currFreq -= 2;

                    nextNum++;
                }

                // If we can form subsequences, consume all numbers of current number
                while (currFreq >= 3 && freq[nextNum] > 0) {
                    if (freq[nextNum] == 1) break;
                    freq[nextNum]--;
                    currFreq -= 3;

                    nextNum++;
                }

                // If we can't form subsequences, return false
                if (nextNum - num < currFreq + 2 || freq[nextNum] > 0) {
                    return false;
                }
            }
        }

        // If no number is left and all numbers were consumed in a subsequence of length 3 or more
        return true;
    }
}

