public class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }

        for (int num : nums) {
            int count = map.get(num);
            if (count == 0) continue;

            int nextNum = num + 1;
            while (map.containsKey(nextNum)) {
                int tempCount = map.get(nextNum);
                if (tempCount >= 2 && !canBeSplit(map, nextNum, nextNum + 1)) return false;

                map.put(nextNum, tempCount - 1);
                nextNum += 1;
            }

            if (!canBeSplit(map, num, nextNum)) return false;

            map.put(num, count - 1);
        }

        return true;
    }

    private boolean canBeSplit(Map<Integer, Integer> map, int startNum, int endNum) {
        int count = map.getOrDefault(startNum, 0) + map.getOrDefault(endNum, 0);
        if (count < 3) return false;

        int tempCount = map.getOrDefault(endNum, 0);
        for (int i = startNum; i <= endNum; i++) {
            while (map.containsKey(i)) {
                if (!canBeSplit(map, i + 1, endNum)) return false;

                count -= map.get(i) == tempCount ? 1 : map.get(i);
                tempCount = Math.min(tempCount - 1, map.get(i));
                i++;
            }
        }

        return true;
    }
}

