public class Solution {
    public String predictPartyVictory(String senate) {
        Queue<Integer> radiant = new LinkedList<>();
        Queue<Integer> dire = new LinkedList<>();

        for (int i = 0; i < senate.length(); i++) {
            if (senate.charAt(i) == 'R') {
                radiant.offer(i);
            } else {
                dire.offer(i);
            }
        }

        while (!radiant.isEmpty() && !dire.isEmpty()) {
            int rIndex = radiant.peek();
            int dIndex = dire.peek();

            if (rIndex < dIndex) {
                radiant.poll();
            } else {
                dire.poll();
            }

            if (!radiant.isEmpty() && !dire.isEmpty()) {
                int nextRIndex = senate.charAt(radiant.peek()) == 'R' ? rIndex + 1 : Integer.MAX_VALUE;
                int nextDIndex = senate.charAt(dire.peek()) == 'D' ? dIndex + 1 : Integer.MAX_VALUE;

                if (nextRIndex < nextDIndex) {
                    radiant.offer(nextRIndex);
                } else {
                    dire.offer(nextDIndex);
                }
            }
        }

        return radiant.isEmpty() ? "Dire" : "Radiant";
    }
