public class Solution {
    public int findShortestSubArray(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        Map<Integer, Integer> firstOccurrenceMap = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            if (!firstOccurrenceMap.containsKey(nums[i])) {
                firstOccurrenceMap.put(nums[i], i);
            }
            countMap.put(nums[i], countMap.getOrDefault(nums[i], 0) + 1);
        }

        int maxCount = 0;
        for (int num : countMap.keySet()) {
            maxCount = Math.max(maxCount, countMap.get(num));
        }

        int minLen = nums.length;
        for (int num : countMap.keySet()) {
            if (countMap.get(num) == maxCount) {
                minLen = Math.min(minLen, i - firstOccurrenceMap.get(num) + 1);
            }
        }

        return minLen;
    }
}

