public class Solution {
    public int[] smallestRange(List<int[]> nums) {
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> a.val - b.val);

        for (int i = 0; i < nums.size(); i++) {
            Node node = new Node(nums.get(i)[0], i, 0);
            pq.offer(node);
        }

        int minDiff = Integer.MAX_VALUE;
        int[] result = {-1,-1};

        while (!pq.isEmpty()) {
            PriorityQueue<Node> tempPq = new PriorityQueue<>((a, b) -> a.val - b.val);

            Node node = pq.poll();
            if (node.num == nums.size() - 1 && node.idx == nums.get(node.num).length - 1) {
                int[] range = {node.val, node.val + minDiff};
                result[0] = Math.min(result[0], range[0]);
                result[1] = Math.max(result[1], range[1]);
            }

            if (tempPq.size() == nums.size()) break;

            Node nextNode;
            if (node.idx < nums.get(node.num).length - 1) {
                nextNode = new Node(nums.get(node.num)[node.idx + 1], node.num, node.idx + 1);
            } else {
                nextNode = null;
            }

            while (!pq.isEmpty() && nextNode != null) {
                if (nextNode.val < pq.peek().val) {
                    tempPq.offer(pq.poll());
                } else {
                    break;
                }
            }

            if (nextNode != null) {
                pq.offer(nextNode);
            }

            while (!tempPq.isEmpty()) {
                Node nodeToOffer = tempPq.poll();
                if (nodeToOffer.idx == nums.get(nodeToOffer.num).length - 1) {
                    int diff = nodeToOffer.val - node.val;
                    minDiff = Math.min(minDiff, diff);
                } else {
                    pq.offer(new Node(nums.get(nodeToOffer.num)[nodeToOffer.idx + 1], nodeToOffer.num, nodeToOffer.idx + 1));
                }
            }
        }

