            this.val = val;
            this.num = num;
            this.idx = idx;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Node)) return false;
            Node node = (Node) o;
            return val == node.val &&
                    num == node.num &&
                    idx == node.idx;
        }

        @Override
        public int hashCode() {
            return Objects.hash(val, num, idx);
        }
    }
}

