    }

    private int dfs(int[] price, int[][] specials, List<Integer> needs) {
        int n = needs.size();
        if (n == 0) {
            return 0;
        }
        int minPrice = 0;
        for (int i = 0; i < n; i++) {
            minPrice += needs.get(i) * price[i];
        }

        for (int[] special : specials) {
            boolean isValid = true;
            List<Integer> newNeeds = new ArrayList<>(needs);
            int offerPrice = special[special.length - 1];

            for (int j = 0; j < n; j++) {
                if (newNeeds.get(j) > special[j]) {
                    isValid = false;
                    break;
                }
                newNeeds.set(j, newNeeds.get(j) - special[j]);
            }

            if (!isValid) {
                continue;
            }

            int newPrice = offerPrice + dfs(price, specials, newNeeds);
            minPrice = Math.min(minPrice, newPrice);
        }

        return minPrice;
    }
}

