public class Solution {
    public int shoppingOffers(int[] price, int[] special, List<List<Integer>> needs) {
        Map<String, Integer> memo = new HashMap<>();
        return helper(price, special, needs, 0, memo);
    }

    private int helper(int[] price, int[] special, List<List<Integer>> needs, int idx, Map<String, Integer> memo) {
        String key = Arrays.toString(needs) + "_" + idx;
        if (memo.containsKey(key)) return memo.get(key);

        int totalCost = 0;
        for (int i = 0; i < price.length; i++) {
            totalCost += needs.get(i).get(0) * price[i];
        }

        boolean isSpecialUsed = false;
        for (int i = idx; i < special.length; i++) {
            if (!isPossible(needs, special[i])) continue;

            List<List<Integer>> newNeeds = new ArrayList<>();
            for (int j = 0; j < needs.size(); j++) {
                int count = Math.min(special[i][j], needs.get(j).get(0));
                newNeeds.add(new ArrayList<>(Arrays.asList(count)));
            }

            isSpecialUsed = true;
            totalCost = Math.min(totalCost, special[i][needs.size()] + helper(price, special, newNeeds, i + 1, memo));
        }

        if (!isSpecialUsed) {
            return totalCost;
        } else {
            memo.put(key, totalCost);
            return totalCost;
        }
    }

    private boolean isPossible(List<List<Integer>> needs, int[] specialArr) {
        for (int i = 0; i < specialArr.length - 1; i++) {
            if (specialArr[i] > needs.get(i).get(0)) return false;
        }
        return true;
    }
}

