// #Medium #Array #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask #Memoization
// #2022_03_21_Time_6_ms_(71.06%)_Space_42.6_MB_(71.63%)
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int shoppingOffers(int[] price, int[] special, List<List<Integer>> needs) {
        Map<String, Integer> memo = new HashMap<>();
        return dp(price, special, needs, 0, memo);
    }

    private int dp(int[] price, int[] special, List<List<Integer>> needs, int idx, Map<String, Integer> memo) {
        String key = getNeedsKey(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int ans = 0;
        for (int i = idx; i < special.length; i++) {
            // skip the offer
            if (i > idx && isOfferValid(special, price, needs)) continue;

            List<List<Integer>> newNeeds = cloneAndModify(needs);
            boolean offerCanBeApplied = canApplyOffer(special[i], newNeeds);
            if (offerCanBeApplied) {
                // apply the offer
                int cost = special[i] - calculateCost(price, newNeeds);
                ans = Math.min(ans, dp(price, special, newNeeds, i + 1, memo));
                ans = Math.min(ans, cost);
            } else {
                // not apply the offer
                ans = Math.min(ans, price[0] * needs.get(0).get(0) + dp(price, special, newNeeds, i + 1, memo));
            }
        }

        memo.put(key, ans);
        return ans;
    }

    private int calculateCost(int[] price, List<List<Integer>> needs) {
        int cost = 0;
        for (int i = 0; i < needs.size(); i++) {
            cost += price[i] * needs.get(i).get(0);
        }
        return cost;
    }

    private boolean canApplyOffer(int[] offer, List<List<Integer>> needs) {
        for (int i = 0; i < offer.length - 1; ++i) {
            if (offer[i] > needs.get(i).get(0)) return false;
        }
        return true;
    }

    private boolean isOfferValid(int[] special, int[] price, List<List<Integer>> needs) {
        for (int i = 0; i < special.length - 1; ++i) {
            if (special[i] > needs.get(i).get(0)) return false;
        }
        return true;
    }

    private String getNeedsKey(List<List<Integer>> needs) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < needs.size(); i++) {
            sb.append(needs.get(i).get(0));
        }
        return sb.toString();
    }

    private List<List<Integer>> cloneAndModify(List<List<Integer>> needs) {
        List<List<Integer>> clonedNeeds = new ArrayList<>();
        for (int i = 0; i < needs.size(); ++i) {
            List<Integer> clonedList = new ArrayList<>(needs.get(i));
            clonedNeeds.add(clonedList);
            clonedList.set(0, clonedList.get(0) - 1);
        }
        return clonedNeeds;
