public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum % k != 0) { // If the sum of all numbers is not divisible by k
            return false;
        }

        int target = totalSum / k; // Calculate the sum of each subset

        Arrays.sort(nums); // Sort the array in ascending order
        Map<Integer, Boolean> used = new HashMap<>(); // To record which subsets are used
        boolean result = dfs(nums, new int[k], 0, target, used);

        return result;
    }

    private boolean dfs(int[] nums, int[] currentSubset, int index, int target, Map<Integer, Boolean> used) {
        if (index == nums.length) { // If all numbers are processed
            for (int num : currentSubset) {
                if (num != target) {
                    return false;
                }
            }
            return true;
        }

        for (int i = 0; i < currentSubset.length; i++) {
            if (!used.containsKey(i)) { // If the subset is not used
                currentSubset[i] += nums[index];
                if (currentSubset[i] <= target) { 
                    if (dfs(nums, currentSubset, index + 1, target, used)) {  
                        return true;
                    }
                    currentSubset[i] -= nums[index]; // Backtrack
                }
                used.put(i, true); // Mark the subset as used
            }
        }

        return false; // If no valid solution is found
    }
}

