public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        // calculate total sum of array
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum % k != 0) return false;  

        int targetSum = totalSum / k;

        Arrays.sort(nums);  
        boolean[] visited = new boolean[nums.length];

        // bitmask to track which subset each number belongs to
        for (int i = 1; i < (1 << nums.length); i++) {
            if (!bitmaskValid(i, nums, targetSum)) continue;
            // check all subsets
            for (int j = 0; j < nums.length; j++) {
                if ((i & (1 << j)) == 0) {
                    if (!subsetSumValid(j, i, nums, visited, targetSum)) break;
                }
            } else {
                return true;
            }
        }

        return false;
    }

    // check bitmask validity
    private boolean bitmaskValid(int bitmask, int[] nums, int targetSum) {
        int cumulativeSum = 0;

        for (int i = 0; i < nums.length; i++) {
            if ((bitmask & (1 << i)) != 0) {
                cumulativeSum += nums[i];
                if (cumulativeSum > targetSum) return false;
            }
        }

        return true;
    }

    // check subset sum validity
    private boolean subsetSumValid(int index, int bitmask, int[] nums, boolean[] visited, int targetSum) {
        if (index == nums.length) return true;

        for (int i = 0; i < nums.length; i++) {
            if (!visited[i] && ((bitmask & (1 << i)) == 0)) {
                visited[i] = true;
                if (nums[index] + targetSum - (targetSum - nums[index]) <= nums[i] || nums[index] >= nums[i])
                    return subsetSumValid(index + 1, bitmask | (1 << i), nums, visited, targetSum);
                visited[i] = false;
            }
        }

        return false;
    }
}

