public class Solution {
    public int[][] imageSmoother(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // Calculate the sum of surrounding cells
                long sum = getSum(matrix, i, j, m, n);

                // Calculate the count of valid surrounding cells
                int count = getCount(matrix, i, j, m, n);

                // Apply smoothing
                result[i][j] = (int) Math.round(sum / count);
            }
        }

        return result;
    }

    private long getSum(int[][] matrix, int x, int y, int m, int n) {
        long sum = 0;

        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int ni = x + i;
                int nj = y + j;

                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                    sum += matrix[ni][nj];
                }
            }
        }

        return sum;
    }

    private int getCount(int[][] matrix, int x, int y, int m, int n) {
        int count = 0;

        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int ni = x + i;
                int nj = y + j;

                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                    count++;
                }
            }
        }

        return count;
    }
}

