import java.util.*;

public class Solution {
    public int[] exclusiveTime(int n, List<String> logs) {
        // Create a stack to store log information
        Deque<LogInfo> stack = new ArrayDeque<>();

        // Initialize a map to store execution times for each function
        Map<Integer, Integer> executionTimes = new HashMap<>();
        Arrays.setAll(executionTimes.values(), ignored -> 0);

        // Iterate over the logs list
        for (String log : logs) {
            String[] parts = log.split(":");
            int functionId = Integer.parseInt(parts[0]);
            String status = parts[1];
            int timestamp = Integer.parseInt(parts[2]);

            // Process 'start' and 'end' statuses separately
            if (status.equals("start")) {
                // If the stack is not empty, add the current execution time for the function at the top of the stack to its overall execution time
                LogInfo logInfo = stack.isEmpty() ? new LogInfo(functionId) : stack.peek();
                if (!stack.isEmpty()) {
                    int previousTimestamp = stack.peek().getPreviousTimestamp();
                    logInfo.setPreviousTimestamp(previousTimestamp);
                    int executionTime = timestamp - previousTimestamp;
                    logInfo.addExecutionTime(executionTime);
                    executionTimes.put(logInfo.getFunctionId(), executionTimes.get(logInfo.getFunctionId()) + executionTime);
                }

                // Push the new log information onto the stack
                stack.push(new LogInfo(functionId));
            } else {
                // If it's an 'end' status, pop the top element from the stack and update its execution time in the map
                LogInfo logInfo = stack.pop();
                int executionTime = timestamp + 1 - logInfo.getPreviousTimestamp();
                executionTimes.put(logInfo.getFunctionId(), executionTimes.get(logInfo.getFunctionId()) + executionTime);
            }
        }

        // Create an array to store exclusive times for each function
        int[] result = new int[n];

        // Calculate the overall execution time and assign it to each function in order of its ID
        int index = 0;
        for (int key : executionTimes.keySet()) {
            result[index++] = executionTimes.get(key);
        }

        return result;
    }

    private static class LogInfo {
        private int functionId;
        private int previousTimestamp;

        public LogInfo(int functionId) {
            this.functionId = functionId;
        }

        public int getFunctionId() {
            return functionId;
        }

        public void setPreviousTimestamp(int previousTimestamp) {
            this.previousTimestamp = previousTimestamp;
        }

        public int getPreviousTimestamp() {
            return previousTimestamp;
        }

        private List<Integer> executionTimes;

        public LogInfo() {
            executionTimes = new ArrayList<>();
        }

        public void addExecutionTime(int executionTime) {
            executionTimes.add(executionTime);
        }
    }
}

