            String[] parts = log.split(":");
            int id = Integer.parseInt(parts[0]);
            String op = parts[1];
            int ts = Integer.parseInt(parts[2]);

            if(op.equals("start")){
                if(preId != null) {
                    res[preId] += ts - preTs;
                }
                stack.push(id);
                preTs = ts;
            } else {
                if(stack.size() > 0){
                    res[stack.peek()] += (ts + 1 - preTs);
                    stack.pop();
                }
                if(preId != null) {
                    res[preId] += ts + 1 - preTs;
                }
                preTs = ts + 1;
            }
            preId = op.equals("start") ? id : null;
        }

        return res;
    }
