// #2022_03_22_Time_3_ms_(79.43%)_Space_68.5_MB_(25.41%)
import com_github_leetcode.TreeNode;

public class Solution {
    int maxPath = 0;

    public int longestUnivaluePath(TreeNode root) {
        if (root == null) return 0;
        if (root.left != null && !isSame(root, root.left)) 
            return 0;
        if (root.right != null && !isSame(root, root.right))
            return 0;

        maxPath = Math.max(maxPath, longestUnivaluePath(root.left));
        maxPath = Math.max(maxPath, longestUnivaluePath(root.right));

        if (root.left == null) 
            return Math.max(1 + longestUnivaluePath(root.left), 1 + longestUnivaluePath(root.right));

        if (isSame(root, root.left)) 
            maxPath = Math.max(maxPath, 2 + longestUnivaluePath(root.left));

        if (isSame(root, root.right)) 
            maxPath = Math.max(maxPath, 2 + longestUnivaluePath(root.right));

        return maxPath;
    }

    public boolean isSame(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;

        return (p.val == q.val);
    }
}

