public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        // Initialize two pointers, one at the start and one at the end of the array.
        int left = 0;
        int right = arr.length - k;

        while (left < right) {
            // Calculate the middle index.
            int mid = left + (right - left) / 2;

            // If the difference between x and the element at the middle index is less than 
            // the difference between x and the element after the middle index, then we know that
            // all elements before the middle index are closer to x than the k closest elements.
            if (x - arr[mid] > arr[mid + k] - x) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        // At this point, we have found the range in which the k closest elements are located. 
        // We can now return these k closest elements by slicing the array.
        List<Integer> result = new ArrayList<>();
        for (int i = left; i < arr.length && i - left < k; i++) {
            result.add(arr[i]);
        }

        // Sort the result in ascending order.
        java.util.Collections.sort(result);

        return result;
    }
}

