        // Find the closest pair of elements in the array
        int start = 0;
        int end = arr.length - k;

        while (start < end) {
            int mid = (start + end) / 2;

            if (x - arr[mid] > arr[mid + k] - x) {
                // If the difference between x and arr[mid] is greater than 
                // the difference between arr[mid+k] and x, then we need to move 
                // our window to the right.
                start = mid + 1;
            } else if (x - arr[mid] < arr[mid + k] - x) {
                // If the difference between x and arr[mid] is less than 
                // the difference between arr[mid+k] and x, then we need to move 
                // our window to the left.
                end = mid;
            } else {
                // If the differences are equal, then we can just add k elements 
                // from the right of mid to our result list.
                for (int i = 0; i < k; i++) {
                    result.add(arr[mid + i]);
                }
                return result;
            }
        }

        // At this point, start and end are equal. So we can just add 
        // elements from arr[start] to arr[start+k-1] to our result list.
        for (int i = 0; i < k; i++) {
            result.add(arr[start + i]);
        }

        return result;
    }
