public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        List<Integer> result = new ArrayList<>();

        // Find the index where elements should be inserted
        int insertIndex = Arrays.binarySearch(arr, x);

        if (insertIndex < 0) {
            insertIndex = -insertIndex - 1;
        }

        // Get elements on both sides of the insertion point
        for (int i = Math.max(0, insertIndex - k); i <= Math.min(insertIndex, arr.length - k); i++) {
            result.add(arr[i]);
        }

        // Sort the list in ascending order
        Collections.sort(result);

        return result;
    }
}

