import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int m = height + 1, n = (1 << (height + 1)) - 1;

        List<List<String>> res = new ArrayList<>();
        for(int i = 0; i < m; i++) {
            List<String> row = new ArrayList<>();
            for(int j = 0; j < n; j++) {
                if(i == 0 && j == (n - 1) / 2) {
                    row.add(root.val + "");
                } else {
                    row.add("");
                }
            }
            res.add(row);
        }

        traverse(res, root, m, n, height);

        return res;
    }

    private void traverse(List<List<String>> res, TreeNode node, int m, int n, int curHeight) {
        if(node == null)  return;

        int r = (m - 1 - curHeight) / 2;
        int c = (n - 1) / 2 + Math.pow(2, curHeight) - 1;
        res.get(r).set(c, node.val + "");

        traverse(res, node.left, m, n, curHeight + 1);
        traverse(res, node.right, m, n, curHeight + 1);
    }

    private int getHeight(TreeNode root){
        if(root == null)  return 0;
        else{
            int left = getHeight(root.left);
            int right = getHeight(root.right);

            if(left > right)
                return left+1;
            else
                return right+1;
        }
    }
}

