            for (int i = 0; i < k / 2 - 1; i++) {
                if (index == n - 1) break;
                result[index++] = --start;
            }
            if (index == n - 1) break;
            result[index++] = ++end;
            k -= 2;
        }

        while (index < n) {
            if (index % 2 != 0) {
                result[index] = start++;
            } else {
                result[index] = end--;
            }
            index++;
        }

