import com.github.leetcode.TreeNode;

public class Solution {
    public TreeNode addOneRow(TreeNode root, int val, int depth) {
        // If the given depth is 1, replace the root node with a new node containing the value 'val'
        if (depth == 1) {
            TreeNode newNode = new TreeNode(val);
            newNode.left = root;
            return newNode;
        }

        // Initialize a queue to hold nodes at each level
        java.util.Queue<TreeNode> queue = new java.util.LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                TreeNode curNode = queue.poll();

                // If the current node is at the given depth - 1, add new nodes with value 'val'
                if (depth - 1 == getDepth(curNode)) {
                    TreeNode leftChild = new TreeNode(val);
                    TreeNode rightChild = new TreeNode(val);

                    leftChild.left = curNode.left;
                    curNode.left = leftChild;

                    rightChild.right = curNode.right;
                    curNode.right = rightChild;
                } else {
                    // Add the children of the current node to the queue for the next level
                    if (curNode.left != null) {
                        queue.offer(curNode.left);
                    }
                    if (curNode.right != null) {
                        queue.offer(curNode.right);
                    }
                }
            }

            // Move to the next level in the tree
            depth--;
        }

        return root;
    }

    private int getDepth(TreeNode node) {
        int depth = 0;
        while (node.parent != null) {
            depth++;
            node = node.parent;
        }
        return depth + 1; // Add 1 because we need to count the current node
    }
}

