public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> wordCount = new HashMap<>();

        // Count frequency of each word
        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }

        // Create a priority queue to store the top K frequent words
        PriorityQueue<Map.Entry<String, Integer>> pq = new PriorityQueue<>(
                (a, b) -> a.getValue().equals(b.getValue())
                        ? a.getKey().compareTo(b.getKey())
                        : b.getValue() - a.getValue()
        );

        for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
            if (pq.size() < k || pq.peek().getValue() < entry.getValue()) {
                // If the queue size is less than K or the current element's frequency
                // is greater than the top of the queue, add it to the queue.
                pq.offer(entry);
            } else {
                // Otherwise, remove the smallest element from the queue (i.e., the top)
                // and add the current element. This ensures that the queue always contains
                // the K most frequent elements in decreasing order of frequency and increasing order of word.
                pq.poll();
                pq.offer(entry);
            }
        }

        // Create a list to store the result
        List<String> result = new ArrayList<>();

        // Poll the queue to get the top K frequent words
        while (!pq.isEmpty()) {
            result.add(pq.poll().getKey());
        }

        // Sort the result in lexicographical order for words with the same frequency
        Collections.sort(result, String.CASE_INSENSITIVE_ORDER);

        return result;
    }
}

