import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.SortedSet;
import java.util.TreeMap;
import java.util.TreeSet;

public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> map = new HashMap<>();
        for (String word : words) {
            if (!map.containsKey(word)) {
                map.put(word, 1);
            } else {
                map.put(word, map.get(word) + 1);
            }
        }

        TreeMap<Integer, TreeSet<String>> treeMap = new TreeMap<>();
        Iterator<Map.Entry<String, Integer>> it = map.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Integer> entry = it.next();
            int freq = entry.getValue();
            if (!treeMap.containsKey(freq)) {
                treeMap.put(freq, new TreeSet<>());
            }
            treeMap.get(freq).add(entry.getKey());
        }

        List<String> result = new ArrayList<>();
        for (int i = map.size(); i >= 1; --i) {
            if (treeMap.containsKey(i)) {
                Iterator<String> it2 = treeMap.get(i).iterator();
                while (it2.hasNext()) {
                    result.add(it2.next());
                    k--;
                    if (k == 0) break;
                }
            }
        }

        return result.subList(0, k);
    }
}

