import com.github.leetcode.TreeNode;

public class Solution {
    public boolean hasPathSum(TreeNode root, int sum) {
        if (root == null) return false;

        // If the current node is a leaf node and its value equals to the remaining sum
        if (root.left == null && root.right == null && root.val == sum) return true;

        // Recursively check whether we can find a path that sums up to the target in either left or right subtree
        if (hasPathSum(root.left, sum - root.val)) return true;
        if (hasPathSum(root.right, sum - root.val)) return true;

        // If we cannot find any path that sums up to the target after traversing both subtrees, return False
        return false;
    }
}

