import com_github_leetcode.TreeNode;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int minDepth(TreeNode root) {
        if (root == null) return 0; // If the tree is empty, its depth is 0

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root); // Add the root node to the queue
        int depth = 1; // Initialize the depth as 1

        while (!queue.isEmpty()) {
            int levelSize = queue.size(); // Get the size of the current level
            for (int i = 0; i < levelSize; i++) {
                TreeNode currentNode = queue.poll(); // Dequeue a node from the front of the queue

                if (currentNode.left == null && currentNode.right == null) { // If it's a leaf node, return its depth
                    return depth;
                }

                if (currentNode.left != null) { // Add its left child to the queue if it exists
                    queue.offer(currentNode.left);
                }
                if (currentNode.right != null) { // Add its right child to the queue if it exists
                    queue.offer(currentNode.right);
                }
            }
            depth++; // Increment the depth after each level
        }

        return depth; // Return the minimum depth of the tree
    }
}

