public class Solution {
    public int maxProfit(int k, int[] prices) {
        if (k == 0 || prices.length < 2) return 0;

        int n = prices.length;
        int[][] dp = new int[n][2];

        for (int i = 1; i < n; i++) {
            int prevProfit = Math.max(dp[i-1][0], dp[i-1][1]);

            if (prices[i] > prices[i-1]) {
                dp[i][1] = Math.max(dp[i][1], prevProfit + prices[i] - prices[i-1]);
            } else {
                dp[i][1] = Math.max(dp[i][1], prevProfit);
            }

            dp[i][0] = Math.max(dp[i][0], dp[i-1][0]);
        }

        return dp[n-1][1];
    }
}

