public class Solution {
    public void rotate(int[] nums, int k) {
        if (nums == null || nums.length < 2 || k == 0) return;

        k %= nums.length; // To handle cases where k is greater than the length of array
        reverse(nums);
        reverse(getSubArray(nums, 0, k));
        reverse(getSubArray(nums, k, nums.length - k));
    }

    private void reverse(int[] arr) {
        int start = 0;
        int end = arr.length - 1;

        while (start < end) {
            // Swap elements
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;

            // Move pointers towards the center of the array
            start++;
            end--;
        }
    }

    private void reverse(int[] arr, int start, int end) {
        while (start < end) {
            // Swap elements
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;

            // Move pointers towards the center of the subarray
            start++;
            end--;
        }
    }

    private int[] getSubArray(int[] nums, int start, int end) {
        return java.util.Arrays.copyOfRange(nums, start, end + 1);
    }
}

