public class Solution {
    public int findPeakElement(int[] nums) {
        int start = 0;
        int end = nums.length - 1;

        while (start < end) {
            int mid = start + (end - start) / 2;

            if (nums[mid] > nums[mid + 1]) {
                // If the middle element is greater than its right neighbor, then
                // the peak must be on the left side of the middle.
                end = mid;
            } else {
                // Otherwise, the peak must be on the right side of the middle.
                start = mid + 1;
            }
        }

        return start;
    }
}

