public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int m = dungeon.length;
        int n = dungeon[0].length;

        // Create a 2D array to store the minimum health required at each cell.
        int[][] dp = new int[m][n];

        // Initialize the last cell of the dp array with the maximum possible value (1).
        dp[m-1][n-1] = Math.max(1, dungeon[m-1][n-1]);

        // Fill up the last row of the dp array.
        for(int i=n-2; i>=0; i--) {
            dp[m-1][i] = Math.max(dp[m-1][i+1]-dungeon[m-1][i], 1);
        }

        // Fill up the last column of the dp array.
        for(int i=m-2; i>=0; i--) {
            dp[i][n-1] = Math.max(dp[i+1][n-1]-dungeon[i][n-1], 1);
        }

        // Fill up the rest of the dp array.
        for(int i=m-2; i>=0; i--) {
            for(int j=n-2; j>=0; j--) {
                dp[i][j] = Math.max(Math.min(dp[i+1][j], dp[i][j+1])-dungeon[i][j], 1);
            }
        }

        // The minimum health required is stored in the top-left cell of the dp array.
        return dp[0][0];
    }
