public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int m = dungeon.length;
        int n = dungeon[0].length;

        // Convert all values to non-negative by subtracting 1 from each value
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (dungeon[i][j] > 0) {
                    dungeon[i][j]--;
                }
            }
        }

        int[][] dp = new int[m][n];

        // Initialize the first cell
        dp[0][0] = Math.max(1, -dungeon[0][0]);

        // Fill in the first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = Math.max(dp[0][j-1] - dungeon[0][j], 1);
        }

        // Fill in the first column
        for (int i = 1; i < m; i++) {
            dp[i][0] = Math.max(dp[i-1][0] - dungeon[i][0], 1);
        }

        // Fill in the rest of the table
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                int max = Math.max(dp[i-1][j] - dungeon[i][j], dp[i][j-1] - dungeon[i][j]);
                dp[i][j] = Math.max(max, 1);
            }
        }

        // The minimum health required is the value in the bottom-right cell
        return dp[m-1][n-1];
