public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int m = dungeon.length;
        int n = dungeon[0].length;

        int[][] dp = new int[m][n];

        // Initialize last row and column of dp table
        for (int i = 0; i < m - 1; i++) {
            dp[i + 1][n - 1] = Math.max(1, dp[i + 1][n - 1] - dungeon[i + 1][n - 1]);
        }

        for (int j = 0; j < n - 1; j++) {
            dp[m - 1][j + 1] = Math.max(1, dp[m - 1][j + 1] - dungeon[m - 1][j + 1]);
        }

        // Fill up the rest of the table in bottom-up manner
        for (int i = m - 2; i >= 0; i--) {
            for (int j = n - 2; j >= 0; j--) {
                int maxVal = Math.max(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j];

                // If the maximum value is greater than or equal to 1, we can move towards it
                if (maxVal >= 1) {
                    dp[i][j] = maxVal;
                } else {
                    // Otherwise, we have to stay in this cell and take the minimum health required
                    dp[i][j] = Math.max(1, maxVal);
                }
            }
        }

        return dp[0][0];
    }
}

