        if (index == s.length()) {
            res.add(path.toString().trim());
            return;
        }
        for (String word : dict) {
            if (s.startsWith(word, index)) {
                path.append(word).append(" ");
                dfs(s, index + word.length(), dict, path, res);
                path.delete(path.length() - word.length() - 1, path.length());
            }
        }
    }
