        for (int i = index + 1; i <= s.length(); i++) {
            if (dp[i] && dict.contains(s.substring(index, i))) {
                start.add(dict.indexOf(s.substring(index, i)));
                backtrack(result, start, s, i, dp, dict);
                start.remove(start.size() - 1); // Remove the last element
            }
        }
    }
