import com.github.leetcode.ListNode;
import java.util.Arrays;

public class Solution {
    /**
     * Given the head of a singly linked list, sort the list using insertion sort,
     * and return the sorted list's head.
     *
     * @param head The head node of the linked list
     * @return The head node of the sorted linked list
     */
    public ListNode insertionSortList(ListNode head) {
        // Initialize a dummy node to store the beginning of the output linked list
        ListNode dummy = new ListNode(0);
        ListNode current = head;

        while (current != null) {
            ListNode nextNode = current.next;
            if (nextNode == null) break; // If there's only one element left, no need for insertion sort

            // Find where the current node should be inserted
            ListNode predecessor = dummy;
            ListNode successor = dummy.next;
            while (successor != nextNode && successor.val < current.val) {
                predecessor = predecessor.next;
                successor = successor.next;
            }

            // Insert the current node into the correct position
            predecessor.next = current;
            current.next = successor;

            // Move to the next element in the list
            current = nextNode;
        }

        return dummy.next;
    }
}

