public class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        int n = rowIndex + 1;

        // Initialize first and last element of the row as 1.
        for (int i = 0; i <= n; i++) {
            row.add(1);
        }

        // Calculate each element in the row based on the previous two elements.
        for (int i = 2; i < n; i++) {
            int prevPrevElement = row.get(i - 2);
            int prevElement = row.get(i - 1);
            row.set(i, prevPrevElement + prevElement);
        }

        // Return the row from index 0 to rowIndex.
        return row.subList(0, rowIndex + 1);
    }
}

