public class Solution {
    public Node cloneGraph(Node node) {
        // Base case: If there's no input, return null.
        if (node == null) {
            return null;
        }

        // Create a HashMap to store the cloned nodes. The key is the original node and the value is the cloned node.
        Map<Node, Node> map = new HashMap<>();

        // Use DFS to clone the graph
        return dfs(node, map);
    }

    private Node dfs(Node node, Map<Node, Node> map) {
        if (map.containsKey(node)) {
            // If the node is already in the map, return it directly.
            return map.get(node);
        }

        // Create a new node and add it to the map
        Node newNode = new Node();
        newNode.val = node.val;
        newNode.neighbors = new ArrayList<>();

        // Add the new node to the map
        map.put(node, newNode);

        // Clone each neighbor of the current node
        for (Node neighbor : node.neighbors) {
            Node clonedNeighbor = dfs(neighbor, map);
            newNode.neighbors.add(clonedNeighbor);
        }

        return newNode;
    }
}

