import java.util.List;
public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        // Base case: If the triangle has only one row, return its first element.
        if (triangle.size() == 1) {
            return triangle.get(0).get(0);
        }

        // Iterate over each row in the triangle from bottom to top.
        for (int i = triangle.size() - 2; i >= 0; i--) {
            // For each element in the current row, add its value to both of its children in the next row.
            for (int j = 0; j < triangle.get(i).size(); j++) {
                triangle.get(i).set(j, Math.min(triangle.get(i + 1).get(j), triangle.get(i + 1).get(j + 1)) + triangle.get(i).get(j));
            }
        }

        // The minimum path sum is the first element in the top row.
        return triangle.get(0).get(0);
    }
}

