import java.util.List;
import java.util.Arrays;

public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        int rows = triangle.size();
        int[] dp = new int[rows];

        // Initialize last row of dynamic programming array with values from the input list
        for (int i = 0; i < rows; i++) {
            dp[i] = triangle.get(rows - 1).get(i);
        }

        // Iterate through each row in reverse order starting from second to last row
        for (int i = rows - 2; i >= 0; i--) {
            // For each element, add the minimum of the two elements below it in the next row
            for (int j = 0; j <= i; j++) {
                dp[j] += Math.min(dp[j], dp[j + 1]);
            }
        }

        // The minimum path sum is stored in the first element of the dynamic programming array
        return dp[0];
    }
}

