import java.util.List;
import java.util.Arrays;

public class Solution {

    public int minimumTotal(List<List<Integer>> triangle) {
        int rows = triangle.size();

        // Start from the second last row and move up to the first row.
        for (int i = rows - 2; i >= 0; --i) {
            // For each element in the current row, add its value with both of its 
            // adjacent elements (in the next row) which are the minimum of two
            // adjacent elements. This is based on the idea that we can either move
            // to an adjacent number or not.
            for (int j = 0; j < triangle.get(i).size(); ++j) {
                if (j == 0) {
                    // For first element, its adjacent elements are only one i.e., 
                    // the second element in the next row.
                    triangle.get(i).set(j, triangle.get(i).get(j) + Math.min(triangle.get(i+1).get(0), triangle.get(i+1).get(1)));
                } else if (j == triangle.get(i).size() - 1) {
                    // For last element, its adjacent elements are only one i.e., 
                    // the second to last element in the next row.
                    triangle.get(i).set(j, triangle.get(i).get(j) + Math.min(triangle.get(i+1).get(j-1), triangle.get(i+1).get(j)));
                } else {
                    // For other elements, their adjacent elements are both i.e., 
                    // the element before it and the element after it in the next row.
                    triangle.get(i).set(j, triangle.get(i).get(j) + Math.min(triangle.get(i+1).get(j-1), triangle.get(i+1).get(j)));
                }
            }
        }

        int min = Integer.MAX_VALUE;

        // Find and return minimum path sum from top to bottom.
        for (int i = 0; i < triangle.get(0).size(); ++i) {
            if (triangle.get(0).get(i) < min)
                min = triangle.get(0).get(i);
        }

        return min;
    }
}

