public class Solution {
    public int compareVersion(String version1, String version2) {
        // split both versions into revisions
        String[] v1 = version1.split("\\.");
        String[] v2 = version2.split("\\.");

        // get number of revisions in each version
        int n1 = v1.length;
        int n2 = v2.length;

        // make them equal to compare easier
        while (n1 < n2) {
            // if first version has less revisions, add a 0 at the end
            v1 = appendZero(v1);
            ++n1;
        }
        while (n2 < n1) {
            // if second version has less revisions, add a 0 at the end
            v2 = appendZero(v2);
            ++n2;
        }

        // compare each revision and return the result
        for (int i = 0; i < Math.min(n1, n2); ++i) {
            int rev1 = Integer.parseInt(v1[i]);
            int rev2 = Integer.parseInt(v2[i]);

            if (rev1 < rev2)
                return -1;

            else if (rev1 > rev2)
                return 1;
        }

        // if all revisions are equal, the versions are equal
        return 0;
    }

    private String[] appendZero(String[] arr) {
        int n = arr.length;
        String[] newArr = new String[n + 1];
        System.arraycopy(arr, 0, newArr, 0, n);
        newArr[n] = "0";
        return newArr;
    }
}

