public class Solution {
    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> paths = new ArrayList<>();
        if (root == null) return paths;

        dfs(root, 0, new ArrayList<>(), targetSum, paths);
        return paths;
    }

    private void dfs(TreeNode node, int currentSum, List<Integer> path, int targetSum, List<List<Integer>> paths) {
        currentSum += node.val;
        path.add(node.val);

        if (node.left == null && node.right == null) {
            if (currentSum == targetSum) {
                paths.add(new ArrayList<>(path));
            }
        } else {
            dfs(node.left, currentSum, path, targetSum, paths);
            dfs(node.right, currentSum, path, targetSum, paths);
        }

        path.remove(path.size() - 1); // backtrack
    }
}

