        return ans;
    }

    private double getSlope(int[] p1, int[] p2) {
        if (p1[0] == p2[0]) return Double.POSITIVE_INFINITY; // vertical line

        return (double) (p2[1] - p1[1]) / (p2[0] - p1[0]);
    }
}

