                    map.put(slope, map.getOrDefault(slope, 0) + 1);
                }
            }
            res = Math.max(res, map.values().stream().max(Integer::compare).get());
        }

        return res + samePoint;
    }

    private int getGcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return Math.abs(a);
    }
}

