        q.offer(root);

        while (!q.isEmpty()) {
            int size = q.size();

            for (int i = 0; i < size; i++) {
                Node node = q.poll();

                // connect current node to next right node
                if (i < size - 1) {
                    node.next = q.peek();
                }

                // add children of current node to queue
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
        }

        return root;
    }
