import com.github.leetcode.left_right.Node;

// Definition for a Node.
public class Solution {
    public Node connect(Node root) {
        if (root == null) return null;

        // If the tree is empty, just return
        Node leftmost = root; // First node of each level
        while (leftmost != null && leftmost.left != null) { // While there are nodes at this level
            Node head = leftmost; // Head of this level
            while (head != null) {
                // Connect all sibling nodes
                head.left.next = head.right;
                if (head.next != null) {  // If there is a next node
                    head.right.next = head.next.left;
                }
                head = head.next;  // Move to the next node on this level
            }
            leftmost = leftmost.left; // Move to the first node of the next level
        }

        return root;
    }
}

