public class Solution {
    public void solve(char[][] board) {
        // Edge case, empty grid
        if (board == null || board.length == 0)
            return;

        int rows = board.length;
        int cols = board[0].length;

        // Traverse first and last rows (boundaries)
        for (int i = 0; i < rows; ++i) {
            dfs(board, i, 0);
            dfs(board, i, cols - 1);
        }

        // Traverse first and last Column (boundaries)
        for (int j = 0; j < cols; ++j) {
            dfs(board, 0, j);
            dfs(board, rows - 1, j);
        }

        // Traverse through entire matrix
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (board[i][j] == 'O') {
                    board[i][j] = 'X';
                } else if (board[i][j] == '#') {
                    board[i][j] = 'O';
                }
            }
        }
    }

    private void dfs(char[][] board, int row, int col) {
        // Check bounds
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length)
            return;

        // If cell is not 'O', return
        if (board[row][col] != 'O')
            return;

        // Mark as visited by converting to '#'
        board[row][col] = '#';

        // Recursively visit all adjacent cells
        dfs(board, row - 1, col);
        dfs(board, row + 1, col);
        dfs(board, row, col - 1);
        dfs(board, row, col + 1);
    }
}

