public class Solution {
    public void solve(char[][] board) {
        // Add a border of '#' around the 'O' regions.
        for (int i = 0; i < board.length; ++i) {
            if (board[i][0] == 'O') dfs(board, i, 0);
            board[0][i] = '#';
        }

        for (int i = 0; i < board.length; ++i) {
            if (board[i][board[0].length - 1] == 'O') dfs(board, i, board[0].length - 1);
            board[i][board[0].length - 1] = '#';
        }

        for (int j = 0; j < board[0].length; ++j) {
            if (board[0][j] == 'O') dfs(board, 0, j);
            board[j][0] = '#';
        }

        for (int j = 0; j < board[0].length; ++j) {
            if (board[board.length - 1][j] == 'O') dfs(board, board.length - 1, j);
            board[board.length - 1][j] = '#';
        }

        // Convert all remaining 'O's to 'X's and '#' to 'O's.
        for (int i = 0; i < board.length; ++i) {
            for (int j = 0; j < board[0].length; ++j) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == '#') board[i][j] = 'O';
            }
        }
    }

    private void dfs(char[][] board, int i, int j) {
        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != 'O') return;
        board[i][j] = '#';
        dfs(board, i - 1, j);
        dfs(board, i + 1, j);
        dfs(board, i, j - 1);
        dfs(board, i, j + 1);
    }
}

