            map.put(inorder[i], i);
        }

        return construct(preorder, inorder, 0, inorder.length - 1);
    }

    private TreeNode construct(int[] preorder, int[] inorder, int start, int end) {
        if (start > end || start >= preorder.length) {
            return null;
