            for (int j = 1; j < i; j++) {
                currentRow.add(previousRow.get(j - 1) + previousRow.get(j));
            }

            // The last element of the current row is always 1.
            currentRow.add(1);

            // Add the current row to Pascal's triangle.
            pascalTriangle.add(currentRow);
        }

        return pascalTriangle;
    }
