public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        // For the first house, we can either steal it or not.
        int noStealFirst = 0;
        int stealFirst = nums[0];

        for (int i = 1; i < nums.length - 1; i++) {
            int newNoSteal = Math.max(noStealFirst, stealFirst);
            int newSteal = noStealFirst + nums[i];
            noStealFirst = newNoSteal;
            stealFirst = newSteal;
        }

        // For the last house, we can either steal it or not.
        int newNoSteal = Math.max(noStealFirst, stealFirst);
        int newSteal = noStealFirst + nums[nums.length - 1];

        return Math.max(newNoSteal, newSteal);
    }
}

