public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 0) {
            return 0;
        }

        int n = nums.length;
        if (n <= 2) {
            return Math.max(nums[0], nums[1]);
        }

        int dp1 = nums[0];
        int dp2 = Math.max(nums[0], nums[1]);

        for (int i = 2; i < n - 1; ++i) {
            int temp = Math.max(dp1 + nums[i], dp2);
            dp1 = dp2;
            dp2 = temp;
        }

        return Math.max(dp1, dp2);
    }
}

