public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 0) {
            return 0;
        } else if (nums.length == 1) {
            return nums[0];
        }

        // dp[i] represents the maximum amount of money that can be robbed up to house i
        int[] dp = new int[nums.length];

        // Base case: If there's only one house, we can rob it.
        dp[0] = nums[0];

        // We cannot rob the first two houses because they are adjacent.
        dp[1] = Math.max(nums[0], nums[1]);

        for (int i = 2; i < nums.length; i++) {
            // For each house, we have two options:
            //   1. Rob this house and skip the previous one.
            //   2. Skip both this house and the previous one.
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
        }

        return dp[nums.length - 1];
    }
}

