public class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        if (inorder.length == 0 || postorder.length == 0) return null;

        TreeNode root = new TreeNode(postorder[postorder.length - 1]);
        int index = inorder.length - 1;
        for (int i = inorder.length - 1; i >= 0; i--) {
            if (inorder[i] == postorder[postorder.length - 1]) {
                index = i;
                break;
            }
        }

        root.left = buildTree(inorder, 0, index - 1, postorder);
        root.right = buildTree(inorder, index + 1, inorder.length - 1, postorder);

        return root;
    }

    private TreeNode buildTree(int[] inorder, int start, int end, int[] postorder) {
        if (start > end || start < 0 || end >= inorder.length) return null;

        TreeNode root = new TreeNode(postorder[postorder.length - 1]);
        int index = start;
        for (int i = start; i <= end; i++) {
            if (inorder[i] == postorder[postorder.length - 1]) {
                index = i;
                break;
            }
        }

        root.left = buildTree(inorder, start, index - 1, postorder);
        root.right = buildTree(inorder, index + 1, end, postorder);

        return root;
    }
}

