import com_github_leetcode.TreeNode;
import java.util.Arrays;

public class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        return buildTree(inorder, 0, inorder.length - 1, postorder, 0, postorder.length - 1);
    }

    private TreeNode buildTree(int[] inorder, int inStart, int inEnd, int[] postorder, int postStart, int postEnd) {
        if (inStart > inEnd || postStart > postEnd) {
            return null;
        }

        // Create a new node with the last element of postorder as its value
        TreeNode root = new TreeNode(postorder[postEnd]);

        // Find the index of the current root in inorder array
        int inIndex = findInorderIndex(inorder, inStart, inEnd, root.val);

        // Recursively build the left and right subtrees
        root.left = buildTree(inorder, inStart, inIndex - 1, postorder, postStart, postStart + (inIndex - inStart) - 1);
        root.right = buildTree(inorder, inIndex + 1, inEnd, postorder, postStart + (inEnd - inIndex), postEnd - 1);

        return root;
    }

    private int findInorderIndex(int[] inorder, int inStart, int inEnd, int target) {
        for (int i = inStart; i <= inEnd; i++) {
            if (inorder[i] == target) {
                return i;
            }
        }

        return -1;
    }
}

