import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        if (inorder.length == 0 || postorder.length == 0) return null;

        TreeNode root = new TreeNode(postorder[postorder.length - 1]);
        int indexInorder = findIndex(inorder, root.val);

        root.left = buildTree(getLeftSubArray(inorder, indexInorder), getRightSubArray(postorder, indexInorder));
        root.right = buildTree(getLeftSubArray(inorder, indexInorder + 1), getPostOrderRightSubArray(postorder, indexInorder));

        return root;
    }

    private int findIndex(int[] array, int value) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == value)
                return i;
        }
        return -1;
    }

    private int[] getLeftSubArray(int[] inorder, int index) {
        int[] subArray = new int[index];
        System.arraycopy(inorder, 0, subArray, 0, index);
        return subArray;
    }

    private int[] getRightSubArray(int[] postorder, int index) {
        int start = postorder.length - index;
        int[] subArray = new int[postorder.length - start];
        System.arraycopy(postorder, start, subArray, 0, subArray.length);
        return subArray;
    }

    private int[] getPostOrderRightSubArray(int[] postorder, int index) {
        int start = postorder.length - (index + 1);
        int[] subArray = new int[postorder.length - start];
        System.arraycopy(postorder, start, subArray, 0, subArray.length);
        return subArray;
    }
}

