        long hash = 0;
        for (int i = 0; i < s.length(); ++i)
            hash = (hash << 2 | (s.charAt(i) == 'A' ? 0 : s.charAt(i) == 'C' ? 1 : s.charAt(i) == 'G' ? 2 : 3));
        return hash;
    }

    private static java.util.HashMap<Integer, String> map = new java.util.HashMap<>();
}

