public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        Map<String, Integer> map = new HashMap<>();
        List<String> res = new ArrayList<>();

        // Iterate over the string with a sliding window of size 10
        for (int i = 0; i <= s.length() - 10; i++) {
            String str = s.substring(i, i + 10);

            // Check if the current substring is already in the map
            if (map.containsKey(str)) {
                // If it's already there, increment its count and add it to the result list
                int count = map.get(str) + 1;
                if (count == 2) {
                    res.add(str);
                }
                map.put(str, count);
            } else {
                // If not, add it to the map with a count of 1
                map.put(str, 1);
            }
        }

        return res;
    }
}

