import com_github_leetcode.ListNode;

public class Solution {
    public ListNode detectCycle(ListNode head) {
        // Check for null pointer exception
        if (head == null || head.next == null) return null;

        ListNode slow = head, fast = head;

        while(fast != null && fast.next != null){
            slow = slow.next;      // Move one step at a time for the slow pointer
            fast = fast.next.next;  // Two steps at a time for the fast pointer

            if(slow == fast){       // If there is an intersection, return the meeting point
                ListNode ptr1 = head;
                ListNode ptr2 = slow;

                while(ptr1 != ptr2){
                    ptr1 = ptr1.next;
                    ptr2 = ptr2.next;
                }

                return ptr1;         // Return the start of the cycle
            }
        }

        return null;              // If no intersection is found, there is no cycle
    }
}

