            return -1;
        }
        int start = 0, end = nums.length-1;

        while(start < end){
            // Calculate the middle index
            int mid = (start + end)/2;

            // If the middle element is greater than the last element,
            // then the minimum element must be in the right half.
            if(nums[mid] > nums[end]){
                start = mid+1;
            }
            // If the middle element is less than or equal to the last element,
            // then the minimum element must be in the left half.
            else{
                end = mid;
            }
        }

        return nums[start];
    }
}

