public class Solution {
    public int numDistinct(String s, String t) {
        int m = s.length();
        int n = t.length();

        // Create a 2D array dp where dp[i][j] represents the number of distinct subsequences
        // of s[0..i-1] which equals t[0..j-1]
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0) {
                    // If s is empty, there's only one way to form an empty string
                    dp[i][j] = 1;
                } else if (j == 0) {
                    // If t is empty, there are i ways to form a string of length i from s
                    dp[i][j] = 1;
                } else if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    // If the current characters in s and t match, we can either include or exclude
                    // the current character in s. So, the number of distinct subsequences is the sum
                    // of the number of distinct subsequences without including the current character
                    // and the number of distinct subsequences with the current character included.
                    dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1];
                } else {
                    // If the current characters in s and t don't match, we can only exclude the
                    // current character in s. So, the number of distinct subsequences is the same as
                    // the number of distinct subsequences without including the current character.
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }

        return dp[m][n];
    }
}

