public class Solution {
    public int numDistinct(String s, String t) {
        int m = s.length();
        int n = t.length();

        // Create a 2D array dp of size (m+1) x (n+1)
        int[][] dp = new int[m + 1][n + 1];

        // Initialize the base case where the substring is empty
        for (int i = 0; i <= m; i++) {
            dp[i][0] = 1;
        }

        // Fill up the rest of the table using dynamic programming
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }

        // The answer is stored in the bottom-right corner of the table
        return dp[m][n];
    }
}

