import com_github_leetcode.ListNode;
import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode sortedListToBST(ListNode head) {
        return sortedListToBST(head, null);
    }

    private TreeNode sortedListToBST(ListNode head, ListNode end) {
        // Base case: Empty list -> empty tree / sub-tree
        if (head == end) {
            return null;
        }

        // Find the middle node of the list. The fast pointer moves twice as 
        // quickly as the slow pointer and will meet at the middle of the linked 
        // list.
        ListNode slow = head, fast = head;
        while (fast.next != end && fast.next.next != end) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // The node pointed to by 'slow' is the middle one in the list. We make it 
        // the root of our BST.
        TreeNode root = new TreeNode(slow.val);

        // Recursively construct the left and right subtrees.
        root.left = sortedListToBST(head, slow);
        root.right = sortedListToBST(slow.next, end);

        return root;
    }
}

