import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = buildGraph(wordSet);
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(beginWord, 0));
        boolean found = false;
        Set<String> visited = new HashSet<>();

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair pair = queue.poll();
                String word = pair.word;
                if (word.equals(endWord)) {
                    found = true;
                    break;
                }

                List<String> neighbors = graph.get(word);
                if (!visited.contains(word)) {
                    visited.add(word);

                    for (String neighbor : neighbors) {
                        if (!visited.contains(neighbor)) {
                            queue.offer(new Pair(neighbor, pair.step + 1));
                        }
                    }
                }
            }

            if (found) break;
        }

        List<List<String>> ans = new ArrayList<>();
        if (found) {
            dfs(graph, beginWord, endWord, visited, ans);
        }

        return ans;
    }

    private void dfs(Map<String, List<String>> graph, String start, String end, Set<String> visited, List<List<String>> ans) {
        if (start.equals(end)) {
            ans.add(new ArrayList<>(visited));
            return;
        }

        for (String word : graph.get(start)) {
            if (!visited.contains(word)) {
                visited.add(word);
                dfs(graph, word, end, visited, ans);
                visited.remove(word);
            }
        }
    }

    private Map<String, List<String>> buildGraph(Set<String> wordSet) {
        Map<String, List<String>> graph = new HashMap<>();

        for (String word : wordSet) {
            char[] chars = word.toCharArray();
            for (int i = 0; i < chars.length; i++) {
                char temp = chars[i];
                chars[i] = '*';

                String nextWord = new String(chars);
                if (!wordSet.contains(nextWord)) continue;

                graph.computeIfAbsent(word, k -> new ArrayList<>()).add(nextWord);

                chars[i] = temp;
            }
        }

        return graph;
    }

    private static class Pair {
        String word;
        int step;

        public Pair(String word, int step) {
            this.word = word;
            this.step = step;
        }
    }
}

