public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        wordSet.add(beginWord);

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        int distance = 0;
        boolean foundEndWord = false;

        while (!queue.isEmpty()) {
            int size = queue.size();
            Set<String> currentLayer = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String word = queue.poll();

                if (word.equals(endWord)) {
                    foundEndWord = true;
                    distance++;
                }

                List<String> neighbors = getNeighbors(word, wordSet);
                graph.putIfAbsent(word, new ArrayList<>());
                for (String neighbor : neighbors) {
                    graph.get(word).add(neighbor);
                    if (!currentLayer.contains(neighbor)) {
                        currentLayer.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }

            distance++;
        }

        if (!foundEndWord) return new ArrayList<>();

        List<List<String>> ans = new ArrayList<>();
        dfs(graph, beginWord, endWord, distance - 1, ans);

        return ans;
    }

    private void dfs(Map<String, List<String>> graph, String currentWord, String endWord, int distance, List<List<String>> ans) {
        if (currentWord.equals(endWord)) {
            ans.add(new ArrayList<>(new LinkedList<>()));
            ans.get(ans.size() - 1).add(currentWord);
            return;
        }

        for (String neighbor : graph.get(currentWord)) {
            if (!neighbor.isEmpty()) {
                List<String> path = new ArrayList<>(ans.get(ans.size() - 1));
                path.add(neighbor);
                dfs(graph, neighbor, endWord, distance - 1, path);
            }
        }
    }

    private List<String> getNeighbors(String word, Set<String> wordSet) {
        List<String> neighbors = new ArrayList<>();

        for (int i = 0; i < word.length(); i++) {
            char[] chars = word.toCharArray();
            for (char c = 'a'; c <= 'z'; c++) {
                if (chars[i] == c) continue;
                chars[i] = c;
                String neighbor = new String(chars);
                if (wordSet.contains(neighbor)) neighbors.add(neighbor);
            }
        }

        return neighbors;
    }
}

