                }

                for (int j = 0; j < curWord.length(); j++) {
                    for (char c = 'a'; c <= 'z'; c++) {
                        String nextWord = curWord.substring(0, j) + c + curWord.substring(j + 1);

                        if (!wordSet.contains(nextWord)) continue;

                        wordSet.remove(nextWord);
                        queue.offer(nextWord);
                        reverseGraph.computeIfAbsent(curWord, k -> new ArrayList<>()).add(nextWord);
