import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();

        addNeighbors(beginWord, wordSet, graph, queue);

        while (!queue.isEmpty()) {
            Node node = queue.poll();
            String currentWord = node.word;

            if (currentWord.equals(endWord)) return constructPath(node, beginWord);

            List<String> neighbors = graph.get(currentWord);
            for (String neighbor : neighbors) {
                addNeighbors(neighbor, wordSet, graph, new Node(neighbor));
            }
        }

        return new ArrayList<>();
    }

    private void addNeighbors(String currentWord, Set<String> wordSet, Map<String, List<String>> graph, Queue<Node> queue) {
        if (!wordSet.contains(currentWord)) return;

        String key = getHashKey(currentWord);

        if (graph.containsKey(key)) return;

        List<String> neighbors = new ArrayList<>();
        for (int i = 0; i < currentWord.length(); i++) {
            StringBuilder sb = new StringBuilder(currentWord);
            for (char c = 'a'; c <= 'z'; c++) {
                sb.setCharAt(i, c);
                String neighbor = sb.toString();
                if (wordSet.contains(neighbor)) neighbors.add(neighbor);
            }
        }

        graph.put(key, neighbors);

        queue.offer(new Node(currentWord));

        wordSet.remove(currentWord);
    }

    private List<List<String>> constructPath(Node node, String beginWord) {
        List<List<String>> paths = new ArrayList<>();
        List<String> path = new ArrayList<>();
        dfs(node, beginWord, path, paths);
        return paths;
    }

    private void dfs(Node node, String endWord, List<String> path, List<List<String>> paths) {
        if (node.word.equals(endWord)) {
            path.add(node.word);
            paths.add(new ArrayList<>(path));
        } else {
            for (String neighbor : node.neighbors) {
                if (!path.contains(neighbor)) {
                    path.add(neighbor);
                    dfs(new Node(neighbor), endWord, path, paths);
                    path.remove(path.size() - 1);
                }
            }
        }
    }

    private String getHashKey(String word) {
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            sb.append(c).append(",");
        }
        return sb.toString().substring(0, sb.length() - 1);
    }

    static class Node {
        String word;
        List<String> neighbors;

        public Node(String word) {
            this.word = word;
        }

        public void addNeighbor(String neighbor) {
            if (neighbors == null) neighbors = new ArrayList<>();
            neighbors.add(neighbor);
        }
    }
}

