import com.github.leetcode.ListNode;
import java.util.Random;

public class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        // Use merge sort to sort the linked list in-place
        head = mergeSort(head);
        return head;
    }

    private ListNode mergeSort(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        // Find the middle of the linked list using quickselect
        ListNode midNode = findMidNode(head);

        // Split the linked list into two halves at the middle node
        ListNode midNext = midNode.next;
        midNode.next = null;

        // Recursively sort the left and right halves separately
        ListNode leftHead = mergeSort(head);
        ListNode rightHead = mergeSort(midNext);

        // Merge the sorted left and right halves together
        return merge(leftHead, rightHead);
    }

    private ListNode findMidNode(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        // Use quickselect to find the middle node in O(log N) time
        int k = 1;
        ListNode midNode = head;

        while (true) {
            ListNode nextNode = midNode.next;
            if (nextNode != null && ((k << 1) & (nextInt() - 1)) == 0) {
                midNode = nextNode;
            } else if (nextNode == null) {
                break;
            }
            k <<= 1;
        }

        return midNode;
    }

    private Random random = new Random();

    private int nextInt() {
        return random.nextInt();
    }

    private ListNode merge(ListNode head1, ListNode head2) {
        ListNode dummyHead = new ListNode(0);
        ListNode current = dummyHead;

        while (head1 != null && head2 != null) {
            if (head1.val <= head2.val) {
                current.next = head1;
                head1 = head1.next;
            } else {
                current.next = head2;
                head2 = head2.next;
            }
            current = current.next;
        }

        if (head1 != null) {
            current.next = head1;
        } else if (head2 != null) {
            current.next = head2;
        }

        return dummyHead.next;
    }
}

