        if (root.left != null)
            root.left.next = root.right;

        if (root.right != null && root.left != null)
            root.right.next = root.left.next;

        // Connect right nodes
        if (root.next != null) {
            Node nextNode = root.next;
            while (nextNode.left != null || nextNode.right != null) {
                if (nextNode.left != null) {
                    nextNode.left.next = nextNode.right;
                    if (nextNode.right.next != null)
                        nextNode.right.next = nextNode.left.next;
                    nextNode = nextNode.left;
                }
                else {
                    nextNode.right.next = nextNode.left.next;
                    nextNode = nextNode.right;
                }
            }
        }

        // Connect left and right subtrees
        connect(root.left);
        connect(root.right);

        return root;
    }
