public class Solution {
    public Node connect(Node root) {
        if (root == null) return null; // Base case: if the tree is empty, there's nothing to do.

        // Perform a level order traversal of the tree
        java.util.LinkedList<Node> queue = new java.util.LinkedList<>();
        queue.offer(root); // Add the root node to the queue

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) { // Iterate over all nodes at this level
                Node current = queue.poll(); // Get the next node from the front of the queue

                if (i < size - 1) { // There's a next node after this one, so link them together
                    current.next = queue.peek();
                }

                if (current.left != null) {
                    queue.offer(current.left); // Add children to the end of the queue for future processing
                }
                if (current.right != null) {
                    queue.offer(current.right);
                }
            }
        }

        return root;
    }
