    public int canCompleteCircuit(int[] gas, int[] cost) {
        // Calculate the total amount of gas and the total cost
        int totalGas = 0;
        int totalCost = 0;

        // Initialize the tank level to 0
        int tankLevel = 0;

        // Find the starting point
        int start = 0;
        for (int i = 0; i < gas.length; i++) {
            // Add the current gas and cost to the total
            totalGas += gas[i];
            totalCost += cost[i];

            // If the tank level becomes negative, it means we need to start from a different point
            if (tankLevel < 0) {
                start = i + 1;
                tankLevel = 0;
            }

            // Add the current gas to the tank level
            tankLevel += gas[i] - cost[i];
        }

        // If the total gas is not enough, return -1
        if (totalGas < totalCost) {
            return -1;
        }

        // Return the starting point
        return start;
    }
}

