public class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        // calculate the total amount of gas and total cost
        int n = gas.length;
        long totalGas = 0, totalCost = 0;

        for (int i = 0; i < n; i++) {
            totalGas += gas[i];
            totalCost += cost[i];
        }

        // if the total gas is not enough to cover all costs, there's no solution
        if (totalGas < totalCost) return -1;

        // initialize the starting point and the remaining gas
        long start = 0, remaining = 0;

        for (int i = 0; i < n; i++) {
            // add the current station's gas to the remaining gas
            remaining += gas[i];
            // subtract the current station's cost from the remaining gas
            remaining -= cost[i];

            // if the remaining gas is negative, it means we've already passed a station that can't support us
            if (remaining < 0) {
                // in this case, we need to find the next starting point by resetting 'start' and updating 'remaining'
                start = i + 1;
                // reset 'remaining' since we're starting fresh from this new position
                remaining = 0;
            }
        }

        return start;
    }
}

