public class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        // First Pass: Create clones of each original node and link them together in the same order
        Node current = head;
        while (current != null) {
            Node clone = new Node(current.val);
            clone.next = current.next;
            clone.random = null;

            current.next = clone;
            current = current.next;
        }

        // Second Pass: Set up random pointers to point to the correct nodes
        current = head;
        while (current != null) {
            if (current.random != null) {
                current.next.random = current.random.next;
            }
            current = current.next.next;
        }

        // Third Pass: Break original list into two separate lists and return the cloned list head
        Node dummyNode = new Node(0);
        Node originalCurrent = head;
        Node cloneCurrent = dummyNode;

        while (originalCurrent != null) {
            Node nextOriginal = originalCurrent.next;
            Node nextClone = originalCurrent.next.next;

            originalCurrent.next = nextOriginal;
            originalCurrent.next.next = nextClone;

            cloneCurrent.next = nextOriginal;
            cloneCurrent = cloneCurrent.next;
            originalCurrent = nextOriginal;
        }

        return dummyNode.next;
    }
}

