        }

        Map<Node, Node> oldToNew = new HashMap<>();
        Node current = head;

        // First pass to create the cloned nodes and store them in a map
        while (current != null) {
            oldToNew.put(current, new Node(current.val));
            current = current.next;
        }
        current = head;

        // Second pass to make the random pointers point to the correct nodes
        while (current != null) {
            if (current.random != null) {
                oldToNew.get(current).random = oldToNew.get(current.random);
