        StringBuilder result = new StringBuilder();

        // Handle negative cases
        if ((numerator < 0) ^ (denominator < 0)) {
            result.append("-");
        }

        // Convert to positive integers and get the sign later
        numerator = Math.abs(numerator);
        denominator = Math.abs(denominator);

        // Integer part
        int integerPart = numerator / denominator;
        result.append(integerPart);

        if (numerator % denominator == 0) {
            return result.toString();
        }

        result.append(".");

        Map<Integer, Integer> remainderMap = new HashMap<>();
        int remainder = (numerator % denominator) * 10;
        int index = 0;

        while (remainder != 0 && !remainderMap.containsKey(remainder)) {
            remainderMap.put(remainder, index++);

            int digit = remainder / denominator;
            result.append(digit);

            remainder = (remainder - digit * denominator) * 10;
        }

        if (remainder != 0) {
            int start = remainderMap.get(remainder);
            result.insert(start + 1, "(");
            result.append(")");
        }

        return result.toString();
    }
}

