        // negative case
        if ((numerator < 0) ^ (denominator < 0)) {
            result.append("-");
        }

        long num = Math.abs((long) numerator);
        long denom = Math.abs((long) denominator);

        // integer part
        result.append(num / denom);

        // decimal part
        if (num % denom != 0) {
            result.append(".");

            Map<Long, Integer> remainders = new HashMap<>();
            long remainder = (num % denom) * 10;
            int index = result.length();

            while (remainder != 0 && !remainders.containsKey(remainder)) {
                remainders.put(remainder, result.length());
                result.append((char) ('0' + remainder / denom));
                remainder = (remainder % denom) * 10;

                if (index < result.length()) {
                    index = result.indexOf(result.substring(index), result.charAt(result.length() - 1));
                }
            }

            if (remainder != 0) {
                result.insert(remainders.get(remainder), "(");
                int start = remainders.get(remainder);
                int end = result.length();
                while (!result.substring(start, end).equals(result.substring(index, result.charAt(end - 1) == ')' ? result.length() : result.indexOf(')', end)))) {
                    start++;
                }
                result.insert(start, ")");
            }
        }

        return result.toString();
    }
}

