public class Solution {
    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] seats = new int[n];

        for (int[] booking : bookings) {
            int start = Math.max(0, booking[0] - 1);
            int end = Math.min(n - 1, booking[1]);

