import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        int n = arr1.length;
        int m = arr2.length;

        // dp[i][j] is the minimum number of operations needed to make arr1[0..i-1] strictly increasing
        // with the last element being at most arr2[j-1]
        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            if (arr1[i - 1] > arr1[i - 2]) {
                // If the current element is already larger than the previous one, no operation needed
                dp[i][0] = dp[i - 1][0];
            } else {
                int minOps = Integer.MAX_VALUE;

                for (int j = 0; j <= m && arr2[j] < arr1[i - 1]; j++) {
                    // Try to replace the current element with an element from arr2
                    minOps = Math.min(minOps, dp[i - 1][j + 1]);
                }

                if (minOps == Integer.MAX_VALUE) {
                    // If no replacement is possible, return -1
                    return -1;
                } else {
                    dp[i][0] = minOps + 1;
                }
            }

            for (int j = 1; j <= m && arr2[j - 1] < arr1[i - 1]; j++) {
                // Try to replace the current element with an element from arr2
                dp[i][j] = Math.min(dp[i][j], dp[i - 1][j]);

                if (arr2[j - 1] > arr1[i - 1]) {
                    // If we can make the current element larger than the previous one, try to replace it with an element from arr2
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j + 1] + 1);
                }
            }
        }

        return dp[n][0];
    }
}

