public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr1);
        Arrays.sort(arr2);

        Integer[] dp = new Integer[arr1.length];
        return dfs(arr1, arr2, 0, dp);
    }

    private int dfs(int[] arr1, int[] arr2, int index, Integer[] dp) {
        if (index == arr1.length - 1) return 0;
        if (dp[index] != null) return dp[index];

        int min = Integer.MAX_VALUE;

        for (int i = index + 1; i < arr1.length; i++) {
            if (arr1[i] > arr1[index]) {
                min = Math.min(min, dfs(arr1, arr2, i, dp));
            }
        }

        int idx;
        for (idx = 0; idx < arr2.length; idx++) {
            if (arr1[index] < arr2[idx] && arr2[idx] <= arr1[i]) {
                break;
            }
        }

        return dp[index] = Math.min(min + 1, dfs(arr1, arr2, index + 1, dp));
    }
}

