import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        int n = arr1.length;
        if (n == 0)
            return 0;

        int []dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;

        for (int i = 1; i < n; i++) {
            int last = arr1[i - 1];
            if (arr1[i] > last)
                dp[i] = Math.min(dp[i], 0);

            int low = 0;
            while (low < arr2.length && arr2[low] <= last) {
                low++;
            }

            for (int j = low; j < arr2.length; j++) {
                if (arr2[j] > arr1[i]) {
                    dp[i] = Math.min(dp[i], 1 + dp[Math.max(0, i-1)]);
                } else
                    break;
            }

        }

        return dp[n - 1] != Integer.MAX_VALUE / 2 ? dp[n - 1] : -1;
    }
}

