        int n = text.length();
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            if (i > 0 && text.charAt(i - 1) == text.charAt(i)) {
                dp[i] = dp[i - 1] + 1;
            } else {
                dp[i] = 1;
            }
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && text.charAt(i) == text.charAt(i - 1)) {
                continue;
            }

            char c = text.charAt(i);
            int count = dp[i];
            int total = charCount.getOrDefault(c, 0);

            // case 1
            maxLen = Math.max(maxLen, total / (count + 1) * (count + 1));

            // case 2
            if (i < n - 1 && text.charAt(i + 1) == c) {
                int nextCount = dp[i + 1];
                maxLen = Math.max(maxLen, count + nextCount);
            } else {
                maxLen = Math.max(maxLen, total % (count + 1));
            }
        }

        return maxLen;
    }
}

