        for (char c : chars) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        int n = text.length();
        int result = 0;
        for (int i = 0; i < n;) {
            char c = chars[i];
            int count = map.get(c);
            while (i < n && chars[i] == c) {
                i++;
                count--;
            }
            if (count > 0) {
                result = Math.max(result, count + 1);
                // Check for possibility of swap to get maximum length
                if (map.containsKey(chars[i - 1]) && map.get(chars[i - 1]) >= 2) {
                    result = Math.max(result, i / 2 + 2);
                }
            } else {
                // Check for pattern xxxxYxxxxx
                int j = i;
                while (j < n && chars[j] == chars[i - 1]) {
                    j++;
                }
                if (map.get(chars[i - 1]) > (j - i) / 2 + 1) {
                    result = Math.max(result, map.get(chars[i - 1]));
                } else {
                    // Check for possibility of swap to get maximum length
                    if (i >= 3 && chars[i - 1] == chars[i - 2] && chars[i - 2] == chars[i - 3]) {
                        result = Math.max(result, i / 3 + 2);
                    }
                }
            }
        }
        return result;
    }

    public static class Pair {
        char c;
        int count;

        public Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }
    }
}

