public class Solution {

    public int maxRepOpt1(String text) {
        Map<Character, Integer> map = new HashMap<>();
        for (char c : text.toCharArray()) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        int n = text.length();
        List<Pair> list = new ArrayList<>();
        int count = 1;
        char prevChar = text.charAt(0);

        for (int i = 1; i < n; ++i) {
            if (text.charAt(i) == prevChar) {
                count++;
            } else {
                list.add(new Pair(prevChar, count));
                map.put(prevChar, map.get(prevChar) - count);
                prevChar = text.charAt(i);
                count = 1;
            }
        }

        list.add(new Pair(prevChar, count));

        int totalMaxLen = 0;

        for (Pair pair : list) {
            char c = pair.c;
            int count = pair.count;

            boolean isPossibleSwap = map.getOrDefault(c, 0) > 0 || count < map.getOrDefault(c, 0);

            if (isPossibleSwap) {
                totalMaxLen = Math.max(totalMaxLen, 1 + count);
            } else {
                totalMaxLen = Math.max(totalMaxLen, count);
            }
        }

        return totalMaxLen;
    }
}

