public class Solution {
    public int maxEqualFreq(String text) {
        Map<Character, Integer> freqMap = new HashMap<>();
        Map<Integer, Integer> freqCountMap = new HashMap<>();

        int longestSubstrLength = 0;

        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);

            int currFreq = freqMap.get(c);

            if (!freqCountMap.containsKey(currFreq)) {
                freqCountMap.put(currFreq, 1);
            } else {
                freqCountMap.put(currFreq, freqCountMap.get(currFreq) + 1);
            }

            // Case 1: Swap an item to the boundary of a consecutive char-block
            if (freqCountMap.containsKey(0)) {
                int zeroFreqCount = freqCountMap.get(0);
                longestSubstrLength = Math.max(longestSubstrLength, currFreq * zeroFreqCount + i);
            }

            // Case 2: Find xxxxYxxxxx pattern
            if ((freqCountMap.containsKey(currFreq) && (currFreq * freqCountMap.get(currFreq) == i)) ||
                    freqCountMap.containsKey(currFreq - 1) && freqCountMap.get(currFreq - 1) <= freqMap.size() - currFreq &&
                            freqCountMap.containsKey(currFreq + 1) && freqCountMap.get(currFreq + 1) >= freqMap.size() - currFreq) {
                longestSubstrLength = Math.max(longestSubstrLength, i + 1);
            }
        }

        return longestSubstrLength;
    }
}

