public class Solution {
    public int minHeightShelves(int[][] books, int shelfWidth) {
        int n = books.length;
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = Integer.MAX_VALUE / 2;
        }
        return dfs(books, 0, shelfWidth, dp);
    }

    private int dfs(int[][] books, int idx, int w, int[] dp) {
        if (idx >= books.length) {
            return 0;
        }
        if (dp[idx] != Integer.MAX_VALUE / 2) {
            return dp[idx];
        }
        int sum = 0, maxH = 0;
        for (int i = idx; i < books.length && w > 0; i++) {
            sum += books[i][0];
            maxH = Math.max(maxH, books[i][1]);
            if (sum <= w) {
                dp[idx] = Math.min(dp[idx], dfs(books, i + 1, w - sum, dp) + maxH);
            }
        }
        return dp[idx];
    }
}

