        // Initialize variables to store the current sum with and without deletion
        int currWithoutDeletion = 0, currWithDeletion = 0;

        for (int i = 0; i < n; i++) {
            // Update the maximum sum without deletion by considering the current element
            maxWithoutDeletion = Math.max(maxWithoutDeletion, currWithoutDeletion += arr[i]);

            // Update the maximum sum with deletion by considering the current element and the previous maximum sum without deletion
            if (i > 0) {
                maxWithDeletion = Math.max(maxWithDeletion, currWithDeletion + arr[i] - Math.min(arr[i-1], arr[i]));
            }

            // Update the current sum with deletion by considering the current element and the previous maximum sum without deletion
            if (i > 0) {
                currWithDeletion = Math.max(currWithDeletion, maxWithoutDeletion - arr[i-1]);
            } else {
                currWithDeletion = 0;
            }
        }

        // Return the maximum of the two sums
        return Math.max(maxWithoutDeletion, maxWithDeletion);
    }
