public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;

        // Initialize variables to store maximum sum and second maximum sum.
        int maxSum = Integer.MIN_VALUE, maxSecondMaxSum = Integer.MIN_VALUE;

        // Initialize variable to store the current sum of subarray ending at index i.
        int currSum = 0;

        for (int i = 0; i < n; i++) {
            // Update the current sum by adding the current element.
            currSum += arr[i];

            // If the current sum is greater than maxSum, update maxSum and maxSecondMaxSum.
            if (currSum > maxSum) {
                maxSecondMaxSum = maxSum;
                maxSum = currSum;
            } 
            // If the current sum is less than maxSum but greater than maxSecondMaxSum, update maxSecondMaxSum.
            else if (currSum < maxSum && currSum > maxSecondMaxSum) {
                maxSecondMaxSum = currSum;
            }

            // If the current sum is negative, reset it to 0 and continue with the next element.
            if (currSum < 0) {
                currSum = 0;
            }
        }

        // Initialize variables to store maximum sum after deleting one element from subarray ending at index i.
        int maxAfterDelete = Integer.MIN_VALUE;

        for (int i = n - 1; i >= 0; i--) {
            // Update the current sum by adding the current element and subtracting the previous maximum second maximum sum.
            currSum += arr[i] - maxSecondMaxSum;

            // If the current sum is greater than maxAfterDelete, update maxAfterDelete.
            if (currSum > maxAfterDelete) {
                maxAfterDelete = currSum;
            }
        }

        // Return the maximum of maxSum and maxAfterDelete.
        return Math.max(maxSum, maxAfterDelete);
    }
}

