public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> set = new HashSet<>();
        for (int i : to_delete) {
            set.add(i);
        }

        List<TreeNode> result = new ArrayList<>();
        TreeNode dummyRoot = null;
        dfs(root, set, result, dummyRoot);

        if (!root.valSet(set)) {
            result.add(0, root);
        }

        return result;
    }

    private void dfs(TreeNode node, Set<Integer> to_delete, List<TreeNode> result, TreeNode parent) {
        if (node == null) {
            return;
        }

        boolean isRoot = true;
        for (TreeNode child : new TreeNode[]{parent.left, parent.right}) {
            if (child != null && !child.valSet(to_delete)) {
                isRoot = false;
            }
        }

        if (!isRoot) {
            if (node.valSet(to_delete)) {
                if (parent == null) {
                    result.add(0, node);
                } else {
                    parent.removeChild(node);
                }
            }
            dfs(node.left, to_delete, result, node);
            dfs(node.right, to_delete, result, node);
        } else {
            dfs(node.left, to_delete, result, node);
            dfs(node.right, to_delete, result, node);
        }
    }

    private boolean valSet(Set<Integer> set) {
        return set.contains(val);
    }

    private int val;
}

