    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> set = new HashSet<>();
        for (int i : to_delete) {
            set.add(i);
        }

        List<TreeNode> res = new ArrayList<>();
        TreeNode dummyRoot = null;
        helper(root, set, res, dummyRoot);
        if(dummyRoot != null){
            res.add(0,dummyRoot);
        }

        return res;
    }

    public void helper(TreeNode root, Set<Integer> to_delete, List<TreeNode> res, TreeNode parent) {

        if (root == null)
            return;

        boolean isLeaf = true;
        for (TreeNode child : new TreeNode[]{root.left, root.right}) {
            if (child != null) {
                isLeaf = false;
                helper(child, to_delete, res, root);
            }
        }

        if (!to_delete.contains(root.val)) {
            if(parent == null){
                res.add(0,root);
            } else {
                parent.left = root.left;
                parent.right = root.right;
            }
        } else {
            if (parent == null)
                dummyRoot = root;
            else
                parent.left = root.left;
            if(root.right != null) {
                helper(root.right,to_delete,res,parent);
            }
        }

    }
