import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> set = new HashSet<>();
        for (int i : to_delete) set.add(i);
        List<TreeNode> res = new ArrayList<>();

        if (!set.contains(root.val)) res.add(root);

        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);

        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (set.contains(node.val)) {
                if (node.left != null && !set.contains(node.left.val))
                    res.add(node.left);
                if (node.right != null && !set.contains(node.right.val))
                    res.add(node.right);

                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            } else {
                node.left = delNodes(node.left, to_delete);
                node.right = delNodes(node.right, to_delete);

                if (node.left == null && node.right == null)
                    res.remove(res.indexOf(node));
                else
                    q.offer(node);
            }
        }

        return res;
    }
}

