import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        boolean hasLand = false;
        boolean hasWater = false;

        // Check if there is any land or water in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    hasLand = true;
                } else if (grid[i][j] == 0) {
                    hasWater = true;
                }
            }
        }

        // If there is no land or water, return -1
        if (!hasLand || !hasWater) {
            return -1;
        }

        Queue<int[]> queue = new LinkedList<>();

        // Add all the land cells to the queue with distance 0
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = -1;
                    queue.offer(new int[] {i, j});
                }
            }
        }

        // BFS to find the farthest water cell
        int maxDistance = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();
                int x = current[0];
                int y = current[1];

                // Check all the neighboring cells
                if (x > 0 && grid[x - 1][y] == 0) {
                    grid[x - 1][y] = -1;
                    queue.offer(new int[] {x - 1, y});
                }
                if (x < n - 1 && grid[x + 1][y] == 0) {
                    grid[x + 1][y] = -1;
                    queue.offer(new int[] {x + 1, y});
                }
                if (y > 0 && grid[x][y - 1] == 0) {
                    grid[x][y - 1] = -1;
                    queue.offer(new int[] {x, y - 1});
                }
                if (y < n - 1 && grid[x][y + 1] == 0) {
                    grid[x][y + 1] = -1;
                    queue.offer(new int[] {x, y + 1});
                }

                // Update the maximum distance
                maxDistance = Math.max(maxDistance, x + y);
            }
        }

        return maxDistance;
    }
}

