public class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        int[] freq = new int[n + 1];
        freq[0] = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (Character.isLetter(c)) {
                freq[i + 1] = freq[i] + 1;
            } else {
                freq[i + 1] = freq[i];
            }
        }

        List<Boolean> result = new ArrayList<>();

        for (int[] query : queries) {
            int left = query[0], right = query[1], k = query[2];
            int len = right - left + 1;

            // Check if the substring is a palindrome
            boolean isPalindrome = true;
            for (int i = 0; i < len / 2; i++) {
                if (s.charAt(left + i) != s.charAt(right - i)) {
                    isPalindrome = false;
                    break;
                }
            }

            // If it's already a palindrome, just return True
            if (isPalindrome) {
                result.add(true);
                continue;
            }

            int diffCount = 0;
            for (int i = left; i <= right; i++) {
                char c = s.charAt(i);
                if (!Character.isLetter(c)) {
                    continue;
                }

                // Count the difference between the frequency of 'c' and 'not c'
                int freqDiff = Math.abs(freq[i + 1] - (freq[i + 1] % 2 == 0 ? freq[i] : freq[i] + 1));
                diffCount += freqDiff;
            }

            // If we can replace at least k characters, the substring is a palindrome
            result.add(diffCount >= len && diffCount <= len * k);
        }

        return result;
    }
}

