import java.util.Arrays;

public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        long[] dp = new long[n];
        Arrays.fill(dp, -1);
        return (int) dfs(piles, 0, 1, piles[0]);
    }

    private long dfs(int[] piles, int i, int m, long sum) {
        if (i >= piles.length) {
            return sum;
        }
        if (dp[i] != -1) {
            return dp[i];
        }
        long max = Long.MIN_VALUE;
        for (int x = 1; x <= 2 * m; x++) {
            int next = i + x;
            if (next >= piles.length) {
                break;
            }
            max = Math.max(max, sum + dfs(piles, next, Math.max(m, x), sum));
        }
        return dp[i] = max;
    }
}

