import java.util.Arrays;
public class Solution {
    public int stoneGameIII(int[] piles) {
        int n = piles.length;
        int N = (n * (n + 1)) / 2;

        int dp[] = new int[n];
        for (int i = 0; i < n; ++i) {
            int sum = 0;
            for (int j = i, k = 1; j < n; ++j, ++k) {
                sum += piles[j];

                if (n - 2 * k + 1 <= j) break;

                dp[i] = Math.max(dp[i], N - sum - dp[Math.min(n - 1, j + k)]);
            }
        }

        return dp[0];
    }
