        Map<String, Integer> skillMap = new HashMap<>();
        for (int i = 0; i < skills.length; i++) {
            skillMap.put(skills[i], i);
        }

        int n = people.size();
        boolean[][] dp = new boolean[n][1 << skills.length];
        int[] ans = new int[Integer.numberOfTrailingZeros(Integer.highestOneBit(n)) + 1];

        for (int i = 0; i < n; i++) {
            for (String skill : people.get(i)) {
                if (!skillMap.containsKey(skill)) continue;
                int index = Integer.highestOneBit(1 << skillMap.get(skill));
                dp[i][index] = true;

                int j = i - 1;
                while (j >= 0) {
                    for (int k = index; k > 0; k = (k - 1) & index) {
                        if (!dp[j][k]) continue;
                        dp[i][index | k] = true;
                    }
                    j--;
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            if (dp[i][(1 << skills.length) - 1]) {
                int j = i - 1, index = (1 << skills.length) - 1;
                while (j >= 0 && index > 0) {
                    for (int k = index; k > 0; k = (k - 1) & index) {
                        if (!dp[j][k]) continue;
                        ans[Integer.numberOfTrailingZeros(index)] = i;
                        index -= k;
                    }
                    j--;
                }

                if (ans.length == Integer.numberOfTrailingZeros(index)) {
                    int t = i, index2 = (1 << skills.length) - 1;
                    while (t >= 0 && index2 > 0) {
                        for (int k = index2; k > 0; k = (k - 1) & index2) {
                            if (!dp[t][k]) continue;
                            ans[Integer.numberOfTrailingZeros(index)] = t;
                            index -= k;
                        }
                        t--;
                    }
                }

                return Arrays.copyOf(ans, Integer.numberOfTrailingZeros(index));
            }
        }

        return new int[]{};
    }
}

