        Deque<Integer> stack = new ArrayDeque<>();
        long sum = 0;

        for (int num : arr) {
            while (!stack.isEmpty() && num >= stack.peekLast()) {
                int minTop = stack.pollLast();
                int maxUntilNow = stack.isEmpty() ? Integer.MIN_VALUE : stack.peekLast();

                if (maxUntilNow < minTop) {
                    sum += (long) minTop * maxUntilNow;
                } else {
                    sum += (long) minTop;
                }
            }

            stack.offerLast(num);
        }

        // pop the remaining numbers from the stack and multiply them
        while (stack.size() > 2) {
            int minTop = stack.pollFirst();
            long mul = 1;
            while (!stack.isEmpty()) {
                mul *= stack.pollFirst();
            }
            sum += mul * minTop;
        }

        return (int) sum;
    }
}

