import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int maxLevelSum(TreeNode root) {
        if (root == null) return 0;

        int res = Integer.MIN_VALUE, level = 1;
        boolean flag = true;
        while (flag) {
            int sum = 0;
            for (TreeNode node : getNodes(root, level)) {
                sum += node.val;
            }
            if (sum > res) {
                res = sum;
            }
            level++;
            if (!hasNextLevel(root, level)) {
                flag = false;
            }
        }

        return level - 1;
    }

    private boolean hasNextLevel(TreeNode root, int level) {
        if (root == null) return false;
        if (level == 1) return true;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if ((level - 1) % 2 == 0 && node.left != null)
                queue.offer(node.left);
            if ((level - 1) % 2 == 0 && node.right != null)
                queue.offer(node.right);

            if (node.left != null || node.right != null) {
                return true;
            }
        }

        return false;
    }

    private List<TreeNode> getNodes(TreeNode root, int level) {
        if (root == null) return new ArrayList<>();

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        List<TreeNode> nodes = new ArrayList<>();

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if ((level - 1) % 2 == 0 && node.left != null)
                queue.offer(node.left);
            if ((level - 1) % 2 == 0 && node.right != null)
                queue.offer(node.right);

            nodes.add(node);
        }

        return nodes;
    }
}

