import java.time.LocalDate;
import java.time.Month;
import java.util.Calendar;

public class Solution {
    public int dayOfYear(String date) {
        // Split the date into year, month and day
        String[] parts = date.split("-");
        int year = Integer.parseInt(parts[0]);
        int month = Integer.parseInt(parts[1]);
        int day = Integer.parseInt(parts[2]);

        // Create a Calendar object for the given date
        Calendar calendar = Calendar.getInstance();
        calendar.set(Calendar.YEAR, year);
        calendar.set(Calendar.MONTH, month - 1);  // Month is 0-based
        calendar.set(Calendar.DAY_OF_MONTH, day);

        // Get the first day of the year and add the difference to get the correct day number
        int firstDayOfYear = calendar.getActualMinimum(Calendar.DAY_OF_YEAR);
        int dayNumber = day + (calendar.get(Calendar.DAY_OF_YEAR) - firstDayOfYear);

        return dayNumber;
    }
}

