public class Solution {
    public boolean parseBoolExpr(String expression) {
        List<Boolean> stack = new ArrayList<>();
        char[] chars = expression.toCharArray();
        int i = 0;
        while (i < chars.length) {
            if (chars[i] == '(') {
                i++;
                while (i < chars.length && chars[i] != ')') {
                    if (chars[i] == '!') {
                        stack.remove(stack.size() - 1);
                        i += 2;
                    } else if (chars[i] == '&') {
                        i = parseAndExpression(chars, i + 1, stack);
                    } else if (chars[i] == '|') {
                        i = parseOrExpression(chars, i + 1, stack);
                    }
                }
                i++;
            } else if (chars[i] == 't' || chars[i] == 'f') {
                stack.add(Boolean.parseBoolean(String.valueOf(chars[i])));
                i += 2;
            }
        }
        return stack.get(0);
    }

    private int parseOrExpression(char[] chars, int i, List<Boolean> stack) {
        while (i < chars.length && chars[i] != ')') {
            if (chars[i] == '&') {
                i = parseAndExpression(chars, i + 1, stack);
            }
            i++;
        }
        return i;
    }

    private int parseAndExpression(char[] chars, int i, List<Boolean> stack) {
        while (i < chars.length && chars[i] != ')') {
            if (chars[i] == '|') {
                i = parseOrExpression(chars, i + 1, stack);
            }
            i++;
        }
        return i;
    }
}

