                        if (valStr.equals("t")) {
                            andValues[j] = true;
                        } else if (valStr.equals("f")) {
                            andValues[j] = false;
                        }
                    }

                    value = true;

                    for (boolean b : andValues) {
                        if (!b) {
                            value = false;
                            break;
                        }
                    }
                } else if (subExpr.charAt(1) == '|') {
                    boolean[] orValues = new boolean[subExpr.length() - 3];

                    for (int j = 0; j < subExpr.length() - 3; j++) {
                        String valStr = subExpr.substring(j + 2, j + 3);
                        if (valStr.equals("t")) {
                            orValues[j] = true;
                        } else if (valStr.equals("f")) {
                            orValues[j] = false;
                        }
                    }

                    value = false;

                    for (boolean b : orValues) {
