public class Solution {
    public boolean parseBoolExpr(String expression) {
        List<String> stack = new ArrayList<>();
        char[] chars = expression.toCharArray();
        int i = 0;

        while (i < chars.length) {
            if (chars[i] == '(') {
                stack.add("(");
            } else if (chars[i] == ')') {
                boolean value;
                StringBuilder sb = new StringBuilder();

                // Skip the closing parenthesis
                ++i;

                while (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("t") && !stack.get(stack.size() - 1).equals("f")) {
                    sb.insert(0, stack.remove(stack.size() - 1));
                }

                if (sb.length() == 0) {
                    value = false;
                } else if (stack.isEmpty()) {
                    value = true;
                } else {
                    String op = stack.remove(stack.size() - 1);

                    // Evaluate OR operation
                    if (op.equals("|")) {
                        boolean leftValue = parseBoolExpr(sb.toString());
                        sb.setLength(0);
                        while (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("t") && !stack.get(stack.size() - 1).equals("f")) {
                            sb.insert(0, stack.remove(stack.size() - 1));
                        }
                        boolean rightValue = parseBoolExpr(sb.toString());
                        value = leftValue || rightValue;
                    } else if (op.equals("&")) {
                        // Evaluate AND operation
                        boolean leftValue = parseBoolExpr(sb.toString());
                        sb.setLength(0);
                        while (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("t") && !stack.get(stack.size() - 1).equals("f")) {
                            sb.insert(0, stack.remove(stack.size() - 1));
                        }
                        boolean rightValue = parseBoolExpr(sb.toString());
                        value = leftValue && rightValue;
                    } else if (op.equals("!")) {
                        // Evaluate NOT operation
                        String innerExpr = sb.toString();
                        sb.setLength(0);
                        while (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("t") && !stack.get(stack.size() - 1).equals("f")) {
                            sb.insert(0, stack.remove(stack.size() - 1));
                        }
                        value = parseBoolExpr(sb.toString()) != parseBoolExpr(innerExpr);
                    } else {
                        // Evaluate simple expression
                        value = op.equals("t");
                    }

                    if (i < chars.length && !Character.isWhitespace(chars[i])) {
                        throw new RuntimeException("Invalid input: " + new String(chars, i, chars.length - i));
                    }
                }

                stack.add(String.valueOf(value));

            } else {
                // Add character to string
                sb.append(chars[i]);
            }

            ++i;
        }

        return parseBoolExpr(stack.get(0));
    }
}

