public class Solution {
    public boolean parseBoolExpr(String expression) {
        List<String> tokens = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < expression.length()) {
            char c = expression.charAt(i);
            if (c == '(' || c == ')') {
                tokens.add(String.valueOf(c));
                sb.setLength(0); // Remove any characters in the current token.
            } else if (c == '&') {
                if (!expression.substring(i - 1, i).equals("&(") && !expression.substring(i + 1, i + 2).equals(")&")) {
                    sb.append(c);
                }
            } else if (c == '|') {
                if (!expression.substring(i - 1, i).equals("|(") && !expression.substring(i + 1, i + 2).equals("|)")) {
                    sb.append(c);
                }
            } else {
                sb.append(c);
            }
            i++;
        }
        return eval(tokens, 0, tokens.size() - 1);
    }

    private boolean eval(List<String> tokens, int fromIndex, int toIndex) {
        if (fromIndex == toIndex) {
            return tokens.get(fromIndex).equals("t");
        } else if (tokens.get(fromIndex).equals("!")) {
            return !eval(tokens, fromIndex + 1, toIndex);
        } else if (tokens.get(fromIndex).equals("&")) {
            boolean result = true;
            for (int i = fromIndex + 1; i <= toIndex; i++) {
                if (!eval(tokens, i, i)) {
                    return false;
                }
            }
            return result;
        } else if (tokens.get(fromIndex).equals("|")) {
            boolean result = false;
            for (int i = fromIndex + 1; i <= toIndex; i++) {
                if (eval(tokens, i, i)) {
                    return true;
                }
            }
            return result;
        }
        throw new IllegalArgumentException();
    }
}

