import java.util.Map;

public class Solution {
    public int numRollsToTarget(int n, int k, int target) {
        Map<String, Integer> memo = new HashMap<>();

        return dfs(n, k, target, memo);
    }

    private int dfs(int n, int k, int target, Map<String, Integer> memo) {
        String key = n + "," + target;

        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        if (n == 0 && target == 0) {
            return 1;
        } else if (n == 0 || target < 0) {
            return 0;
        }

        int count = 0;
        for (int i = 1; i <= k; i++) {
            count += dfs(n - 1, k, target - i, memo);
            count %= 1000000007;
        }

        memo.put(key, count);
        return count;
    }
}

