import java.util.Arrays;
public class Solution {
    public int numRollsToTarget(int n, int k, int target) {
        long[][] dp = new long[n + 1][target + 1];
        for (long[] row : dp) Arrays.fill(row, -1);
        return (int) dfs(dp, 0, 0, n, k, target) % ((int)Math.pow(10,9) + 7);
    }

    private long dfs(long[][] dp, int i, int sum, int n, int k, int target){
        if(sum > target || i > n) return 0;
        if(dp[i][sum] != -1) return dp[i][sum];

        long ways = 0;
        for(int j = 1; j <= Math.min(k, target-sum); j++){
            ways += dfs(dp, i+1, sum+j, n, k, target);
        }
        return dp[i][sum] = ways % ((int)Math.pow(10,9) + 7);
    }
}

