                for (int j = 2; j * j <= i; j++) {
                    if (i % j == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
            if (isPrime) primes++;
            else nonPrimes++;
        }

        long result = (factorial((int)primes) * factorial((int)nonPrimes)) % (Math.pow(10,9) + 7);
        return (int)result;
    }

    public static long factorial(int n) {
        long res = 1;
        for (int i=2; i<=n; i++) res=res*i;
        return res;
    }
}

