        else if (rightDepth > leftDepth) return lcaDeepestLeaves(root.right);
        else {
            TreeNode ancestor = root;
            while (ancestor.left != null && ancestor.right != null && ancestor.left.val == ancestor.right.val) {
                ancestor = ancestor.left;
