public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        int n = 1, level = 0;
        while (n <= label) {
            n *= 2;
            level++;
        }
        n /= 2;
        List<Integer> res = new LinkedList<>();
        while (level >= 0) {
            if ((label - n + 1) % 2 == 1) {
                res.add(label);
                label -= (n / 2) + 1;
            } else {
                res.add(0, label);
                label -= n / 2;
            }
            n /= 2;
            level--;
        }
        return res;
    }
}

