public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        int level = 1, prev = 0, curr = 1;
        while (curr <= label) {
            prev = curr;
            curr *= 2;
            level++;
        }

        List<Integer> res = new LinkedList<>();
        res.add(label);
        for (int i = level - 1; i > 0; i--) {
            int val = (prev + curr / 2 - label) * Math.pow(2, i - 1);
            if ((i & 1) == 0) { // even
                res.add(val);
            } else { // odd
                res.add(curr - val - 1);
            }
            prev = val;
            curr /= 2;
        }

        return res;
    }
}

