        int m = arr2.length;

        // Create a hash map to store the elements of arr2
        java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
        for (int i = 0; i < m; i++) {
            map.put(arr2[i], i);
        }

        // Sort the elements of arr1 based on their presence in arr2 and value
        int[] sortedArr = new int[n];
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (map.containsKey(arr1[i])) {
                sortedArr[j++] = arr1[i];
            } else {
                // If the element is not in arr2, add it to the end of the array
                sortedArr[n - j + i] = arr1[i];
            }
        }

        // Sort the elements that are not in arr2 in ascending order
        java.util.Arrays.sort(sortedArr, n - j, n);

        return sortedArr;
    }
}

