import java.util.Stack;

public class Solution {
    public String reverseParentheses(String s) {
        Stack<Character> stack = new Stack<>();
        StringBuilder sb = new StringBuilder();

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
                continue;
            }

            if (c == ')') {
                StringBuilder innerSb = new StringBuilder();

                while (!stack.isEmpty() && stack.peek() != '(') {
                    innerSb.insert(0, stack.pop());
                }

                if (!stack.isEmpty()) {
                    stack.pop(); // Remove the '('
                } else {
                    sb.append(innerSb.reverse().toString());  // If no '(' is found then append the reverse of the string 
                    continue;
                }

                for (int i = innerSb.length() - 1; i >= 0; i--) {
                    stack.push(innerSb.charAt(i));
                }
            } else {
                stack.push(c);
            }
        }

        while (!stack.isEmpty()) {
            sb.append(stack.pop());
        }

        return sb.toString();
    }
}

