        // Create a 2D array to store the number of consecutive 1s in each row and column.
        int[][] rows = new int[m][n];
        int[][] cols = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    rows[i][j] = (i == 0) ? 1 : rows[i - 1][j] + 1;
                    cols[j][i] = (j == 0) ? 1 : cols[j - 1][i] + 1;
                }
            }
        }

        int maxSide = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    // Check all possible square sizes.
                    for (int k = Math.min(rows[i][j], cols[j][i]); k >= 1; k--) {
                        boolean isValid = true;
                        for (int x = i - k + 1; x <= i; x++) {
                            if (grid[x][j] != 1 || grid[x][j + k - 1] != 1) {
                                isValid = false;
                                break;
                            }
                        }
                        for (int y = j - k + 1; y <= j; y++) {
                            if (grid[i - k + 1][y] != 1 || grid[i][y + k - 1] != 1) {
