        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    leftCount[i][j] = (i == 0 ? 0 : leftCount[i - 1][j]) + 1;
                    topCount[i][j] = (j == 0 ? 0 : topCount[i][j - 1]) + 1;
                }
            }
        }

        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    bottomCount[i][j] = (i == m - 1 ? 0 : bottomCount[i + 1][j]) + 1;
                    rightCount[i][j] = (j == n - 1 ? 0 : rightCount[i][j + 1]) + 1;
                }
            }
        }

        // Find the maximum size of square subgrid with all ones on its border
        int maxSideLength = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    // Calculate the minimum side length of a square subgrid with all ones on its border
                    int minSideLength = Math.min(leftCount[i][j], topCount[i][j]);
                    minSideLength = Math.min(minSideLength, bottomCount[i][j]);
                    minSideLength = Math.min(minSideLength, rightCount[i][j]);

                    // Update the maximum side length of square subgrid with all ones on its border
