            for (int j = 1; j <= n; ++j) {
                if (grid[i - 1][j] == 1 && grid[i][j] == 1 &&
                        rowTop[j - 1] + colLeft[i - 1] >= grid[i - 1][j]) {
                    int k = Math.min(rowTop[j - 1], colLeft[i - 1]);
                    while (k > 0) {
                        if (grid[i + k - 1][j] == 0 || grid[i][j + k - 1] == 0 ||
                                grid[i - k][j] == 0 || grid[i][j - k] == 0)
                            break;
                        ++k;
                    }
                    rowTop[j] = colLeft[i] = k;
                } else {
                    rowTop[j] = rowBottom[j] = colLeft[i] = colRight[i] = 1;
                }

                if (grid[m - i][n - j] == 1 && grid[m - i + 1][n - j] == 1 &&
                        rowBottom[n - j] + colRight[m - i + 1] >= grid[m - i][n - j]) {
                    int k = Math.min(rowBottom[n - j], colRight[m - i + 1]);
                    while (k > 0) {
                        if (grid[m - i + k][n - j] == 0 || grid[m - i][n - j + k] == 0 ||
                                grid[m - i][n - j - k] == 0 || grid[m - i - k][n - j] == 0)
                            break;
