                    dp[r][c] = Math.min(dp[r + 1][c], dp[r][c + 1]) + 1;
                } else {
                    int min = Integer.MAX_VALUE;
                    for (int i = r; i <= rows; i++) {
                        if (visited[i - 1][c]) {
                            break;
