    public int longestDecomposition(String text) {
        int max = 0;
        for (int i = 1; i <= text.length() / 2; i++) {
            if (text.length() % i == 0 && isPalindrome(text.substring(0, i)) 
                    && isPalindrome(text.substring(i * 2 - 1))) {
                int count = 0;
                for (int j = 0; j < text.length(); j += i) {
                    if (!isPalindrome(text.substring(j, j + i)))
