        result[0] = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            for (int[] dir : directions) {
                int nextNode = current[0] + dir[0];
                int color = current[2] ^ 1; // toggle the color

                if (nextNode >= 0 && nextNode < n && !visited[nextNode][color]) {
                    visited[nextNode][color] = true;

                    if (result[nextNode] == -1) {
                        result[nextNode] = result[current[0]] + 1;
                        queue.offer(new int[]{nextNode, color, current[2]});
                    }
                }
            }
        }

        return result;
    }
