            graph.add(new ArrayList<>());
        }

        for (int[] edge : redEdges) {
            graph.get(edge[0]).add(edge[1]);
        }
        for (int[] edge : blueEdges) {
            graph.get(edge[0]).add(edge[1]);
        }

        int[][] directions = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][2];
        int[][] distance = new int[n][2];

        for (int i = 0; i < n; i++) {
            Arrays.fill(distance[i], -1);
        }

        queue.offer(new int[] {0, 0});
        distance[0][0] = 0;
        visited[0][0] = true;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();
                int u = current[0], color = current[1];

                for (int j = 0; j < graph.get(u).size(); j++) {
                    int v = graph.get(u).get(j);

                    if (!visited[v][1 - color]) {
                        visited[v][1 - color] = true;

                        int newColor;
                        if (color == 0) {
                            newColor = 1;
                        } else {
                            newColor = 0;
                        }

                        if (distance[u][color] + 1 < distance[v][newColor]) {
                            distance[v][newColor] = distance[u][color] + 1;
                            queue.offer(new int[] {v, newColor});
                        }
                    }

                    for (int[] dir : directions) {
                        int x = u + dir[0], y = v + dir[1];

                        if (x >= 0 && x < n && y >= 0 && y < n && distance[u][color] + 1 < distance[x][y]) {
                            distance[x][y] = distance[u][color] + 1;
                            queue.offer(new int[] {x, y});
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (distance[i][0] == -1 && distance[i][1] == -1) {
                distance[i][0] = distance[i][1] = 0;
            } else if (distance[i][0] != -1) {
                distance[i][1] = Math.min(distance[i][1], distance[i][0]);
            } else if (distance[i][1] != -1) {
                distance[i][0] = Math.min(distance[i][0], distance[i][1]);
            }
        }

        int[] answer = new int[n];
        Arrays.fill(answer, n);

        for (int i = 0; i < n; i++) {
            if (distance[i][0] != -1) {
                answer[i] = Math.min(answer[i], distance[i][0]);
            }
            if (distance[i][1] != -1) {
                answer[i] = Math.min(answer[i], distance[i][1]);
            }
        }

        return answer;
    }
}

