public class Solution {
    public String alphabetBoardPath(String target) {
        int[] pos = new int[]{0, 0};
        StringBuilder sb = new StringBuilder();
        for (char c : target.toCharArray()) {
            int row = c - 'a';
            if (pos[0] == row) {
                // same row
                if (pos[1] < row) {
                    // move right
                    while (pos[1] < row) {
                        sb.append("R");
                        pos[1]++;
                    }
                } else if (pos[1] > row) {
                    // move left
                    while (pos[1] > row) {
                        sb.append("L");
                        pos[1]--;
                    }
                }
            } else {
                // different row
                int diff = Math.abs(pos[0] - row);
                if (pos[0] < row) {
                    // move down
                    for (int i = 0; i < diff; i++) {
                        sb.append("D");
                    }
                } else {
                    // move up
                    for (int i = 0; i < diff; i++) {
                        sb.append("U");
                    }
                }
                if (pos[1] < row) {
                    // move right
                    while (pos[1] < row) {
                        sb.append("R");
                        pos[1]++;
                    }
                } else if (pos[1] > row) {
                    // move left
                    while (pos[1] > row) {
                        sb.append("L");
                        pos[1]--;
                    }
                }
            }
            sb.append("!");
            pos[0] = row;
        }
        return sb.toString();
    }
