    public String alphabetBoardPath(String target) {
        Map<Character, int[]> charPos = new HashMap<>();
        init(charPos);

        StringBuilder sb = new StringBuilder();
        char[] chars = target.toCharArray();
        int curRow = 0;
        for (char c : chars) {
