            if (pos[0] != curRow || pos[1] != 0) {
                // move to the row first
                sb.append(getMoveToRow(curRow, pos[0]));
                curRow = pos[0];
                // then move to the column
                sb.append(getMoveToCol(pos[1]));
            }
            sb.append("!");
