    private String getMoveToRow(int from, int to) {
        if (from == to) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.abs(to - from); ++i) {
            if (to > from) {
                sb.append("D");
            } else {
                sb.append("U");
            }
        }
        return sb.toString();
    }

    private String getMoveToCol(int from, int to) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.abs(to - from); ++i) {
            if (to > from) {
                sb.append("R");
            } else {
                sb.append("L");
            }
        }
        return sb.toString();
    }
