public class Solution {
    public String alphabetBoardPath(String target) {
        Map<Character, int[]> position = new HashMap<>();

        // Define the positions of each character on the board.
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                char c = board[i][j];
                if (c != ' ') {
                    position.put(c, new int[]{i, j});
                }
            }
        }

        StringBuilder result = new StringBuilder();

        // Initialize the current character and its position.
        int prevCharIndex = 0;
        for (char c : target.toCharArray()) {
            // Check if the character is on the board.
            if (!position.containsKey(c)) {
                throw new RuntimeException("Character " + c + " not found in alphabet");
            }

            // Calculate the number of rows and columns to move.
            int[] currPosition = position.get(c);
            int[] prevPosition = position.get(target.charAt(prevCharIndex));
            int rowsToMove = Math.abs(currPosition[0] - prevPosition[0]);
            int colsToMove = Math.abs(currPosition[1] - prevPosition[1]);

            // Add the move commands to the result.
            for (int i = 0; i < rowsToMove; i++) {
                if (currPosition[0] > prevPosition[0]) {
                    result.append("D");
                } else {
                    result.append("U");
                }
            }

            for (int i = 0; i < colsToMove; i++) {
                if (currPosition[1] > prevPosition[1]) {
                    result.append("R");
                } else {
                    result.append("L");
                }
            }

            // Add the character at the current position.
            result.append("!").append(c);

            prevCharIndex++;
        }

        return result.toString();
    }

    private static String[][] board = {{"a", "b", "c", "d", "e"}, {"f","g", "h", "i", "j"},
