    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        int i = 0;
        int j = 1;
        while (candies > 0) {
            if (i == numPeople) {
                i = 0;
            }
            result[i] += Math.min(j, candies);
            candies -= Math.min(j, candies);
            i++;
            j++;
        }
        return result;
    }
}

