public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        int n = 1;

        while (candies > 0) {
            for (int i = 0; i < numPeople; i++) {
                if (i == numPeople - 1 && candies <= n) {
                    result[i] += candies;
                    break;
                }
                result[i] += n;
                candies -= n;
                if (candies <= n) {
                    break;
                }
            }
            n++;
        }

        return result;
    }
}

