public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        int index = 0;
        while (candies > 0) {
            for (int i = 0; i < numPeople && candies != 0; i++) {
                if (index == numPeople - 1 && candies <= numPeople) {
                    result[index] += candies;
                    return result;
                }
                int candy = Math.min(candies, index + 1);
                result[i] += candy;
                candies -= candy;
            }
            index++;
        }
        return result;
    }
