public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] res = new int[numPeople];
        int idx = 0;
        int step = 1;
        while (candies > 0) {
            for (int i = idx; candies > 0 && i < numPeople; i++) {
                if (i == numPeople - 1) {
                    res[i] += Math.min(candies, step + 1);
                } else {
                    res[i] += Math.min(candies, step);
                }
                candies -= Math.min(candies, step);
            }
            idx = 0;
            step++;
        }
        return res;
    }
}

