// #Easy #Math #Simulation #2023_06_01_Time_1_ms_(97.48%)_Space_40.8_MB_(8.63%)
public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] arr = new int[numPeople];
        for (int i = 0; i < candies; i++) {
            int person = i % numPeople;
            if ((i + 1) / 2 <= numPeople - person - 1) { // check if it's a left or right pass
                arr[person] += (i / 2) + 1;
            } else {
                arr[(numPeople - person - 1)] += i / 2 + 1;
            }
        }

        // distribute the remaining candies
        for (int i = numPeople-1; i >=0 ; i--) {
            int remainingCandies = candies - arr[i];
            if(remainingCandies > 0) {
                arr[i] += remainingCandies;
            }
            break;
        }

        return arr;
    }
}

