public class Solution {
    public int[] maxDepthAfterSplit(String seq) {
        int[] result = new int[seq.length()];
        int depthA = 0, depthB = 0;

        for (int i = 0; i < seq.length(); i++) {
            if (seq.charAt(i) == '(') {
                depthA++;
            } else {
                depthB++;

                // If the current string is a VPS and its depth is less than or equal to 
                // the maximum of depths A and B, then it should be part of the sequence with
                // minimum possible max(depth(A), depth(B)).
                if (depthA <= depthB) {
                    result[i] = 0;
                    depthA--;
                } else {
                    result[i] = 1;
                    depthB--;
                }
            }
        }

        return result;
    }
}

