import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        // Calculate frequency of each word and store it in an array along with the word itself
        int[][] wordFreq = new int[words.length][2];
        for (int i = 0; i < words.length; i++) {
            char minChar = findMinChar(words[i]);
            int freq = countCharFrequency(words[i], minChar);
            wordFreq[i] = new int[]{freq, i};
        }

        // Sort the array based on frequency in descending order
        Arrays.sort(wordFreq, Comparator.comparingInt(a -> a[0]));

        // Initialize an answer array to store the result for each query
        int[] answer = new int[queries.length];

        // For each query, find the number of words with higher frequency and add it to the answer array
        for (int i = 0; i < queries.length; i++) {
            char minChar = findMinChar(queries[i]);
            int freq = countCharFrequency(queries[i], minChar);
            int j;
            for (j = wordFreq.length - 1; j >= 0 && wordFreq[j][0] > freq; j--) {}
            answer[i] = wordFreq.length - j;
        }

        return answer;
    }

    // Helper function to find the lexicographically smallest character in a string
    private char findMinChar(String s) {
        char minChar = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < minChar) {
                minChar = s.charAt(i);
            }
        }
        return minChar;
    }

    // Helper function to count the frequency of a character in a string
    private int countCharFrequency(String s, char c) {
        int freq = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == c) {
                freq++;
            }
        }
        return freq;
    }
}

