public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int n = words.length;
        int[] result = new int[queries.length];

        for (int i = 0; i < queries.length; i++) {
            char minChar1 = getMinChar(queries[i]);
            int count1 = getCount(queries[i], minChar1);

            int count2 = 0;
            for (String word : words) {
                char minChar2 = getMinChar(word);
                if (count(minChar2, word) < count(minChar1, queries[i])) {
                    count2++;
                }
            }

            result[i] = n - count2;
        }

        return result;
    }

    private int getCount(String str, char c) {
        int count = 0;
        for (char ch : str.toCharArray()) {
            if (ch == c) {
                count++;
            }
        }
        return count;
    }

    private char getMinChar(String str) {
        char minChar = str.charAt(0);
        for (int i = 1; i < str.length(); i++) {
            if (str.charAt(i) < minChar) {
                minChar = str.charAt(i);
            }
        }
        return minChar;
    }

    private int count(char c, String str) {
        int count = 0;
        for (char ch : str.toCharArray()) {
            if (ch == c) {
                count++;
            }
        }
        return count;
    }
}

