import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        // Calculate frequency of smallest character in each word and store it in an array along with its index
        int[][] wordFreq = new int[words.length][2];
        for (int i = 0; i < words.length; i++) {
            char minChar = getMinChar(words[i]);
            int count = getCharCount(words[i], minChar);
            wordFreq[i] = new int[]{count, i};
        }

        // Sort the array based on frequency of smallest character in descending order
        Arrays.sort(wordFreq, Comparator.comparingInt(a -> a[0]).reversed());

        // Initialize answer array and count variable
        int[] answer = new int[queries.length];
        int count = 0;

        // Iterate over each query
        for (int i = 0; i < queries.length; i++) {
            char minChar = getMinChar(queries[i]);
            int queryCount = getCharCount(queries[i], minChar);

            // Find the index of first word with frequency greater than or equal to query's frequency
            int idx = Arrays.binarySearch(wordFreq, new int[]{queryCount + 1, -1}, Comparator.comparingInt(a -> a[0]).reversed());

            // If no such index is found, set it to -idx - 2 (to handle duplicate frequencies)
            if (idx < 0) idx = -idx - 2;

            // Count the number of words with frequency greater than query's frequency
            count += wordFreq.length - idx;
            answer[i] = count;
        }

        return answer;
    }

    private char getMinChar(String str) {
        char minChar = str.charAt(0);
        for (int i = 1; i < str.length(); i++) {
            if (str.charAt(i) < minChar) {
                minChar = str.charAt(i);
            }
        }
        return minChar;
    }

    private int getCharCount(String str, char c) {
        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == c) {
                count++;
            }
        }
        return count;
    }
}

