public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        Arrays.sort(words, Comparator.comparingInt(s -> getMinCharCount(s)));

        int n = queries.length;
        int m = words.length;
        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            int count = 0;

            for (String word : words) {
                if (getMinCharCount(queries[i]) < getMinCharCount(word)) {
                    count++;
                }
            }

            answer[i] = m - count;
        }

        return answer;
    }

    private int getMinCharCount(String s) {
        char minChar = 'z';
        int count = 0;

        for (char c : s.toCharArray()) {
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c == minChar) {
                count++;
            }
        }

        return count;
    }
}

