import java.util.Arrays;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        long[] freq = new long[2];
        Arrays.sort(words, (a, b) -> {
            long fa = a.length() - getMinIdx(a);
            long fb = b.length() - getMinIdx(b);
            return Long.compare(fa, fb);
        });

        for(String word : words) {
            freq[getMinIdx(word)]++;
        }

        int n = queries.length;
        int[] res = new int[n];
        for(int i = 0; i < n; ++i) {
            long query = getFrequency(queries[i]);
            long smallCount = 0;
            if(query != -1) {
                for(int j = 0; j < query; ++j) {
                    smallCount += freq[j];
                }
            } 
            res[i] = smallCount;
        }

        return res;
    }

    private int getMinIdx(String word) {
        char minChar = 'z' + 1;
        int minIdx = -1;
        for(int i = 0; i < word.length(); ++i) {
            if(word.charAt(i) < minChar) {
                minChar = word.charAt(i);
                minIdx = i;
            }
        }
        return minIdx + 1;
    }

    private long getFrequency(String word) {
        int minIdx = getMinIdx(word);
        if(minIdx == -1) return -1; // for empty string
        return (long)(word.length() - minIdx);
    }
}

