public class Solution {
    public int distanceBetweenBusStops(int[] distance, int start, int destination) {
        int totalDistance = 0;
        int tempStart = Math.min(start, destination);
        int tempDestination = Math.max(start, destination);

        for (int i = 0; i < distance.length; i++) {
            totalDistance += distance[i];
        }

        int clockwise = 0;
        for (int i = tempStart; i != tempDestination && i != (tempStart - 1 + distance.length) % distance.length; i = (i + 1) % distance.length) {
            clockwise += distance[i];
        }

        return Math.min(clockwise, totalDistance - clockwise);
    }
}

