public class Solution {
    private List<List<Integer>> result;
    private int[] rank;
    private boolean[] visited;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (List<Integer> connection : connections) {
            graph.get(connection.get(0)).add(connection.get(1));
            graph.get(connection.get(1)).add(connection.get(0));
        }

        // record rank
        rank = new int[n];
        Arrays.fill(rank, -1);

        // store result
        result = new ArrayList<>();

        // run dfs to get the rank of each node
        for (int i = 0; i < n; i++) {
            if (rank[i] == -1) {
                dfs(i, graph, connections);
            }
        }

        return result;
    }

    private void dfs(int node, List<List<Integer>> graph, List<List<Integer>> connections) {
        visited[node] = true;

        int minRank = Integer.MAX_VALUE;
        for (int nei : graph.get(node)) {
            if (!visited[nei]) {
                rank[node] = Math.min(rank[node], dfs(nei, graph, connections));
            } else if (rank[nei] < rank[node]) {
                result.add(Arrays.asList(node, nei));
            }
            minRank = Math.min(minRank, rank[nei]);
        }

        return minRank;
    }
}

