public class Solution {
    int[] rank;
    List<List<Integer>> result = new ArrayList<>();
    boolean[] visited;
    int time = 1;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (List<Integer> connection : connections) {
            int a = connection.get(0);
            int b = connection.get(1);
            graph.get(a).add(b);
            graph.get(b).add(a); // undirected graph
        }

        // record rank and store result
        rank = new int[n];
        visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(graph, i, -1);
            }
        }
        return result;
    }

    private void dfs(Map<Integer, List<Integer>> graph, int node, int parent) {
        // step1: run dfs to get the rank of this nei
        rank[node] = time++;
        visited[node] = true;

        for (int nei : graph.get(node)) {
            if (nei == parent) continue; // skip the parent since it's undirected
            if (!visited[nei]) { // step1: run dfs to get the rank of this nei, if it is visited before, it will reach base case immediately
                dfs(graph, nei, node);
                // if neiTime is strictly larger than current node's rank, there is no cycle,
                // connections between node and nei is a critically connection.
                if (rank[nei] < rank[node]) {
                    result.add(Arrays.asList(node, nei));
                }
            } else { // nei has been visited before
                // keep updating current node's rank with nei's smaller ranks
                rank[node] = Math.min(rank[node], rank[nei]);
            }
        }
    }
}

