            }
        }

        return res;
    }

    private void dfs(int node, Set<Integer> nei) {
        visited[node] = true;

        int minRank = Integer.MAX_VALUE;
        for (int neiNode : nei) {
            if (!visited[neiNode]) {
                rank[neiNode] = dfs(neiNode, graph.get(neiNode));
                minRank = Math.min(minRank, rank[neiNode]);
            } else {
                minRank = Math.min(minRank, rank[neiNode]);
            }
        }

        if (minRank == Integer.MAX_VALUE) {
            return;
        }

        if (rank[node] == minRank) {
            res.add(Arrays.asList(node, nei.iterator().next()));
        }

        this.rank[node] = minRank;
    }
}

