public class Solution {
    public int minNonZeroProduct(int p) {
        long MOD = (long) 1e9 + 7;
        long x = (long) Math.pow(2, p);
        long y = (x - 1);

        if (p == 1) return 1;

        long ans = 1;
        for (int i = p - 1; i >= 0; --i) {
            if (i % 2 == 0) {
                ans *= x;
                ans %= MOD;
                x--;
            } else {
                ans *= y;
                ans %= MOD;
                y--;
            }
        }

        return (int) ans;
    }
}

