        for(int i = p - 2; i >= 0; i--){
            if(i == 0){
                x = (x + 1) % mod;
                y = ((y * (2 << (p - i - 1))) % mod);
                break;
            }

            long prod = (((y * (2 << (p - i - 1) - 1)) % mod));
            if(prod != 0){
                ans += prod;
                x -= prod;
                y = ((y * (2 << (p - i - 1))) % mod);
