public class Solution {
    public int minNonZeroProduct(int p) {
        long mod = (long) Math.pow(10, 9) + 7;
        long start = 2L;
        long pow = 1L;
        long maxNum = 1L;

        for (int i = 0; i < p - 1; i++) {
            // Calculate the next power of 2
            pow *= 2;
            // Update the maximum number that can be formed by swapping bits
            maxNum = (maxNum * pow + start) % mod;
            start = pow;
        }

        long secondMaxNum = (pow - 1) / 2;

        return (int)((maxNum * secondMaxNum) % mod);
    }
