import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[][] result = new int[n][];

        for (int i = 0; i < n / 2 + n % 2; i++) {
            List<Integer> currDiff = new ArrayList<>();

            // Find all differences between the sums, excluding the last two
            if (i == n / 2) {
                currDiff.add(Math.abs(sums[sums.length - 1] - sums[0]));
            } else {
                for (int j = 0; j < sums.length - 1; j++) {
                    currDiff.add(Math.abs(sums[j + 1] - sums[j]));
                }
            }

            result[i] = bfs(currDiff, i);
        }

        // The answer is in the second half of the result array
        int[] ans = new int[n];
        for (int i = n / 2; i < n; i++) {
            System.arraycopy(result[i], 0, ans, n - 1 - i, result[i].length);
        }

        return ans;
    }

    private int[] bfs(List<Integer> currDiff, int idx) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{idx, 0});
        Set<String> visited = new HashSet<>();
        List<Integer> res = new ArrayList<>();

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            if (cur[1] == currDiff.size() - 1) {
                res.add(cur[0]);
                continue;
            }

            for (int j = 0; j < currDiff.size(); j++) {
                if (!visited.contains((cur[0] + j) + "," + (cur[1] + 1))) {
                    visited.add((cur[0] + j) + "," + (cur[1] + 1));
                    queue.offer(new int[]{cur[0] + j, cur[1] + 1});
                }
            }
        }

        return res.stream().mapToInt(i -> i).toArray();
    }
}

