public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfUniqueGoodSubsequences(String binary) {
        Map<String, Integer> dp = new HashMap<>();
        dp.put("", 0);
        for (char c : binary.toCharArray()) {
            Map<String, Integer> nextDp = new HashMap<>(dp);
            if (c == '1') {
                nextDp.put("1", 1 + dp.getOrDefault("1", 0));
                nextDp.put("01", 1 + dp.getOrDefault("01", 0));
            } else {
                nextDp.put("0", 1 + dp.getOrDefault("0", 0));
            }
            for (String s : nextDp.keySet()) {
                if (!s.isEmpty() && s.charAt(0) == '0') {
                    nextDp.put(s, nextDp.get(s) - nextDp.getOrDefault(s.substring(1), 0));
                }
            }
            dp = nextDp;
        }

        int ans = 0;
        for (String s : dp.keySet()) {
            if (!s.isEmpty() && s.charAt(0) != '0') {
                ans += dp.get(s);
            }
        }
        return (ans + dp.getOrDefault("0", 0)) % MOD;
    }
}

