public class Solution {
    public int numberOfUniqueGoodSubsequences(String binary) {
        // Remove empty string and "0"
        if (binary.equals("0") || binary.equals("")) return 1;

        Set<String> uniqueSubs = new HashSet<>();
        String current = "";

        for (int i = binary.length() - 1; i >= 0; i--) {
            char c = binary.charAt(i);

            if (!current.isEmpty()) {
                // If last char was '0', add "0" to the end and remove duplicates
                if (c == '0') {
                    String newSubs = current + "0";
                    uniqueSubs.add(newSubs);
                }

                // Add all possible subsequences without c at the end minus dups
                for (String sub : getSubsequences(current)) {
                    if (!uniqueSubs.contains(sub)) {
                        uniqueSubs.add(sub);
                    }
                }
            } else {
                current = String.valueOf(c);
            }
        }

        return uniqueSubs.size();
    }

    private Set<String> getSubsequences(String str) {
        Set<String> subsequences = new HashSet<>();
        subsequences.add("");

        for (int i = 0; i < str.length(); i++) {
            String s = str.substring(0, i + 1);

            if (!subsequences.contains(s)) {
                subsequences.add(s);
            }

            for (String sub : getSubsequences(str.substring(i + 1))) {
                String newSub = s + sub;

                if (!subsequences.contains(newSub)) {
                    subsequences.add(newSub);
                }
            }
        }

        return subsequences;
    }
}

