            } else {
                countZeros[i] = countZeros[i + 1];
            }
        }

        // Calculate the total number of unique good subsequences
        long totalCount = (countOnes[0] * (countOnes[0] + 1) / 2) % MOD +
                          (countZeros[0] * (countZeros[0] + 1) / 2) % MOD -
                          countOnes[0] * countOnes[0] % MOD;

        // Subtract the duplicate subsequence "00"
        totalCount = (totalCount - countZeros[0]) % MOD;

        return (int) ((totalCount + 1) % MOD);
    }
}

