import java.util.Map;

public class Solution {
    public int numberOfUniqueGoodSubsequences(String binary) {
        Map<Integer, Integer> map = new HashMap<>();
        long MOD = (long) 1e9 + 7;
        for(char c : binary.toCharArray()){
            if(c == '0'){
                if(map.containsKey(0)){
                    map.put(0, map.get(0) + 1);
                }else{
                    map.put(0, 1);
                }
            } else {
                long value = (map.getOrDefault(0, 0) + map.getOrDefault(2, 0) + 1);
                if(value >= MOD){
                    value -= MOD;
                }
                map.put(2, (int)value);
            }
        }
        long result = map.getOrDefault(0, 0) + map.getOrDefault(2, 0);
        if(result < 0){
            result += MOD;
        }
        return (int)result;
    }
}

