import java.util.Random;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        Random random = new Random();
        int n = nums.length;

        // Create a copy of input array and shuffle it.
        int[] shuffled = nums.clone();
        for (int i = 0; i < n; i++) {
            int j = random.nextInt(n);
            int temp = shuffled[i];
            shuffled[i] = shuffled[j];
            shuffled[j] = temp;
        }

        // Sort the array and then rearrange it.
        quickSort(shuffled, 0, n - 1);
        for (int i = 0; i < n; i += 2) {
            int temp = shuffled[i];
            shuffled[i] = shuffled[n - i - 1];
            shuffled[n - i - 1] = temp;
        }

        return shuffled;
    }

    private void quickSort(int[] arr, int low, int high) {
        if (low < high) {
            int pi = partition(arr, low, high);
            quickSort(arr, low, pi - 1);
            quickSort(arr, pi + 1, high);
        }
    }

    private int partition(int[] arr, int low, int high) {
        int pivot = arr[high];
        int i = (low - 1);

        for (int j = low; j <= high - 1; j++) {
            if (arr[j] < pivot) {
                i++;
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        int temp2 = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp2;

        return (i + 1);
    }
}

