public class Solution {
    public int[] rearrangeArray(int[] nums) {
        // Sort the array in ascending order
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[i - 1]) {
                // Swap the elements at indices i and i-1
                int temp = nums[i];
                nums[i] = nums[i - 1];
                nums[i - 1] = temp;
            }
        }

        // Initialize variables to store the result array and its length
        int[] res = new int[nums.length];
        int j = -1;

        // Rearrange the elements in the sorted array such that every element is not equal to the average of its neighbors
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 == 0) {
                res[++j] = nums[i];
            }
        }

        j = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 != 0) {
                res[++j] = nums[i];
            }
        }

        return res;
    }
}

