import java.util.Arrays;

public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        // Calculate time taken by each monster to reach the city
        int[] time = new int[dist.length];
        for (int i = 0; i < dist.length; i++) {
            time[i] = (int) Math.ceil((double) dist[i] / speed[i]);
        }

        // Sort the times in ascending order
        Arrays.sort(time);

        // Initialize a variable to keep track of the number of monsters eliminated
        int eliminated = 0;

        // Iterate over the sorted times
        for (int t : time) {
            // If the current time is less than or equal to the total time taken by all monsters,
            // it means that we can eliminate one more monster before losing.
            if (t <= dist.length - eliminated) {
                eliminated++;
            } else {
                break;
            }
        }

        return eliminated;
    }
}

