public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        // Eliminate monsters based on time taken to reach the city
        for (int i = 0; i < dist.length; i++) {
            // Calculate time taken by each monster to reach the city
            double time = (double) dist[i] / speed[i];

            // Store the times in an array and sort it in ascending order
            double[] times = new double[dist.length];
            for (int j = 0; j < dist.length; j++) {
                times[j] = (double) dist[j] / speed[j];
            }
            Arrays.sort(times);

            // If the time taken by a monster to reach the city is less than or equal to
            // its index in the sorted array, then we can't eliminate it.
            if (time <= i + 1) {
                return i;
            }
        }

        // If all monsters take more than their index to reach the city, then we can
        // eliminate them one by one until any of them reaches the city.
        int count = dist.length;
        for (int i = 0; i < dist.length; i++) {
            double time = (double) dist[i] / speed[i];

            if (time <= i + 1) {
                return count - i - 1;
            }
        }

        // If none of the above conditions are met, then we can eliminate all monsters
        // before they reach the city.
        return dist.length;
    }
