public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = mentors.length;

        // Initialize a 2D array to store the compatibility score for each student-mentor pair.
        int[][] dp = new int[m][n];

        // Iterate over each question and calculate the compatibility scores.
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int score = 0;
                for (int k = 0; k < students[i].length; k++) {
                    // If the answers are the same, increase the compatibility score.
                    if ((students[i][k] & mentors[j][k]) == students[i][k]) {
                        score++;
