                }
                dp[i][j] = score;
            }
        }

        int maxScore = 0;

        for (int i = 0; i < m; i++) {
            // Try to assign each student to a mentor.
            Arrays.sort(dp[i]);

            for (int j = 0; j <= n - 1; j++) {
                // Assign the student to the mentor with the highest compatibility score so far.
                maxScore = Math.max(maxScore, dp[i][j] + getComplementarySum(i, students.length, dp));
            }
        }

        return maxScore;
    }

    private int getComplementarySum(int index, int m, int[][] dp) {
        // Find the student with the next highest compatibility score.
        for (int i = 0; i < m; i++) {
            if (i != index) {
                Arrays.sort(dp[i]);
                return dp[i][dp[i].length - 1];
            }
        }

        return 0;
    }
