        // Try with next Mentor
        if (mentor < m-1 && !visitedMentors[mentor+1]) {
            ans = Math.max(ans, compatibilityScore + maxCompatibilitySumHelper(students, mentors, visitedMentors, student+1, mentor+1, n, m));
        }

        return ans;
    }

    private int getCompatibilityScore(int[] studentAnswers, int[] mentorAnswers) {
        int score = 0;
        for (int i = 0; i < studentAnswers.length; ++i)
            if (studentAnswers[i] == mentorAnswers[i])
                ++score;

