public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        TreeSet<Integer> set = new TreeSet<>();
        int[] ans = new int[obstacles.length];

        for (int i = 0; i < obstacles.length; i++) {
            if (set.isEmpty() || obstacles[i] >= obstacles[set.last()]) {
                set.add(i);
                ans[i] = set.size();
            } else {
                Integer idx = set.ceiling(i - obstacles[i]);
                if (idx == null) {
                    continue;
                }
                int prevIdx = set.lower(idx);
                set.remove(prevIdx);
                set.add(i);
                ans[i] = set.size() + 1;
            }
        }

        return ans;
    }
