// #2022_05_21_Time_79_ms_(85.00%)_Space_146.3_MB_(35.00%)
public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];

        // Binary Indexed Tree to store the heights of obstacles
        BIT bit = new BIT(n);

        for (int i = 0; i < n; i++) {
            // Find the smallest number of obstacles that can be included in the course 
            // such that the ith obstacle is included and satisfies all conditions.
            int k = binarySearch(bit, obstacles[i]);

            // Update the Binary Indexed Tree
            bit.update(i + 1, obstacles[i], k);

            ans[i] = k;
        }

        return ans;
    }

    private BIT getBIT(int[] obstacles) {
        BIT bit = new BIT(obstacles.length);
        for (int i = 0; i < obstacles.length; i++) {
            bit.update(i + 1, obstacles[i], 1);
        }
        return bit;
    }

    class BIT {
        int size;
        int[] tree;

        public BIT(int size) {
            this.size = size;
            this.tree = new int[size + 1];
        }

        void update(int i, int val, int delta) {
            while (i <= size) {
                tree[i] += delta;
                i += i & -i;
            }
        }

        int query(int i) {
            int sum = 0;
            while (i > 0) {
                sum += tree[i];
                i -= i & -i;
            }
            return sum;
        }

        int rangeQuery(int i, int j) {
            return query(j) - query(i - 1);
        }
    }

    private int binarySearch(BIT bit, int target) {
        int left = 0, right = bit.size;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (bit.query(mid) >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}

