public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;

        int left = 0, right = n - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            boolean foundRowWithPeak = false;

            for (int row = 0; row < m && !foundRowWithPeak; row++) {
                if (mat[row][mid] > mat[row][(mid + 1) % n]) {
                    int nextMid = mid - 1;
                    while (nextMid >= left && mat[row][nextMid] > mat[row][mid]) {
                        nextMid--;
                    }

                    if (nextMid < left || (nextMid >= left && mat[row][left] <= mat[row][mid])) {
                        foundRowWithPeak = true;
                    } else {
                        int prevMid = mid + 1;
                        while (prevMid <= right && mat[row][prevMid] > mat[row][mid]) {
                            prevMid++;
                        }

                        if (prevMid > right || (prevMid <= right && mat[row][(right - 1)] <= mat[row][mid])) {
                            foundRowWithPeak = true;
                        } else {
                            left = nextMid + 2;
                            right = prevMid - 2;
                        }
                    }
                }
            }

            if (!foundRowWithPeak) {
                left = mid + 1;
                right = mid;
            }
        }

        int peakRow = 0, peakCol = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] > mat[peakRow][peakCol]) {
                    peakRow = i;
                    peakCol = j;
                }
            }
        }

        return new int[] {peakRow, peakCol};
    }
}

