public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;

        // Find the cell with maximum value in the entire grid.
        int maxVal = Integer.MIN_VALUE;
        int maxI = -1, maxJ = -1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] > maxVal) {
                    maxVal = mat[i][j];
                    maxI = i;
                    maxJ = j;
                }
            }
        }

        // Check the cells around the maximum value cell.
        for (int i = Math.max(0, maxI - 1); i <= Math.min(maxI + 1, m - 1); i++) {
            for (int j = Math.max(0, maxJ - 1); j <= Math.min(maxJ + 1, n - 1); j++) {
                // Check all four directions.
                boolean isPeak = true;
                if (mat[i][j] < mat[maxI][maxJ]) {
                    int dirX[] = {1, -1, 0, 0};
                    int dirY[] = {0, 0, 1, -1};
                    for (int k = 0; k < 4; k++) {
                        if (i + dirX[k] >= 0 && i + dirX[k] <= m - 1 
                                && j + dirY[k] >= 0 && j + dirY[k] <= n - 1) {
                            if (mat[i][j] < mat[i + dirX[k]][j + dirY[k]]) {
                                isPeak = false;
                                break;
                            }
                        } else {
                            // If cell out of bound, it's a peak.
                            continue;
                        }
                    }

                    if (isPeak) {
                        return new int[] {i, j};
                    }
                }
            }
        }

        // If no peak found in the entire grid.
        return new int[] {-1, -1};
    }
}

