public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = (m > n ? m : n) / 2; // calculate the number of layers

        k %= 2 * layers; // reduce k to be within [0, layers)

        for (int i = 0; i < Math.min(k, layers); i++) {
            int top = grid[0][i];
            int left = grid[i][n - i - 1];

            for (int j = n - i - 2; j >= 0; j--) {
                grid[i][j + 1] = grid[i + 1][j]; // move right to down
            }

            for (int j = i + 1; j < m - i - 1; j++) {
                grid[j][n - i - 1] = grid[j + 1][n - i - 2]; // move down to left
            }

            for (int j = n - i - 2; j >= 0; j--) {
                grid[m - i - 1][j] = grid[m - i - 2][j + 1]; // move left to up
            }

            for (int j = m - i - 2; j > i; j--) {
                grid[j - 1][i] = grid[j][n - i - 1]; // move up to right
            }

            grid[0][i] = left;
            grid[i][n - i - 1] = top;
        }

        return grid;
    }
}

