// #Medium #Array #Matrix #Simulation #2022_05_14_Time_2_ms_(91.30%)_Space_43_MB_(86.96%)
public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Determine the number of rotations required for each layer
        int layers = (int) Math.ceil(Math.sqrt(rows * cols) / 2.0);

        k %= layers; // In case k is greater than the total number of layers

        int[][] directions = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}}; // right, down, left, up
        int[] dirIdx = {1, 2, 3, 0}; // index for the next direction to move

        int r = 0, c = 0;
        int i = 0;

        while (i < rows * cols / 4) {
            int layerSize = 2 * (k + i) - 1; // The size of the current layer
            int layerNum = (int) Math.ceil((layerSize * layerSize) / (double) (rows * cols)); // The number of the current layer

            for (int j = 0; j < layerSize * layerSize; j++) {
                grid[r][c] = grid[r + (j % layerSize)][c + (j / layerSize)];

                int nextDirIdx = dirIdx[(i + k) % 4]; // The direction to move in the next step
                int[] nextDir = directions[nextDirIdx];

                r += nextDir[0];
                c += nextDir[1];

                if (r < 0 || r >= rows - layerSize || c < 0 || c >= cols - layerSize) {
                    // If we've reached the edge of the grid, move to the next direction
                    dirIdx = dirIdx[(i + k) % 4];
                    nextDir = directions[dirIdx[0]];
                    r += nextDir[0];
                    c += nextDir[1];

                    i++;
                }
            }

            // Move to the next layer
            i++;

            // Reset the current position for the next layer
            r = 0;
            c = 0;

            // Update k for the next layer
            k -= (int) Math.ceil((layerSize * layerSize) / (double) (rows * cols));
        }

        return grid;
    }
}

