public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // Check if rotations are needed
        k %= (m / 2 + n / 2);

        for (int i = 0; i < Math.min(m / 2, n / 2); i++) {
            int layerSize = 2 * (i + 1);
            int layerStartX = m - layerSize;
            int layerStartY = n - layerSize;

            for (int j = 0; j < layerSize / 2; j++) {
                int temp = grid[layerStartY][layerStartX + j];
                grid[layerStartY][layerStartX + j] = grid[layerStartY + j][layerStartX];
                grid[layerStartY + j][layerStartX] = grid[layerStartY + layerSize - 1 - j][layerStartX + layerSize - 1];
                grid[layerStartY + layerSize - 1 - j][layerStartX + layerSize - 1] = grid[layerStartY + layerSize - 1][layerStartX + layerSize - 1 - j];
                grid[layerStartY + layerSize - 1][layerStartX + layerSize - 1 - j] = temp;
            }
        }

        // Apply the remaining rotations
        for (int i = 0; i < k; i++) {
            int[] tempRow = new int[n];
            for (int j = 0; j < n; j++) {
                tempRow[j] = grid[m - 1][j];
            }
            for (int j = m - 2; j >= 0; j--) {
                grid[j + 1][n - 1] = grid[j][n - 1];
            }
            for (int j = n - 2; j >= 0; j--) {
                grid[0][j] = tempRow[j];
            }
        }

        return grid;
    }
}

