public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layerSize = 2;

        while (k > 0 || m * n > 4) {
            if (k > 0) {
                for (int i = 0; i < m / 2 - layerSize / 2; ++i) {
                    rotateLayer(grid, i, m - i - 1, n);
                }
                k--;
                layerSize += 2;
            } else if ((m & 3) == 4 || (n & 3) == 4) {
                int temp = m;
                m = n;
                n = temp;
                rotateLayer(grid, 0, m - 1, n / 2);
                k += (m * n) / 4 - 1;
            }
        }

        return grid;
    }

    private void rotateLayer(int[][] grid, int startR, int endR, int stepN) {
        for (int i = 0; i < stepN; ++i) {
            int temp = grid[startR][startR + i];
            grid[startR][startR + i] = grid[endR - i][startR];
            grid[endR - i][startR] = grid[endR][endR - i];
            grid[endR][endR - i] = grid[startR + i][endR];
            grid[startR + i][endR] = temp;
        }
    }
}

